// In-Memory Cache untuk System Settings SSOT (Edge Isolate Caching)
// TTL: 5 Menit dengan Immediate Invalidation pada setiap Mutasi (PUT/POST/DELETE)
const systemSettingsMemoryCache = new Map(); // key -> { value, updated_at, expiry }
const homeroomTeacherMemoryCache = new Map(); // normClass -> { data, expiresAt }
let allSystemSettingsMemoryCache = {
    data: null,
    expiry: 0
};

function getCachedSystemSetting(key) {
    if (!key) return null;
    const entry = systemSettingsMemoryCache.get(key);
    if (entry && entry.expiry > Date.now()) {
        return entry;
    }
    return null;
}

function setCachedSystemSetting(key, value, updated_at = null, ttlMs = 5 * 60 * 1000) {
    if (!key) return;
    systemSettingsMemoryCache.set(key, {
        value,
        updated_at: updated_at || new Date().toISOString(),
        expiry: Date.now() + ttlMs
    });
}

function invalidateSystemSettingCache(key = null) {
    if (key) {
        systemSettingsMemoryCache.delete(key);
    } else {
        systemSettingsMemoryCache.clear();
    }
    allSystemSettingsMemoryCache = {
        data: null,
        expiry: 0
    };
}

// In-Memory Edge Cache untuk LMS Student Learning Path (TTL 45 Detik pada environment production)
const lmsStudentLearningPathCache = new Map(); // "normClass:normSubject:nis" -> { data, expiry }

function getCachedLmsStudentLearningPath(className, subjectName, studentNis) {
    if (!studentNis || !className) return null;
    const cacheKey = `${String(className).toLowerCase().trim()}:${String(subjectName || "").toLowerCase().trim()}:${String(studentNis).trim()}`;
    const entry = lmsStudentLearningPathCache.get(cacheKey);
    if (entry && entry.expiry > Date.now()) {
        return entry.data;
    }
    if (entry) lmsStudentLearningPathCache.delete(cacheKey);
    return null;
}

function setCachedLmsStudentLearningPath(className, subjectName, studentNis, data, ttlMs = 45 * 1000) {
    if (!studentNis || !className) return;
    if (lmsStudentLearningPathCache.size > 2000) {
        lmsStudentLearningPathCache.clear();
    }
    const cacheKey = `${String(className).toLowerCase().trim()}:${String(subjectName || "").toLowerCase().trim()}:${String(studentNis).trim()}`;
    lmsStudentLearningPathCache.set(cacheKey, {
        data,
        expiry: Date.now() + ttlMs
    });
}

function invalidateLmsClassCache(className = null, studentNis = null) {
    if (!className && !studentNis) {
        lmsStudentLearningPathCache.clear();
        return;
    }
    const normClass = className ? String(className).toLowerCase().trim() : null;
    const targetNis = studentNis ? String(studentNis).trim() : null;
    for (const key of lmsStudentLearningPathCache.keys()) {
        const parts = key.split(":");
        const cls = parts[0];
        const nis = parts[2];
        if (normClass && (cls === normClass || cls === "")) {
            lmsStudentLearningPathCache.delete(key);
        } else if (targetNis && nis === targetNis) {
            lmsStudentLearningPathCache.delete(key);
        }
    }
}

// Hak pengelolaan pengaturan jurnal mengikuti akses halaman Admin Jurnal.
// Kunci jurnal klien tidak boleh memberi hak mengubah mode global.
async function requireJurnalSettingsManager(request, env) {
    const key = request.headers.get('X-Migration-Key') || request.headers.get('X-Sync-Key') || request.headers.get('X-Api-Key') || new URL(request.url).searchParams.get('key');
    if (key && env.MIGRATION_SECRET && key === env.MIGRATION_SECRET) return null;
    const authResult = await verifyFirebaseToken(request, env);
    if (!authResult.valid || authResult.user.isAnonymous) {
        return errorResponse('Sesi pengelola jurnal diperlukan.', 401, request);
    }
    const roles = ['super_admin', 'wakasek_kurikulum', 'kurikulum', 'kepala_lab'];
    if (!roles.some(role => userHasRole(authResult.user, role))) {
        return errorResponse('Hanya pengelola jurnal yang dapat mengubah pengaturan jurnal.', 403, request);
    }
    return null;
}

function invalidateMasterBundleCache() {
    masterBundleMemoryCache = {
        data: null,
        expiry: 0
    };
    gtkListMemoryCache = {
        data: null,
        expiry: 0
    };
}

// Helper untuk menyinkronkan metadata_classes ke system_settings secara otomatis (Zero Full Table Scan)
async function autoSyncMetadataClasses(db, explicitClasses = null) {
    try {
        let classesToSave = [];
        if (Array.isArray(explicitClasses) && explicitClasses.length > 0) {
            const existingSetting = await db.prepare(`SELECT value FROM system_settings WHERE key = 'metadata_classes' LIMIT 1`).first();
            let currentList = [];
            if (existingSetting && existingSetting.value) {
                try {
                    const parsed = JSON.parse(existingSetting.value);
                    currentList = Array.isArray(parsed) ? parsed : (Array.isArray(parsed.list) ? parsed.list : []);
                } catch (e) {}
            }
            const set = new Set(currentList);
            for (const c of explicitClasses) {
                if (c && typeof c === 'string') {
                    const trimmed = c.trim();
                    const u = trimmed.toUpperCase();
                    if (!u.startsWith('ALUMNI') && !u.startsWith('KELUAR') && !u.startsWith('LULUS') && !u.startsWith('DROP') && !u.startsWith('MUTASI') && trimmed !== '') {
                        set.add(trimmed);
                    }
                }
            }
            classesToSave = Array.from(set);
        } else {
            const classStmt = db.prepare(`
                SELECT DISTINCT class FROM students 
                WHERE (status IS NULL OR status = 'active') 
                  AND class IS NOT NULL AND class != ''
                ORDER BY class ASC
            `);
            const { results: classRows } = await classStmt.all();
            const rawClasses = (classRows || []).map(r => r.class);
            classesToSave = rawClasses.filter(c => {
                if (!c) return false;
                const u = String(c).trim().toUpperCase();
                return !u.startsWith('ALUMNI') && !u.startsWith('KELUAR') && !u.startsWith('LULUS') && !u.startsWith('DROP') && !u.startsWith('MUTASI');
            });
        }

        const getRank = (name) => {
            const u = String(name || '').trim().toUpperCase();
            if (u.startsWith('XII')) return 12;
            if (u.startsWith('XI')) return 11;
            if (u.startsWith('X')) return 10;
            return 99;
        };
        classesToSave.sort((a, b) => {
            const rankA = getRank(a);
            const rankB = getRank(b);
            if (rankA !== rankB) return rankA - rankB;
            return a.localeCompare(b, 'id', { numeric: true });
        });

        if (classesToSave.length > 0) {
            await db.prepare(`
                INSERT INTO system_settings (key, value, updated_at)
                VALUES ('metadata_classes', ?, datetime('now'))
                ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = datetime('now')
            `).bind(JSON.stringify({ list: classesToSave })).run();
        }
        invalidateMasterBundleCache();
        invalidateSystemSettingCache('metadata_classes');
        return classesToSave;
    } catch (e) {
        console.error('[autoSyncMetadataClasses] Gagal sinkronisasi metadata_classes:', e);
        return [];
    }
}

// Helper untuk memperbarui metadata timestamp (lastUpdateStudents, lastUpdateTeachers, dll.)
// secara atomik tanpa menghapus field metadata lainnya (SSOT D1)
async function updateServerMetadata(db, partialMetadata) {
    try {
        if (!db || !partialMetadata || typeof partialMetadata !== 'object') return;
        let existing = getCachedSystemSetting('metadata');
        if (!existing) {
            existing = await db.prepare("SELECT value FROM system_settings WHERE key = 'metadata' LIMIT 1").first();
            if (existing) setCachedSystemSetting('metadata', existing.value);
        }
        let existingObj = {};
        if (existing && existing.value) {
            try { existingObj = typeof existing.value === 'string' ? JSON.parse(existing.value) : existing.value; } catch (e) {}
        }
        const merged = { ...existingObj, ...partialMetadata };
        await db.prepare(`
            INSERT INTO system_settings (key, value, updated_at)
            VALUES ('metadata', ?, datetime('now'))
            ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = datetime('now')
        `).bind(JSON.stringify(merged)).run();
        invalidateSystemSettingCache('metadata');
    } catch (e) {
        console.warn("[updateServerMetadata] Gagal update metadata:", e.message);
    }
}

// Ambil Google JWKS dengan Caching di Memory & Edge
async function getGoogleJwks() {
    const now = Date.now();
    if (jwksMemoryCache.keys && jwksMemoryCache.keys.length > 0 && jwksMemoryCache.expiry > now) {
        return jwksMemoryCache.keys;
    }

    try {
        const res = await fetch(GOOGLE_JWKS_URL, {
            cf: {
                cacheTtl: 21600, // 6 jam di Edge
                cacheEverything: true
            }
        });

        if (!res.ok) {
            throw new Error(`HTTP ${res.status} fetching Google JWKS`);
        }

        const data = await res.json();
        const keys = data.keys || [];

        const cacheControl = res.headers.get("Cache-Control") || "";
        const match = cacheControl.match(/max-age=(\d+)/i);
        const maxAgeSeconds = match ? parseInt(match[1], 10) : 21600;

        jwksMemoryCache = {
            keys,
            expiry: now + (maxAgeSeconds * 1000)
        };

        return keys;
    } catch (e) {
        if (jwksMemoryCache.keys && jwksMemoryCache.keys.length > 0) {
            return jwksMemoryCache.keys;
        }
        throw e;
    }
}

// Helper: Base64URL string to Uint8Array
function base64UrlToUint8Array(base64Url) {
    const base64 = base64Url.replace(/-/g, "+").replace(/_/g, "/");
    const padLen = (4 - (base64.length % 4)) % 4;
    const padded = base64 + "=".repeat(padLen);
    const raw = atob(padded);
    const output = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) {
        output[i] = raw.charCodeAt(i);
    }
    return output;
}

// Helper: Uint8Array to Base64URL string
function uint8ArrayToBase64Url(bytes) {
    let binary = "";
    for (let i = 0; i < bytes.byteLength; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=/g, "");
}

// Helper: Decode Base64URL JSON part
function parseJwtPart(base64Url) {
    try {
        if (!base64Url || typeof base64Url !== "string") return null;
        const base64 = base64Url.replace(/-/g, "+").replace(/_/g, "/");
        const padLen = (4 - (base64.length % 4)) % 4;
        const padded = base64 + "=".repeat(padLen);
        const jsonStr = decodeURIComponent(
            atob(padded)
                .split("")
                .map(c => "%" + ("00" + c.charCodeAt(0).toString(16)).slice(-2))
                .join("")
        );
        return JSON.parse(jsonStr);
    } catch (err) {
        return null;
    }
}

// Verifikasi Tanda Tangan Kriptografis Token JWT Firebase (RS256 via Web Crypto Subtle)
function decodeFirestoreValue(value) {
    if (!value || typeof value !== "object") return null;
    if ("nullValue" in value) return null;
    if ("stringValue" in value) return value.stringValue;
    if ("booleanValue" in value) return value.booleanValue;
    if ("integerValue" in value) return Number(value.integerValue);
    if ("doubleValue" in value) return Number(value.doubleValue);
    if ("timestampValue" in value) return value.timestampValue;
    if ("arrayValue" in value) return (value.arrayValue.values || []).map(decodeFirestoreValue);
    if ("mapValue" in value) return decodeFirestoreFields(value.mapValue.fields || {});
    return null;
}

function decodeFirestoreFields(fields = {}) {
    return Object.fromEntries(Object.entries(fields).map(([key, value]) => [key, decodeFirestoreValue(value)]));
}

async function loadOwnFirebaseProfile(idToken, uid, env = null) {
    let document = null;
    const url = `https://firestore.googleapis.com/v1/projects/${FIREBASE_PROJECT_ID}/databases/(default)/documents/users/${encodeURIComponent(uid)}`;
    try {
        const response = await fetch(url, { headers: { Authorization: `Bearer ${idToken}` } });
        if (response.status === 404) return {};
        if (response.ok) {
            document = await response.json();
        }
    } catch (eFetch) {
        // Lanjut ke percobaan melalui admin credentials di bawah
    }

    if (!document && env && (env.GOOGLE_SERVICE_ACCOUNT_EMAIL || env.FCM_SERVICE_ACCOUNT_EMAIL)) {
        try {
            document = await getFirestoreAdminDocument(env, `users/${encodeURIComponent(uid)}`);
        } catch (eAdmin) {
            // Abaikan jika service account belum siap
        }
    }

    if (!document) return {};
    const profile = decodeFirestoreFields(document.fields || {});

    // Profil guru/staf menyimpan phone dan telegramChatId di D1 gtk / teachers (SSOT).
    if (profile.linkedTeacherId && env && env.DB) {
        try {
            const teacherRow = await env.DB.prepare(
                "SELECT name, phone, telegram_chat_id AS telegramChatId FROM gtk WHERE id = ? OR nik = ? LIMIT 1"
            ).bind(profile.linkedTeacherId, profile.linkedTeacherId).first();
            if (teacherRow) {
                profile.name = teacherRow.name || profile.name;
                profile.phone = teacherRow.phone || profile.phone;
                profile.telegramChatId = teacherRow.telegramChatId || profile.telegramChatId;
            }
        } catch (eGtk) {
            console.warn("[Worker] Gagal query kontak GTK dari D1 di loadOwnFirebaseProfile:", eGtk.message);
        }
    } else if (!profile.linkedTeacherId && env && env.DB) {
        // Auto-resolve GTK dari D1 jika linkedTeacherId belum terpasang di Firestore users
        try {
            const userEmail = (profile.email || "").toLowerCase().trim();
            const userNik = (profile.nik || "").trim();
            const userNip = (profile.nip || "").trim();
            const userName = (profile.name || "").trim().toLowerCase();

            let matchedTeacher = null;
            if (userEmail) {
                matchedTeacher = await env.DB.prepare(
                    "SELECT id, nik, nip, name, phone, telegram_chat_id AS telegramChatId FROM gtk WHERE lower(email) = ? LIMIT 1"
                ).bind(userEmail).first();
            }
            if (!matchedTeacher && userNik && userNik !== '-') {
                matchedTeacher = await env.DB.prepare(
                    "SELECT id, nik, nip, name, phone, telegram_chat_id AS telegramChatId FROM gtk WHERE nik = ? LIMIT 1"
                ).bind(userNik).first();
            }
            if (!matchedTeacher && userNip && userNip !== '-') {
                matchedTeacher = await env.DB.prepare(
                    "SELECT id, nik, nip, name, phone, telegram_chat_id AS telegramChatId FROM gtk WHERE nip = ? LIMIT 1"
                ).bind(userNip).first();
            }
            if (!matchedTeacher && userName) {
                matchedTeacher = await env.DB.prepare(
                    "SELECT id, nik, nip, name, phone, telegram_chat_id AS telegramChatId FROM gtk WHERE lower(name) = ? LIMIT 1"
                ).bind(userName).first();
            }

            if (matchedTeacher) {
                profile.linkedTeacherId = matchedTeacher.id;
                if (!profile.nik && matchedTeacher.nik) profile.nik = matchedTeacher.nik;
                if (!profile.nip && matchedTeacher.nip) profile.nip = matchedTeacher.nip;
                if (!profile.phone && matchedTeacher.phone) profile.phone = matchedTeacher.phone;
                if (!profile.telegramChatId && matchedTeacher.telegramChatId) profile.telegramChatId = matchedTeacher.telegramChatId;
                if (!profile.name && matchedTeacher.name) profile.name = matchedTeacher.name;
            }
        } catch (eResolve) {
            console.warn("[Worker] Gagal auto-resolve linkedTeacherId dari D1 di loadOwnFirebaseProfile:", eResolve.message);
        }
    }
    return profile;
}

async function verifyFirebaseToken(request, env = null) {
    const authHeader = request.headers.get("Authorization") || "";
    if (!authHeader.startsWith("Bearer ")) {
        return { valid: false, error: "Missing or invalid Authorization header" };
    }

    const token = authHeader.substring(7).trim();
    if (!token) return { valid: false, error: "Empty Bearer token" };

    try {
        const parts = token.split(".");
        if (parts.length !== 3) {
            return { valid: false, error: "Malformed JWT token structure" };
        }

        const [headerB64, payloadB64, signatureB64] = parts;
        const header = parseJwtPart(headerB64);
        const payload = parseJwtPart(payloadB64);

        if (header.alg !== "RS256") {
            return { valid: false, error: `Unsupported JWT algorithm: ${header.alg}` };
        }

        if (!header.kid) {
            return { valid: false, error: "Missing Key ID (kid) in token header" };
        }

        // 1. Validasi Standard Claims Firebase
        const expectedIssuer = `https://securetoken.google.com/${FIREBASE_PROJECT_ID}`;
        if (payload.iss !== expectedIssuer) {
            return { valid: false, error: "Invalid token issuer" };
        }

        if (payload.aud !== FIREBASE_PROJECT_ID) {
            return { valid: false, error: "Invalid token audience" };
        }

        const now = Math.floor(Date.now() / 1000);
        // Toleransi clock-skew 300 detik
        if (payload.exp && payload.exp < (now - 300)) {
            return { valid: false, error: "Token expired" };
        }

        if (payload.iat && payload.iat > (now + 300)) {
            return { valid: false, error: "Token issued in the future" };
        }

        if (payload.auth_time && payload.auth_time > (now + 300)) {
            return { valid: false, error: "Token auth_time is in the future" };
        }

        const uid = payload.user_id || payload.sub;
        if (!uid || typeof uid !== "string") {
            return { valid: false, error: "Missing user_id / subject claim" };
        }

        // 2. Verifikasi Kriptografis Tanda Tangan RS256 via Web Crypto Subtle API
        const jwks = await getGoogleJwks();
        const matchedKey = jwks.find(k => k.kid === header.kid);
        if (!matchedKey) {
            return { valid: false, error: `Public key with kid '${header.kid}' not found in Google JWKS` };
        }

        const cryptoKey = await crypto.subtle.importKey(
            "jwk",
            matchedKey,
            { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
            false,
            ["verify"]
        );

        const signatureBytes = base64UrlToUint8Array(signatureB64);
        const signedDataBytes = new TextEncoder().encode(`${headerB64}.${payloadB64}`);

        const isValid = await crypto.subtle.verify(
            "RSASSA-PKCS1-v1_5",
            cryptoKey,
            signatureBytes,
            signedDataBytes
        );

        if (!isValid) {
            return { valid: false, error: "Invalid cryptographic signature" };
        }

        const isAnonymous = payload.firebase && payload.firebase.sign_in_provider === "anonymous";
        let profile = {};
        if (!isAnonymous) {
            try {
                profile = await loadOwnFirebaseProfile(token, uid, env);
            } catch (profileError) {
                console.warn("[Auth] Profil server tidak dapat dimuat:", profileError.message);
            }
        }

        const email = payload.email || profile.email || "";
        const role = String(payload.role || payload.user_role || profile.role || "").toLowerCase().trim();
        const rawAdditionalRoles = Array.isArray(payload.additionalRoles)
            ? payload.additionalRoles
            : (Array.isArray(profile.additionalRoles) ? profile.additionalRoles : []);
        const additionalRoles = rawAdditionalRoles.map(roleName => String(roleName).toLowerCase().trim()).filter(Boolean);

        const linkedTeacherId = profile.linkedTeacherId || payload.linkedTeacherId || "";

        return {
            valid: true,
            user: {
                uid,
                email,
                role,
                additionalRoles,
                linkedTeacherId,
                profile,
                assignedClass: profile.assignedClass || profile.class || "",
                displayName: profile.name || payload.name || email,
                phone: profile.phone || "",
                telegramChatId: profile.telegramChatId || "",
                isAnonymous,
                claims: payload
            }
        };
    } catch (err) {
        return { valid: false, error: "Cryptographic JWT verification failed: " + err.message };
    }
}

/**
 * Helper: Autentikasi token JWT Firebase dan mengembalikan objek user profil
 * @param {Request} request - HTTP Request dengan header Authorization Bearer token
 * @param {object} env - Cloudflare Worker Environment (opsional)
 * @returns {Promise<object|null>} Objek user jika valid, atau null jika tidak valid
 */
async function verifyAuthToken(request, env = null) {
    const authResult = await verifyFirebaseToken(request, env);
    if (!authResult || !authResult.valid || !authResult.user) return null;
    return {
        ...authResult.user,
        name: authResult.user.displayName || authResult.user.email || "Pengguna"
    };
}

// Helper RBAC: Cek apakah user memiliki peran manajerial / manajer agenda
function isManager(user) {
    if (!user) return false;
    const allRoles = [user.role, ...(user.additionalRoles || [])].filter(Boolean);
    return allRoles.some(r => MANAGER_ROLES.includes(r));
}

