                const canUpload = isManager(authResult.user) || hasAnyUserRole(authResult.user, ['wakasek_kurikulum', 'kurikulum']);
                if (!canUpload) {
                    return errorResponse("Forbidden: Insufficient privileges to upload documents", 403, request);
                }

                const body = await request.json();
                const { id, title, category, drive_url, file_type, uploader_name, description, is_archived } = body;

