            async function ensureWorkloadActivityCatalog(db) {
                if (!db || _workloadCatalogSeeded) return;
                try {
                    // Cek apakah ada entri lama yang masih mengandung 'Tugas Tambahan: ' atau nama upacara lama
                    const needsNameFix = await db.prepare("SELECT 1 FROM activity_catalog WHERE name LIKE 'Tugas Tambahan:%' OR name = 'Upacara Bendera / Apel Pagi (Hari Senin)' LIMIT 1").first();
                    const hasSpecificWaka = await db.prepare("SELECT 1 FROM activity_catalog WHERE id = 'cat_tt_waka_kurikulum' LIMIT 1").first();
                    const hasCutiIzin = await db.prepare("SELECT 1 FROM activity_catalog WHERE id = 'cat_cuti_izin' LIMIT 1").first();

                    const check = await db.prepare("SELECT count(*) as cnt FROM activity_catalog LIMIT 1").first();
                    const existingCnt = check ? (check.cnt ?? check['count(*)'] ?? 0) : 0;
                    if (existingCnt >= 30 && !needsNameFix && hasSpecificWaka && hasCutiIzin) {
                        _workloadCatalogSeeded = true;
                        return;
                    }

                    const stmts = STANDARD_WORKLOAD_CATALOG.map(c => db.prepare(`
                        INSERT INTO activity_catalog (
                            id, code, category_code, category_name, name, description,
                            default_duration_minutes, is_teaching, requires_evidence, sort_order, is_active, created_at
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
                        ON CONFLICT(id) DO UPDATE SET
                            code = excluded.code,
                            category_code = excluded.category_code,
                            category_name = excluded.category_name,
                            name = excluded.name,
                            description = excluded.description,
                            default_duration_minutes = excluded.default_duration_minutes,
                            is_teaching = excluded.is_teaching,
                            requires_evidence = excluded.requires_evidence,
                            sort_order = excluded.sort_order,
                            is_active = excluded.is_active
                    `).bind(
                        c.id, c.code, c.category_code, c.category_name, c.name, c.description,
                        c.default_duration_minutes, c.is_teaching, c.requires_evidence, c.sort_order, c.is_active
                    ));

                    // Bersihkan prefix 'Tugas Tambahan: ', nonaktifkan cat_tt_waka umum, dan perbarui nama upacara di D1
                    stmts.push(db.prepare("UPDATE activity_catalog SET name = SUBSTR(name, 17) WHERE name LIKE 'Tugas Tambahan: %'"));
                    stmts.push(db.prepare("UPDATE activity_catalog SET is_active = 0 WHERE id = 'cat_tt_waka'"));
                    stmts.push(db.prepare("UPDATE activity_catalog SET name = 'Upacara Bendera / Apel Pagi (selain Senin)', description = 'Mengikuti upacara bendera hari besar nasional/peringatan khusus atau apel pagi pembinaan karakter bersama seluruh siswa dan guru di luar hari Senin' WHERE id = 'cat_upacara' OR name = 'Upacara Bendera / Apel Pagi (Hari Senin)'"));

                    await db.batch(stmts);
                    _workloadCatalogSeeded = true;
                } catch (e) {
                    console.warn("[Workload] Gagal auto-ensure activity_catalog:", e.message);
                }
            }

