            async function ensureWakaDutyItems(db) {
                if (!db || _wakaDutiesSeeded) return;
                try {
                    await db.prepare(`
                        CREATE TABLE IF NOT EXISTS waka_duty_items (
                            id TEXT PRIMARY KEY,
                            waka_type TEXT NOT NULL,
                            duty_number INTEGER NOT NULL,
                            duty_title TEXT NOT NULL,
                            duty_description TEXT,
                            is_active INTEGER NOT NULL DEFAULT 1,
                            created_at TEXT DEFAULT (datetime('now')),
                            updated_at TEXT DEFAULT (datetime('now'))
                        )
                    `).run();

                    await db.prepare(`CREATE INDEX IF NOT EXISTS idx_waka_duty_items_type ON waka_duty_items(waka_type, duty_number)`).run();

                    const countRow = await db.prepare("SELECT count(*) as cnt FROM waka_duty_items LIMIT 1").first();
                    const cnt = countRow ? (countRow.cnt ?? countRow['count(*)'] ?? 0) : 0;
                    // Seed hanya saat tabel masih kosong; jika sudah berisi, data hasil kelola
                    // (edit, nonaktif, hapus) tidak boleh ditimpa atau dihidupkan kembali.
                    if (cnt > 0) {
                        _wakaDutiesSeeded = true;
                        return;
                    }

                    const insertStmt = db.prepare(`
                        INSERT INTO waka_duty_items (id, waka_type, duty_number, duty_title, duty_description, is_active, created_at, updated_at)
                        VALUES (?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))
                        ON CONFLICT(id) DO NOTHING
                    `);
                    const batch = WAKA_DUTIES_INITIAL_SEED.map(item => insertStmt.bind(
                        item.id, item.waka_type, item.duty_number, item.duty_title, item.duty_description || '', item.is_active ?? 1
                    ));
                    await db.batch(batch);
                    _wakaDutiesSeeded = true;
                } catch (e) {
                    console.warn("[Workload] Gagal auto-ensure waka_duty_items:", e.message);
                }
            }

            async function resolveWorkloadTeacherId(db, user, requestedTeacherId = null) {
                if (!db || !user) return requestedTeacherId || user?.uid || "";
                const isMgr = isWorkloadManager(user);
                let targetId = (isMgr && requestedTeacherId) ? requestedTeacherId : (user.linkedTeacherId || user.uid);
                if (!targetId) targetId = user.uid;

                try {
                    // 1. Coba cocokkan langsung ke gtk.id
                    const exact = await db.prepare("SELECT id FROM gtk WHERE id = ? LIMIT 1").bind(targetId).first();
                    if (exact && exact.id) return exact.id;

                    // 2. Jika user punya linkedTeacherId, periksa apakah cocok dengan id, nik, atau nip di gtk
                    if (user.linkedTeacherId && user.linkedTeacherId !== targetId) {
                        const byLinked = await db.prepare("SELECT id FROM gtk WHERE id = ? OR nik = ? OR nip = ? LIMIT 1").bind(user.linkedTeacherId, user.linkedTeacherId, user.linkedTeacherId).first();
                        if (byLinked && byLinked.id) return byLinked.id;
                    }

                    // 3. Cek berdasarkan NIK, NIP, atau Email user di tabel gtk
                    const userNik = user.profile?.nik || user.claims?.nik || "___";
                    const userNip = user.profile?.nip || user.claims?.nip || "___";
                    const userEmail = (user.email || user.profile?.email || "").toLowerCase().trim();

                    const byProfile = await db.prepare(`
                        SELECT id FROM gtk 
                        WHERE id = ? OR nik = ? OR nip = ? OR (LOWER(email) = ? AND email != '')
                        LIMIT 1
                    `).bind(user.uid, userNik, userNip, userEmail).first();
                    if (byProfile && byProfile.id) return byProfile.id;
                } catch (e) {
                    console.warn("[Workload] Gagal query resolusi GTK:", e.message);
                }

                return targetId;
            }

            function isWorkloadSuperAdmin(user) {
                if (!user) return false;
                const role = String(user.role || "").toLowerCase().trim();
                const addRoles = Array.isArray(user.additionalRoles) ? user.additionalRoles.map(r => String(r).toLowerCase().trim()) : [];
                return role === "super_admin" || role === "admin" ||
                    addRoles.includes("super_admin") || addRoles.includes("admin");
            }

            function isWorkloadManager(user) {
                if (!user) return false;
                const role = String(user.role || "").toLowerCase().trim();
                const addRoles = Array.isArray(user.additionalRoles) ? user.additionalRoles.map(r => String(r).toLowerCase().trim()) : [];
                return role === "kepala_sekolah" || role === "super_admin" ||
                    addRoles.includes("kepala_sekolah") || addRoles.includes("super_admin");
            }

            function isWorkloadSupervisor(user) {
                if (!user) return false;
                const role = String(user.role || "").toLowerCase().trim();
                const addRoles = Array.isArray(user.additionalRoles) ? user.additionalRoles.map(r => String(r).toLowerCase().trim()) : [];
                return isWorkloadManager(user) || role === "wakasek_kurikulum" || addRoles.includes("wakasek_kurikulum");
            }

            function isWorkloadOwner(targetTeacherId, user, resolvedTeacherId = null) {
                if (!targetTeacherId || !user) return false;
                const cleanTarget = String(targetTeacherId).trim();
                if (resolvedTeacherId && cleanTarget === String(resolvedTeacherId).trim()) return true;
                if (user.uid && cleanTarget === String(user.uid).trim()) return true;
                if (user.linkedTeacherId && cleanTarget === String(user.linkedTeacherId).trim()) return true;
                if (user.profile?.linkedTeacherId && cleanTarget === String(user.profile.linkedTeacherId).trim()) return true;
                return false;
            }

            async function checkWorkloadReviewerAuth(db, user, targetTeacherId = null, targetTeacherUid = null) {
                if (!user) return { allowed: false, reason: "Tidak terautentikasi" };
                const reviewerUid = user.uid;
                const reviewerTeacherId = user.linkedTeacherId || "";

                // Anti Self-Approval: Reviewer dilarang menyetujui atau memverifikasi pekerjaannya sendiri
                if (targetTeacherUid && reviewerUid === targetTeacherUid) {
                    return { allowed: false, selfApproval: true, reason: "Reviewer dilarang menyetujui atau memverifikasi pekerjaan diri sendiri (Anti Self-Approval)" };
                }
                if (targetTeacherId && reviewerTeacherId && reviewerTeacherId === targetTeacherId) {
                    return { allowed: false, selfApproval: true, reason: "Reviewer dilarang menyetujui atau memverifikasi pekerjaan diri sendiri (Anti Self-Approval)" };
                }

                if (isWorkloadSupervisor(user)) {
                    return { allowed: true, role: user.role, isDelegate: false };
                }

                // Cek pendelegasian wewenang yang sah di D1
                try {
                    const todayDate = new Date(Date.now() + 8 * 3600 * 1000).toISOString().slice(0, 10);
                    const delegation = await db.prepare(`
                        SELECT * FROM workload_delegations
                        WHERE delegatee_uid = ? AND status = 'active'
                        AND ? >= valid_from AND ? <= valid_until
                        LIMIT 1
                    `).bind(reviewerUid, todayDate, todayDate).first();

                    if (delegation) {
                        return { allowed: true, role: "delegated_reviewer", isDelegate: true, delegationId: delegation.id };
                    }
                } catch (e) {
                    console.warn("[WorkloadAuth] Gagal memeriksa delegasi:", e.message);
                }

                return { allowed: false, reason: "Akses ditolak: Hanya Kepala Sekolah atau Pejabat yang Didelegasikan sah yang berwenang" };
            }

            async function getWorkloadPolicyConfig(db) {
                let cfg = { require_plan_approval: 1, require_log_verification: 1, vip_teacher_ids: [] };
                try {
                    const row = await db.prepare("SELECT value FROM system_settings WHERE key = 'workload_policy_config'").first();
                    if (row && row.value) {
                        const parsed = typeof row.value === 'string' ? JSON.parse(row.value) : row.value;
                        if (parsed.require_plan_approval !== undefined) cfg.require_plan_approval = Number(parsed.require_plan_approval) ? 1 : 0;
                        if (parsed.require_log_verification !== undefined) cfg.require_log_verification = Number(parsed.require_log_verification) ? 1 : 0;
                        if (Array.isArray(parsed.vip_teacher_ids)) cfg.vip_teacher_ids = parsed.vip_teacher_ids.map(String);
                    }
                } catch (_) {}
                return cfg;
            }

            function parseTimeToMinutesWl(timeStr) {
                if (!timeStr || typeof timeStr !== "string") return 0;
                const parts = timeStr.trim().split(":");
                const h = parseInt(parts[0], 10) || 0;
                const m = parseInt(parts[1], 10) || 0;
                return h * 60 + m;
            }

            function calculateEffectiveMinutesWl(startTime, endTime, breaks = WORKLOAD_OFFICIAL_BREAKS) {
                const s = parseTimeToMinutesWl(startTime);
                const e = parseTimeToMinutesWl(endTime);
                if (e <= s) return 0;
                const gross = e - s;
                let breakDeduction = 0;
                for (const b of breaks) {
                    const bs = parseTimeToMinutesWl(b.start);
                    const be = parseTimeToMinutesWl(b.end);
                    const overlapStart = Math.max(s, bs);
                    const overlapEnd = Math.min(e, be);
                    if (overlapEnd > overlapStart) {
                        breakDeduction += (overlapEnd - overlapStart);
                    }
                }
                return Math.max(0, gross - breakDeduction);
            }

            function validateSegmentsNoOverlapWl(segments) {
                if (!Array.isArray(segments) || segments.length <= 1) return { valid: true };
                for (let i = 0; i < segments.length; i++) {
                    const s1 = parseTimeToMinutesWl(segments[i].start_time);
                    const e1 = parseTimeToMinutesWl(segments[i].end_time);
                    for (let j = i + 1; j < segments.length; j++) {
                        const s2 = parseTimeToMinutesWl(segments[j].start_time);
                        const e2 = parseTimeToMinutesWl(segments[j].end_time);
                        if (Math.max(s1, s2) < Math.min(e1, e2)) {
                            return {
                                valid: false,
                                conflict: [segments[i], segments[j]],
                                message: `Benturan jam kerja terdeteksi: ${segments[i].start_time}-${segments[i].end_time} bertumpuk dengan ${segments[j].start_time}-${segments[j].end_time}`
                            };
                        }
                    }
                }
                return { valid: true };
            }

            async function performDeduplicatePlanWl(db, plan_version_id, work_week_id, options = {}) {
                if (!plan_version_id) return { removedCount: 0, newTotal: 0 };

                // Ambil seluruh segmen pada versi ini beserta data keterkaitan log
                const segsRes = await db.prepare(`
                    SELECT pts.*, pa.title, pa.origin_source, pa.catalog_id,
                        (SELECT COUNT(*) FROM plan_log_links pll WHERE pll.plan_activity_id = pa.id) AS has_log
                    FROM plan_time_segments pts
                    JOIN plan_activities pa ON pts.activity_id = pa.id
                    WHERE pts.plan_version_id = ?
                    ORDER BY pts.date ASC, pts.start_time ASC
                `).bind(plan_version_id).all();
                const allSegs = segsRes?.results || [];
                if (allSegs.length === 0) return { removedCount: 0, newTotal: 0 };

                // Deteksi tanggal hari libur resmi pada rentang tanggal segmen
                const holidayDatesSet = new Set();
                if (Array.isArray(options.holiday_dates)) {
                    options.holiday_dates.forEach(d => {
                        if (typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d.trim())) {
                            holidayDatesSet.add(d.trim());
                        }
                    });
                }
                const minDate = allSegs[0]?.date;
                const maxDate = allSegs[allSegs.length - 1]?.date;
                if (minDate && maxDate) {
                    try {
                        const calHols = await db.prepare(`
                            SELECT date, time FROM calendar_events
                            WHERE (category = 'libur' OR color = 'rose' OR LOWER(title) LIKE '%libur%')
                              AND (date <= ? AND (time >= ? OR date >= ?))
                        `).bind(maxDate, minDate, minDate).all();
                        for (const ch of (calHols.results || [])) {
                            const s = (ch.date || "").substring(0, 10);
                            let e = (ch.time && /^\d{4}-\d{2}-\d{2}$/.test(ch.time)) ? ch.time : s;
                            if (e < s) e = s;
                            for (let cur = new Date(s); cur.toISOString().slice(0, 10) <= e; cur.setDate(cur.getDate() + 1)) {
                                const curStr = cur.toISOString().slice(0, 10);
                                if (curStr >= minDate && curStr <= maxDate) {
                                    holidayDatesSet.add(curStr);
                                }
                            }
                        }
                    } catch (e) {
                        console.warn("[performDeduplicatePlanWl] Gagal query calendar_events:", e.message);
                    }
                }

                const idsToDelete = new Set();
                let removedCount = 0;

                // 1. Bersihkan kegiatan rencana draf tanpa log yang bertengger di hari libur resmi
                if (holidayDatesSet.size > 0) {
                    for (const s of allSegs) {
                        const isLeaveSeg = s.is_leave === 1 || s.catalog_id === 'cat_cuti_izin';
                        const isHolidaySeg = s.catalog_id === 'cat_libur';
                        if (holidayDatesSet.has(s.date) && s.has_log === 0 && !isLeaveSeg && !isHolidaySeg) {
                            idsToDelete.add(s.id);
                            removedCount++;
                        }
                    }
                }

                // Kelompokkan per tanggal
                const segsByDate = {};
                allSegs.forEach(s => {
                    if (idsToDelete.has(s.id)) return;
                    if (!segsByDate[s.date]) segsByDate[s.date] = [];
                    segsByDate[s.date].push(s);
                });

                for (const d in segsByDate) {
                    const dayList = segsByDate[d];
                    for (let i = 0; i < dayList.length; i++) {
                        if (idsToDelete.has(dayList[i].id)) continue;
                        for (let j = i + 1; j < dayList.length; j++) {
                            if (idsToDelete.has(dayList[j].id)) continue;
                            const a = dayList[i];
                            const b = dayList[j];

                            // Cek benturan waktu (start_time < b.end_time AND b.start_time < a.end_time)
                            if (a.start_time < b.end_time && b.start_time < a.end_time) {
                                // Tentukan kandidat yang akan dihapus:
                                // Prioritas 1: Yang TIDAK punya log dihapus jika lawannya punya log
                                let victim = b;
                                if (a.has_log === 0 && b.has_log > 0) {
                                    victim = a;
                                } else if (a.has_log > 0 && b.has_log === 0) {
                                    victim = b;
                                } else {
                                    // Prioritas 2: Jadwal resmi KBM (schedule_import) diutamakan dibandingkan template/manual generik
                                    if (a.origin_source === "schedule_import" && b.origin_source !== "schedule_import") {
                                        victim = b;
                                    } else if (b.origin_source === "schedule_import" && a.origin_source !== "schedule_import") {
                                        victim = a;
                                    } else {
                                        victim = b;
                                    }
                                }
                                idsToDelete.add(victim.id);
                                removedCount++;
                            }
                        }
                    }
                }

                if (idsToDelete.size > 0) {
                    for (const segId of idsToDelete) {
                        const segRow = await db.prepare("SELECT activity_id FROM plan_time_segments WHERE id = ?").bind(segId).first();
                        await db.prepare("DELETE FROM plan_time_segments WHERE id = ? AND plan_version_id = ?").bind(segId, plan_version_id).run();
                        if (segRow?.activity_id) {
                            const rem = await db.prepare("SELECT COUNT(*) AS c FROM plan_time_segments WHERE activity_id = ?").bind(segRow.activity_id).first();
                            if (!rem || rem.c === 0) {
                                await db.prepare("DELETE FROM plan_activities WHERE id = ?").bind(segRow.activity_id).run();
                            }
                        }
                    }
                }

                // Hitung ulang total menit
                const sumRes = await db.prepare("SELECT SUM(planned_minutes) AS total FROM plan_time_segments WHERE plan_version_id = ?").bind(plan_version_id).first();
                const newTotal = sumRes?.total || 0;
                await db.prepare("UPDATE weekly_plan_versions SET total_planned_minutes = ?, updated_at = datetime('now') WHERE id = ?").bind(newTotal, plan_version_id).run();

                return { removedCount, newTotal };
            }

            function sanitizeWorkloadCsvCell(val) {
                if (val === null || val === undefined) return '""';
                let s = String(val);
                if (/^[=+\-@\t\r]/.test(s)) {
                    s = "'" + s;
                }
                return '"' + s.replace(/"/g, '""') + '"';
            }

            async function recordWorkloadAuditLog(db, entityType, entityId, action, actorUid, actorName, details = null) {
                try {
                    const actStr = String(action || 'UNKNOWN').trim();
                    const fullAction = actStr.startsWith('WORKLOAD_') ? actStr : `WORKLOAD_${actStr}`;
                    const detailStr = typeof details === "object" && details !== null 
                        ? JSON.stringify(details) 
                        : (details ? String(details) : null);
                    await recordAuditLog(env, {
                        action: fullAction,
                        target_id: `${entityType || 'workload'}:${entityId || ''}`,
                        actor_uid: actorUid || "system",
                        actor_name: actorName || "Sistem",
                        details: detailStr
                    });
                } catch (e) {
                    console.warn("[WorkloadAudit] Gagal mencatat audit log ke Supabase:", e.message);
                }
            }

            function matchPlanSegmentWithJournal(segments, journal) {
                if (!Array.isArray(segments) || segments.length === 0 || !journal) return null;

                const cleanStr = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                const normJournalClass = cleanStr(journal.kelas);
                const normJournalMapel = cleanStr(journal.mapel);

                let bestSegment = null;
                let highestScore = 0;

                for (const seg of segments) {
                    const segTitle = cleanStr(seg.activity_title || seg.title || '');
                    const segDesc = cleanStr(seg.description || '');
                    const segText = segTitle + ' ' + segDesc;
                    const normSegMapel = cleanStr(seg.mapel || '');
                    const normSegClass = cleanStr(seg.className || '');

                    // 1. Cek kecocokan mapel (syarat utama: mapel harus cocok)
                    const hasMapelMatch = normJournalMapel && (
                        segText.includes(normJournalMapel) ||
                        (normSegMapel && (normJournalMapel.includes(normSegMapel) || normSegMapel.includes(normJournalMapel)))
                    );
                    if (!hasMapelMatch) {
                        continue;
                    }

                    let score = 40;

                    // 2. Cek kecocokan kelas
                    const hasClassMatch = normJournalClass && (
                        segText.includes(normJournalClass) ||
                        (normSegClass && (normJournalClass.includes(normSegClass) || normSegClass.includes(normJournalClass)))
                    );
                    if (hasClassMatch) {
                        score += 40;
                    }

                    // 3. Tambahan jika flag is_teaching atau category_code KBM
                    if (seg.is_teaching || seg.category_code === 'PELAKSANAAN_KBM' || seg.catalog_id === 'cat_kbm') {
                        score += 10;
                    }

                    // 4. Jika JP diberikan dan cocok
                    if (journal.jp && seg.jp_count) {
                        let journalJpCount = 0;
                        if (Array.isArray(journal.jp)) {
                            journalJpCount = journal.jp.length;
                        } else if (typeof journal.jp === 'string') {
                            try {
                                const parsed = JSON.parse(journal.jp);
                                if (Array.isArray(parsed)) journalJpCount = parsed.length;
                                else journalJpCount = 1;
                            } catch {
                                if (journal.jp.includes('-')) {
                                    const parts = journal.jp.split('-');
                                    journalJpCount = Math.abs(parseInt(parts[1], 10) - parseInt(parts[0], 10)) + 1;
                                } else {
                                    journalJpCount = 1;
                                }
                            }
                        }
                        if (journalJpCount === seg.jp_count) {
                            score += 10;
                        }
                    }

                    if (score > highestScore) {
                        highestScore = score;
                        bestSegment = seg;
                    }
                }

                if (highestScore >= 50 && bestSegment) {
                    return { segment: bestSegment, score: highestScore };
                }

                return null;
            }

            async function syncJournalToWorkload(db, journalRow, actorUser = null) {
                if (!db || !journalRow || !journalRow.id || !journalRow.tanggal) {
                    return { success: false, reason: "Data jurnal tidak lengkap" };
                }

                try {
                    await ensureWorkloadActivityCatalog(db);

                    // 1. Tentukan teacher_id dari data jurnal (SSOT: guru pengajar KBM)
                    let teacherId = null;
                    if (journalRow.uid_guru) {
                        const g = await db.prepare("SELECT id FROM gtk WHERE id = ? OR nik = ? OR nip = ? LIMIT 1").bind(journalRow.uid_guru, journalRow.uid_guru, journalRow.uid_guru).first();
                        if (g && g.id) teacherId = g.id;
                    }
                    if (!teacherId && journalRow.guru) {
                        const g = await db.prepare("SELECT id FROM gtk WHERE name = ? OR name LIKE ? LIMIT 1").bind(journalRow.guru, `%${journalRow.guru}%`).first();
                        if (g && g.id) teacherId = g.id;
                    }
                    if (!teacherId && journalRow.uid_guru) {
                        teacherId = journalRow.uid_guru;
                    }
                    if (!teacherId && actorUser) {
                        teacherId = await resolveWorkloadTeacherId(db, actorUser);
                    }
                    if (!teacherId) {
                        teacherId = journalRow.guru || "";
                    }

                    // 2. Cari minggu kerja (work_weeks) guru yang mencakup tanggal jurnal
                    const targetDate = journalRow.tanggal;
                    let week = await db.prepare(`
                        SELECT * FROM work_weeks
                        WHERE teacher_id = ? AND ? >= week_start_date AND ? <= week_end_date
                        LIMIT 1
                    `).bind(teacherId, targetDate, targetDate).first();

                    if (!week && journalRow.uid_guru && journalRow.uid_guru !== teacherId) {
                        week = await db.prepare(`
                            SELECT * FROM work_weeks
                            WHERE teacher_id = ? AND ? >= week_start_date AND ? <= week_end_date
                            LIMIT 1
                        `).bind(journalRow.uid_guru, targetDate, targetDate).first();
                    }

                    if (!week) {
                        return {
                            success: true,
                            matched: false,
                            ignored: true,
                            reason: `Tidak ada minggu kerja (work_weeks) guru untuk tanggal ${targetDate}`
                        };
                    }

                    if (week.is_locked === 1) {
                        return {
                            success: false,
                            matched: false,
                            ignored: true,
                            reason: "Minggu kerja telah dikunci oleh pimpinan"
                        };
                    }

                    // Proteksi Gerbang Realisasi: Rencana kerja mingguan wajib berstatus 'approved' sebelum sinkronisasi
                    const latestPlanVersion = await db.prepare(`
                        SELECT status FROM weekly_plan_versions 
                        WHERE work_week_id = ? 
                        ORDER BY version_number DESC 
                        LIMIT 1
                    `).bind(week.id).first();

                    if (!latestPlanVersion || latestPlanVersion.status !== "approved") {
                        return {
                            success: false,
                            matched: false,
                            ignored: true,
                            reason: "Rencana kerja mingguan belum disetujui atau difinalisasi oleh guru/pimpinan"
                        };
                    }

                    const actualTeacherId = week.teacher_id || teacherId;

                    // 3. Ambil segmen rencana pada tanggal tersebut untuk mencocokkan rencana KBM
                    const planSegmentsRes = await db.prepare(`
                        SELECT pts.*, pa.title AS activity_title, pa.category_code, pa.catalog_id
                        FROM plan_time_segments pts
                        JOIN plan_activities pa ON pts.activity_id = pa.id
                        WHERE pa.work_week_id = ?
                          AND pts.date = ?
                          AND (pts.is_teaching = 1 OR pa.category_code = 'PELAKSANAAN_KBM' OR pa.catalog_id = 'cat_kbm')
                          ${String(journalRow.id).startsWith('lmsj_') ? "AND pa.is_cancelled = 0 AND pts.plan_version_id = (SELECT id FROM weekly_plan_versions WHERE work_week_id = pa.work_week_id ORDER BY version_number DESC LIMIT 1)" : ''}
                        ORDER BY pts.start_time ASC
                    `).bind(week.id, targetDate).all();

                    const candidateSegments = planSegmentsRes.results || [];
                    if (candidateSegments.length === 0) {
                        return {
                            success: true,
                            matched: false,
                            ignored: true,
                            reason: `Tidak ada rencana kegiatan KBM pada tanggal ${targetDate}`
                        };
                    }

                    // 4. Logika Pencocokan Jurnal ke Rencana KBM (matching algorithm)
                    const lmsMatch = await resolveLmsJournalPlanSegment(db, journalRow, candidateSegments);
                    const matchResult = lmsMatch || matchPlanSegmentWithJournal(candidateSegments, journalRow);
                    if (!matchResult || !matchResult.segment) {
                        return {
                            success: true,
                            matched: false,
                            ignored: true,
                            reason: lmsMatch?.reason || "Tidak ada rencana KBM yang cocok dengan kelas dan mata pelajaran jurnal ini"
                        };
                    }

                    const matchedSegment = matchResult.segment;
                    const matchedActivityId = matchedSegment.activity_id;

                    // 5. Simpan / perbarui work_logs dengan ID deterministik & idempotent: wl_jurnal_${id}
                    const logId = `wl_jurnal_${journalRow.id}`;

                    const existingLog = await db.prepare("SELECT is_locked, verification_status, verified_by_uid, output_summary, evidence_url, status_execution, obstacle_notes FROM work_logs WHERE id = ?").bind(logId).first();
                    if (existingLog && existingLog.is_locked === 1) {
                        return {
                            success: true,
                            matched: true,
                            log_id: logId,
                            ignored: true,
                            reason: "Laporan realisasi telah dikunci oleh pimpinan"
                        };
                    }
                    if (existingLog && existingLog.status_execution === "tidak_terlaksana" && /^\[(Sakit|Cuti|Izin)\]/i.test(existingLog.obstacle_notes || "")) {
                        return {
                            success: true,
                            matched: true,
                            log_id: logId,
                            already_synced: true,
                            ignored: true,
                            reason: "Hari ini tercatat Tidak Terlaksana (Sakit/Cuti/Izin)"
                        };
                    }

                    const policyCfg = await getWorkloadPolicyConfig(db);
                    const isManualVerified = existingLog &&
                                             existingLog.verification_status === "verified" &&
                                             existingLog.verified_by_uid &&
                                             existingLog.verified_by_uid !== "system_auto_policy" &&
                                             policyCfg.require_log_verification !== 0;
                    if (isManualVerified) {
                        return {
                            success: true,
                            matched: true,
                            log_id: logId,
                            ignored: true,
                            reason: "Laporan realisasi telah diverifikasi secara manual oleh Kepala Sekolah"
                        };
                    }

                    const isAutoVerified = policyCfg.require_log_verification === 0;
                    const defaultVerStatus = isAutoVerified ? 'verified' : 'unverified';

                    const actualMinutes = matchedSegment.planned_minutes || calculateEffectiveMinutesWl(matchedSegment.start_time, matchedSegment.end_time);

                    const summaryParts = [];
                    if (journalRow.topik) summaryParts.push(`Materi: ${journalRow.topik}`);
                    if (journalRow.catatan) summaryParts.push(`Refleksi: ${journalRow.catatan}`);
                    if (journalRow.lokasi_mengajar) summaryParts.push(`Ruang: ${journalRow.lokasi_mengajar}`);
                    const outputSummary = summaryParts.length > 0
                        ? summaryParts.join(' | ')
                        : `KBM ${journalRow.mapel} Kelas ${journalRow.kelas}`;

                    // Proteksi No-Op & Anti Thundering-Herd:
                    // Jika data realisasi KBM sudah ada di work_logs, berstatus 'terlaksana', isi materi dan foto identik,
                    // serta sudah tertaut ke rencana yang benar di plan_log_links:
                    // Langsung lewati penulisan ulang ke D1 & Supabase (0 writes, 0 lock contention).
                    if (existingLog &&
                        existingLog.status_execution === 'terlaksana' &&
                        existingLog.output_summary === outputSummary &&
                        (existingLog.evidence_url || '') === (journalRow.foto_url || '')) {
                        const existingLink = await db.prepare("SELECT 1 FROM plan_log_links WHERE work_log_id = ? AND plan_activity_id = ? LIMIT 1").bind(logId, matchedActivityId).first();
                        if (existingLink) {
                            return {
                                success: true,
                                matched: true,
                                log_id: logId,
                                already_synced: true,
                                reason: "Data realisasi KBM sudah mutakhir dan sinkron (no-op skip, 0 D1 write)"
                            };
                        }
                    }

                    const dayOfWeek = matchedSegment.day_of_week || (new Date(targetDate).getDay() || 7);
                    const logTitle = matchedSegment.activity_title || `KBM ${journalRow.mapel} (${journalRow.kelas})`;
                    const catalogId = matchedSegment.catalog_id || 'cat_kbm';

                    const syncBatch = [
                        db.prepare(`
                            INSERT INTO work_logs (
                                id, work_week_id, teacher_id, date, day_of_week, title,
                                catalog_id, is_unplanned, output_summary, evidence_url,
                                status_execution, obstacle_notes,
                                verification_status, is_locked, verified_at, verified_by_uid, created_at, updated_at
                            ) VALUES (
                                ?, ?, ?, ?, ?, ?,
                                ?, 0, ?, ?,
                                'terlaksana', NULL,
                                ?, 0, ${isAutoVerified ? "datetime('now')" : "NULL"}, ${isAutoVerified ? "'system_auto_policy'" : "NULL"},
                                datetime('now'), datetime('now')
                            )
                            ON CONFLICT(id) DO UPDATE SET
                                date = excluded.date,
                                day_of_week = excluded.day_of_week,
                                title = excluded.title,
                                catalog_id = excluded.catalog_id,
                                is_unplanned = 0,
                                output_summary = excluded.output_summary,
                                evidence_url = CASE WHEN excluded.evidence_url IS NOT NULL AND excluded.evidence_url != '' THEN excluded.evidence_url ELSE work_logs.evidence_url END,
                                status_execution = excluded.status_execution,
                                verification_status = CASE WHEN work_logs.verification_status = 'verified' THEN 'verified' ELSE excluded.verification_status END,
                                updated_at = datetime('now')
                        `).bind(
                            logId, week.id, actualTeacherId, targetDate,
                            Number(dayOfWeek), logTitle, catalogId,
                            outputSummary, journalRow.foto_url || '',
                            defaultVerStatus
                        ),
                        db.prepare("DELETE FROM work_log_segments WHERE work_log_id = ?").bind(logId),
                        db.prepare(`
                            INSERT INTO work_log_segments (id, work_log_id, start_time, end_time, actual_minutes, notes, created_at)
                            VALUES (?, ?, ?, ?, ?, ?, datetime('now'))
                        `).bind(
                            crypto.randomUUID(), logId, matchedSegment.start_time, matchedSegment.end_time,
                            actualMinutes, `Otomatis dari Jurnal Mengajar Kelas ${journalRow.kelas}`
                        ),
                        db.prepare("DELETE FROM plan_log_links WHERE work_log_id = ? AND plan_activity_id != ?").bind(logId, matchedActivityId),
                        db.prepare(`
                            INSERT INTO plan_log_links (id, plan_activity_id, work_log_id, link_type, reason_notes, created_at)
                            VALUES (?, ?, ?, 'fulfillment', 'Sinkron otomatis Jurnal KBM', datetime('now'))
                            ON CONFLICT(plan_activity_id, work_log_id) DO UPDATE SET
                                link_type = excluded.link_type,
                                reason_notes = excluded.reason_notes
                        `).bind(crypto.randomUUID(), matchedActivityId, logId)
                    ];

                    await db.batch(syncBatch);

                    // 8. Catat jejak audit (non-blocking jika gagal)
                    try {
                        await recordWorkloadAuditLog(
                            db, "work_log", logId, "SYNC_FROM_JOURNAL",
                            actorUser?.uid || "system", actorUser?.name || actorUser?.email || "Sistem Jurnal",
                            { journal_id: journalRow.id, plan_activity_id: matchedActivityId, mapel: journalRow.mapel, kelas: journalRow.kelas }
                        );
                    } catch (eAudit) {
                        console.warn("[syncJournalToWorkload] Audit log warning:", eAudit.message);
                    }

                    return {
                        success: true,
                        matched: true,
                        log_id: logId,
                        plan_activity_id: matchedActivityId,
                        actual_minutes: actualMinutes
                    };
                } catch (err) {
                    console.error("[syncJournalToWorkload] Error:", err);
                    return { success: false, error: err.message };
                }
            }

            async function syncMentoringToWorkload(db, noteData, actorUser = null) {
                if (!db || !noteData || !noteData.date) {
                    return { success: false, reason: "Data pembinaan tidak lengkap" };
                }

                try {
                    await ensureWorkloadActivityCatalog(db);

                    // 1. Tentukan teacher_id dari guru_uid
                    let teacherId = null;
                    if (noteData.guru_uid) {
                        const g = await db.prepare("SELECT id FROM gtk WHERE id = ? OR nik = ? OR nip = ? LIMIT 1").bind(noteData.guru_uid, noteData.guru_uid, noteData.guru_uid).first();
                        if (g && g.id) teacherId = g.id;
                    }
                    if (!teacherId && actorUser) {
                        teacherId = await resolveWorkloadTeacherId(db, actorUser);
                    }
                    if (!teacherId) {
                        teacherId = noteData.guru_uid || "";
                    }

                    // 2. Cari minggu kerja (work_weeks) guru yang mencakup tanggal pembinaan
                    const targetDate = noteData.date;
                    let week = await db.prepare(`
                        SELECT * FROM work_weeks
                        WHERE teacher_id = ? AND ? >= week_start_date AND ? <= week_end_date
                        LIMIT 1
                    `).bind(teacherId, targetDate, targetDate).first();

                    if (!week && noteData.guru_uid && noteData.guru_uid !== teacherId) {
                        week = await db.prepare(`
                            SELECT * FROM work_weeks
                            WHERE teacher_id = ? AND ? >= week_start_date AND ? <= week_end_date
                            LIMIT 1
                        `).bind(noteData.guru_uid, targetDate, targetDate).first();
                    }

                    if (!week) {
                        return {
                            success: true,
                            matched: false,
                            ignored: true,
                            reason: `Tidak ada minggu kerja (work_weeks) guru untuk tanggal ${targetDate}`
                        };
                    }

                    if (week.is_locked === 1) {
                        return {
                            success: false,
                            matched: false,
                            ignored: true,
                            reason: "Minggu kerja telah dikunci oleh pimpinan"
                        };
                    }

                    // 3. Rencana kerja mingguan wajib berstatus 'approved' sebelum sinkronisasi
                    const latestPlanVersion = await db.prepare(`
                        SELECT id, status FROM weekly_plan_versions 
                        WHERE work_week_id = ? 
                        ORDER BY version_number DESC 
                        LIMIT 1
                    `).bind(week.id).first();

                    if (!latestPlanVersion || latestPlanVersion.status !== "approved") {
                        return {
                            success: false,
                            matched: false,
                            ignored: true,
                            reason: "Rencana kerja mingguan belum disetujui atau difinalisasi oleh guru/pimpinan"
                        };
                    }

                    const actualTeacherId = week.teacher_id || teacherId;
                    const startTime = String(noteData.start_time || "08:00").trim();
                    const endTime = String(noteData.end_time || "08:45").trim();
                    const startMin = parseTimeToMinutesWl(startTime);
                    const endMin = parseTimeToMinutesWl(endTime);
                    const durationMinutes = Number(noteData.duration_minutes) || calculateEffectiveMinutesWl(startTime, endTime) || 45;

                    // Kategori tugas sesuai portal
                    const isWaliKelas = noteData.source_portal === 'wali_kelas';
                    const catalogId = isWaliKelas ? 'cat_wali_kelas' : 'cat_bimbing_guru_wali';
                    const logTitle = noteData.title
                        ? (isWaliKelas ? `Pembinaan Wali Kelas: ${noteData.title}` : `Pendampingan Guru Wali: ${noteData.title}`)
                        : (isWaliKelas ? `Pembinaan Siswa Wali Kelas (${noteData.student_class || ''})` : `Pendampingan Siswa Dampingan (${noteData.student_name || ''})`);

                    // 4. Ambil segmen rencana pada tanggal tersebut
                    const planSegmentsRes = await db.prepare(`
                        SELECT pts.*, pa.title AS activity_title, pa.category_code, pa.catalog_id
                        FROM plan_time_segments pts
                        JOIN plan_activities pa ON pts.activity_id = pa.id
                        WHERE pa.work_week_id = ?
                          AND pts.date = ?
                          AND pts.plan_version_id = ?
                          AND pa.is_cancelled = 0
                        ORDER BY pts.start_time ASC
                    `).bind(week.id, targetDate, latestPlanVersion.id).all();

                    const candidateSegments = planSegmentsRes.results || [];

                    // Deteksi bentrok dengan KBM jika ada
                    const kbmSegments = candidateSegments.filter(s => s.is_teaching === 1 || s.catalog_id === 'cat_kbm' || s.category_code === 'PELAKSANAAN_KBM');
                    const conflictingKbm = kbmSegments.find(s => {
                        const sStart = parseTimeToMinutesWl(s.start_time);
                        const sEnd = parseTimeToMinutesWl(s.end_time);
                        return Math.max(startMin, sStart) < Math.min(endMin, sEnd);
                    });

                    // Jika berbenturan dengan KBM dan user BELUM mengonfirmasi replace_kbm:
                    if (conflictingKbm && !noteData.replace_kbm) {
                        return {
                            success: false,
                            conflict_kbm: true,
                            kbm: {
                                activity_id: conflictingKbm.activity_id,
                                title: conflictingKbm.activity_title,
                                start_time: conflictingKbm.start_time,
                                end_time: conflictingKbm.end_time
                            },
                            message: `Jam pembinaan (${startTime}–${endTime}) bertepatan dengan jadwal KBM Anda: "${conflictingKbm.activity_title}" (${conflictingKbm.start_time}–${conflictingKbm.end_time}).`
                        };
                    }

                    let matchedSegment = null;
                    let linkType = 'fulfillment';

                    // Kasus 1 & 2: Cari segmen pembinaan yang sudah direncanakan
                    matchedSegment = candidateSegments.find(s => s.catalog_id === catalogId);

                    // Kasus Penggantian KBM yang telah dikonfirmasi
                    if (!matchedSegment && noteData.replace_kbm && (noteData.kbm_activity_id || conflictingKbm)) {
                        const targetActId = noteData.kbm_activity_id || conflictingKbm.activity_id;
                        matchedSegment = candidateSegments.find(s => s.activity_id === targetActId);
                        if (matchedSegment) {
                            linkType = 'substitution';
                        }
                    }

                    // Kasus 3: Jika belum ada dan tidak menggantikan KBM, cari segmen non-KBM terdekat di hari itu
                    if (!matchedSegment) {
                        const nonKbmSegments = candidateSegments.filter(s => s.is_teaching === 0 && s.catalog_id !== 'cat_kbm' && s.category_code !== 'PELAKSANAAN_KBM');
                        if (nonKbmSegments.length > 0) {
                            let closest = nonKbmSegments[0];
                            let minDiff = Math.abs(parseTimeToMinutesWl(closest.start_time) - startMin);
                            for (let i = 1; i < nonKbmSegments.length; i++) {
                                const diff = Math.abs(parseTimeToMinutesWl(nonKbmSegments[i].start_time) - startMin);
                                if (diff < minDiff) {
                                    minDiff = diff;
                                    closest = nonKbmSegments[i];
                                }
                            }
                            matchedSegment = closest;
                            linkType = 'substitution';
                        }
                    }

                    // 5. Simpan / perbarui work_logs
                    const logId = noteData.shared_work_log_id || `wl_pembinaan_${noteData.id}`;

                    const policyCfg = await getWorkloadPolicyConfig(db);
                    const isAutoVerified = policyCfg.require_log_verification === 0;
                    const defaultVerStatus = isAutoVerified ? 'verified' : 'unverified';
                    const dayOfWeek = new Date(targetDate).getDay() || 7;

                    const studentLabel = noteData.collective_students || `${noteData.student_name || ''} (${noteData.student_class || ''})`;
                    const outputSummary = `Pembinaan Siswa [${studentLabel}]: ${noteData.notes || noteData.title || ''}`;
                    const isUnplanned = matchedSegment ? 0 : 1;
                    const matchedActivityId = matchedSegment ? matchedSegment.activity_id : null;

                    const syncBatch = [
                        db.prepare(`
                            INSERT INTO work_logs (
                                id, work_week_id, teacher_id, date, day_of_week, title,
                                catalog_id, is_unplanned, output_summary, evidence_url,
                                status_execution, obstacle_notes,
                                verification_status, is_locked, verified_at, verified_by_uid, created_at, updated_at
                            ) VALUES (
                                ?, ?, ?, ?, ?, ?,
                                ?, ?, ?, ?,
                                'terlaksana', NULL,
                                ?, 0, ${isAutoVerified ? "datetime('now')" : "NULL"}, ${isAutoVerified ? "'system_auto_policy'" : "NULL"},
                                datetime('now'), datetime('now')
                            )
                            ON CONFLICT(id) DO UPDATE SET
                                date = excluded.date,
                                day_of_week = excluded.day_of_week,
                                title = excluded.title,
                                catalog_id = excluded.catalog_id,
                                is_unplanned = excluded.is_unplanned,
                                output_summary = excluded.output_summary,
                                evidence_url = CASE WHEN excluded.evidence_url IS NOT NULL AND excluded.evidence_url != '' THEN excluded.evidence_url ELSE work_logs.evidence_url END,
                                status_execution = excluded.status_execution,
                                verification_status = CASE WHEN work_logs.verification_status = 'verified' THEN 'verified' ELSE excluded.verification_status END,
                                updated_at = datetime('now')
                        `).bind(
                            logId, week.id, actualTeacherId, targetDate,
                            Number(dayOfWeek), logTitle, catalogId,
                            isUnplanned, outputSummary, noteData.evidence_url || '',
                            defaultVerStatus
                        ),
                        db.prepare("DELETE FROM work_log_segments WHERE work_log_id = ?").bind(logId),
                        db.prepare(`
                            INSERT INTO work_log_segments (id, work_log_id, start_time, end_time, actual_minutes, notes, created_at)
                            VALUES (?, ?, ?, ?, ?, ?, datetime('now'))
                        `).bind(
                            crypto.randomUUID(), logId, startTime, endTime,
                            durationMinutes, noteData.title || 'Pembinaan Siswa'
                        )
                    ];

                    if (matchedActivityId) {
                        syncBatch.push(
                            db.prepare("DELETE FROM plan_log_links WHERE work_log_id = ? AND plan_activity_id != ?").bind(logId, matchedActivityId),
                            db.prepare(`
                                INSERT INTO plan_log_links (id, plan_activity_id, work_log_id, link_type, reason_notes, created_at)
                                VALUES (?, ?, ?, ?, ?, datetime('now'))
                                ON CONFLICT(plan_activity_id, work_log_id) DO UPDATE SET
                                    link_type = excluded.link_type,
                                    reason_notes = excluded.reason_notes
                            `).bind(
                                crypto.randomUUID(), matchedActivityId, logId, linkType,
                                linkType === 'substitution'
                                    ? `Diganti oleh: Pembinaan Siswa (${studentLabel})`
                                    : 'Realisasi pembinaan siswa terencana'
                            )
                        );
                    } else {
                        syncBatch.push(
                            db.prepare("DELETE FROM plan_log_links WHERE work_log_id = ?").bind(logId)
                        );
                    }

                    await db.batch(syncBatch);

                    // Jejak audit
                    try {
                        await recordWorkloadAuditLog(
                            db, "work_log", logId, "SYNC_FROM_MENTORING",
                            actorUser?.uid || "system", actorUser?.name || actorUser?.email || "Portal Perwalian",
                            { note_id: noteData.id, plan_activity_id: matchedActivityId, link_type: linkType, student: studentLabel }
                        );
                    } catch (_) {}

                    return {
                        success: true,
                        log_id: logId,
                        matched: Boolean(matchedSegment),
                        link_type: linkType,
                        plan_activity_id: matchedActivityId,
                        actual_minutes: durationMinutes
                    };
                } catch (err) {
                    console.error("[syncMentoringToWorkload] Error:", err);
                    return { success: false, reason: err.message };
                }
            }

            async function removeJournalFromWorkload(db, journalIds) {
                if (!db || !Array.isArray(journalIds) || journalIds.length === 0) return { deletedCount: 0 };
                const logIds = journalIds.map(id => id.startsWith('wl_jurnal_') ? id : `wl_jurnal_${id}`);

                let deletedCount = 0;
                for (const logId of logIds) {
                    await db.prepare("DELETE FROM plan_log_links WHERE work_log_id = ?").bind(logId).run();
                    await db.prepare("DELETE FROM work_log_segments WHERE work_log_id = ?").bind(logId).run();
                    await db.prepare("DELETE FROM work_logs WHERE id = ?").bind(logId).run();
                    deletedCount++;
                }
                return { success: true, deletedCount };
            }

            async function syncWorkWeekJournals(db, workWeekId, actorUser = null) {
                if (!db || !workWeekId) return { success: false, syncedCount: 0, ignoredCount: 0 };
                try {
                    await ensureWorkloadActivityCatalog(db);

                    // 1. Ambil minggu kerja
                    const weekRow = await db.prepare("SELECT * FROM work_weeks WHERE id = ?").bind(workWeekId).first();
                    if (!weekRow || !weekRow.week_start_date || !weekRow.week_end_date) {
                        return { success: false, reason: "Minggu kerja tidak ditemukan", syncedCount: 0, ignoredCount: 0 };
                    }
                    if (weekRow.is_locked === 1) {
                        return { success: false, reason: "Minggu kerja telah dikunci oleh pimpinan", syncedCount: 0, ignoredCount: 0 };
                    }

                    // 2. Proteksi Gerbang Realisasi: Rencana kerja mingguan wajib berstatus 'approved' sebelum sinkronisasi
                    const latestPlanVersion = await db.prepare(`
                        SELECT id, status FROM weekly_plan_versions 
                        WHERE work_week_id = ? 
                        ORDER BY version_number DESC 
                        LIMIT 1
                    `).bind(workWeekId).first();

                    if (!latestPlanVersion || latestPlanVersion.status !== "approved") {
                        return {
                            success: false,
                            reason: "Rencana kerja mingguan belum disetujui atau difinalisasi oleh guru/pimpinan",
                            syncedCount: 0,
                            ignoredCount: 0
                        };
                    }

                    // 3. Ambil data GTK guru
                    const teacherId = weekRow.teacher_id;
                    const teacherRow = await db.prepare("SELECT * FROM gtk WHERE id = ? OR nik = ? OR nip = ? LIMIT 1").bind(teacherId, teacherId, teacherId).first();
                    const teacherName = teacherRow ? teacherRow.name : "";

                    // 4. Pre-fetch seluruh segmen rencana KBM aktif di minggu ini (1 query JOIN)
                    const { results: allPlanSegments } = await db.prepare(`
                        SELECT pts.*, pa.title AS activity_title, pa.category_code, pa.catalog_id
                        FROM plan_time_segments pts
                        JOIN plan_activities pa ON pts.activity_id = pa.id
                        WHERE pa.work_week_id = ?
                          AND (pts.is_teaching = 1 OR pa.category_code = 'PELAKSANAAN_KBM' OR pa.catalog_id = 'cat_kbm')
                          AND pa.is_cancelled = 0
                          AND pts.plan_version_id = ?
                        ORDER BY pts.date ASC, pts.start_time ASC
                    `).bind(workWeekId, latestPlanVersion.id).all();

                    const planSegments = allPlanSegments || [];

                    // 5. Query seluruh entri jurnal guru pada rentang tanggal minggu kerja
                    let journalQuery = "SELECT * FROM jurnal_guru WHERE tanggal >= ? AND tanggal <= ?";
                    const queryParams = [weekRow.week_start_date, weekRow.week_end_date];

                    const teacherConditions = [];
                    if (teacherId) {
                        teacherConditions.push("uid_guru = ?");
                        queryParams.push(teacherId);
                    }
                    if (teacherRow) {
                        if (teacherRow.nik && teacherRow.nik !== teacherId) {
                            teacherConditions.push("uid_guru = ?");
                            queryParams.push(teacherRow.nik);
                        }
                        if (teacherRow.nip && teacherRow.nip !== teacherId) {
                            teacherConditions.push("uid_guru = ?");
                            queryParams.push(teacherRow.nip);
                        }
                    }
                    if (teacherName) {
                        teacherConditions.push("guru = ? OR guru LIKE ?");
                        queryParams.push(teacherName, `%${teacherName}%`);
                    }

                    if (teacherConditions.length > 0) {
                        journalQuery += ` AND (${teacherConditions.join(" OR ")})`;
                    }

                    journalQuery += " ORDER BY tanggal ASC, created_at ASC";

                    const { results: journalEntries } = await db.prepare(journalQuery).bind(...queryParams).all();
                    const journals = journalEntries || [];
                    if (journals.length === 0) {
                        return { success: true, totalJournals: 0, syncedCount: 0, ignoredCount: 0 };
                    }

                    // 6. Pre-fetch existing work_logs & plan_log_links di minggu ini untuk deteksi idempotensi / no-op
                    const { results: existingLogsList } = await db.prepare(`
                        SELECT id, date, is_locked, verification_status, verified_by_uid, output_summary, evidence_url, status_execution, obstacle_notes
                        FROM work_logs
                        WHERE work_week_id = ?
                    `).bind(workWeekId).all();
                    const existingLogsMap = new Map((existingLogsList || []).map(l => [l.id, l]));

                    const { results: existingLinksList } = await db.prepare(`
                        SELECT pll.work_log_id, pll.plan_activity_id
                        FROM plan_log_links pll
                        JOIN plan_activities pa ON pll.plan_activity_id = pa.id
                        WHERE pa.work_week_id = ?
                    `).bind(workWeekId).all();
                    const existingLinksSet = new Set((existingLinksList || []).map(l => `${l.work_log_id}_${l.plan_activity_id}`));

                    const policyCfg = await getWorkloadPolicyConfig(db);
                    const isAutoVerified = policyCfg.require_log_verification === 0;
                    const defaultVerStatus = isAutoVerified ? 'verified' : 'unverified';

                    let syncedCount = 0;
                    let ignoredCount = 0;
                    const batchStatements = [];

                    for (const jRow of journals) {
                        const targetDate = jRow.tanggal;
                        const candidateSegments = planSegments.filter(s => s.date === targetDate);
                        if (candidateSegments.length === 0) {
                            ignoredCount++;
                            continue;
                        }

                        const lmsMatch = await resolveLmsJournalPlanSegment(db, jRow, candidateSegments);
                        const matchResult = lmsMatch || matchPlanSegmentWithJournal(candidateSegments, jRow);
                        if (!matchResult || !matchResult.segment) {
                            ignoredCount++;
                            continue;
                        }

                        const matchedSegment = matchResult.segment;
                        const matchedActivityId = matchedSegment.activity_id;
                        const logId = `wl_jurnal_${jRow.id}`;

                        const existingLog = existingLogsMap.get(logId);
                        if (existingLog && existingLog.is_locked === 1) {
                            ignoredCount++;
                            continue;
                        }
                        if (existingLog && existingLog.status_execution === "tidak_terlaksana" && /^\[(Sakit|Cuti|Izin)\]/i.test(existingLog.obstacle_notes || "")) {
                            ignoredCount++;
                            continue;
                        }

                        const isManualVerified = existingLog &&
                                                 existingLog.verification_status === "verified" &&
                                                 existingLog.verified_by_uid &&
                                                 existingLog.verified_by_uid !== "system_auto_policy" &&
                                                 policyCfg.require_log_verification !== 0;
                        if (isManualVerified) {
                            ignoredCount++;
                            continue;
                        }

                        const actualMinutes = matchedSegment.planned_minutes || calculateEffectiveMinutesWl(matchedSegment.start_time, matchedSegment.end_time);

                        const summaryParts = [];
                        if (jRow.topik) summaryParts.push(`Materi: ${jRow.topik}`);
                        if (jRow.catatan) summaryParts.push(`Refleksi: ${jRow.catatan}`);
                        if (jRow.lokasi_mengajar) summaryParts.push(`Ruang: ${jRow.lokasi_mengajar}`);
                        const outputSummary = summaryParts.length > 0
                            ? summaryParts.join(' | ')
                            : `KBM ${jRow.mapel} Kelas ${jRow.kelas}`;

                        // Proteksi No-Op: jika data sudah identik dan link sudah terhubung sempurna
                        const linkKey = `${logId}_${matchedActivityId}`;
                        if (existingLog &&
                            existingLog.status_execution === 'terlaksana' &&
                            existingLog.output_summary === outputSummary &&
                            (existingLog.evidence_url || '') === (jRow.foto_url || '') &&
                            existingLinksSet.has(linkKey)) {
                            syncedCount++;
                            continue;
                        }

                        const dayOfWeek = matchedSegment.day_of_week || (new Date(targetDate).getDay() || 7);
                        const logTitle = matchedSegment.activity_title || `KBM ${jRow.mapel} (${jRow.kelas})`;
                        const catalogId = matchedSegment.catalog_id || 'cat_kbm';

                        batchStatements.push(
                            db.prepare(`
                                INSERT INTO work_logs (
                                    id, work_week_id, teacher_id, date, day_of_week, title,
                                    catalog_id, is_unplanned, output_summary, evidence_url,
                                    status_execution, obstacle_notes,
                                    verification_status, is_locked, verified_at, verified_by_uid, created_at, updated_at
                                ) VALUES (
                                    ?, ?, ?, ?, ?, ?,
                                    ?, 0, ?, ?,
                                    'terlaksana', NULL,
                                    ?, 0, ${isAutoVerified ? "datetime('now')" : "NULL"}, ${isAutoVerified ? "'system_auto_policy'" : "NULL"},
                                    datetime('now'), datetime('now')
                                )
                                ON CONFLICT(id) DO UPDATE SET
                                    date = excluded.date,
                                    day_of_week = excluded.day_of_week,
                                    title = excluded.title,
                                    catalog_id = excluded.catalog_id,
                                    is_unplanned = 0,
                                    output_summary = excluded.output_summary,
                                    evidence_url = CASE WHEN excluded.evidence_url IS NOT NULL AND excluded.evidence_url != '' THEN excluded.evidence_url ELSE work_logs.evidence_url END,
                                    status_execution = excluded.status_execution,
                                    verification_status = CASE WHEN work_logs.verification_status = 'verified' THEN 'verified' ELSE excluded.verification_status END,
                                    updated_at = datetime('now')
                            `).bind(
                                logId, workWeekId, weekRow.teacher_id, targetDate,
                                Number(dayOfWeek), logTitle, catalogId,
                                outputSummary, jRow.foto_url || '',
                                defaultVerStatus
                            ),
                            db.prepare("DELETE FROM work_log_segments WHERE work_log_id = ?").bind(logId),
                            db.prepare(`
                                INSERT INTO work_log_segments (id, work_log_id, start_time, end_time, actual_minutes, notes, created_at)
                                VALUES (?, ?, ?, ?, ?, ?, datetime('now'))
                            `).bind(
                                crypto.randomUUID(), logId, matchedSegment.start_time, matchedSegment.end_time,
                                actualMinutes, `Otomatis dari Jurnal Mengajar Kelas ${jRow.kelas}`
                            ),
                            db.prepare("DELETE FROM plan_log_links WHERE work_log_id = ? AND plan_activity_id != ?").bind(logId, matchedActivityId),
                            db.prepare(`
                                INSERT INTO plan_log_links (id, plan_activity_id, work_log_id, link_type, reason_notes, created_at)
                                VALUES (?, ?, ?, 'fulfillment', 'Sinkron otomatis Jurnal KBM', datetime('now'))
                                ON CONFLICT(plan_activity_id, work_log_id) DO UPDATE SET
                                    link_type = excluded.link_type,
                                    reason_notes = excluded.reason_notes
                            `).bind(crypto.randomUUID(), matchedActivityId, logId)
                        );

                        syncedCount++;
                    }

                    // 7. Eksekusi seluruh batch statement dalam SATU network call atomik ke D1
                    if (batchStatements.length > 0) {
                        await db.batch(batchStatements);
                    }

                    // 8. Catat jejak audit ringkasan di Supabase (non-blocking jika gagal)
                    try {
                        await recordWorkloadAuditLog(
                            db, "work_week", workWeekId, "SYNC_WEEK_JOURNALS_BULK",
                            actorUser?.uid || "system", actorUser?.name || actorUser?.email || "Sistem Jurnal",
                            { work_week_id: workWeekId, total_journals: journals.length, synced_count: syncedCount }
                        );
                    } catch (eAudit) {
                        console.warn("[syncWorkWeekJournals] Audit log warning:", eAudit.message);
                    }

                    return {
                        success: true,
                        totalJournals: journals.length,
                        syncedCount,
                        ignoredCount
                    };
                } catch (err) {
                    console.error("[syncWorkWeekJournals] Error:", err);
                    return { success: false, error: err.message, syncedCount: 0, ignoredCount: 0 };
                }
            }

            // 1. GET /api/workload/policy & PUT /api/workload/policy
            if (path === "/api/workload/policy") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                if (method === "GET") {
                    try {
                        const policy = await env.DB.prepare(`
                            SELECT * FROM school_work_policies WHERE is_active = 1 ORDER BY updated_at DESC LIMIT 1
                        `).first();

                        const qStart = url.searchParams.get("start_date");
                        const qEnd = url.searchParams.get("end_date");
                        let overrides = [];
                        if (qStart && qEnd) {
                            const ovRows = await env.DB.prepare(`
                                SELECT * FROM work_calendar_overrides
                                WHERE date >= ? AND date <= ?
                                ORDER BY date ASC
                            `).bind(qStart, qEnd).all();
                            overrides = ovRows.results || [];
                        }

                        const defaultPolicy = {
                            id: "default_policy",
                            academic_year: "2026/2027",
                            work_days_per_week: 5,
                            target_minutes_per_day: 450,
                            total_target_minutes: 2250,
                            default_start_time: "07:30",
                            default_end_time: "15:30",
                            break_intervals: JSON.stringify(WORKLOAD_OFFICIAL_BREAKS),
                            is_active: 1
                        };

                        const policyCfg = await getWorkloadPolicyConfig(env.DB);
                        const isSuperAdminUser = isWorkloadSuperAdmin(authResult.user);
                        const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user).catch(() => null);
                        const vipList = Array.isArray(policyCfg.vip_teacher_ids) ? policyCfg.vip_teacher_ids : [];

                        // Cek apakah pengguna saat ini berhak mengakses fitur VIP
                        const canAccessVip = isSuperAdminUser ||
                            authResult.user.role === "kepala_sekolah" ||
                            (Array.isArray(authResult.user.additionalRoles) && authResult.user.additionalRoles.includes("kepala_sekolah")) ||
                            (userTeacherId && vipList.includes(userTeacherId)) ||
                            (authResult.user.uid && vipList.includes(authResult.user.uid)) ||
                            (authResult.user.nip && vipList.includes(authResult.user.nip));

                        const mergedPolicy = {
                            ...(policy || defaultPolicy),
                            require_plan_approval: policyCfg.require_plan_approval,
                            require_log_verification: policyCfg.require_log_verification,
                            can_access_vip: Boolean(canAccessVip)
                        };

                        // HANYA Super Admin yang menerima array vip_teacher_ids.
                        // Kepala Sekolah dan guru biasa tidak memiliki akses read ke array ini.
                        if (isSuperAdminUser) {
                            mergedPolicy.vip_teacher_ids = vipList;
                        }

                        return jsonResponse({
                            success: true,
                            data: {
                                policy: mergedPolicy,
                                overrides
                            }
                        }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal mengambil kebijakan jam kerja: " + err.message, 500, request);
                    }
                }

                if (method === "PUT") {
                    if (!isWorkloadManager(authResult.user)) {
                        return errorResponse("Forbidden: Hanya Kepala Sekolah / Super Admin yang dapat mengubah kebijakan jam kerja", 403, request);
                    }
                    try {
                        const body = await request.json();

                        // 1. Simpan toggle mode persetujuan fleksibel di system_settings
                        if (body.require_plan_approval !== undefined || body.require_log_verification !== undefined) {
                            let currentCfg = await getWorkloadPolicyConfig(env.DB);
                            if (body.require_plan_approval !== undefined) currentCfg.require_plan_approval = Number(body.require_plan_approval) ? 1 : 0;
                            if (body.require_log_verification !== undefined) currentCfg.require_log_verification = Number(body.require_log_verification) ? 1 : 0;

                            await env.DB.prepare(`
                                INSERT INTO system_settings (key, value, updated_at)
                                VALUES ('workload_policy_config', ?, datetime('now'))
                                ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = datetime('now')
                            `).bind(JSON.stringify(currentCfg)).run();

                            await recordWorkloadAuditLog(
                                env.DB, "system_settings", "workload_policy_config", "UPDATE_APPROVAL_POLICY",
                                authResult.user.uid, authResult.user.name || authResult.user.email,
                                currentCfg
                            );
                        }

                        // 1b. Simpan whitelist guru VIP (HANYA SUPER ADMIN)
                        if (body.vip_teacher_ids !== undefined) {
                            if (!isWorkloadSuperAdmin(authResult.user)) {
                                return errorResponse("Forbidden: Hanya Super Admin yang berwenang melihat atau mengubah daftar whitelist guru VIP", 403, request);
                            }
                            let currentCfg = await getWorkloadPolicyConfig(env.DB);
                            currentCfg.vip_teacher_ids = Array.isArray(body.vip_teacher_ids)
                                ? body.vip_teacher_ids.map(id => String(id).trim()).filter(Boolean)
                                : [];

                            await env.DB.prepare(`
                                INSERT INTO system_settings (key, value, updated_at)
                                VALUES ('workload_policy_config', ?, datetime('now'))
                                ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = datetime('now')
                            `).bind(JSON.stringify(currentCfg)).run();

                            await recordWorkloadAuditLog(
                                env.DB, "system_settings", "workload_policy_config", "UPDATE_VIP_WHITELIST",
                                authResult.user.uid, authResult.user.name || authResult.user.email,
                                { vip_teacher_count: currentCfg.vip_teacher_ids.length }
                            );
                        }

                        // 2. Simpan kebijakan jam kerja fisik (jika dikirim)
                        const hasWorkHourUpdate = body.target_minutes_per_day !== undefined || body.work_days_per_week !== undefined || body.default_start_time !== undefined;
                        if (hasWorkHourUpdate) {
                            const {
                                academic_year = "2026/2027",
                                policy_name,
                                work_days_per_week = 5,
                                target_minutes_per_day = 450,
                                default_start_time = "07:30",
                                default_end_time = "15:30",
                                break_intervals = JSON.stringify(WORKLOAD_OFFICIAL_BREAKS),
                                legal_basis_document
                            } = body;

                            // Aturan Uji 27: Penyesuaian target administratif tanpa dokumen dasar yang sah ditolak
                            if (Number(target_minutes_per_day) !== 450 && (!legal_basis_document || !String(legal_basis_document).trim())) {
                                return errorResponse("Penyesuaian target jam kerja administratif wajib menyertakan nomor dokumen dasar hukum / SK yang sah", 422, request);
                            }

                            const totalTarget = Number(work_days_per_week) * Number(target_minutes_per_day);
                            const policyId = body.id || crypto.randomUUID();

                            await env.DB.prepare(`
                                INSERT INTO school_work_policies (
                                    id, school_id, policy_name, work_days_count, normal_daily_minutes,
                                    normal_weekly_minutes, work_start_time, work_end_time,
                                    breaks_json, is_active, legal_basis_doc, created_at, updated_at
                                ) VALUES (?, 'sch_smagesa_01', ?, ?, ?, ?, ?, ?, ?, 1, ?, datetime('now'), datetime('now'))
                                ON CONFLICT(id) DO UPDATE SET
                                    work_days_count = excluded.work_days_count,
                                    normal_daily_minutes = excluded.normal_daily_minutes,
                                    normal_weekly_minutes = excluded.normal_weekly_minutes,
                                    work_start_time = excluded.work_start_time,
                                    work_end_time = excluded.work_end_time,
                                    breaks_json = excluded.breaks_json,
                                    legal_basis_doc = excluded.legal_basis_doc,
                                    updated_at = datetime('now')
                            `).bind(
                                policyId, policy_name || `Kebijakan Kerja ${academic_year || '2026/2027'}`,
                                Number(work_days_per_week || 5), Number(target_minutes_per_day || 450),
                                totalTarget || 2250, default_start_time || '07:30', default_end_time || '15:30',
                                typeof break_intervals === "string" ? break_intervals : JSON.stringify(break_intervals || WORKLOAD_OFFICIAL_BREAKS),
                                legal_basis_document || null
                            ).run();

                            await recordWorkloadAuditLog(
                                env.DB, "school_work_policies", policyId, "UPDATE_POLICY",
                                authResult.user.uid, authResult.user.name || authResult.user.email,
                                { target_minutes_per_day, work_days_per_week, legal_basis_document }
                            );
                        }

                        return jsonResponse({ success: true, message: "Kebijakan dan alur persetujuan beban kerja berhasil diperbarui" }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal menyimpan kebijakan jam kerja: " + err.message, 500, request);
                    }
                }

                return errorResponse("Method tidak didukung", 405, request);
            }

            // 2. GET, POST, & PUT /api/workload/catalog (Master Katalog Tugas Pokok & Kategori Guru)
            if (path === "/api/workload/catalog") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                if (method === "GET") {
                    try {
                        await ensureWorkloadActivityCatalog(env.DB);
                        const isMgr = isWorkloadManager(authResult.user);
                        const includeInactive = isMgr && url.searchParams.get("include_inactive") === "1";

                        const query = includeInactive
                            ? "SELECT * FROM activity_catalog ORDER BY sort_order ASC, name ASC"
                            : "SELECT * FROM activity_catalog WHERE is_active = 1 ORDER BY sort_order ASC, name ASC";

                        const catalogRows = await env.DB.prepare(query).all();
                        let items = catalogRows.results || [];
                        if (items.length === 0) {
                            items = STANDARD_WORKLOAD_CATALOG;
                        }
                        items = items.map(it => ({
                            ...it,
                            description: (it.description || '').replace(/\s*\([Ee]kuivalensi[^)]*\)/gi, '').trim()
                        }));

                        return jsonResponse({ success: true, data: items }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal mengambil katalog aktivitas: " + err.message, 500, request);
                    }
                }

                if (method === "POST" || method === "PUT") {
                    if (!isWorkloadManager(authResult.user)) {
                        return errorResponse("Forbidden: Hanya Kepala Sekolah / Super Admin yang dapat mengelola master katalog aktivitas", 403, request);
                    }
                    try {
                        const body = await request.json();
                        await ensureWorkloadActivityCatalog(env.DB);

                        const {
                            id = crypto.randomUUID(),
                            code,
                            category_code = "PELAKSANAAN_KBM",
                            category_name,
                            name,
                            description = "",
                            default_duration_minutes = 45,
                            is_teaching = 0,
                            requires_evidence = 0,
                            sort_order = 500,
                            is_active = 1
                        } = body;

                        if (!name || !name.trim()) {
                            return errorResponse("Nama sub-kegiatan wajib diisi", 400, request);
                        }

                        const dutyNameMap = {
                            'PERENCANAAN': 'Merencanakan Pembelajaran/Pembimbingan',
                            'PELAKSANAAN_KBM': 'Melaksanakan Pembelajaran/Pembimbingan',
                            'PENILAIAN': 'Menilai Hasil Pembelajaran/Pembimbingan',
                            'PEMBIMBINGAN': 'Membimbing dan Melatih Murid',
                            'TUGAS_TAMBAHAN': 'Melaksanakan Tugas Tambahan'
                        };
                        const resolvedCategoryName = category_name || dutyNameMap[category_code] || 'Kegiatan Guru';
                        const generatedCode = code || name.toLowerCase().replace(/[^a-z0-9]+/g, '_').slice(0, 50);

                        await env.DB.prepare(`
                            INSERT INTO activity_catalog (
                                id, code, category_code, category_name, name, description,
                                default_duration_minutes, is_teaching, requires_evidence, sort_order, is_active, created_at
                            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
                            ON CONFLICT(id) DO UPDATE SET
                                category_code = excluded.category_code,
                                category_name = excluded.category_name,
                                name = excluded.name,
                                description = excluded.description,
                                default_duration_minutes = excluded.default_duration_minutes,
                                is_teaching = excluded.is_teaching,
                                requires_evidence = excluded.requires_evidence,
                                sort_order = excluded.sort_order,
                                is_active = excluded.is_active
                        `).bind(
                            id, generatedCode, category_code, resolvedCategoryName, name.trim(), description.trim(),
                            Number(default_duration_minutes || 45), is_teaching ? 1 : 0, requires_evidence ? 1 : 0,
                            Number(sort_order || 500), Number(is_active) === 0 ? 0 : 1
                        ).run();

                        await recordWorkloadAuditLog(
                            env.DB, "activity_catalog", id, "UPSERT_CATALOG_ITEM",
                            authResult.user.uid, authResult.user.name || authResult.user.email,
                            { id, name, category_code, default_duration_minutes, is_active }
                        );

                        return jsonResponse({
                            success: true,
                            message: "Katalog aktivitas berhasil disimpan",
                            data: { id, name, category_code, is_active }
                        }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal menyimpan katalog aktivitas: " + err.message, 500, request);
                    }
                }

                return errorResponse("Method tidak didukung", 405, request);
            }

            // 3. GET & POST /api/workload/assignments (Penugasan Tugas Tambahan Guru)
            if (path === "/api/workload/assignments") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                if (method === "GET") {
                    try {
                        const qTeacherId = url.searchParams.get("teacher_id");
                        const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                        const isMgr = isWorkloadManager(authResult.user);

                        // Guru hanya bisa melihat miliknya, manajer bisa melihat siapa saja
                        const targetTeacherId = isMgr && qTeacherId ? qTeacherId : userTeacherId;

                        const assignments = await env.DB.prepare(`
                            SELECT ta.*, g.name AS teacher_name, g.nip AS teacher_nip
                            FROM teacher_assignments ta
                            LEFT JOIN gtk g ON ta.teacher_id = g.id
                            WHERE ta.teacher_id = ?
                            ORDER BY ta.created_at DESC
                        `).bind(targetTeacherId).all();

                        return jsonResponse({ success: true, data: assignments.results || [] }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal mengambil data penugasan tugas tambahan: " + err.message, 500, request);
                    }
                }

                if (method === "POST") {
                    if (!isWorkloadManager(authResult.user)) {
                        return errorResponse("Forbidden: Hanya Kepala Sekolah / Super Admin yang dapat mengelola penugasan tugas tambahan", 403, request);
                    }
                    try {
                        const body = await request.json();
                        const { action = "upsert" } = body;

                        if (action === "delete") {
                            const { id } = body;
                            if (!id) return errorResponse("ID penugasan diperlukan", 400, request);
                            await env.DB.prepare("DELETE FROM teacher_assignments WHERE id = ?").bind(id).run();
                            return jsonResponse({ success: true, message: "Penugasan berhasil dihapus" }, 200, request);
                        }

                        const {
                            id = crypto.randomUUID(),
                            teacher_id,
                            academic_year = "2026/2027",
                            duty_code,
                            duty_name,
                            sk_number,
                            sk_date,
                            valid_from,
                            valid_until,
                            rombel_count = 0,
                            equivalent_jp = 0,
                            is_active = 1
                        } = body;

                        if (!teacher_id || !duty_code || !duty_name) {
                            return errorResponse("Data guru, kode tugas, dan nama tugas wajib diisi", 400, request);
                        }

                        // Kepatuhan Permendikdasmen 11/2025 & Kepmendikdasmen 221/P/2025:
                        // 1. Tugas BKK ditolak/0 JP-Eq untuk jenjang SMA (Uji 21)
                        if (String(duty_code).toLowerCase().trim() === "bkk") {
                            return errorResponse("Tugas BKK (Bursa Kerja Khusus) khusus untuk jenjang SMK dan tidak berlaku untuk jenjang SMA (Kepmendikdasmen 221/P/2025)", 422, request);
                        }

                        // 2. Pembina OSIS: max 2 JP tatap muka/minggu (Uji 19)
                        let parsedEquivalentJp = Number(equivalent_jp || 0);
                        if (String(duty_code).toLowerCase().trim() === "pembina_osis") {
                            parsedEquivalentJp = Math.min(2, Math.max(0, parsedEquivalentJp));
                        }

                        // 3. Guru Wali: max 2 JP tatap muka/minggu (Uji 20)
                        if (String(duty_code).toLowerCase().trim() === "guru_wali" || String(duty_code).toLowerCase().trim() === "wali_kelas") {
                            parsedEquivalentJp = Math.min(2, Math.max(0, parsedEquivalentJp));
                        }

                        await env.DB.prepare(`
                            INSERT INTO teacher_assignments (
                                id, teacher_id, user_uid, assignment_type, title,
                                sk_number, sk_date, start_date, end_date, scope_target,
                                equivalency_jp, rule_code, status, created_at, updated_at
                            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))
                            ON CONFLICT(id) DO UPDATE SET
                                assignment_type = excluded.assignment_type,
                                title = excluded.title,
                                sk_number = excluded.sk_number,
                                sk_date = excluded.sk_date,
                                start_date = excluded.start_date,
                                end_date = excluded.end_date,
                                scope_target = excluded.scope_target,
                                equivalency_jp = excluded.equivalency_jp,
                                rule_code = excluded.rule_code,
                                status = excluded.status,
                                updated_at = datetime('now')
                        `).bind(
                            id, teacher_id, authResult.user.uid, duty_code || "TUGAS_TAMBAHAN", duty_name || "Tugas Tambahan",
                            sk_number || "", sk_date || "", valid_from || "", valid_until || "",
                            rombel_count ? String(rombel_count) : null, parsedEquivalentJp, duty_code || null,
                            is_active !== false && is_active !== 0 ? "active" : "inactive"
                        ).run();

                        await recordWorkloadAuditLog(
                            env.DB, "teacher_assignments", id, "UPSERT_ASSIGNMENT",
                            authResult.user.uid, authResult.user.name || authResult.user.email,
                            { teacher_id, duty_code, equivalent_jp: parsedEquivalentJp }
                        );

                        return jsonResponse({ success: true, message: "Penugasan guru berhasil disimpan" }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal mengelola penugasan tugas tambahan: " + err.message, 500, request);
                    }
                }

                return errorResponse("Method tidak didukung", 405, request);
            }

            // 3b. GET & POST /api/workload/waka-duties (Master Butir Tugas Dinamis Wakil Kepala Sekolah)
            if (path === "/api/workload/waka-duties") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                await ensureWakaDutyItems(env.DB);

                if (method === "GET") {
                    try {
                        const qType = (url.searchParams.get("waka_type") || "").toLowerCase().trim();
                        const isMgr = isWorkloadManager(authResult.user);
                        const includeInactive = isMgr && url.searchParams.get("include_inactive") === "1";

                        let query = "SELECT * FROM waka_duty_items WHERE 1=1";
                        const params = [];

                        if (qType) {
                            query += " AND waka_type = ?";
                            params.push(qType);
                        }
                        if (!includeInactive) {
                            query += " AND is_active = 1";
                        }
                        query += " ORDER BY waka_type ASC, duty_number ASC";

                        const dutiesRows = await env.DB.prepare(query).bind(...params).all();
                        return jsonResponse({ success: true, data: dutiesRows.results || [] }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal mengambil butir tugas waka: " + err.message, 500, request);
                    }
                }

                if (method === "POST") {
                    if (!isWorkloadManager(authResult.user)) {
                        return errorResponse("Forbidden: Hanya Kepala Sekolah / Super Admin yang dapat mengelola master butir tugas waka", 403, request);
                    }
                    try {
                        const body = await request.json();
                        const { action = "upsert" } = body;

                        if (action === "delete") {
                            const { id } = body;
                            if (!id) return errorResponse("ID butir tugas waka diperlukan", 400, request);
                            await env.DB.prepare("DELETE FROM waka_duty_items WHERE id = ?").bind(id).run();
                            await recordWorkloadAuditLog(
                                env.DB, "waka_duty_items", id, "DELETE_WAKA_DUTY_ITEM",
                                authResult.user.uid, authResult.user.name || authResult.user.email,
                                { id }
                            );
                            return jsonResponse({ success: true, message: "Butir tugas waka berhasil dihapus" }, 200, request);
                        }

                        const {
                            id = crypto.randomUUID(),
                            waka_type,
                            is_active = 1
                        } = body;

                        const duty_number = Number(body.duty_number ?? body.order_number ?? 1);
                        const duty_title = String(body.duty_title || body.title || "").trim();
                        const duty_description = String(body.duty_description || body.description || "").trim();

                        if (!waka_type || !duty_title) {
                            return errorResponse("Bidang Waka dan teks butir tugas wajib diisi", 400, request);
                        }

                        const validTypes = ['kurikulum', 'kesiswaan', 'sarpras', 'humas'];
                        const normalizedType = String(waka_type).toLowerCase().trim();
                        if (!validTypes.includes(normalizedType)) {
                            return errorResponse("Bidang Waka tidak valid. Pilihan: kurikulum, kesiswaan, sarpras, humas", 400, request);
                        }

                        await env.DB.prepare(`
                            INSERT INTO waka_duty_items (
                                id, waka_type, duty_number, duty_title, duty_description, is_active, created_at, updated_at
                            ) VALUES (?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))
                            ON CONFLICT(id) DO UPDATE SET
                                waka_type = excluded.waka_type,
                                duty_number = excluded.duty_number,
                                duty_title = excluded.duty_title,
                                duty_description = excluded.duty_description,
                                is_active = excluded.is_active,
                                updated_at = datetime('now')
                        `).bind(
                            id, normalizedType, Number(duty_number || 1), duty_title, duty_description,
                            Number(is_active) === 0 ? 0 : 1
                        ).run();

                        await recordWorkloadAuditLog(
                            env.DB, "waka_duty_items", id, "UPSERT_WAKA_DUTY_ITEM",
                            authResult.user.uid, authResult.user.name || authResult.user.email,
                            { id, waka_type: normalizedType, duty_number, duty_title, is_active }
                        );

                        return jsonResponse({
                            success: true,
                            message: "Butir tugas waka berhasil disimpan",
                            data: {
                                id,
                                waka_type: normalizedType,
                                duty_number,
                                order_number: duty_number,
                                duty_title,
                                title: duty_title,
                                duty_description,
                                description: duty_description,
                                is_active
                            }
                        }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal menyimpan butir tugas waka: " + err.message, 500, request);
                    }
                }

                return errorResponse("Method tidak didukung", 405, request);
            }

            // 4. GET, POST, DELETE /api/workload/templates
            if (path.startsWith("/api/workload/templates")) {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                const isMgr = isWorkloadManager(authResult.user);

                if (method === "GET") {
                    try {
                        const qTeacherId = url.searchParams.get("teacher_id");
                        const targetTeacherId = isMgr && qTeacherId ? qTeacherId : userTeacherId;

                        const templates = await env.DB.prepare(`
                            SELECT * FROM weekly_templates WHERE teacher_id = ? ORDER BY is_default DESC, created_at DESC
                        `).bind(targetTeacherId).all();

                        const templateList = templates.results || [];
                        const templateIds = templateList.map(t => t.id);

                        let itemsMap = {};
                        if (templateIds.length > 0) {
                            const placeholders = templateIds.map(() => "?").join(",");
                            const itemsRes = await env.DB.prepare(`
                                SELECT ti.*, c.name AS catalog_name, c.category_code
                                FROM weekly_template_items ti
                                LEFT JOIN activity_catalog c ON ti.catalog_id = c.id
                                WHERE ti.template_id IN (${placeholders})
                                ORDER BY ti.day_of_week ASC, ti.start_time ASC
                            `).bind(...templateIds).all();

                            (itemsRes.results || []).forEach(it => {
                                if (!itemsMap[it.template_id]) itemsMap[it.template_id] = [];
                                itemsMap[it.template_id].push(it);
                            });
                        }

                        const result = templateList.map(t => ({
                            ...t,
                            items: itemsMap[t.id] || []
                        }));

                        return jsonResponse({ success: true, data: result }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal mengambil template mingguan: " + err.message, 500, request);
                    }
                }

                if (method === "POST") {
                    try {
                        const body = await request.json();
                        await ensureWorkloadActivityCatalog(env.DB);

                        const {
                            id = crypto.randomUUID(),
                            teacher_id,
                            template_name,
                            is_default = 0,
                            items = []
                        } = body;

                        const finalTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user, teacher_id);

                        if (!isMgr && finalTeacherId !== userTeacherId) {
                            return errorResponse("Akses ditolak: Anda hanya dapat membuat template untuk diri sendiri", 403, request);
                        }

                        if (!template_name || !String(template_name).trim()) {
                            return errorResponse("Nama template wajib diisi", 400, request);
                        }

                        // Hitung total estimasi menit dari items
                        let totalMinutes = 0;
                        items.forEach(it => {
                            const m = calculateEffectiveMinutesWl(it.start_time, it.end_time);
                            totalMinutes += m;
                        });

                        const batchStatements = [];

                        // Jika dijadikan default, non-aktifkan default lain
                        if (is_default) {
                            batchStatements.push(env.DB.prepare(`
                                UPDATE weekly_templates SET is_default = 0 WHERE teacher_id = ?
                            `).bind(finalTeacherId));
                        }

                        batchStatements.push(env.DB.prepare(`
                            INSERT INTO weekly_templates (id, teacher_id, template_name, is_default, total_estimated_minutes, created_at, updated_at)
                            VALUES (?, ?, ?, ?, ?, datetime('now'), datetime('now'))
                            ON CONFLICT(id) DO UPDATE SET
                                template_name = excluded.template_name,
                                is_default = excluded.is_default,
                                total_estimated_minutes = excluded.total_estimated_minutes,
                                updated_at = datetime('now')
                        `).bind(id, finalTeacherId, String(template_name).trim(), is_default ? 1 : 0, totalMinutes));

                        // Hapus item lama dan masukkan item baru secara atomik
                        batchStatements.push(env.DB.prepare("DELETE FROM weekly_template_items WHERE template_id = ?").bind(id));

                        for (const it of items) {
                            const estMin = calculateEffectiveMinutesWl(it.start_time, it.end_time);
                            const catId = it.catalog_id || "cat_kbm";
                            batchStatements.push(env.DB.prepare(`
                                INSERT INTO weekly_template_items (
                                    id, template_id, day_of_week, catalog_id, title,
                                    start_time, end_time, estimated_minutes, is_teaching, jp_count, description, created_at
                                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
                            `).bind(
                                crypto.randomUUID(), id, Number(it.day_of_week), catId,
                                it.title || "Kegiatan KBM", it.start_time, it.end_time,
                                estMin, it.is_teaching ? 1 : 0, Number(it.jp_count || 0), it.description || ""
                            ));
                        }

                        await env.DB.batch(batchStatements);

                        return jsonResponse({ success: true, message: "Template berhasil disimpan", data: { id, total_estimated_minutes: totalMinutes } }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal menyimpan template mingguan: " + err.message, 500, request);
                    }
                }

                if (method === "DELETE") {
                    const templateId = path.replace("/api/workload/templates/", "").trim();
                    if (!templateId) return errorResponse("ID template diperlukan", 400, request);
                    try {
                        const existing = await env.DB.prepare("SELECT * FROM weekly_templates WHERE id = ?").bind(templateId).first();
                        if (!existing) return errorResponse("Template tidak ditemukan", 404, request);
                        if (!isMgr && !isWorkloadOwner(existing.teacher_id, authResult.user, userTeacherId)) {
                            return errorResponse("Akses ditolak: Anda tidak berhak menghapus template ini", 403, request);
                        }
                        await env.DB.prepare("DELETE FROM weekly_templates WHERE id = ?").bind(templateId).run();
                        return jsonResponse({ success: true, message: "Template berhasil dihapus" }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal menghapus template: " + err.message, 500, request);
                    }
                }

                return errorResponse("Method tidak didukung", 405, request);
            }

            // 5. POST /api/workload/week/initialize (Inisialisasi atomik & idempotent)
            if (path === "/api/workload/week/initialize" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                const isMgr = isWorkloadManager(authResult.user);

                try {
                    const body = await request.json();
                    const {
                        teacher_id,
                        week_start_date,
                        academic_year = "2026/2027",
                        semester = "1"
                    } = body;

                    const finalTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user, teacher_id);

                    if (!week_start_date) return errorResponse("Tanggal awal minggu (week_start_date) diperlukan", 400, request);
                    if (!isMgr && finalTeacherId !== userTeacherId) {
                        return errorResponse("Akses ditolak: Anda hanya dapat menginisialisasi minggu kerja Anda sendiri", 403, request);
                    }

                    // Cek apakah work_weeks sudah ada
                    let existingWeek = await env.DB.prepare(`
                        SELECT * FROM work_weeks WHERE teacher_id = ? AND week_start_date = ? LIMIT 1
                    `).bind(finalTeacherId, week_start_date).first();

                    if (existingWeek) {
                        const activeVersion = await env.DB.prepare(`
                            SELECT * FROM weekly_plan_versions
                            WHERE work_week_id = ?
                            ORDER BY version_number DESC LIMIT 1
                        `).bind(existingWeek.id).first();

                        return jsonResponse({
                            success: true,
                            message: "Minggu kerja sudah ada",
                            data: {
                                work_week: existingWeek,
                                plan_version: activeVersion
                            }
                        }, 200, request);
                    }

                    // Ambil policy kerja aktif
                    let activePolicy = await env.DB.prepare("SELECT * FROM school_work_policies WHERE is_active = 1 LIMIT 1").first();
                    if (!activePolicy) {
                        const defaultPolicyId = "policy_smagesa_default";
                        await env.DB.prepare(`
                            INSERT OR IGNORE INTO school_work_policies (
                                id, school_id, policy_name, work_days_count, normal_daily_minutes,
                                normal_weekly_minutes, work_start_time, work_end_time, effective_from, is_active
                            ) VALUES (?, 'smagesa', 'Kebijakan Standar 5 Hari Sekolah (Permendikbudristek)', 5, 450, 2250, '07:30', '15:30', '2026-07-01', 1)
                        `).bind(defaultPolicyId).run();
                        activePolicy = { id: defaultPolicyId };
                    }
                    const policyId = activePolicy ? activePolicy.id : "policy_smagesa_default";
                    const workWeekId = crypto.randomUUID();
                    const planVersionId = crypto.randomUUID();

                    // Hitung week_end_date (Senin + 4 hari = Jumat)
                    const startDateObj = new Date(week_start_date + "T00:00:00Z");
                    const endDateObj = new Date(startDateObj.getTime() + 4 * 24 * 60 * 60 * 1000);
                    const weekEndDate = body.week_end_date || endDateObj.toISOString().slice(0, 10);

                    // Insert work_weeks sesuai SSOT skema D1 (tanpa kolom fiktif week_number, isi week_end_date dan active_plan_version_id)
                    await env.DB.prepare(`
                        INSERT INTO work_weeks (
                            id, teacher_id, school_id, week_start_date, week_end_date,
                            academic_year, semester, policy_id, target_minutes, active_plan_version_id,
                            is_locked, created_at, updated_at
                        ) VALUES (?, ?, 'smagesa', ?, ?, ?, ?, ?, 2250, ?, 0, datetime('now'), datetime('now'))
                    `).bind(
                        workWeekId, finalTeacherId, week_start_date, weekEndDate,
                        academic_year, semester, policyId, planVersionId
                    ).run();

                    await env.DB.prepare(`
                        INSERT INTO weekly_plan_versions (
                            id, work_week_id, version_number, status, revision_lock,
                            total_planned_minutes, created_at, updated_at
                        ) VALUES (?, ?, 1, 'draft', 1, 0, datetime('now'), datetime('now'))
                    `).bind(planVersionId, workWeekId).run();

                    return jsonResponse({
                        success: true,
                        message: "Minggu kerja dan draft rencana berhasil diinisialisasi",
                        data: {
                            work_week_id: workWeekId,
                            plan_version_id: planVersionId,
                            version_number: 1,
                            revision_lock: 1
                        }
                    }, 200, request);
                } catch (err) {
                    return errorResponse("Gagal menginisialisasi minggu kerja: " + err.message, 500, request);
                }
            }

            // Penetapan HBG berlaku untuk satu versi milik guru yang bersangkutan.
            if (path === "/api/workload/study-day" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized", 401, request);
                const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                try {
                    const { work_week_id, plan_version_id, revision_lock, manual_day_index } = await request.json();
                    if (!work_week_id || !plan_version_id || !Number.isInteger(revision_lock) ||
                        !(manual_day_index === null || (Number.isInteger(manual_day_index) && manual_day_index >= 0 && manual_day_index <= 4))) {
                        return errorResponse("Minggu, versi, revision lock dan pilihan hari (0–4 atau null untuk otomatis) diperlukan", 400, request);
                    }
                    const week = await env.DB.prepare('SELECT * FROM work_weeks WHERE id = ?').bind(work_week_id).first();
                    const version = await env.DB.prepare('SELECT * FROM weekly_plan_versions WHERE id = ? AND work_week_id = ?').bind(plan_version_id, work_week_id).first();
                    if (!week || !version) return errorResponse("Rencana kerja tidak ditemukan", 404, request);
                    if (!isWorkloadManager(authResult.user) && !isWorkloadOwner(week.teacher_id, authResult.user, userTeacherId)) return errorResponse("Akses ditolak", 403, request);
                    if (week.is_locked === 1 || !['draft', 'needs_revision'].includes(version.status)) return errorResponse("Hari belajar hanya dapat diubah pada rencana draf atau perlu revisi", 403, request);
                    if (version.revision_lock !== revision_lock) return errorResponse("Rencana telah diperbarui. Muat ulang sebelum mengubah hari belajar.", 409, request);
                    const segments = await env.DB.prepare(`SELECT pts.*, pa.catalog_id, pa.category_code, pa.title AS activity_title
                        FROM plan_time_segments pts JOIN plan_activities pa ON pa.id = pts.activity_id WHERE pts.plan_version_id = ?`).bind(version.id).all();
                    const studyDay = await resolveWorkloadStudyDay(env.DB, week, version, segments.results || [], manual_day_index, env);
                    await env.DB.prepare(WORKLOAD_STUDY_DAY_SCHEMA).run();
                    const writes = await env.DB.batch([
                        env.DB.prepare(`UPDATE weekly_plan_versions SET revision_lock = revision_lock + 1, updated_at = datetime('now')
                            WHERE id = ? AND work_week_id = ? AND revision_lock = ? AND status IN ('draft', 'needs_revision')
                            AND EXISTS (SELECT 1 FROM work_weeks WHERE id = ? AND is_locked = 0)`)
                            .bind(version.id, week.id, revision_lock, week.id),
                        workloadStudyDayStatement(env.DB, version.id, studyDay, authResult.user.uid, manual_day_index)
                    ]);
                    if (!writes[0].meta?.changes) return errorResponse("Rencana telah diperbarui. Muat ulang sebelum mengubah hari belajar.", 409, request);
                    return jsonResponse({ success: true, data: { study_day: studyDay, revision_lock: revision_lock + 1 } }, 200, request);
                } catch (error) {
                    return errorResponse("Gagal menyimpan Hari Belajar Guru: " + error.message, 500, request);
                }
            }

            // 6. GET /api/workload/week (Murni Read-Only, Uji 17)
            if (path === "/api/workload/week" && method === "GET") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                const isMgr = isWorkloadManager(authResult.user);
                const qTeacherId = url.searchParams.get("teacher_id");
                const weekStartDate = url.searchParams.get("week_start_date");

                if (!weekStartDate) return errorResponse("Parameter week_start_date (YYYY-MM-DD) diperlukan", 400, request);

                const targetTeacherId = isMgr && qTeacherId ? (await resolveWorkloadTeacherId(env.DB, authResult.user, qTeacherId)) : userTeacherId;
                if (!isMgr && targetTeacherId !== userTeacherId) {
                    return errorResponse("Akses ditolak: Anda hanya dapat melihat data beban kerja Anda sendiri", 403, request);
                }

                try {
                    const week = await env.DB.prepare(`
                        SELECT ww.*, g.name AS teacher_name, g.nip AS teacher_nip, g.jenis_ptk, g.foto AS teacher_foto
                        FROM work_weeks ww
                        LEFT JOIN gtk g ON ww.teacher_id = g.id
                        WHERE ww.teacher_id = ? AND ww.week_start_date = ?
                        LIMIT 1
                    `).bind(targetTeacherId, weekStartDate).first();

                    if (!week) {
                        const gtkRow = await env.DB.prepare("SELECT name, nip, jenis_ptk, foto FROM gtk WHERE id = ?").bind(targetTeacherId).first();
                        // Belum diinisialisasi. Kembalikan respons murni read-only tanpa efek samping mutasi (Uji 17)
                        return jsonResponse({
                            success: true,
                            data: {
                                initialized: false,
                                teacher_id: targetTeacherId,
                                teacher_name: gtkRow?.name || targetTeacherId,
                                teacher_nip: gtkRow?.nip || "-",
                                teacher_foto: gtkRow?.foto || null,
                                week_start_date: weekStartDate,
                                study_day: await readWorkloadStudyDayResolution(env.DB, { teacher_id: targetTeacherId, week_start_date: weekStartDate }, null, [], env)
                            }
                        }, 200, request);
                    }

                    // Ambil versi-versi rencana
                    const versionsRes = await env.DB.prepare(`
                        SELECT * FROM weekly_plan_versions WHERE work_week_id = ? ORDER BY version_number ASC
                    `).bind(week.id).all();
                    const versions = versionsRes.results || [];

                    // Tentukan versi aktif yang akan ditampilkan:
                    // Jika ada versi draft/needs_revision/submitted terbaru, tampilkan itu untuk guru.
                    // Jika untuk reviewer, jika ada versi submitted, prioritaskan itu.
                    const latestVersion = versions[versions.length - 1] || null;
                    const approvedVersion = versions.find(v => v.id === week.active_plan_version_id) || null;
                    const activeVersion = latestVersion;

                    let activities = [];
                    let segments = [];
                    if (activeVersion) {
                        const segRes = await env.DB.prepare(`
                            SELECT pts.*, pa.title AS activity_title, pa.catalog_id, pa.category_code,
                                pa.origin_source, pa.schedule_occurrence_id, pa.assignment_id,
                                c.name AS catalog_name,
                                (SELECT COUNT(*) FROM plan_log_links pll WHERE pll.plan_activity_id = pa.id) AS has_realized_log
                            FROM plan_time_segments pts
                            JOIN plan_activities pa ON pts.activity_id = pa.id
                            LEFT JOIN activity_catalog c ON pa.catalog_id = c.id
                            WHERE pts.plan_version_id = ?
                            ORDER BY pts.date ASC, pts.start_time ASC
                        `).bind(activeVersion.id).all();
                        segments = segRes.results || [];

                        const actRes = await env.DB.prepare(`
                            SELECT pa.*, c.name AS catalog_name
                            FROM plan_activities pa
                            LEFT JOIN activity_catalog c ON pa.catalog_id = c.id
                            WHERE pa.work_week_id = ?
                        `).bind(week.id).all();
                        activities = actRes.results || [];
                    }

                    // Ambil seluruh logs realisasi di minggu tersebut
                    const logsRes = await env.DB.prepare(`
                        SELECT wl.*, c.name AS catalog_name, c.category_code
                        FROM work_logs wl
                        LEFT JOIN activity_catalog c ON wl.catalog_id = c.id
                        WHERE wl.work_week_id = ?
                        ORDER BY wl.date ASC, wl.created_at ASC
                    `).bind(week.id).all();
                    const logs = logsRes.results || [];

                    // Ambil log segments dan links
                    let logSegments = [];
                    let planLinks = [];
                    if (logs.length > 0) {
                        const segRes = await env.DB.prepare(`
                            SELECT wls.* FROM work_log_segments wls
                            JOIN work_logs wl ON wls.work_log_id = wl.id
                            WHERE wl.work_week_id = ?
                            ORDER BY wls.start_time ASC
                        `).bind(week.id).all();
                        logSegments = segRes.results || [];

                        const linkRes = await env.DB.prepare(`
                            SELECT pll.* FROM plan_log_links pll
                            JOIN work_logs wl ON pll.work_log_id = wl.id
                            WHERE wl.work_week_id = ?
                        `).bind(week.id).all();
                        planLinks = linkRes.results || [];
                    }

                    // Petakan durasi aktual segmen riil ke masing-masing objek logs
                    const logSegDurationMap = {};
                    logSegments.forEach(ls => {
                        logSegDurationMap[ls.work_log_id] = (logSegDurationMap[ls.work_log_id] || 0) + Number(ls.actual_minutes || 0);
                    });
                    logs.forEach(l => {
                        l.actual_minutes = logSegDurationMap[l.id] !== undefined ? logSegDurationMap[l.id] : 0;
                    });

                    // Agregasi Durasi Akurat (SSOT):
                    // Total Rencana = jumlah planned_minutes dari activeVersion (atau total_planned_minutes)
                    const totalPlannedMinutes = segments.reduce((sum, s) => sum + Number(s.planned_minutes || 0), 0);

                    // Total Aktual = SUM actual_minutes dari work_log_segments unik (mencegah duplikasi JOIN, Uji 11 & Uji 10)
                    const totalActualMinutes = logSegments.reduce((sum, s) => sum + Number(s.actual_minutes || 0), 0);

                    // Total Jam Mengajar Tatap Muka (JP)
                    const totalTeachingJp = segments
                        .filter(s => s.is_teaching === 1 || s.is_teaching === true || s.catalog_id === "cat_kbm" || s.category_code === "PELAKSANAAN_KBM")
                        .reduce((sum, s) => sum + (Number(s.jp_count) || Math.round(Number(s.planned_minutes || 45) / 45) || 1), 0);

                    // Total Terverifikasi = subset dari log terverifikasi (Uji 37)
                    const verifiedLogIds = new Set(logs.filter(l => l.verification_status === "verified").map(l => l.id));
                    const totalVerifiedMinutes = logSegments
                        .filter(s => verifiedLogIds.has(s.work_log_id))
                        .reduce((sum, s) => sum + Number(s.actual_minutes || 0), 0);

                    return jsonResponse({
                        success: true,
                        data: {
                            initialized: true,
                            week,
                            versions,
                            active_version: activeVersion,
                            study_day: await readWorkloadStudyDayResolution(env.DB, week, activeVersion, segments, env),
                            approved_version: approvedVersion,
                            activities,
                            segments,
                            logs,
                            log_segments: logSegments,
                            plan_links: planLinks,
                            summary: {
                                target_minutes: 2250,
                                planned_minutes: totalPlannedMinutes,
                                actual_minutes: totalActualMinutes,
                                verified_minutes: totalVerifiedMinutes,
                                teaching_jp: totalTeachingJp,
                                status_rencana: activeVersion ? activeVersion.status : "draft"
                            }
                        }
                    }, 200, request);
                } catch (err) {
                    return errorResponse("Gagal mengambil rincian minggu kerja: " + err.message, 500, request);
                }
            }

            // 7. POST & DELETE /api/workload/plan-items (Optimistic Locking & Overlap Check)
            if (path.startsWith("/api/workload/plan-items")) {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                const isMgr = isWorkloadManager(authResult.user);

                if (method === "POST") {
                    try {
                        const body = await request.json();
                        await ensureWorkloadActivityCatalog(env.DB);
                        const {
                            work_week_id,
                            plan_version_id,
                            revision_lock,
                            items = [],
                            clear_date
                        } = body;

                        if (!work_week_id || !plan_version_id) {
                            return errorResponse("work_week_id dan plan_version_id diperlukan", 400, request);
                        }

                        // Verifikasi kepemilikan dan status versi
                        const version = await env.DB.prepare(`
                            SELECT pv.*, ww.teacher_id, ww.is_locked
                            FROM weekly_plan_versions pv
                            JOIN work_weeks ww ON pv.work_week_id = ww.id
                            WHERE pv.id = ? AND pv.work_week_id = ?
                            LIMIT 1
                        `).bind(plan_version_id, work_week_id).first();

                        if (!version) return errorResponse("Versi rencana kerja tidak ditemukan", 404, request);
                        if (!isMgr && version.teacher_id !== userTeacherId) {
                            return errorResponse("Akses ditolak: Anda hanya dapat menyunting rencana kerja Anda sendiri", 403, request);
                        }
                        if (version.is_locked === 1) {
                            return errorResponse("Minggu kerja telah dikunci oleh pimpinan", 403, request);
                        }
                        if (!["draft", "needs_revision"].includes(version.status)) {
                            return errorResponse(`Rencana kerja dalam status '${version.status}' tidak dapat diubah`, 400, request);
                        }

                        // Optimistic Concurrency Control (Uji 33)
                        if (revision_lock !== undefined && Number(revision_lock) !== Number(version.revision_lock)) {
                            return errorResponse("Data rencana telah diperbarui oleh sesi lain. Silakan muat ulang halaman sebelum menyimpan perubahan.", 409, request);
                        }

                        // Validasi Benturan Jam Kerja pada hari yang sama (Uji 4 & Uji 34 & Anti-Overlap Mandate)
                        // Muat segmen yang sudah ada di DB untuk versi rencana ini
                        const existingDbSegsRes = await env.DB.prepare(`
                            SELECT pts.id, pts.activity_id, pts.date, pts.day_of_week, pts.start_time, pts.end_time, pa.title
                            FROM plan_time_segments pts
                            JOIN plan_activities pa ON pts.activity_id = pa.id
                            WHERE pts.plan_version_id = ?
                        `).bind(plan_version_id).all();
                        const dbSegs = existingDbSegsRes?.results || [];

                        const updatingItemIds = new Set(items.map(it => it.id).filter(Boolean));
                        const updatingActIds = new Set(items.map(it => it.activity_id).filter(Boolean));

                        const itemsByDate = {};
                        // Masukkan segmen yang sudah ada di DB (yang tidak sedang di-update dan tidak dibersihkan via clear_date)
                        dbSegs.forEach(seg => {
                            if (clear_date && seg.date === clear_date) return;
                            if (updatingItemIds.has(seg.id) || updatingActIds.has(seg.activity_id)) return;
                            const d = seg.date || `day_${seg.day_of_week}`;
                            if (!itemsByDate[d]) itemsByDate[d] = [];
                            itemsByDate[d].push({
                                id: seg.id,
                                date: seg.date,
                                day_of_week: seg.day_of_week,
                                start_time: seg.start_time,
                                end_time: seg.end_time,
                                title: seg.title
                            });
                        });

                        // Tambahkan item yang sedang dikirim
                        items.forEach(it => {
                            const d = it.date || `day_${it.day_of_week}`;
                            if (!itemsByDate[d]) itemsByDate[d] = [];
                            itemsByDate[d].push(it);
                        });

                        for (const dateKey in itemsByDate) {
                            const overlapCheck = validateSegmentsNoOverlapWl(itemsByDate[dateKey]);
                            if (!overlapCheck.valid) {
                                return errorResponse(overlapCheck.message, 422, request);
                            }
                        }

                        // Jika diminta pembersihan hari (misal saat menandai Cuti/Izin seharian penuh), bersihkan segmen lama secara atomik
                        if (clear_date) {
                            const segsToClear = await env.DB.prepare(`
                                SELECT pts.id, pts.activity_id,
                                       (SELECT COUNT(*) FROM plan_log_links pll WHERE pll.plan_activity_id = pts.activity_id) AS has_log
                                FROM plan_time_segments pts
                                WHERE pts.plan_version_id = ? AND pts.date = ?
                            `).bind(plan_version_id, clear_date).all();

                            const clearResults = segsToClear?.results || [];
                            const actIdsToCheck = new Set();
                            for (const s of clearResults) {
                                if (s.has_log === 0 && !updatingItemIds.has(s.id)) {
                                    await env.DB.prepare("DELETE FROM plan_time_segments WHERE id = ?").bind(s.id).run();
                                    if (s.activity_id) actIdsToCheck.add(s.activity_id);
                                }
                            }
                            for (const actId of actIdsToCheck) {
                                const remaining = await env.DB.prepare("SELECT COUNT(*) AS c FROM plan_time_segments WHERE activity_id = ?").bind(actId).first();
                                if (!remaining || remaining.c === 0) {
                                    await env.DB.prepare("DELETE FROM plan_activities WHERE id = ?").bind(actId).run();
                                }
                            }
                        }

                        // Simpan items: Buat entitas aktivitas stabil (plan_activities) dan slot waktu (plan_time_segments)
                        let newTotalPlannedMinutes = 0;
                        for (const it of items) {
                            let activityId = it.activity_id;
                            if (!activityId && it.id) {
                                const existingSegRow = await env.DB.prepare("SELECT activity_id FROM plan_time_segments WHERE id = ?").bind(it.id).first();
                                if (existingSegRow && existingSegRow.activity_id) {
                                    activityId = existingSegRow.activity_id;
                                }
                            }
                            if (activityId) {
                                // Proteksi Integritas: Kegiatan yang telah memiliki laporan realisasi dilarang keras disunting
                                const hasLogLink = await env.DB.prepare(`
                                    SELECT COUNT(*) AS c FROM plan_log_links WHERE plan_activity_id = ?
                                `).bind(activityId).first();
                                if (hasLogLink && hasLogLink.c > 0) {
                                    return errorResponse("Akses ditolak: Kegiatan rencana yang telah direalisasikan tidak dapat disunting atau diubah jadwalnya", 422, request);
                                }

                                await env.DB.prepare(`
                                    UPDATE plan_activities SET
                                        catalog_id = ?,
                                        assignment_id = ?,
                                        title = ?,
                                        category_code = ?
                                    WHERE id = ?
                                `).bind(
                                    it.catalog_id || "cat_kbm",
                                    it.assignment_id || null,
                                    it.title || "Kegiatan KBM",
                                    it.category_code || "PELAKSANAAN_KBM",
                                    activityId
                                ).run();
                            } else {
                                const isLeaveItem = it.catalog_id === 'cat_cuti_izin' || it.category_code === 'CUTI_IZIN' || it.is_leave === 1 || it.is_leave === true;
                                activityId = crypto.randomUUID();
                                await env.DB.prepare(`
                                    INSERT INTO plan_activities (
                                        id, work_week_id, catalog_id, assignment_id, title,
                                        category_code, origin_source, schedule_occurrence_id, created_at
                                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
                                `).bind(
                                    activityId, work_week_id, it.catalog_id || (isLeaveItem ? "cat_cuti_izin" : "cat_kbm"),
                                    it.assignment_id || null, it.title || (isLeaveItem ? "Cuti / Izin" : "Kegiatan KBM"),
                                    it.category_code || (isLeaveItem ? "CUTI_IZIN" : "PELAKSANAAN_KBM"), it.origin_source || "manual",
                                    it.schedule_occurrence_id || null
                                ).run();
                            }

                            const isLeaveItem = it.catalog_id === 'cat_cuti_izin' || it.category_code === 'CUTI_IZIN' || it.is_leave === 1 || it.is_leave === true;
                            const plannedMinutes = isLeaveItem ? 0 : calculateEffectiveMinutesWl(it.start_time, it.end_time);
                            newTotalPlannedMinutes += plannedMinutes;

                            const segmentId = it.id || crypto.randomUUID();
                            await env.DB.prepare(`
                                INSERT INTO plan_time_segments (
                                    id, plan_version_id, activity_id, date, day_of_week,
                                    start_time, end_time, planned_minutes, is_teaching, jp_count, description, created_at
                                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
                                ON CONFLICT(id) DO UPDATE SET
                                    date = excluded.date,
                                    day_of_week = excluded.day_of_week,
                                    start_time = excluded.start_time,
                                    end_time = excluded.end_time,
                                    planned_minutes = excluded.planned_minutes,
                                    is_teaching = excluded.is_teaching,
                                    jp_count = excluded.jp_count,
                                    description = excluded.description
                            `).bind(
                                segmentId, plan_version_id, activityId, it.date,
                                Number(it.day_of_week), it.start_time, it.end_time,
                                plannedMinutes, it.is_teaching ? 1 : 0, Number(it.jp_count || 0), it.description || ""
                            ).run();
                        }

                        // Hitung ulang total durasi dari seluruh segmen di versi tersebut
                        const allSegs = await env.DB.prepare(`
                            SELECT SUM(planned_minutes) AS total FROM plan_time_segments WHERE plan_version_id = ?
                        `).bind(plan_version_id).first();

                        const totalPlanM = allSegs ? (allSegs.total || 0) : newTotalPlannedMinutes;

                        await env.DB.prepare(`
                            UPDATE weekly_plan_versions
                            SET total_planned_minutes = ?, updated_at = datetime('now')
                            WHERE id = ?
                        `).bind(totalPlanM, plan_version_id).run();

                        return jsonResponse({
                            success: true,
                            message: "Item rencana berhasil disimpan",
                            data: {
                                total_planned_minutes: totalPlanM,
                                revision_lock: version.revision_lock
                            }
                        }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal menyimpan item rencana: " + err.message, 500, request);
                    }
                }

                if (method === "DELETE") {
                    const segmentId = path.replace("/api/workload/plan-items/", "").trim();
                    if (!segmentId) return errorResponse("ID segmen rencana diperlukan", 400, request);

                    try {
                        const seg = await env.DB.prepare(`
                            SELECT pts.*, pv.status, pv.work_week_id, ww.teacher_id, ww.is_locked
                            FROM plan_time_segments pts
                            JOIN weekly_plan_versions pv ON pts.plan_version_id = pv.id
                            JOIN work_weeks ww ON pv.work_week_id = ww.id
                            WHERE pts.id = ?
                            LIMIT 1
                        `).bind(segmentId).first();

                        if (!seg) return errorResponse("Item rencana tidak ditemukan", 404, request);
                        if (!isMgr && !isWorkloadOwner(seg.teacher_id, authResult.user, userTeacherId)) {
                            return errorResponse("Akses ditolak: Anda tidak berhak menghapus item rencana ini", 403, request);
                        }
                        if (seg.is_locked === 1) return errorResponse("Minggu kerja telah dikunci", 403, request);
                        if (!["draft", "needs_revision"].includes(seg.status)) {
                            return errorResponse(`Item tidak dapat dihapus dalam status '${seg.status}'`, 400, request);
                        }

                        // Proteksi Integritas: Kegiatan yang telah memiliki laporan realisasi dilarang keras dihapus
                        const hasLogLink = await env.DB.prepare(`
                            SELECT COUNT(*) AS c FROM plan_log_links WHERE plan_activity_id = ?
                        `).bind(seg.activity_id).first();
                        if (hasLogLink && hasLogLink.c > 0) {
                            return errorResponse("Akses ditolak: Kegiatan rencana yang telah direalisasikan tidak dapat dihapus", 422, request);
                        }

                        await env.DB.prepare("DELETE FROM plan_time_segments WHERE id = ?").bind(segmentId).run();

                        // Periksa apakah aktivitas masih punya segmen lain
                        const remaining = await env.DB.prepare("SELECT COUNT(*) AS c FROM plan_time_segments WHERE activity_id = ?").bind(seg.activity_id).first();
                        if (!remaining || remaining.c === 0) {
                            await env.DB.prepare("DELETE FROM plan_activities WHERE id = ?").bind(seg.activity_id).run();
                        }

                        // Update total menit versi
                        const allSegs = await env.DB.prepare(`
                            SELECT SUM(planned_minutes) AS total FROM plan_time_segments WHERE plan_version_id = ?
                        `).bind(seg.plan_version_id).first();
                        const updatedTotal = allSegs ? (allSegs.total || 0) : 0;

                        await env.DB.prepare(`
                            UPDATE weekly_plan_versions SET total_planned_minutes = ?, updated_at = datetime('now') WHERE id = ?
                        `).bind(updatedTotal, seg.plan_version_id).run();

                        return jsonResponse({ success: true, message: "Item rencana berhasil dihapus", total_planned_minutes: updatedTotal }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal menghapus item rencana: " + err.message, 500, request);
                    }
                }

                return errorResponse("Method tidak didukung", 405, request);
            }

            // 8. POST /api/workload/apply-template (Uji 15: Tidak menyalin status/realisasi)
            if (path === "/api/workload/apply-template" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                const isMgr = isWorkloadManager(authResult.user);

                try {
                    const body = await request.json();
                    await ensureWorkloadActivityCatalog(env.DB);
                    const { work_week_id, plan_version_id, template_id, revision_lock, replace_existing = true } = body;
                    if (!work_week_id || !plan_version_id || !template_id) {
                        return errorResponse("work_week_id, plan_version_id, dan template_id wajib diisi", 400, request);
                    }

                    const version = await env.DB.prepare(`
                        SELECT pv.*, ww.teacher_id, ww.week_start_date, ww.is_locked
                        FROM weekly_plan_versions pv
                        JOIN work_weeks ww ON pv.work_week_id = ww.id
                        WHERE pv.id = ? AND pv.work_week_id = ?
                        LIMIT 1
                    `).bind(plan_version_id, work_week_id).first();

                    if (!version) return errorResponse("Versi rencana kerja tidak ditemukan", 404, request);
                    if (!isMgr && !isWorkloadOwner(version.teacher_id, authResult.user, userTeacherId)) {
                        return errorResponse("Akses ditolak: Anda hanya dapat menyusun rencana kerja Anda sendiri", 403, request);
                    }
                    if (version.is_locked === 1) return errorResponse("Minggu kerja telah dikunci", 403, request);
                    if (!["draft", "needs_revision"].includes(version.status)) {
                        return errorResponse(`Rencana kerja dalam status '${version.status}' tidak dapat diubah`, 400, request);
                    }
                    if (version.submitted_at) {
                        return errorResponse("Penerapan template ditolak: Rencana kerja minggu ini sudah pernah difinalisasi sebelumnya", 403, request);
                    }

                    if (revision_lock !== undefined && Number(revision_lock) !== Number(version.revision_lock)) {
                        return errorResponse("Data rencana telah diperbarui oleh sesi lain. Silakan muat ulang halaman.", 409, request);
                    }

                    const templateItemsRes = await env.DB.prepare(`
                        SELECT ti.*, c.category_code AS catalog_category_code
                        FROM weekly_template_items ti
                        LEFT JOIN activity_catalog c ON ti.catalog_id = c.id
                        WHERE ti.template_id = ?
                        ORDER BY ti.day_of_week ASC, ti.start_time ASC
                    `).bind(template_id).all();
                    const tItems = templateItemsRes.results || [];

                    if (tItems.length === 0) {
                        return errorResponse("Template ini tidak memiliki butir kegiatan", 400, request);
                    }

                    // Smart Diffing Engine: Bandingkan butir template dengan rencana yang sudah ada di D1
                    // 1. Ambil seluruh segmen dan aktivitas eksisting pada versi draf ini beserta status realisasinya (has_log)
                    const existingSegsRes = await env.DB.prepare(`
                        SELECT pts.id AS segment_id, pts.date, pts.day_of_week, pts.start_time, pts.end_time,
                               pts.is_teaching, pts.jp_count, pts.description, pts.planned_minutes,
                               pa.id AS activity_id, pa.catalog_id, pa.title, pa.category_code, pa.origin_source,
                               pa.schedule_occurrence_id,
                               (SELECT COUNT(*) FROM plan_log_links pll WHERE pll.plan_activity_id = pa.id) AS has_log
                        FROM plan_time_segments pts
                        JOIN plan_activities pa ON pts.activity_id = pa.id
                        WHERE pts.plan_version_id = ? AND pa.work_week_id = ?
                    `).bind(plan_version_id, work_week_id).all();
                    // Item hasil Sinkron KBM (jadwal resmi aSc) dilindungi seperti item ber-log:
                    // tidak ditimpa/dihapus template agar tetap cocok dengan Jurnal Mengajar
                    const existingSegs = (existingSegsRes.results || []).map(s => (
                        s.schedule_occurrence_id ? { ...s, has_log: Math.max(1, Number(s.has_log || 0)) } : s
                    ));

                    // Hitung tanggal riil untuk tiap hari (day_of_week 1 = Senin = week_start_date)
                    const baseDate = new Date(version.week_start_date);
                    const weekStartStr = String(version.week_start_date).slice(0, 10);
                    const weekStartDateObj = new Date(weekStartStr);
                    const weekEndStr = new Date(weekStartDateObj.getTime() + 4 * 86400000).toISOString().slice(0, 10);

                    // Deteksi tanggal hari libur resmi pada pekan aktif (SSOT: calendar_events D1 + payload holiday_dates)
                    const holidayDatesSet = new Set();
                    if (Array.isArray(body.holiday_dates)) {
                        body.holiday_dates.forEach(d => {
                            if (typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d.trim())) {
                                holidayDatesSet.add(d.trim());
                            }
                        });
                    }
                    try {
                        const calHols = await env.DB.prepare(`
                            SELECT date, time FROM calendar_events
                            WHERE (category = 'libur' OR color = 'rose' OR LOWER(title) LIKE '%libur%')
                              AND (date <= ? AND (time >= ? OR date >= ?))
                        `).bind(weekEndStr, weekStartStr, weekStartStr).all();
                        for (const ch of (calHols.results || [])) {
                            const s = (ch.date || "").substring(0, 10);
                            let e = (ch.time && /^\d{4}-\d{2}-\d{2}$/.test(ch.time)) ? ch.time : s;
                            if (e < s) e = s;
                            for (let cur = new Date(s); cur.toISOString().slice(0, 10) <= e; cur.setDate(cur.getDate() + 1)) {
                                const curStr = cur.toISOString().slice(0, 10);
                                if (curStr >= weekStartStr && curStr <= weekEndStr) {
                                    holidayDatesSet.add(curStr);
                                }
                            }
                        }
                    } catch (e) {
                        console.warn("[apply-template] Gagal query calendar_events:", e.message);
                    }

                    // Deteksi hari yang telah ditandai Cuti/Izin resmi
                    const leaveDatesSet = new Set(
                        existingSegs.filter(s => s.is_leave === 1 || s.catalog_id === 'cat_cuti_izin').map(s => s.date)
                    );

                    const batchStatements = [];
                    const handledSegmentIds = new Set();
                    const matchedActivityIds = new Set();
                    let totalMinutes = 0;
                    let insertedCount = 0;
                    let updatedCount = 0;
                    let skippedCount = 0;
                    let skippedHolidaysCount = 0;
                    let deletedCount = 0;

                    for (const ti of tItems) {
                        const dayOffset = Math.max(0, Number(ti.day_of_week) - 1);
                        const itemDateObj = new Date(baseDate.getTime() + dayOffset * 86400000);
                        const dateStr = itemDateObj.toISOString().slice(0, 10);

                        // Auto-Skip jika hari ini merupakan hari libur resmi atau hari cuti/izin
                        if (holidayDatesSet.has(dateStr) || leaveDatesSet.has(dateStr)) {
                            skippedHolidaysCount++;
                            continue;
                        }

                        const effMin = calculateEffectiveMinutesWl(ti.start_time, ti.end_time);
                        const targetCatalogId = ti.catalog_id || "cat_kbm";
                        const targetTitle = (ti.title || "").trim();
                        const targetJp = Number(ti.jp_count || 0);
                        const targetIsTeaching = ti.is_teaching ? 1 : 0;
                        const targetDesc = (ti.description || "").trim();
                        const targetDutyCode = ti.catalog_category_code || (ti.is_teaching ? "PELAKSANAAN_KBM" : "PERENCANAAN");

                        // Cari apakah ada segmen eksisting pada slot waktu yang sama persis
                        const exactSlotSeg = existingSegs.find(s => 
                            !handledSegmentIds.has(s.segment_id) &&
                            s.date === dateStr &&
                            s.start_time === ti.start_time &&
                            s.end_time === ti.end_time
                        );

                        if (exactSlotSeg) {
                            // Cek apakah kontennya sama persis (Exact Match)
                            const isExactContent = (exactSlotSeg.title || "").trim() === targetTitle &&
                                (exactSlotSeg.catalog_id || "cat_kbm") === targetCatalogId &&
                                Number(exactSlotSeg.jp_count || 0) === targetJp &&
                                (exactSlotSeg.is_teaching ? 1 : 0) === targetIsTeaching;

                            if (isExactContent) {
                                // Skenario 1: Sama persis -> LEWATI (0 write ke DB)
                                handledSegmentIds.add(exactSlotSeg.segment_id);
                                matchedActivityIds.add(exactSlotSeg.activity_id);
                                skippedCount++;
                                totalMinutes += Number(exactSlotSeg.planned_minutes || effMin);
                                continue;
                            }

                            // Skenario 2: Slot waktu sama tetapi konten berbeda
                            if (exactSlotSeg.has_log > 0) {
                                // Lindungi rencana yang sudah memiliki realisasi log
                                handledSegmentIds.add(exactSlotSeg.segment_id);
                                matchedActivityIds.add(exactSlotSeg.activity_id);
                                skippedCount++;
                                totalMinutes += Number(exactSlotSeg.planned_minutes || effMin);
                                continue;
                            }

                            // Belum ada realisasi -> Timpa in-place (UPDATE)
                            handledSegmentIds.add(exactSlotSeg.segment_id);
                            matchedActivityIds.add(exactSlotSeg.activity_id);
                            batchStatements.push(env.DB.prepare(`
                                UPDATE plan_activities
                                SET catalog_id = ?, title = ?, category_code = ?, origin_source = 'template'
                                WHERE id = ?
                            `).bind(targetCatalogId, targetTitle, targetDutyCode, exactSlotSeg.activity_id));
                            batchStatements.push(env.DB.prepare(`
                                UPDATE plan_time_segments
                                SET is_teaching = ?, jp_count = ?, description = ?, planned_minutes = ?
                                WHERE id = ?
                            `).bind(targetIsTeaching, targetJp, targetDesc, effMin, exactSlotSeg.segment_id));
                            updatedCount++;
                            totalMinutes += effMin;
                            continue;
                        }

                        // Skenario 3: Cek irisan / benturan waktu non-identik
                        const overlappingSegs = existingSegs.filter(s =>
                            !handledSegmentIds.has(s.segment_id) &&
                            s.date === dateStr &&
                            s.start_time < ti.end_time &&
                            ti.start_time < s.end_time
                        );

                        if (!replace_existing) {
                            // Mode non-replace: lewati jika ada benturan
                            if (overlappingSegs.length > 0) {
                                skippedCount++;
                                continue;
                            }
                        } else {
                            // Mode replace: jika ada irisan dan belum ber-log, timpa (hapus segmen lama yang bentrok)
                            const hasLoggedOverlap = overlappingSegs.some(s => s.has_log > 0);
                            if (hasLoggedOverlap) {
                                skippedCount++;
                                continue;
                            }
                            for (const olSeg of overlappingSegs) {
                                handledSegmentIds.add(olSeg.segment_id);
                                batchStatements.push(env.DB.prepare("DELETE FROM plan_time_segments WHERE id = ?").bind(olSeg.segment_id));
                                deletedCount++;
                            }
                        }

                        // Buat kegiatan dan segmen baru dari template
                        const actId = crypto.randomUUID();
                        batchStatements.push(env.DB.prepare(`
                            INSERT INTO plan_activities (
                                id, work_week_id, catalog_id, title, category_code, origin_source, created_at
                            ) VALUES (?, ?, ?, ?, ?, 'template', datetime('now'))
                        `).bind(actId, work_week_id, targetCatalogId, targetTitle, targetDutyCode));
                        batchStatements.push(env.DB.prepare(`
                            INSERT INTO plan_time_segments (
                                id, plan_version_id, activity_id, date, day_of_week,
                                start_time, end_time, planned_minutes, is_teaching, jp_count, description, created_at
                            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
                        `).bind(
                            crypto.randomUUID(), plan_version_id, actId, dateStr,
                            Number(ti.day_of_week), ti.start_time, ti.end_time,
                            effMin, targetIsTeaching, targetJp, targetDesc
                        ));
                        insertedCount++;
                        totalMinutes += effMin;
                    }

                    // Pembersihan selektif untuk mode replace_existing:
                    // Hapus segmen draf lama yang tidak tersentuh oleh template baru (asalkan belum memiliki log dan bukan cuti/izin)
                    if (replace_existing) {
                        for (const s of existingSegs) {
                            if (!handledSegmentIds.has(s.segment_id) && s.has_log === 0) {
                                // Pertahankan segmen cuti/izin resmi
                                if (s.is_leave === 1 || s.catalog_id === 'cat_cuti_izin') {
                                    continue;
                                }
                                handledSegmentIds.add(s.segment_id);
                                batchStatements.push(env.DB.prepare("DELETE FROM plan_time_segments WHERE id = ?").bind(s.segment_id));
                                deletedCount++;
                            }
                        }
                        // Bersihkan aktivitas yatim yang seluruh segmennya telah terhapus dan belum ber-log
                        batchStatements.push(env.DB.prepare(`
                            DELETE FROM plan_activities
                            WHERE work_week_id = ?
                              AND id NOT IN (SELECT activity_id FROM plan_time_segments WHERE activity_id IS NOT NULL)
                              AND id NOT IN (SELECT plan_activity_id FROM plan_log_links)
                        `).bind(work_week_id));
                    }

                    // Eksekusi seluruh mutasi dalam transaksi atomik Cloudflare D1
                    if (batchStatements.length > 0) {
                        await env.DB.batch(batchStatements);
                    }

                    // Hitung total menit riil versi
                    const allSegs = await env.DB.prepare(`
                        SELECT SUM(planned_minutes) AS total FROM plan_time_segments WHERE plan_version_id = ?
                    `).bind(plan_version_id).first();
                    const newTotal = allSegs ? (allSegs.total || 0) : totalMinutes;

                    if (batchStatements.length > 0 || Number(version.total_planned_minutes) !== Number(newTotal)) {
                        await env.DB.prepare(`
                            UPDATE weekly_plan_versions SET total_planned_minutes = ?, updated_at = datetime('now') WHERE id = ?
                        `).bind(newTotal, plan_version_id).run();
                    }

                    // Jalankan silent auto-deduplication di background untuk menjamin 0 kegiatan tumpang tindih & membersihkan hari libur
                    const dedup = await performDeduplicatePlanWl(env.DB, plan_version_id, work_week_id, {
                        holiday_dates: Array.from(holidayDatesSet)
                    });
                    const finalTotal = dedup.newTotal;

                    const totalReplaced = updatedCount + deletedCount;
                    const holidayNote = skippedHolidaysCount > 0 ? `, ${skippedHolidaysCount} kegiatan hari libur dilewati` : "";
                    let message = `Template berhasil diterapkan (${insertedCount} baru, ${updatedCount} diperbarui, ${skippedCount} dipertahankan${holidayNote})`;
                    if (insertedCount === 0 && updatedCount === 0 && deletedCount === 0) {
                        message = `Template sudah sesuai (${skippedCount} kegiatan dipertahankan${holidayNote} tanpa perubahan database)`;
                    }

                    return jsonResponse({
                        success: true,
                        message,
                        data: {
                            total_planned_minutes: finalTotal,
                            inserted_count: insertedCount,
                            updated_count: updatedCount,
                            skipped_count: skippedCount,
                            skipped_holidays: skippedHolidaysCount,
                            deleted_count: deletedCount,
                            replaced_count: totalReplaced,
                            removed_duplicates: dedup.removedCount
                        }
                    }, 200, request);
                } catch (err) {
                    return errorResponse("Gagal menerapkan template ke rencana kerja: " + err.message, 500, request);
                }
            }

            // 8b. POST /api/workload/deduplicate-plan (Self-Healing Deduplikasi & Pembersihan Benturan Waktu Rencana)
            if (path === "/api/workload/deduplicate-plan" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                const isMgr = isWorkloadManager(authResult.user);

                try {
                    const body = await request.json();
                    const { work_week_id, plan_version_id } = body;
                    if (!work_week_id || !plan_version_id) {
                        return errorResponse("work_week_id dan plan_version_id diperlukan", 400, request);
                    }

                    const version = await env.DB.prepare(`
                        SELECT pv.*, ww.teacher_id, ww.is_locked
                        FROM weekly_plan_versions pv
                        JOIN work_weeks ww ON pv.work_week_id = ww.id
                        WHERE pv.id = ? AND pv.work_week_id = ?
                        LIMIT 1
                    `).bind(plan_version_id, work_week_id).first();

                    if (!version) return errorResponse("Versi rencana kerja tidak ditemukan", 404, request);
                    if (!isMgr && !isWorkloadOwner(version.teacher_id, authResult.user, userTeacherId)) {
                        return errorResponse("Akses ditolak: Anda hanya dapat membersihkan rencana kerja Anda sendiri", 403, request);
                    }
                    if (version.is_locked === 1) return errorResponse("Minggu kerja telah dikunci", 403, request);
                    if (!["draft", "needs_revision"].includes(version.status)) {
                        return errorResponse(`Rencana kerja dalam status '${version.status}' tidak dapat diubah`, 400, request);
                    }

                    const dedup = await performDeduplicatePlanWl(env.DB, plan_version_id, work_week_id, {
                        holiday_dates: Array.isArray(body.holiday_dates) ? body.holiday_dates : []
                    });

                    return jsonResponse({
                        success: true,
                        message: dedup.removedCount > 0
                            ? `Berhasil membersihkan ${dedup.removedCount} kegiatan duplikat/bentrok.`
                            : "Tidak ditemukan kegiatan duplikat atau bentrok.",
                        data: { removed_count: dedup.removedCount, total_planned_minutes: dedup.newTotal }
                    }, 200, request);
                } catch (err) {
                    return errorResponse("Gagal membersihkan duplikat rencana: " + err.message, 500, request);
                }
            }

            // 8b. POST /api/workload/clean-holiday-drafts (Peniadaan Reaktif Rencana pada Hari Libur Resmi)
            if (path === "/api/workload/clean-holiday-drafts" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                const isMgr = isWorkloadManager(authResult.user);

                try {
                    const body = await request.json();
                    const { work_week_id, plan_version_id } = body;
                    if (!work_week_id || !plan_version_id) {
                        return errorResponse("work_week_id dan plan_version_id diperlukan", 400, request);
                    }

                    const version = await env.DB.prepare(`
                        SELECT pv.*, ww.teacher_id, ww.week_start_date, ww.is_locked
                        FROM weekly_plan_versions pv
                        JOIN work_weeks ww ON pv.work_week_id = ww.id
                        WHERE pv.id = ? AND pv.work_week_id = ?
                        LIMIT 1
                    `).bind(plan_version_id, work_week_id).first();

                    if (!version) return errorResponse("Versi rencana kerja tidak ditemukan", 404, request);
                    if (!isMgr && !isWorkloadOwner(version.teacher_id, authResult.user, userTeacherId)) {
                        return errorResponse("Akses ditolak: Anda hanya dapat membersihkan rencana kerja Anda sendiri", 403, request);
                    }
                    if (version.is_locked === 1) return errorResponse("Minggu kerja telah dikunci", 403, request);

                    let holidayDates = [];
                    if (Array.isArray(body.holiday_dates) && body.holiday_dates.length > 0) {
                        holidayDates = body.holiday_dates;
                    } else if (version.week_start_date) {
                        const start = version.week_start_date;
                        const startDate = new Date(start + "T00:00:00Z");
                        const endDate = new Date(startDate.getTime() + 4 * 86400000);
                        const endStr = endDate.toISOString().slice(0, 10);
                        const calHols = await env.DB.prepare(`
                            SELECT date, time FROM calendar_events
                            WHERE (category = 'libur' OR color = 'rose' OR LOWER(title) LIKE '%libur%')
                              AND (date <= ? AND (time >= ? OR date >= ?))
                        `).bind(endStr, start, start).all();
                        for (const ch of (calHols.results || [])) {
                            const exp = expandHolidayDateRangeWl(ch.date, ch.time);
                            holidayDates.push(...exp);
                        }
                    }

                    const cleanResult = await cleanWorkloadPlansOnHolidayDates(env.DB, holidayDates, {
                        plan_version_id,
                        work_week_id
                    });

                    if (cleanResult.removedCount > 0) {
                        await recordWorkloadAuditLog(
                            env.DB,
                            "weekly_plan_version",
                            plan_version_id,
                            "CLEAN_HOLIDAY_DRAFTS",
                            authResult.user.uid,
                            authResult.user.name || authResult.user.email || "User",
                            JSON.stringify({
                                removed_count: cleanResult.removedCount,
                                holiday_dates: holidayDates,
                                new_total_minutes: cleanResult.newTotal,
                                version_status: version.status
                            })
                        );
                    }

                    return jsonResponse({
                        success: true,
                        message: cleanResult.removedCount > 0
                            ? `Berhasil meniadakan ${cleanResult.removedCount} kegiatan rencana pada hari libur resmi.`
                            : "Tidak ditemukan kegiatan rencana yang perlu ditiadakan pada hari libur.",
                        data: {
                            removed_count: cleanResult.removedCount,
                            total_planned_minutes: cleanResult.newTotal
                        }
                    }, 200, request);
                } catch (err) {
                    return errorResponse("Gagal membersihkan rencana hari libur: " + err.message, 500, request);
                }
            }

            // 9. POST /api/workload/sync-schedule (Uji 14: Idempotensi, Uji 16: Proteksi laporan terverifikasi)
            if (path === "/api/workload/sync-schedule" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                const isMgr = isWorkloadManager(authResult.user);

                try {
                    const body = await request.json();
                    await ensureWorkloadActivityCatalog(env.DB);
                    const { work_week_id, plan_version_id, schedule_items = [], replace_existing = false } = body;
                    if (!work_week_id || !plan_version_id) {
                        return errorResponse("work_week_id dan plan_version_id diperlukan", 400, request);
                    }

                    const version = await env.DB.prepare(`
                        SELECT pv.*, ww.teacher_id, ww.week_start_date, ww.is_locked
                        FROM weekly_plan_versions pv
                        JOIN work_weeks ww ON pv.work_week_id = ww.id
                        WHERE pv.id = ? AND pv.work_week_id = ?
                        LIMIT 1
                    `).bind(plan_version_id, work_week_id).first();

                    if (!version) return errorResponse("Versi rencana kerja tidak ditemukan", 404, request);
                    if (!isMgr && !isWorkloadOwner(version.teacher_id, authResult.user, userTeacherId)) {
                        return errorResponse("Akses ditolak: Anda hanya dapat menyelaraskan jadwal Anda sendiri", 403, request);
                    }
                    if (version.is_locked === 1) return errorResponse("Minggu kerja telah dikunci", 403, request);
                    if (!["draft", "needs_revision"].includes(version.status)) {
                        return errorResponse(`Rencana kerja dalam status '${version.status}' tidak dapat diubah`, 400, request);
                    }

                    // Jika replace_existing aktif, hapus jadwal KBM impor lama yang BELUM memiliki keterikatan log realisasi (Uji 16)
                    let replacedCount = 0;
                    if (replace_existing) {
                        const existingScheduleActs = await env.DB.prepare(`
                            SELECT pa.id FROM plan_activities pa
                            WHERE pa.work_week_id = ? AND pa.origin_source = 'schedule_import'
                            AND pa.id NOT IN (SELECT plan_activity_id FROM plan_log_links)
                        `).bind(work_week_id).all();

                        const idsToDelete = (existingScheduleActs.results || []).map(r => r.id);
                        for (const actId of idsToDelete) {
                            await env.DB.prepare("DELETE FROM plan_time_segments WHERE activity_id = ? AND plan_version_id = ?").bind(actId, plan_version_id).run();
                            const rem = await env.DB.prepare("SELECT COUNT(*) AS c FROM plan_time_segments WHERE activity_id = ?").bind(actId).first();
                            if (!rem || rem.c === 0) {
                                await env.DB.prepare("DELETE FROM plan_activities WHERE id = ?").bind(actId).run();
                            }
                            replacedCount++;
                        }
                    }

                    // Deteksi tanggal hari libur resmi pada pekan aktif (SSOT: calendar_events D1 + payload holiday_dates)
                    const holidayDatesSet = new Set();
                    if (Array.isArray(body.holiday_dates)) {
                        body.holiday_dates.forEach(d => {
                            if (typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d.trim())) {
                                holidayDatesSet.add(d.trim());
                            }
                        });
                    }
                    const weekStartStr = String(version.week_start_date).slice(0, 10);
                    const weekStartDateObj = new Date(weekStartStr);
                    const weekEndStr = new Date(weekStartDateObj.getTime() + 4 * 86400000).toISOString().slice(0, 10);
                    try {
                        const calHols = await env.DB.prepare(`
                            SELECT date, time FROM calendar_events
                            WHERE (category = 'libur' OR color = 'rose' OR LOWER(title) LIKE '%libur%')
                              AND (date <= ? AND (time >= ? OR date >= ?))
                        `).bind(weekEndStr, weekStartStr, weekStartStr).all();
                        for (const ch of (calHols.results || [])) {
                            const s = (ch.date || "").substring(0, 10);
                            let e = (ch.time && /^\d{4}-\d{2}-\d{2}$/.test(ch.time)) ? ch.time : s;
                            if (e < s) e = s;
                            for (let cur = new Date(s); cur.toISOString().slice(0, 10) <= e; cur.setDate(cur.getDate() + 1)) {
                                const curStr = cur.toISOString().slice(0, 10);
                                if (curStr >= weekStartStr && curStr <= weekEndStr) {
                                    holidayDatesSet.add(curStr);
                                }
                            }
                        }
                    } catch (e) {
                        console.warn("[sync-schedule] Gagal query calendar_events:", e.message);
                    }

                    let importedCount = 0;
                    let skippedCount = 0;

                    for (const s of schedule_items) {
                        const occId = s.schedule_occurrence_id;
                        if (!occId) continue;

                        // Auto-skip jika sesi jadwal KBM berada di hari libur resmi
                        if (holidayDatesSet.has(s.date)) {
                            skippedCount++;
                            continue;
                        }

                        // Periksa apakah sudah ada (Idempotensi, Uji 14)
                        const existingAct = await env.DB.prepare(`
                            SELECT id FROM plan_activities
                            WHERE work_week_id = ? AND schedule_occurrence_id = ?
                            LIMIT 1
                        `).bind(work_week_id, occId).first();

                        // Idempotensi (Uji 14): lewati hanya jika kegiatan masih memiliki slot di versi rencana AKTIF.
                        // Kegiatan yatim (slotnya terhapus: cuti, hapus manual, atau versi rencana baru) dipulihkan
                        // dengan membuat ulang slotnya memakai kegiatan yang sama (tanpa INSERT plan_activities baru).
                        if (existingAct) {
                            const segInVersion = await env.DB.prepare(
                                "SELECT 1 FROM plan_time_segments WHERE activity_id = ? AND plan_version_id = ? LIMIT 1"
                            ).bind(existingAct.id, plan_version_id).first();
                            if (segInVersion) {
                                skippedCount++;
                                continue;
                            }
                        }

                        const actId = existingAct ? existingAct.id : crypto.randomUUID();
                        const isTeaching = s.is_teaching !== undefined ? (s.is_teaching ? 1 : 0) : 1;
                        const catCode = s.category_code || (isTeaching ? "PELAKSANAAN_KBM" : "TUGAS_TAMBAHAN");
                        const jpCount = Number(s.jp_count !== undefined ? s.jp_count : (isTeaching ? 2 : 1));

                        if (!existingAct) {
                            await env.DB.prepare(`
                                INSERT INTO plan_activities (
                                    id, work_week_id, catalog_id, title, category_code,
                                    origin_source, schedule_occurrence_id, created_at
                                ) VALUES (?, ?, ?, ?, ?, 'schedule_import', ?, datetime('now'))
                            `).bind(actId, work_week_id, s.catalog_id || "cat_kbm", s.title, catCode, occId).run();
                        }

                        const effMin = calculateEffectiveMinutesWl(s.start_time, s.end_time);
                        await env.DB.prepare(`
                            INSERT INTO plan_time_segments (
                                id, plan_version_id, activity_id, date, day_of_week,
                                start_time, end_time, planned_minutes, is_teaching, jp_count, description, created_at
                            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
                        `).bind(
                            crypto.randomUUID(), plan_version_id, actId, s.date,
                            Number(s.day_of_week), s.start_time, s.end_time,
                            effMin, isTeaching, jpCount, s.description || ""
                        ).run();

                        importedCount++;
                    }

                    // Jalankan silent auto-deduplication di background untuk memprioritaskan KBM resmi atas template/manual kembar
                    const dedup = await performDeduplicatePlanWl(env.DB, plan_version_id, work_week_id, {
                        holiday_dates: Array.isArray(body.holiday_dates) ? body.holiday_dates : []
                    });
                    const finalTotal = dedup.newTotal;

                    await recordWorkloadAuditLog(
                        env.DB, "weekly_plan_versions", plan_version_id, "SYNC_SCHEDULE",
                        authResult.user.uid, authResult.user.name || authResult.user.email,
                        { work_week_id, imported_count: importedCount, skipped_count: skippedCount, replaced_count: replacedCount, removed_duplicates: dedup.removedCount, replace_existing: !!replace_existing }
                    );

                    const dedupMsg = dedup.removedCount > 0 ? `, ${dedup.removedCount} kegiatan berbenturan otomatis diselaraskan` : "";
                    return jsonResponse({
                        success: true,
                        message: `Sinkronisasi jadwal KBM berhasil: ${importedCount} diimpor, ${skippedCount} dilewati (idempotent)${dedupMsg}.`,
                        data: { imported: importedCount, skipped: skippedCount, replaced: replacedCount, removed_duplicates: dedup.removedCount, total_planned_minutes: finalTotal }
                    }, 200, request);
                } catch (err) {
                    return errorResponse("Gagal menyinkronkan jadwal KBM: " + err.message, 500, request);
                }
            }

            // 9b. POST /api/workload/sync-from-journal (Sinkronisasi otomatis realisasi dari Jurnal Mengajar)
            if (path === "/api/workload/sync-from-journal" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                const isMgr = isWorkloadManager(authResult.user);

                try {
                    const body = await request.json();
                    const { date, work_week_id, teacher_id } = body;

                    // Otorisasi OWASP Top 10 / ASVS: Guru hanya dapat menyinkronkan data bebannya sendiri
                    if (!isMgr && teacher_id && teacher_id !== userTeacherId) {
                        return errorResponse("Akses ditolak: Anda hanya dapat menyinkronkan beban kerja Anda sendiri", 403, request);
                    }

                    if (!date && !work_week_id) {
                        return errorResponse("Parameter 'date' atau 'work_week_id' wajib disertakan", 400, request);
                    }

                    const finalTeacherId = (isMgr && teacher_id) ? teacher_id : userTeacherId;

                    // Query jurnal guru yang relevan
                    let journalQuery = "SELECT * FROM jurnal_guru WHERE 1=1";
                    const queryParams = [];

                    if (date) {
                        journalQuery += " AND tanggal = ?";
                        queryParams.push(date);
                    }
                    if (work_week_id) {
                        const weekRow = await env.DB.prepare("SELECT week_start_date, week_end_date, teacher_id FROM work_weeks WHERE id = ?").bind(work_week_id).first();
                        if (weekRow) {
                            if (!isMgr && weekRow.teacher_id !== userTeacherId) {
                                return errorResponse("Akses ditolak: Anda tidak memiliki akses ke minggu kerja ini", 403, request);
                            }
                            // Proteksi Gerbang Realisasi: Rencana kerja mingguan wajib berstatus 'approved' sebelum sinkronisasi
                            const latestVersion = await env.DB.prepare("SELECT status FROM weekly_plan_versions WHERE work_week_id = ? ORDER BY version_number DESC LIMIT 1").bind(work_week_id).first();
                            if (!latestVersion || latestVersion.status !== "approved") {
                                const curStatus = latestVersion ? latestVersion.status : "belum_ada";
                                let statusDesc = "belum disetujui atau difinalisasi";
                                if (curStatus === "draft") statusDesc = "masih berstatus draf";
                                else if (curStatus === "submitted") statusDesc = "sedang menunggu persetujuan Kepala Sekolah";
                                else if (curStatus === "needs_revision") statusDesc = "memerlukan revisi perbaikan";
                                return errorResponse(`Akses ditolak: Rencana kerja mingguan ${statusDesc}. Sinkronisasi jurnal hanya dapat dilakukan setelah rencana kerja disetujui atau difinalisasi.`, 422, request);
                            }
                            if (!date) {
                                journalQuery += " AND tanggal >= ? AND tanggal <= ?";
                                queryParams.push(weekRow.week_start_date, weekRow.week_end_date);
                            }
                        } else {
                            return errorResponse("Minggu kerja tidak ditemukan", 404, request);
                        }
                    }

                    // Cari data GTK untuk mendapatkan nama dan identitas guru target
                    const teacherRow = await env.DB.prepare("SELECT * FROM gtk WHERE id = ? OR nik = ? OR nip = ? LIMIT 1").bind(finalTeacherId, finalTeacherId, finalTeacherId).first();
                    const teacherName = teacherRow ? teacherRow.name : "";

                    const teacherConditions = [];
                    if (finalTeacherId) {
                        teacherConditions.push("uid_guru = ?");
                        queryParams.push(finalTeacherId);
                    }
                    // Hanya sertakan authResult.user.uid jika guru menyinkronkan datanya sendiri
                    if (!isMgr || finalTeacherId === userTeacherId) {
                        if (authResult.user.uid && authResult.user.uid !== finalTeacherId) {
                            teacherConditions.push("uid_guru = ?");
                            queryParams.push(authResult.user.uid);
                        }
                    }
                    if (teacherRow) {
                        if (teacherRow.nik && teacherRow.nik !== finalTeacherId) {
                            teacherConditions.push("uid_guru = ?");
                            queryParams.push(teacherRow.nik);
                        }
                        if (teacherRow.nip && teacherRow.nip !== finalTeacherId) {
                            teacherConditions.push("uid_guru = ?");
                            queryParams.push(teacherRow.nip);
                        }
                    }
                    if (teacherName) {
                        teacherConditions.push("guru = ? OR guru LIKE ?");
                        queryParams.push(teacherName, `%${teacherName}%`);
                    }

                    if (teacherConditions.length > 0) {
                        journalQuery += ` AND (${teacherConditions.join(" OR ")})`;
                    }

                    journalQuery += " ORDER BY tanggal ASC, created_at ASC";

                    const { results: journalEntries } = await env.DB.prepare(journalQuery).bind(...queryParams).all();
                    const journals = journalEntries || [];

                    // Fast-path Bulk Sync jika sinkronisasi mencakup seluruh minggu kerja
                    if (work_week_id && !date) {
                        const bulkRes = await syncWorkWeekJournals(env.DB, work_week_id, authResult.user);
                        return jsonResponse({
                            success: true,
                            message: `Sinkronisasi realisasi KBM selesai: ${bulkRes.syncedCount || 0} realisasi diperbarui, ${bulkRes.ignoredCount || 0} diabaikan.`,
                            data: {
                                syncedCount: bulkRes.syncedCount || 0,
                                ignoredCount: bulkRes.ignoredCount || 0,
                                totalJournals: bulkRes.totalJournals || 0,
                                details: []
                            }
                        }, 200, request);
                    }

                    let syncedCount = 0;
                    let ignoredCount = 0;
                    const details = [];

                    for (const jRow of journals) {
                        const syncRes = await syncJournalToWorkload(env.DB, jRow, authResult.user);
                        if (syncRes && syncRes.matched) {
                            if (!syncRes.already_synced) {
                                syncedCount++;
                                details.push({ journal_id: jRow.id, status: 'synced', log_id: syncRes.log_id });
                            } else {
                                details.push({ journal_id: jRow.id, status: 'already_synced', log_id: syncRes.log_id });
                            }
                        } else {
                            ignoredCount++;
                            details.push({ journal_id: jRow.id, status: 'ignored', reason: syncRes.reason || 'Tidak cocok' });
                        }
                    }

                    return jsonResponse({
                        success: true,
                        message: `Sinkronisasi realisasi KBM selesai: ${syncedCount} realisasi diperbarui, ${ignoredCount} diabaikan.`,
                        data: {
                            syncedCount,
                            ignoredCount,
                            totalJournals: journals.length,
                            details
                        }
                    }, 200, request);
                } catch (err) {
                    return errorResponse("Gagal memproses sinkronisasi dari jurnal: " + err.message, 500, request);
                }
            }

            // 10. POST /api/workload/submit-plan / /api/workload/submit-plan-version (Guru mengajukan rencana ke Kepala Sekolah)
            if ((path === "/api/workload/submit-plan" && method === "POST") || (path === "/api/workload/submit-plan-version" && method === "POST")) {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                const isMgr = isWorkloadManager(authResult.user);

                try {
                    const body = await request.json();
                    const { work_week_id, plan_version_id, revision_lock } = body;
                    if (!work_week_id || !plan_version_id) {
                        return errorResponse("work_week_id dan plan_version_id diperlukan", 400, request);
                    }

                    const version = await env.DB.prepare(`
                        SELECT pv.*, ww.teacher_id, ww.is_locked
                        FROM weekly_plan_versions pv
                        JOIN work_weeks ww ON pv.work_week_id = ww.id
                        WHERE pv.id = ? AND pv.work_week_id = ?
                        LIMIT 1
                    `).bind(plan_version_id, work_week_id).first();

                    if (!version) return errorResponse("Versi rencana kerja tidak ditemukan", 404, request);
                    if (!isMgr && !isWorkloadOwner(version.teacher_id, authResult.user, userTeacherId)) {
                        return errorResponse("Akses ditolak: Anda hanya dapat mengajukan rencana kerja Anda sendiri", 403, request);
                    }
                    if (version.is_locked === 1) return errorResponse("Minggu kerja telah dikunci", 403, request);
                    if (!["draft", "needs_revision"].includes(version.status)) {
                        return errorResponse(`Rencana kerja dalam status '${version.status}' tidak dapat diajukan ulang`, 400, request);
                    }

                    if (revision_lock !== undefined && Number(revision_lock) !== Number(version.revision_lock)) {
                        return errorResponse("Data rencana telah diperbarui. Silakan muat ulang halaman sebelum mengajukan.", 409, request);
                    }

                    // Jalankan pembersihan otomatis sebelum submit/approval agar versi rencana 100% bebas bentrok
                    await performDeduplicatePlanWl(env.DB, plan_version_id, work_week_id);

                    const studyWeek = await env.DB.prepare('SELECT * FROM work_weeks WHERE id = ?').bind(work_week_id).first();
                    const studySegments = await env.DB.prepare(`SELECT pts.*, pa.catalog_id, pa.category_code, pa.title AS activity_title
                        FROM plan_time_segments pts JOIN plan_activities pa ON pa.id = pts.activity_id WHERE pts.plan_version_id = ?`).bind(plan_version_id).all();
                    const studyValidation = await validateWorkloadStudyDaySubmission(env.DB, studyWeek, version, studySegments.results || [], env);
                    if (!studyValidation.isValid) return errorResponse(studyValidation.message, 422, request);
                    await env.DB.prepare(WORKLOAD_STUDY_DAY_SCHEMA).run();

                    const newLock = Number(version.revision_lock) + 1;
                    const policyCfg = await getWorkloadPolicyConfig(env.DB);
                    const isAutoApproved = policyCfg.require_plan_approval === 0;

                    if (isAutoApproved) {
                        const submissionWrites = await env.DB.batch([env.DB.prepare(`
                            UPDATE weekly_plan_versions
                            SET status = 'approved',
                                submitted_at = datetime('now'),
                                submitted_by_uid = ?,
                                reviewed_at = datetime('now'),
                                reviewed_by_uid = 'system_auto_approval',
                                review_notes = 'Disetujui otomatis melalui kebijakan mode mandiri sekolah',
                                revision_lock = ?,
                                updated_at = datetime('now')
                            WHERE id = ? AND revision_lock = ? AND status IN ('draft', 'needs_revision')
                              AND EXISTS (SELECT 1 FROM work_weeks WHERE id = ? AND is_locked = 0)
                        `).bind(authResult.user.uid, newLock, plan_version_id, version.revision_lock, work_week_id),
                        workloadStudyDayStatement(env.DB, plan_version_id, studyValidation.studyDay, authResult.user.uid)]);
                        if (!submissionWrites[0].meta?.changes) return errorResponse("Rencana telah diperbarui. Silakan muat ulang sebelum mengajukan.", 409, request);

                        // Kunci versi aktif minggu kerja ke versi ini
                        await env.DB.prepare(`
                            UPDATE work_weeks SET active_plan_version_id = ?, updated_at = datetime('now') WHERE id = ?
                        `).bind(plan_version_id, work_week_id).run();

                        await recordWorkloadAuditLog(
                            env.DB, "weekly_plan_versions", plan_version_id, "AUTO_APPROVE_PLAN",
                            authResult.user.uid, authResult.user.name || authResult.user.email,
                            { work_week_id, version_number: version.version_number, total_minutes: version.total_planned_minutes }
                        );

                        // Otomatis sinkronkan jurnal mengajar yang sudah terisi di minggu ini (Mode Mandiri)
                        await syncWorkWeekJournals(env.DB, work_week_id, authResult.user);

                        return jsonResponse({
                            success: true,
                            message: "Rencana kerja mingguan berhasil difinalisasi secara otomatis (Mode Mandiri Aktif)",
                            data: { status: "approved", revision_lock: newLock, auto_approved: true }
                        }, 200, request);
                    } else {
                        const submissionWrites = await env.DB.batch([env.DB.prepare(`
                            UPDATE weekly_plan_versions
                            SET status = 'submitted', submitted_at = datetime('now'),
                                submitted_by_uid = ?, revision_lock = ?, updated_at = datetime('now')
                            WHERE id = ? AND revision_lock = ? AND status IN ('draft', 'needs_revision')
                              AND EXISTS (SELECT 1 FROM work_weeks WHERE id = ? AND is_locked = 0)
                        `).bind(authResult.user.uid, newLock, plan_version_id, version.revision_lock, work_week_id),
                        workloadStudyDayStatement(env.DB, plan_version_id, studyValidation.studyDay, authResult.user.uid)]);
                        if (!submissionWrites[0].meta?.changes) return errorResponse("Rencana telah diperbarui. Silakan muat ulang sebelum mengajukan.", 409, request);

                        await recordWorkloadAuditLog(
                            env.DB, "weekly_plan_versions", plan_version_id, "SUBMIT_PLAN",
                            authResult.user.uid, authResult.user.name || authResult.user.email,
                            { work_week_id, version_number: version.version_number, total_minutes: version.total_planned_minutes }
                        );

                        // Notifikasi Ekosistem: Buat job ke Kepala Sekolah jika require_plan_approval === 1
                        if (policyCfg.require_plan_approval === 1 && typeof ctx.waitUntil === 'function') {
                            ctx.waitUntil((async () => {
                                try {
                                    const teacherName = authResult.user.name || authResult.user.displayName || "Guru";
                                    const job = await createNotificationJob(env, authResult.user.uid, {
                                        title: "📋 Pengajuan Rencana Kerja Mingguan",
                                        body: `${teacherName} telah mengajukan rencana kerja mingguan ke Kepala Sekolah untuk ditinjau.`,
                                        url: "./kinerja-approval.html",
                                        targetType: "role",
                                        targetValue: "kepala_sekolah"
                                    });
                                    if (job.targetCount) await processPendingNotifications(env, job.jobId);
                                } catch (ePlanNotif) {
                                    console.warn("[Workload Submit Notif] Error:", ePlanNotif.message);
                                }
                            })());
                        }

                        return jsonResponse({
                            success: true,
                            message: "Rencana kerja mingguan berhasil diajukan kepada Kepala Sekolah",
                            data: { status: "submitted", revision_lock: newLock }
                        }, 200, request);
                    }
                } catch (err) {
                    return errorResponse("Gagal mengajukan rencana kerja: " + err.message, 500, request);
                }
            }

            // 10b. POST /api/workload/reopen-plan (Kembalikan rencana yang difinalisasi mandiri / diajukan ke status draf untuk diedit kembali)
            if (path === "/api/workload/reopen-plan" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                const isMgr = isWorkloadManager(authResult.user);

                try {
                    const body = await request.json();
                    const {
                        work_week_id,
                        plan_version_id,
                        revision_lock,
                        reason = "Pengembalian rencana ke status draf untuk penyuntingan kembali"
                    } = body;

                    if (!work_week_id || !plan_version_id) {
                        return errorResponse("work_week_id dan plan_version_id wajib diisi", 400, request);
                    }

                    const version = await env.DB.prepare(`
                        SELECT pv.*, ww.teacher_id, ww.is_locked
                        FROM weekly_plan_versions pv
                        JOIN work_weeks ww ON pv.work_week_id = ww.id
                        WHERE pv.id = ? AND pv.work_week_id = ?
                        LIMIT 1
                    `).bind(plan_version_id, work_week_id).first();

                    if (!version) return errorResponse("Versi rencana kerja tidak ditemukan", 404, request);
                    if (!isMgr && !isWorkloadOwner(version.teacher_id, authResult.user, userTeacherId)) {
                        return errorResponse("Akses ditolak: Anda hanya dapat mengubah rencana kerja milik Anda sendiri", 403, request);
                    }
                    if (version.is_locked === 1) {
                        return errorResponse("Minggu kerja telah dikunci oleh pimpinan", 403, request);
                    }

                    if (version.status === "draft") {
                        return jsonResponse({
                            success: true,
                            message: "Rencana kerja sudah berada dalam status draf",
                            data: { status: "draft", revision_lock: version.revision_lock }
                        }, 200, request);
                    }

                    if (!["approved", "submitted", "needs_revision"].includes(version.status)) {
                        return errorResponse(`Rencana kerja dalam status '${version.status}' tidak dapat dikembalikan ke draf`, 400, request);
                    }

                    if (revision_lock !== undefined && Number(revision_lock) !== Number(version.revision_lock)) {
                        return errorResponse("Data rencana telah diperbarui. Silakan muat ulang halaman sebelum melanjutkan.", 409, request);
                    }

                    const newLock = Number(version.revision_lock) + 1;

                    await env.DB.prepare(`
                        UPDATE weekly_plan_versions
                        SET status = 'draft',
                            submitted_at = COALESCE(submitted_at, datetime('now')),
                            revision_lock = ?,
                            updated_at = datetime('now')
                        WHERE id = ?
                    `).bind(newLock, plan_version_id).run();

                    await recordWorkloadAuditLog(
                        env.DB, "weekly_plan_versions", plan_version_id, "REOPEN_PLAN_TO_DRAFT",
                        authResult.user.uid, authResult.user.name || authResult.user.email,
                        { work_week_id, version_number: version.version_number, reason, previous_status: version.status }
                    );

                    return jsonResponse({
                        success: true,
                        message: "Rencana kerja berhasil dikembalikan ke status draf. Anda dapat menyunting dan memfinalisasi atau mengajukan kembali rencana ini.",
                        data: { status: "draft", revision_lock: newLock, previous_status: version.status }
                    }, 200, request);
                } catch (err) {
                    return errorResponse("Gagal mengembalikan rencana ke draf: " + err.message, 500, request);
                }
            }

            // 11. POST /api/workload/review-plan / /api/workload/review-plan-version (Kepala Sekolah / Reviewer Sah menyetujui / minta revisi)
            // Uji 30: Anti Self-Approval, Uji 35: Proteksi Delegasi Kedaluwarsa
            if ((path === "/api/workload/review-plan" && method === "POST") || (path === "/api/workload/review-plan-version" && method === "POST")) {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                try {
                    const body = await request.json();
                    const {
                        work_week_id,
                        plan_version_id,
                        review_notes = "",
                        revision_reason = ""
                    } = body;
                    const action = body.action || (body.decision === 'approved' ? 'approve' : (body.decision === 'needs_revision' ? 'request_revision' : body.decision));

                    if (!work_week_id || !plan_version_id || !action) {
                        return errorResponse("work_week_id, plan_version_id, dan action wajib diisi", 400, request);
                    }

                    const version = await env.DB.prepare(`
                        SELECT pv.*, ww.teacher_id
                        FROM weekly_plan_versions pv
                        JOIN work_weeks ww ON pv.work_week_id = ww.id
                        WHERE pv.id = ? AND pv.work_week_id = ?
                        LIMIT 1
                    `).bind(plan_version_id, work_week_id).first();

                    if (!version) return errorResponse("Versi rencana kerja tidak ditemukan", 404, request);

                    // Ambil UID guru target untuk validasi Anti Self-Approval
                    const teacherGtk = await env.DB.prepare("SELECT nik, nip, role FROM gtk WHERE id = ?").bind(version.teacher_id).first();
                    const targetTeacherUid = (teacherGtk && teacherGtk.nik) || version.teacher_id;

                    // Otorisasi Reviewer & Anti Self-Approval (Uji 30 & Uji 35)
                    const reviewerAuth = await checkWorkloadReviewerAuth(env.DB, authResult.user, version.teacher_id, targetTeacherUid);
                    if (!reviewerAuth.allowed) {
                        const statusCode = reviewerAuth.selfApproval ? 403 : 403;
                        return errorResponse(reviewerAuth.reason, statusCode, request);
                    }

                    if (action === "approve") {
                        await env.DB.prepare(`
                            UPDATE weekly_plan_versions
                            SET status = 'approved', reviewed_at = datetime('now'),
                                reviewed_by_uid = ?, reviewed_by_name = ?,
                                review_notes = ?, updated_at = datetime('now')
                            WHERE id = ?
                        `).bind(
                            authResult.user.uid,
                            authResult.user.name || authResult.user.email || "Kepala Sekolah",
                            review_notes,
                            plan_version_id
                        ).run();

                        // Kunci versi yang disetujui di work_weeks
                        await env.DB.prepare(`
                            UPDATE work_weeks SET active_plan_version_id = ?, updated_at = datetime('now') WHERE id = ?
                        `).bind(plan_version_id, work_week_id).run();

                        await recordWorkloadAuditLog(
                            env.DB, "weekly_plan_versions", plan_version_id, "APPROVE_PLAN",
                            authResult.user.uid, authResult.user.name || authResult.user.email,
                            { work_week_id, version_number: version.version_number, review_notes }
                        );

                        // Otomatis sinkronkan jurnal mengajar yang sudah terisi di minggu ini
                        await syncWorkWeekJournals(env.DB, work_week_id, authResult.user);

                        // Notifikasi Ekosistem: Beritahu guru pemilik rencana bahwa rencana telah disetujui
                        const targetTeacherRecipient = version.submitted_by_uid || targetTeacherUid;
                        if (targetTeacherRecipient) {
                            ctx.waitUntil((async () => {
                                try {
                                    const job = await createNotificationJob(env, authResult.user.uid, {
                                        title: "✅ Rencana Kerja Mingguan Disetujui",
                                        body: `Rencana kerja mingguan Anda telah disetujui oleh Kepala Sekolah.${review_notes ? ' Catatan: ' + review_notes : ''}`,
                                        url: "./guru-kinerja.html",
                                        targetType: "user",
                                        targetValue: targetTeacherRecipient
                                    });
                                    if (job.targetCount) await processPendingNotifications(env, job.jobId);
                                } catch (eApproveNotif) {
                                    console.warn("[Workload Review Notif] Error approve:", eApproveNotif.message);
                                }
                            })());
                        }

                        return jsonResponse({ success: true, message: "Rencana kerja berhasil disetujui", status: "approved" }, 200, request);
                    }

                    if (action === "request_revision") {
                        const newLock = Number(version.revision_lock || 0) + 1;
                        const notes = review_notes || revision_reason || "";
                        await env.DB.prepare(`
                            UPDATE weekly_plan_versions
                            SET status = 'needs_revision',
                                reviewed_at = datetime('now'),
                                reviewed_by_uid = ?,
                                reviewed_by_name = ?,
                                review_notes = ?,
                                revision_reason = ?,
                                revision_lock = ?,
                                updated_at = datetime('now')
                            WHERE id = ?
                        `).bind(
                            authResult.user.uid,
                            authResult.user.name || authResult.user.email || "Kepala Sekolah",
                            notes,
                            revision_reason || notes,
                            newLock,
                            plan_version_id
                        ).run();

                        // Pastikan active_plan_version_id pada work_weeks tetap menunjuk ke versi ini
                        await env.DB.prepare(`
                            UPDATE work_weeks SET active_plan_version_id = ?, updated_at = datetime('now') WHERE id = ?
                        `).bind(plan_version_id, work_week_id).run();

                        await recordWorkloadAuditLog(
                            env.DB, "weekly_plan_versions", plan_version_id, "REQUEST_REVISION",
                            authResult.user.uid, authResult.user.name || authResult.user.email,
                            { work_week_id, version_number: version.version_number, revision_reason: revision_reason || notes, review_notes: notes }
                        );

                        // Notifikasi Ekosistem: Beritahu guru pemilik rencana bahwa rencana perlu revisi
                        const targetTeacherRecipient = version.submitted_by_uid || targetTeacherUid;
                        if (targetTeacherRecipient) {
                            ctx.waitUntil((async () => {
                                try {
                                    const job = await createNotificationJob(env, authResult.user.uid, {
                                        title: "⚠️ Revisi Rencana Kerja Mingguan",
                                        body: `Rencana kerja mingguan Anda memerlukan revisi.${notes ? ' Catatan: ' + notes : ''}`,
                                        url: "./guru-kinerja.html",
                                        targetType: "user",
                                        targetValue: targetTeacherRecipient
                                    });
                                    if (job.targetCount) await processPendingNotifications(env, job.jobId);
                                } catch (eRevNotif) {
                                    console.warn("[Workload Review Notif] Error revision:", eRevNotif.message);
                                }
                            })());
                        }

                        return jsonResponse({
                            success: true,
                            message: "Permintaan revisi berhasil dikirim ke guru. Rencana kerja dapat langsung disunting kembali.",
                            data: {
                                status: "needs_revision",
                                plan_version_id: plan_version_id,
                                version_number: version.version_number,
                                revision_lock: newLock
                            }
                        }, 200, request);
                    }

                    return errorResponse("Action tidak valid. Gunakan 'approve' atau 'request_revision'", 400, request);
                } catch (err) {
                    return errorResponse("Gagal memproses review rencana: " + err.message, 500, request);
                }
            }

            // 12. POST & DELETE /api/workload/logs (Laporan Realisasi Aktual Guru)
            // Uji 5, 6, 7, 8, 9, 10, 11, 12
            if (path.startsWith("/api/workload/logs")) {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                const isMgr = isWorkloadManager(authResult.user);

                if (method === "POST") {
                    try {
                        const body = await request.json();
                        await ensureWorkloadActivityCatalog(env.DB);
                        let targetLogId = body.id || null;
                        if (!targetLogId && body.plan_activity_id) {
                            const existingLink = await env.DB.prepare(
                                "SELECT work_log_id FROM plan_log_links WHERE plan_activity_id = ? LIMIT 1"
                            ).bind(body.plan_activity_id).first();
                            if (existingLink?.work_log_id) {
                                targetLogId = existingLink.work_log_id;
                            }
                        }

                        const {
                            id = targetLogId || crypto.randomUUID(),
                            work_week_id,
                            teacher_id,
                            date,
                            day_of_week,
                            title,
                            catalog_id = "cat_kbm",
                            plan_activity_id,
                            is_unplanned = 0,
                            output_summary = "",
                            evidence_url = "",
                            status_execution = "terlaksana", // terlaksana, sebagian, tidak_terlaksana, diganti
                            obstacle_notes = "",
                            substitute_notes = "",
                            segments = [] // [ { start_time, end_time, actual_minutes, notes } ]
                        } = body;

                        const finalTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user, teacher_id);

                        if (!work_week_id || !date || !title) {
                            return errorResponse("work_week_id, date, dan title wajib diisi", 400, request);
                        }

                        if (!isMgr && finalTeacherId !== userTeacherId) {
                            return errorResponse("Akses ditolak: Anda hanya dapat melaporkan realisasi pekerjaan Anda sendiri", 403, request);
                        }

                        // Uji 9: Pelaporan realisasi untuk waktu/tanggal di masa depan ditolak secara ketat
                        const nowWitaObj = new Date(Date.now() + 8 * 3600 * 1000);
                        const todayWita = nowWitaObj.toISOString().slice(0, 10);
                        if (date > todayWita) {
                            return errorResponse("Tanggal pelaksanaan tidak boleh di masa depan", 422, request);
                        }

                        // Proteksi jam kegiatan belum berakhir (dengan toleransi 10 menit sebelum end_time)
                        // Jika berstatus draft, guru diizinkan mengunggah foto dan menyimpan draf persiapan sebelum kegiatan berakhir
                        if (date === todayWita && status_execution !== "draft") {
                            let activityEndTime = body.end_time || (Array.isArray(segments) && segments[0]?.end_time) || null;
                            if (!activityEndTime && plan_activity_id) {
                                const planSeg = await env.DB.prepare(
                                    "SELECT end_time FROM plan_time_segments WHERE activity_id = ? LIMIT 1"
                                ).bind(plan_activity_id).first();
                                if (planSeg?.end_time) {
                                    activityEndTime = planSeg.end_time;
                                }
                            }

                            if (status_execution !== "tidak_terlaksana" && activityEndTime && typeof activityEndTime === "string" && activityEndTime.includes(":")) {
                                const parts = activityEndTime.split(":");
                                const endH = parseInt(parts[0], 10);
                                const endM = parseInt(parts[1], 10);
                                if (!isNaN(endH) && !isNaN(endM)) {
                                    const endMinutes = endH * 60 + endM;
                                    const allowedMinutes = Math.max(0, endMinutes - 10);
                                    const currentMinutes = nowWitaObj.getUTCHours() * 60 + nowWitaObj.getUTCMinutes();

                                    if (currentMinutes < allowedMinutes) {
                                        const allowedH = Math.floor(allowedMinutes / 60);
                                        const allowedM = allowedMinutes % 60;
                                        const allowedTimeStr = `${String(allowedH).padStart(2, "0")}:${String(allowedM).padStart(2, "0")}`;
                                        return errorResponse(
                                            `Kegiatan belum berakhir. Pelaporan realisasi baru dapat dilakukan mulai pukul ${allowedTimeStr} WITA (toleransi 10 menit sebelum jam ${activityEndTime} WITA).`,
                                            422,
                                            request
                                        );
                                    }
                                }
                            }
                        }

                        // Verifikasi minggu kerja tidak terkunci
                        const week = await env.DB.prepare("SELECT is_locked FROM work_weeks WHERE id = ?").bind(work_week_id).first();
                        if (week && week.is_locked === 1) {
                            return errorResponse("Minggu kerja telah dikunci oleh pimpinan", 403, request);
                        }

                        // Proteksi Gerbang Realisasi: Rencana kerja mingguan wajib berstatus 'approved' sebelum dapat direalisasikan
                        const latestPlanVersion = await env.DB.prepare(`
                            SELECT status FROM weekly_plan_versions 
                            WHERE work_week_id = ? 
                            ORDER BY version_number DESC 
                            LIMIT 1
                        `).bind(work_week_id).first();

                        if (!latestPlanVersion || latestPlanVersion.status !== "approved") {
                            const curStatus = latestPlanVersion ? latestPlanVersion.status : "belum_ada";
                            let statusDesc = "belum disetujui atau difinalisasi";
                            if (curStatus === "draft") statusDesc = "masih berstatus draf";
                            else if (curStatus === "submitted") statusDesc = "sedang menunggu persetujuan Kepala Sekolah";
                            else if (curStatus === "needs_revision") statusDesc = "memerlukan revisi perbaikan";

                            return errorResponse(`Akses ditolak: Rencana kerja mingguan ${statusDesc}. Pelaporan realisasi hanya dapat dilakukan setelah rencana kerja disetujui atau difinalisasi.`, 422, request);
                        }

                        // Proteksi Integritas Data KBM: Realisasi KBM terencana tidak dapat dilaporkan 'terlaksana' secara manual
                        // Realisasi KBM otomatis disinkronkan dari Jurnal Mengajar Digital
                        let effectivePlanActId = plan_activity_id || null;
                        if (!effectivePlanActId && id) {
                            const existingLink = await env.DB.prepare(
                                "SELECT plan_activity_id FROM plan_log_links WHERE work_log_id = ? LIMIT 1"
                            ).bind(id).first();
                            if (existingLink?.plan_activity_id) {
                                effectivePlanActId = existingLink.plan_activity_id;
                            }
                        }

                        if (effectivePlanActId && Number(is_unplanned) === 0 && status_execution === "terlaksana") {
                            const planAct = await env.DB.prepare(`
                                SELECT pa.catalog_id, pa.category_code, pts.is_teaching
                                FROM plan_activities pa
                                LEFT JOIN plan_time_segments pts ON pts.activity_id = pa.id
                                WHERE pa.id = ?
                                LIMIT 1
                            `).bind(effectivePlanActId).first();

                            const isKbm = planAct && (
                                planAct.is_teaching === 1 ||
                                planAct.catalog_id === "cat_kbm" ||
                                planAct.category_code === "PELAKSANAAN_KBM"
                            );

                            if (isKbm) {
                                let isExistingLog = false;
                                if (id) {
                                    const checkLog = await env.DB.prepare("SELECT id FROM work_logs WHERE id = ? LIMIT 1").bind(id).first();
                                    if (checkLog) isExistingLog = true;
                                }

                                if (!isExistingLog) {
                                    return errorResponse(
                                        "Realisasi kegiatan tatap muka KBM tidak dapat dicentang atau dilaporkan secara manual. Data wajib disinkronkan dari Jurnal Mengajar Digital demi menjaga integritas data.",
                                        422,
                                        request
                                    );
                                }
                            }
                        }

                        // Uji 7: Realisasi tidak terlaksana wajib mencantumkan alasan dan aktual = 0 menit
                        let effectiveActualMinutes = 0;
                        if (status_execution === "tidak_terlaksana" || status_execution === "draft") {
                            if (status_execution === "tidak_terlaksana" && !obstacle_notes && !output_summary) {
                                return errorResponse("Alasan tidak terlaksana wajib diisi", 422, request);
                            }
                            effectiveActualMinutes = 0;
                        } else {
                            // Hitung durasi dari segments atau payload
                            if (Array.isArray(segments) && segments.length > 0) {
                                segments.forEach(seg => {
                                    const dur = seg.actual_minutes !== undefined ? Number(seg.actual_minutes) : calculateEffectiveMinutesWl(seg.start_time, seg.end_time);
                                    effectiveActualMinutes += Math.max(0, dur);
                                });
                            } else if (body.actual_minutes !== undefined) {
                                effectiveActualMinutes = Math.max(0, Number(body.actual_minutes));
                            } else if (body.start_time && body.end_time) {
                                effectiveActualMinutes = calculateEffectiveMinutesWl(body.start_time, body.end_time);
                            }
                        }

                        const policyCfg = await getWorkloadPolicyConfig(env.DB);
                        const isAutoVerified = policyCfg.require_log_verification === 0;
                        const initialVerStatus = isAutoVerified ? 'verified' : 'unverified';

                        // Cek jika memperbarui laporan yang sudah ada
                        if (id) {
                            const existingLog = await env.DB.prepare("SELECT * FROM work_logs WHERE id = ?").bind(id).first();
                            if (existingLog) {
                                if (existingLog.is_locked === 1) {
                                    return errorResponse("Laporan kegiatan telah dikunci dan tidak dapat diubah", 403, request);
                                }
                                const isManualVerified = existingLog.verification_status === "verified" &&
                                                         existingLog.verified_by_uid &&
                                                         existingLog.verified_by_uid !== "system_auto_policy" &&
                                                         policyCfg.require_log_verification !== 0;
                                if (isManualVerified && !isMgr) {
                                    return errorResponse("Laporan ini telah diverifikasi oleh Kepala Sekolah dan tidak dapat diubah", 403, request);
                                }
                            }
                        }

                        // Validasi Benturan Jam Kerja Realisasi (Anti-Overlap Mandate)
                        if (status_execution !== "tidak_terlaksana") {
                            let targetTimeRanges = [];
                            if (Array.isArray(segments) && segments.length > 0) {
                                targetTimeRanges = segments.filter(s => s.start_time && s.end_time);
                            } else if (body.start_time && body.end_time) {
                                targetTimeRanges = [{ start_time: body.start_time, end_time: body.end_time }];
                            }

                            if (targetTimeRanges.length > 0) {
                                const internalOverlap = validateSegmentsNoOverlapWl(targetTimeRanges);
                                if (!internalOverlap.valid) {
                                    return errorResponse(internalOverlap.message, 422, request);
                                }

                                const existingOtherLogs = await env.DB.prepare(`
                                    SELECT wl.id, wl.title, wls.start_time, wls.end_time
                                    FROM work_logs wl
                                    JOIN work_log_segments wls ON wl.id = wls.work_log_id
                                    WHERE wl.teacher_id = ? AND wl.date = ? AND wl.id != ?
                                      AND (wl.status_execution IS NULL OR wl.status_execution != 'tidak_terlaksana')
                                `).bind(finalTeacherId, date, id || "").all();

                                const otherSegs = existingOtherLogs?.results || [];
                                for (const target of targetTimeRanges) {
                                    const tStart = parseTimeToMinutesWl(target.start_time);
                                    const tEnd = parseTimeToMinutesWl(target.end_time);
                                    if (tStart >= tEnd) continue;

                                    for (const other of otherSegs) {
                                        const oStart = parseTimeToMinutesWl(other.start_time);
                                        const oEnd = parseTimeToMinutesWl(other.end_time);
                                        if (oStart >= oEnd) continue;

                                        if (Math.max(tStart, oStart) < Math.min(tEnd, oEnd)) {
                                            return errorResponse(`Benturan jam kerja terdeteksi: waktu ${target.start_time}–${target.end_time} beririsan dengan laporan "${other.title}" (${other.start_time}–${other.end_time})`, 422, request);
                                        }
                                    }
                                }
                            }
                        }

                        // Simpan laporan, sesi aktual, relasi rencana, dan pembersihan duplikat
                        // dalam satu transaksi D1. Kegagalan satu statement membatalkan semuanya.
                        // Durasi aktual tetap boleh berbeda dari rencana, termasuk kegiatan pengganti.
                        const logBatch = [];
                        logBatch.push(env.DB.prepare(`
                            INSERT INTO work_logs (
                                id, work_week_id, teacher_id, date, day_of_week, title,
                                catalog_id, is_unplanned, output_summary, evidence_url,
                                status_execution, obstacle_notes,
                                verification_status, is_locked, verified_at, verified_by_uid, created_at, updated_at
                            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ${isAutoVerified ? "datetime('now')" : "NULL"}, ${isAutoVerified ? "'system_auto_policy'" : "NULL"}, datetime('now'), datetime('now'))
                            ON CONFLICT(id) DO UPDATE SET
                                date = excluded.date,
                                day_of_week = excluded.day_of_week,
                                title = excluded.title,
                                catalog_id = excluded.catalog_id,
                                is_unplanned = excluded.is_unplanned,
                                output_summary = excluded.output_summary,
                                evidence_url = excluded.evidence_url,
                                status_execution = excluded.status_execution,
                                obstacle_notes = excluded.obstacle_notes,
                                verification_status = CASE WHEN ${isAutoVerified ? "1" : "0"} = 1 THEN 'verified' ELSE work_logs.verification_status END,
                                verified_by_uid = CASE WHEN ${isAutoVerified ? "1" : "0"} = 1 THEN 'system_auto_policy' ELSE work_logs.verified_by_uid END,
                                verified_at = CASE WHEN ${isAutoVerified ? "1" : "0"} = 1 THEN datetime('now') ELSE work_logs.verified_at END,
                                updated_at = datetime('now')
                        `).bind(
                            id, work_week_id, finalTeacherId, date,
                            Number(day_of_week || 1), title, catalog_id,
                            is_unplanned ? 1 : 0,
                            output_summary,
                            evidence_url,
                            status_execution || "terlaksana",
                            obstacle_notes || null,
                            initialVerStatus
                        ));

                        // Simpan sesi durasi di work_log_segments (Uji 10 & 11)
                        logBatch.push(env.DB.prepare("DELETE FROM work_log_segments WHERE work_log_id = ?").bind(id));

                        if (status_execution !== "tidak_terlaksana") {
                            const isDraft = status_execution === "draft";
                            if (Array.isArray(segments) && segments.length > 0) {
                                for (const s of segments) {
                                    const segDur = isDraft ? 0 : (s.actual_minutes !== undefined ? Number(s.actual_minutes) : calculateEffectiveMinutesWl(s.start_time, s.end_time));
                                    logBatch.push(env.DB.prepare(`
                                        INSERT INTO work_log_segments (id, work_log_id, start_time, end_time, actual_minutes, notes, created_at)
                                        VALUES (?, ?, ?, ?, ?, ?, datetime('now'))
                                    `).bind(crypto.randomUUID(), id, s.start_time || "07:30", s.end_time || "08:15", segDur, s.notes || ""));
                                }
                            } else if (body.start_time && body.end_time) {
                                const segDur = isDraft ? 0 : effectiveActualMinutes;
                                logBatch.push(env.DB.prepare(`
                                    INSERT INTO work_log_segments (id, work_log_id, start_time, end_time, actual_minutes, notes, created_at)
                                    VALUES (?, ?, ?, ?, ?, ?, datetime('now'))
                                `).bind(crypto.randomUUID(), id, body.start_time, body.end_time, segDur, obstacle_notes || ""));
                            }
                        }

                        // Hubungkan dengan plan_activities via plan_log_links
                        if (plan_activity_id) {
                            const isDraftSubstitution = status_execution === "draft" && body.draft_status_execution === "diganti";
                            const linkType = status_execution === "diganti" || isDraftSubstitution ? "substitution" : "fulfillment";
                            logBatch.push(env.DB.prepare(`
                                INSERT INTO plan_log_links (id, plan_activity_id, work_log_id, link_type, reason_notes, created_at)
                                VALUES (?, ?, ?, ?, ?, datetime('now'))
                                ON CONFLICT(plan_activity_id, work_log_id) DO UPDATE SET
                                    link_type = excluded.link_type,
                                    reason_notes = excluded.reason_notes
                            `).bind(crypto.randomUUID(), plan_activity_id, id, linkType, substitute_notes || obstacle_notes || ""));

                            // Bersihkan relasi duplikat historis jika ada log lain yang pernah tertaut ke plan_activity_id yang sama
                            const duplicateLinks = await env.DB.prepare(
                                "SELECT work_log_id FROM plan_log_links WHERE plan_activity_id = ? AND work_log_id != ?"
                            ).bind(plan_activity_id, id).all();
                            if (duplicateLinks?.results?.length > 0) {
                                for (const dup of duplicateLinks.results) {
                                    logBatch.push(env.DB.prepare("DELETE FROM plan_log_links WHERE plan_activity_id = ? AND work_log_id = ?").bind(plan_activity_id, dup.work_log_id));
                                    logBatch.push(env.DB.prepare("DELETE FROM work_log_segments WHERE work_log_id = ?").bind(dup.work_log_id));
                                    logBatch.push(env.DB.prepare("DELETE FROM work_logs WHERE id = ?").bind(dup.work_log_id));
                                }
                            }
                        }

                        await env.DB.batch(logBatch);

                        return jsonResponse({
                            success: true,
                            message: "Laporan realisasi kegiatan berhasil disimpan",
                            data: {
                                log_id: id,
                                actual_minutes: effectiveActualMinutes,
                                status_execution
                            }
                        }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal menyimpan laporan realisasi: " + err.message, 500, request);
                    }
                }

                if (method === "DELETE") {
                    const logId = path.replace("/api/workload/logs/", "").trim();
                    if (!logId) return errorResponse("ID log realisasi diperlukan", 400, request);

                    try {
                        const existing = await env.DB.prepare("SELECT * FROM work_logs WHERE id = ?").bind(logId).first();
                        if (!existing) return errorResponse("Laporan kegiatan tidak ditemukan", 404, request);
                        if (!isMgr && !isWorkloadOwner(existing.teacher_id, authResult.user, userTeacherId)) {
                            return errorResponse("Akses ditolak: Anda tidak berhak menghapus laporan ini", 403, request);
                        }
                        if (existing.is_locked === 1) {
                            return errorResponse("Laporan kegiatan telah dikunci dan tidak dapat dihapus", 403, request);
                        }

                        const policyCfg = await getWorkloadPolicyConfig(env.DB);
                        const isManualVerified = existing.verification_status === "verified" &&
                                                 existing.verified_by_uid &&
                                                 existing.verified_by_uid !== "system_auto_policy" &&
                                                 policyCfg.require_log_verification !== 0;
                        if (isManualVerified && !isMgr) {
                            return errorResponse("Laporan ini telah diverifikasi oleh Kepala Sekolah dan tidak dapat dihapus", 403, request);
                        }

                        await env.DB.batch([
                            env.DB.prepare("DELETE FROM plan_log_links WHERE work_log_id = ?").bind(logId),
                            env.DB.prepare("DELETE FROM work_log_segments WHERE work_log_id = ?").bind(logId),
                            env.DB.prepare("DELETE FROM work_logs WHERE id = ?").bind(logId)
                        ]);
                        return jsonResponse({ success: true, message: "Laporan realisasi berhasil dihapus" }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal menghapus laporan realisasi: " + err.message, 500, request);
                    }
                }

                return errorResponse("Method tidak didukung", 405, request);
            }

            // 13. POST /api/workload/review-logs (Verifikasi Massal / Tunggal Realisasi oleh Reviewer)
            // Uji 30: Anti Self-Approval
            if (path === "/api/workload/review-logs" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                try {
                    const body = await request.json();
                    const { log_ids = [], action = "verify", verification_notes = "" } = body;
                    if (!Array.isArray(log_ids) || log_ids.length === 0) {
                        return errorResponse("log_ids (array) diperlukan", 400, request);
                    }

                    const targetStatus = action === "verify" ? "verified" : "rejected";
                    const reviewerUid = authResult.user.uid;
                    const reviewerTeacherId = authResult.user.linkedTeacherId || "";

                    let verifiedCount = 0;
                    for (const logId of log_ids) {
                        const log = await env.DB.prepare("SELECT * FROM work_logs WHERE id = ?").bind(logId).first();
                        if (!log) continue;

                        // Anti Self-Approval (Uji 30)
                        if (log.teacher_id === reviewerTeacherId || log.teacher_id === reviewerUid) {
                            return errorResponse("Reviewer dilarang memverifikasi laporan pelaksanaan pekerjaannya sendiri (Anti Self-Approval)", 403, request);
                        }

                        const authChk = await checkWorkloadReviewerAuth(env.DB, authResult.user, log.teacher_id, null);
                        if (!authChk.allowed) {
                            return errorResponse(authChk.reason, 403, request);
                        }

                        await env.DB.prepare(`
                            UPDATE work_logs
                            SET verification_status = ?, verified_at = datetime('now'),
                                verified_by_uid = ?, verified_by_name = ?,
                                verification_notes = ?, updated_at = datetime('now')
                            WHERE id = ?
                        `).bind(
                            targetStatus, reviewerUid,
                            authResult.user.name || authResult.user.email || "Kepala Sekolah",
                            verification_notes, logId
                        ).run();

                        verifiedCount++;
                    }

                    return jsonResponse({
                        success: true,
                        message: `${verifiedCount} laporan kegiatan berhasil di-${targetStatus === "verified" ? "verifikasi" : "tolak"}`
                    }, 200, request);
                } catch (err) {
                    return errorResponse("Gagal memproses verifikasi laporan: " + err.message, 500, request);
                }
            }

            // 14. GET /api/workload/monitoring-summary (Uji 36: Guru tanpa work_weeks tetap muncul)
            if (path === "/api/workload/monitoring-summary" && method === "GET") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                if (!isWorkloadSupervisor(authResult.user)) {
                    // Cek delegasi
                    const todayDate = new Date(Date.now() + 8 * 3600 * 1000).toISOString().slice(0, 10);
                    const del = await env.DB.prepare(`
                        SELECT * FROM workload_delegations
                        WHERE delegatee_uid = ? AND status = 'active'
                        AND ? >= valid_from AND ? <= valid_until
                        LIMIT 1
                    `).bind(authResult.user.uid, todayDate, todayDate).first();

                    if (!del) {
                        return errorResponse("Forbidden: Akses monitoring beban kerja guru khusus untuk Kepala Sekolah, Wakasek Kurikulum, & Pengawas yang ditugaskan", 403, request);
                    }
                }

                const weekStartDate = url.searchParams.get("week_start_date");
                if (!weekStartDate) return errorResponse("Parameter week_start_date (YYYY-MM-DD) diperlukan", 400, request);

                try {
                    // LEFT JOIN dari master GTK yang aktif (Guru Mapel, BK, dll. kecuali Kepala Sekolah)
                    const teachersRes = await env.DB.prepare(`
                        SELECT g.id, g.name, g.nip, g.nuptk, g.jenis_ptk, g.mapel, g.foto,
                            ww.id AS work_week_id, ww.active_plan_version_id, ww.is_locked
                        FROM gtk g
                        LEFT JOIN work_weeks ww ON (g.id = ww.teacher_id AND ww.week_start_date = ?)
                        WHERE g.status = 'active'
                          AND (g.jenis_ptk LIKE '%Guru%' OR g.jenis_ptk = 'Pendidik')
                          AND g.jenis_ptk NOT LIKE '%Kepala Sekolah%'
                          AND g.jenis_ptk NOT LIKE '%Tenaga Kependidikan%'
                          AND g.jenis_ptk NOT LIKE '%Kependidikan%'
                          AND g.jenis_ptk NOT LIKE '%Tendik%'
                          AND g.jenis_ptk NOT LIKE '%Keamanan%'
                          AND g.jenis_ptk NOT LIKE '%Tata Usaha%'
                          AND g.jenis_ptk NOT LIKE '%Pegawai%'
                          AND g.jenis_ptk NOT LIKE '%Staff%'
                          AND g.jenis_ptk != 'PPPK'
                          AND g.role != 'kepala_sekolah'
                          AND g.role NOT IN ('tendik', 'tenaga_kependidikan', 'pegawai', 'staff', 'keamanan')
                        ORDER BY g.name ASC
                    `).bind(weekStartDate).all();

                    const teachers = teachersRes.results || [];
                    const workWeekIds = teachers.map(t => t.work_week_id).filter(Boolean);

                    // Ambil versi rencana untuk work_weeks yang ada
                    let versionMap = {};
                    let segmentsMap = {};
                    let logsMap = {};
                    let logSegmentsMap = {};

                    if (workWeekIds.length > 0) {
                        const placeholders = workWeekIds.map(() => "?").join(",");

                        const versRes = await env.DB.prepare(`
                            SELECT * FROM weekly_plan_versions WHERE work_week_id IN (${placeholders}) ORDER BY version_number ASC
                        `).bind(...workWeekIds).all();
                        (versRes.results || []).forEach(v => {
                            if (!versionMap[v.work_week_id]) versionMap[v.work_week_id] = [];
                            versionMap[v.work_week_id].push(v);
                        });

                        // Ambil durasi rencana per segmen dan jam mengajar (JP) untuk versi approved / active
                        const segsRes = await env.DB.prepare(`
                            SELECT pts.plan_version_id,
                                SUM(pts.planned_minutes) AS total_plan_minutes,
                                SUM(CASE WHEN pts.is_teaching = 1 OR pa.catalog_id = 'cat_kbm' OR pa.category_code = 'PELAKSANAAN_KBM' THEN COALESCE(pts.jp_count, ROUND(pts.planned_minutes / 45.0), 1) ELSE 0 END) AS teaching_jp
                            FROM plan_time_segments pts
                            JOIN plan_activities pa ON pts.activity_id = pa.id
                            JOIN weekly_plan_versions wpv ON pts.plan_version_id = wpv.id
                            WHERE wpv.work_week_id IN (${placeholders})
                            GROUP BY pts.plan_version_id
                        `).bind(...workWeekIds).all();
                        (segsRes.results || []).forEach(s => {
                            segmentsMap[s.plan_version_id] = {
                                planned: s.total_plan_minutes || 0,
                                teaching_jp: s.teaching_jp || 0
                            };
                        });

                        // Ambil log realisasi
                        const logsRes = await env.DB.prepare(`
                            SELECT * FROM work_logs WHERE work_week_id IN (${placeholders})
                        `).bind(...workWeekIds).all();
                        (logsRes.results || []).forEach(l => {
                            if (!logsMap[l.work_week_id]) logsMap[l.work_week_id] = [];
                            logsMap[l.work_week_id].push(l);
                        });

                        // Ambil durasi aktual segmen log
                        const logSegsRes = await env.DB.prepare(`
                            SELECT wl.work_week_id, wl.verification_status, SUM(wls.actual_minutes) AS total_actual_minutes
                            FROM work_log_segments wls
                            JOIN work_logs wl ON wls.work_log_id = wl.id
                            WHERE wl.work_week_id IN (${placeholders})
                            GROUP BY wl.work_week_id, wl.verification_status
                        `).bind(...workWeekIds).all();
                        (logSegsRes.results || []).forEach(ls => {
                            if (!logSegmentsMap[ls.work_week_id]) logSegmentsMap[ls.work_week_id] = { total: 0, verified: 0 };
                            logSegmentsMap[ls.work_week_id].total += (ls.total_actual_minutes || 0);
                            if (ls.verification_status === "verified") {
                                logSegmentsMap[ls.work_week_id].verified += (ls.total_actual_minutes || 0);
                            }
                        });
                    }

                    const targetMinutes = 2250; // 5 hari x 450 menit
                    let totalTargetSchool = 0;
                    let totalPlannedSchool = 0;
                    let totalActualSchool = 0;
                    let totalVerifiedSchool = 0;

                    // Format ringkasan tiap guru
                    const summaries = teachers.map(t => {
                        totalTargetSchool += targetMinutes;

                        if (!t.work_week_id) {
                            return {
                                teacher_id: t.id,
                                teacher_name: t.name,
                                nip: t.nip || "-",
                                nuptk: t.nuptk || "-",
                                jenis_ptk: t.jenis_ptk || "Guru Mapel",
                                mapel: t.mapel || "-",
                                foto: t.foto || null,
                                photo_url: t.foto || null,
                                work_week_id: null,
                                plan_version_id: null,
                                plan_status: "not_started",
                                plan_status_label: "Belum Menyusun",
                                plan_version_number: 0,
                                is_locked: 0,
                                planned_minutes: 0,
                                actual_minutes: 0,
                                verified_minutes: 0,
                                teaching_jp: 0,
                                unverified_log_count: 0,
                                target_minutes: targetMinutes,
                                completion_pct: 0
                            };
                        }

                        const versions = versionMap[t.work_week_id] || [];
                        const approvedVer = versions.find(v => v.id === t.active_plan_version_id);
                        const latestVer = versions[versions.length - 1] || null;
                        const activeVer = approvedVer || latestVer;

                        let plannedMin = 0;
                        let teachingJp = 0;
                        if (activeVer) {
                            if (segmentsMap[activeVer.id]) {
                                plannedMin = segmentsMap[activeVer.id].planned || 0;
                                teachingJp = segmentsMap[activeVer.id].teaching_jp || 0;
                            } else {
                                plannedMin = activeVer.total_planned_minutes || 0;
                            }
                        }

                        const weekLogStats = logSegmentsMap[t.work_week_id] || { total: 0, verified: 0 };
                        const actualMin = weekLogStats.total || 0;
                        const verifiedMin = weekLogStats.verified || 0;
                        const teacherLogs = logsMap[t.work_week_id] || [];
                        const unverifiedCount = teacherLogs.filter(l => l.verification_status !== "verified").length;

                        totalPlannedSchool += plannedMin;
                        totalActualSchool += actualMin;
                        totalVerifiedSchool += verifiedMin;

                        const completionPct = Math.min(100, Math.round((actualMin / targetMinutes) * 100));

                        return {
                            teacher_id: t.id,
                            teacher_name: t.name,
                            teacher_nip: t.nip || "-",
                            nip: t.nip || "-",
                            nuptk: t.nuptk || "-",
                            jenis_ptk: t.jenis_ptk || "Guru Mapel",
                            mapel: t.mapel || "-",
                            foto: t.foto || null,
                            photo_url: t.foto || null,
                            has_work_week: true,
                            work_week_id: t.work_week_id,
                            plan_status: latestVer ? latestVer.status : "draft",
                            status_rencana: latestVer ? latestVer.status : "draft",
                            plan_version_id: latestVer ? latestVer.id : null,
                            planned_minutes: plannedMin,
                            actual_minutes: actualMin,
                            verified_minutes: verifiedMin,
                            teaching_jp: teachingJp,
                            unverified_log_count: unverifiedCount,
                            target_minutes: targetMinutes,
                            completion_pct: completionPct
                        };
                    });

                    return jsonResponse({
                        success: true,
                        data: {
                            week_start_date: weekStartDate,
                            kpi: {
                                total_teachers: teachers.length,
                                total_target_minutes: totalTargetSchool,
                                total_planned_minutes: totalPlannedSchool,
                                total_actual_minutes: totalActualSchool,
                                total_verified_minutes: totalVerifiedSchool,
                                average_completion_pct: teachers.length > 0 ? Math.round((totalActualSchool / totalTargetSchool) * 100) : 0
                            },
                            teachers: summaries
                        }
                    }, 200, request);
                } catch (err) {
                    return errorResponse("Gagal mengambil ringkasan monitoring: " + err.message, 500, request);
                }
            }

            // 15. GET /api/workload/export (Uji 39: Formula Injection Defense)
            if (path === "/api/workload/export" && method === "GET") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const format = url.searchParams.get("format") || "csv";
                const weekStartDate = url.searchParams.get("week_start_date");
                if (!weekStartDate) return errorResponse("Parameter week_start_date diperlukan", 400, request);

                try {
                    // Ambil summary
                    const teachersRes = await env.DB.prepare(`
                        SELECT g.id, g.name, g.nip, g.jenis_ptk,
                            ww.id AS work_week_id, ww.active_plan_version_id
                        FROM gtk g
                        LEFT JOIN work_weeks ww ON (g.id = ww.teacher_id AND ww.week_start_date = ?)
                        WHERE g.status = 'active'
                          AND (g.jenis_ptk LIKE '%Guru%' OR g.jenis_ptk = 'Pendidik')
                          AND g.jenis_ptk NOT LIKE '%Kepala Sekolah%'
                          AND g.jenis_ptk NOT LIKE '%Tenaga Kependidikan%'
                          AND g.jenis_ptk NOT LIKE '%Kependidikan%'
                          AND g.jenis_ptk NOT LIKE '%Tendik%'
                          AND g.jenis_ptk NOT LIKE '%Keamanan%'
                          AND g.jenis_ptk NOT LIKE '%Tata Usaha%'
                          AND g.jenis_ptk NOT LIKE '%Pegawai%'
                          AND g.jenis_ptk NOT LIKE '%Staff%'
                          AND g.jenis_ptk != 'PPPK'
                          AND g.role != 'kepala_sekolah'
                          AND g.role NOT IN ('tendik', 'tenaga_kependidikan', 'pegawai', 'staff', 'keamanan')
                        ORDER BY g.name ASC
                    `).bind(weekStartDate).all();

                    const teachers = teachersRes.results || [];
                    const workWeekIds = teachers.map(t => t.work_week_id).filter(Boolean);

                    let versionMap = {};
                    let logSegsTotalMap = {};
                    let logVerifiedTotalMap = {};

                    if (workWeekIds.length > 0) {
                        const placeholders = workWeekIds.map(() => "?").join(",");
                        const versRes = await env.DB.prepare(`
                            SELECT * FROM weekly_plan_versions WHERE work_week_id IN (${placeholders})
                        `).bind(...workWeekIds).all();
                        (versRes.results || []).forEach(v => {
                            if (!versionMap[v.work_week_id]) versionMap[v.work_week_id] = [];
                            versionMap[v.work_week_id].push(v);
                        });

                        const logsRes = await env.DB.prepare(`
                            SELECT wl.id, wl.work_week_id, wl.verification_status, COALESCE(SUM(wls.actual_minutes), 0) AS actual_m
                            FROM work_logs wl
                            LEFT JOIN work_log_segments wls ON wl.id = wls.work_log_id
                            WHERE wl.work_week_id IN (${placeholders})
                            GROUP BY wl.id
                        `).bind(...workWeekIds).all();

                        (logsRes.results || []).forEach(l => {
                            if (!logSegsTotalMap[l.work_week_id]) logSegsTotalMap[l.work_week_id] = 0;
                            logSegsTotalMap[l.work_week_id] += Number(l.actual_m || 0);

                            if (l.verification_status === "verified") {
                                if (!logVerifiedTotalMap[l.work_week_id]) logVerifiedTotalMap[l.work_week_id] = 0;
                                logVerifiedTotalMap[l.work_week_id] += Number(l.actual_m || 0);
                            }
                        });
                    }

                    if (format === "csv") {
                        // Header CSV
                        const headers = ["No", "Nama Guru", "NIP", "Jenis PTK", "Status Rencana", "Target (Menit)", "Rencana (Menit)", "Realisasi (Menit)", "Terverifikasi (Menit)", "Ketercapaian (%)"];
                        const rows = [headers.map(sanitizeWorkloadCsvCell).join(",")];

                        teachers.forEach((t, idx) => {
                            const versions = versionMap[t.work_week_id] || [];
                            const latestVer = versions[versions.length - 1] || null;
                            const statusRencana = latestVer ? latestVer.status : "Belum Menyusun";
                            const plannedM = latestVer ? (latestVer.total_planned_minutes || 0) : 0;
                            const actualM = logSegsTotalMap[t.work_week_id] || 0;
                            const verifiedM = logVerifiedTotalMap[t.work_week_id] || 0;
                            const pct = Math.min(100, Math.round((actualM / 2250) * 100));

                            const row = [
                                idx + 1,
                                t.name,
                                t.nip || "-",
                                t.jenis_ptk || "Guru Mapel",
                                statusRencana,
                                2250,
                                plannedM,
                                actualM,
                                verifiedM,
                                `${pct}%`
                            ];
                            rows.push(row.map(sanitizeWorkloadCsvCell).join(","));
                        });

                        const csvContent = "\uFEFF" + rows.join("\r\n"); // UTF-8 BOM untuk Excel
                        return new Response(csvContent, {
                            status: 200,
                            headers: {
                                "Content-Type": "text/csv; charset=utf-8",
                                "Content-Disposition": `attachment; filename="rekap_beban_kerja_${weekStartDate}.csv"`,
                                ...getCorsHeaders(request)
                            }
                        });
                    }

                    return jsonResponse({ success: true, teachers }, 200, request);
                } catch (err) {
                    return errorResponse("Gagal mengekspor data beban kerja: " + err.message, 500, request);
                }
            }

            // 15b. GET /api/workload/monthly-recap (Rekapitulasi Realisasi Bulanan Berbasis 5 Kategori Tugas Pokok)
            if (path === "/api/workload/monthly-recap" && method === "GET") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                let month = url.searchParams.get("month");
                if (!month || !/^\d{4}-\d{2}$/.test(month)) {
                    month = new Date(Date.now() + 8 * 3600 * 1000).toISOString().slice(0, 7);
                }

                const userTeacherId = await resolveWorkloadTeacherId(env.DB, authResult.user);
                const isMgr = isWorkloadManager(authResult.user) || isWorkloadSupervisor(authResult.user);
                const requestedTeacherId = url.searchParams.get("teacher_id");
                const targetTeacherId = isMgr && requestedTeacherId ? (await resolveWorkloadTeacherId(env.DB, authResult.user, requestedTeacherId)) : userTeacherId;

                // Isolasi Data Guru: Guru umum tidak dapat mengintip rekapitulasi beban kerja guru lain
                if (!isMgr && requestedTeacherId && requestedTeacherId !== userTeacherId) {
                    return errorResponse("Akses ditolak: Anda hanya dapat melihat rekap realisasi beban kerja Anda sendiri", 403, request);
                }

                // Batasan Akses: Modul Rekapitulasi Realisasi eksklusif untuk Pimpinan (Kepsek / Super Admin) dan Guru Whitelist VIP
                const policyCfg = await getWorkloadPolicyConfig(env.DB);
                const vipList = Array.isArray(policyCfg.vip_teacher_ids) ? policyCfg.vip_teacher_ids : [];
                const isVipUser = isMgr ||
                    (userTeacherId && vipList.includes(userTeacherId)) ||
                    (authResult.user.uid && vipList.includes(authResult.user.uid)) ||
                    (authResult.user.nip && vipList.includes(authResult.user.nip));

                if (!isVipUser) {
                    return errorResponse("Akses Terbatas: Modul Rekapitulasi Realisasi merupakan fitur eksklusif SIMAS VIP. Hubungi Super Admin untuk mendapatkan hak akses.", 403, request);
                }

                try {
                    // 1. Profil Guru
                    let teacherRow = await env.DB.prepare(`
                        SELECT id, name, nip, nuptk, jenis_ptk, mapel, foto
                        FROM gtk
                        WHERE id = ? OR nip = ?
                        LIMIT 1
                    `).bind(targetTeacherId, targetTeacherId).first();

                    if (!teacherRow && authResult.user?.email) {
                        teacherRow = await env.DB.prepare(`
                            SELECT id, name, nip, nuptk, jenis_ptk, mapel, foto
                            FROM gtk
                            WHERE LOWER(email) = ?
                            LIMIT 1
                        `).bind(authResult.user.email.toLowerCase().trim()).first();
                    }

                    const resolvedNip = (teacherRow?.nip && teacherRow.nip !== "-")
                        ? teacherRow.nip
                        : (authResult.user?.profile?.nip || authResult.user?.nip || teacherRow?.nip || "-");

                    const teacherInfo = {
                        id: targetTeacherId,
                        name: teacherRow?.name || targetTeacherId,
                        nip: resolvedNip,
                        nuptk: teacherRow?.nuptk || "-",
                        jenis_ptk: teacherRow?.jenis_ptk || "Guru Mapel",
                        mapel: teacherRow?.mapel || "-",
                        foto: teacherRow?.foto || null
                    };

                    // 2. Query work_logs guru pada bulan tersebut
                    const logsRes = await env.DB.prepare(`
                        SELECT wl.*,
                               c.name AS catalog_name,
                               c.category_code,
                               c.category_name,
                               c.is_teaching
                        FROM work_logs wl
                        LEFT JOIN activity_catalog c ON wl.catalog_id = c.id
                        WHERE wl.teacher_id = ? AND wl.date LIKE ?
                        ORDER BY wl.date ASC, wl.created_at ASC
                    `).bind(targetTeacherId, `${month}-%`).all();

                    const logs = logsRes.results || [];

                    let segmentsMap = {};
                    if (logs.length > 0) {
                        const segRes = await env.DB.prepare(`
                            SELECT wls.*
                            FROM work_log_segments wls
                            JOIN work_logs wl ON wls.work_log_id = wl.id
                            WHERE wl.teacher_id = ? AND wl.date LIKE ?
                            ORDER BY wls.start_time ASC
                        `).bind(targetTeacherId, `${month}-%`).all();

                        (segRes.results || []).forEach(seg => {
                            if (!segmentsMap[seg.work_log_id]) segmentsMap[seg.work_log_id] = [];
                            segmentsMap[seg.work_log_id].push(seg);
                        });
                    }

                    // 3. Konfigurasi 5 Kategori Tugas Pokok Permendikdasmen No. 11/2025
                    const CATEGORY_DEFS = [
                        { code: "PELAKSANAAN_KBM", name: "1. Pelaksanaan Pembelajaran (KBM Tatap Muka)", shortName: "Pelaksanaan Pembelajaran", icon: "fa-chalkboard-user" },
                        { code: "PERENCANAAN", name: "2. Perencanaan Pembelajaran (Modul Ajar, Prota, Promes, MGMP)", shortName: "Perencanaan Pembelajaran", icon: "fa-book-open" },
                        { code: "PENILAIAN", name: "3. Penilaian Hasil Pembelajaran (Asesmen & Evaluasi)", shortName: "Penilaian Hasil Pembelajaran", icon: "fa-clipboard-check" },
                        { code: "PEMBIMBINGAN", name: "4. Pembimbingan & Pelatihan Siswa (Ekskul, BK, P5)", shortName: "Pembimbingan & Pelatihan Siswa", icon: "fa-user-graduate" },
                        { code: "TUGAS_TAMBAHAN", name: "5. Pelaksanaan Tugas Tambahan (Wali Kelas, Pembina, Piket, Upacara)", shortName: "Pelaksanaan Tugas Tambahan", icon: "fa-briefcase" }
                    ];

                    const categoriesMap = {};
                    CATEGORY_DEFS.forEach(cat => {
                        categoriesMap[cat.code] = {
                            code: cat.code,
                            name: cat.name,
                            shortName: cat.shortName,
                            icon: cat.icon,
                            total_minutes: 0,
                            total_activities: 0,
                            total_teaching_jp: 0,
                            verified_count: 0,
                            unverified_count: 0,
                            rejected_count: 0,
                            sub_catalogs: {},
                            activities: []
                        };
                    });

                    const distinctDates = new Set();

                    function mapLogToCategoryCode(l) {
                        if (l.is_teaching === 1 || l.catalog_id === "cat_kbm" || l.category_code === "PELAKSANAAN_KBM") return "PELAKSANAAN_KBM";
                        if (l.category_code && categoriesMap[l.category_code]) return l.category_code;
                        const catStr = String(l.category_code || l.category_name || l.catalog_name || "").toUpperCase();
                        if (catStr.includes("RENCANA") || catStr.includes("MODUL") || catStr.includes("MGMP")) return "PERENCANAAN";
                        if (catStr.includes("NILAI") || catStr.includes("ASESMEN") || catStr.includes("EVALUASI")) return "PENILAIAN";
                        if (catStr.includes("BIMBING") || catStr.includes("EKSKUL") || catStr.includes("EKSTRA") || catStr.includes("BK") || catStr.includes("P5")) return "PEMBIMBINGAN";
                        return "TUGAS_TAMBAHAN";
                    }

                    logs.forEach(l => {
                        if (l.date) distinctDates.add(l.date);

                        const targetCode = mapLogToCategoryCode(l);
                        const catObj = categoriesMap[targetCode];

                        const segs = segmentsMap[l.id] || [];
                        let logMinutes = segs.reduce((acc, s) => acc + Number(s.actual_minutes || 0), 0);
                        if (logMinutes <= 0) logMinutes = 45;

                        const isTeaching = l.is_teaching === 1 || l.catalog_id === "cat_kbm" || targetCode === "PELAKSANAAN_KBM";
                        const teachingJp = isTeaching ? Math.max(1, Math.round(logMinutes / 45)) : 0;

                        catObj.total_minutes += logMinutes;
                        catObj.total_activities += 1;
                        if (isTeaching) catObj.total_teaching_jp += teachingJp;

                        const verStatus = (l.verification_status || "unverified").toLowerCase();
                        if (verStatus === "verified") {
                            catObj.verified_count += 1;
                        } else if (verStatus === "rejected" || verStatus === "needs_revision") {
                            catObj.rejected_count += 1;
                        } else {
                            catObj.unverified_count += 1;
                        }

                        const subCatKey = l.catalog_id || "lainnya";
                        const subCatName = l.catalog_name || l.title || "Kegiatan Beban Kerja";
                        if (!catObj.sub_catalogs[subCatKey]) {
                            catObj.sub_catalogs[subCatKey] = {
                                catalog_id: subCatKey,
                                catalog_name: subCatName,
                                total_minutes: 0,
                                total_activities: 0,
                                total_jp: 0
                            };
                        }
                        catObj.sub_catalogs[subCatKey].total_minutes += logMinutes;
                        catObj.sub_catalogs[subCatKey].total_activities += 1;
                        if (isTeaching) catObj.sub_catalogs[subCatKey].total_jp += teachingJp;

                        catObj.activities.push({
                            id: l.id,
                            work_week_id: l.work_week_id,
                            date: l.date,
                            day_of_week: l.day_of_week,
                            title: l.title,
                            catalog_id: l.catalog_id,
                            catalog_name: l.catalog_name || l.title,
                            category_code: targetCode,
                            output_summary: l.output_summary || "-",
                            evidence_url: l.evidence_url || "",
                            status_execution: l.status_execution || "terlaksana",
                            verification_status: l.verification_status || "unverified",
                            verified_at: l.verified_at || null,
                            verified_by_name: l.verified_by_name || null,
                            obstacle_notes: l.obstacle_notes || "",
                            actual_minutes: logMinutes,
                            teaching_jp: teachingJp,
                            segments: segs.map(s => ({
                                id: s.id,
                                start_time: s.start_time,
                                end_time: s.end_time,
                                actual_minutes: s.actual_minutes,
                                notes: s.notes || ""
                            }))
                        });
                    });

                    let grandMinutes = 0;
                    let grandActivities = 0;
                    let grandTeachingJp = 0;
                    let grandVerified = 0;
                    let grandUnverified = 0;
                    let grandRejected = 0;

                    const categoriesList = CATEGORY_DEFS.map(def => {
                        const item = categoriesMap[def.code];
                        grandMinutes += item.total_minutes;
                        grandActivities += item.total_activities;
                        grandTeachingJp += item.total_teaching_jp;
                        grandVerified += item.verified_count;
                        grandUnverified += item.unverified_count;
                        grandRejected += item.rejected_count;

                        const hours = Math.floor(item.total_minutes / 60);
                        const mins = item.total_minutes % 60;
                        item.total_hours_formatted = `${hours}j ${mins}m`;
                        item.sub_catalogs_list = Object.values(item.sub_catalogs);
                        return item;
                    });

                    categoriesList.forEach(c => {
                        c.percentage = grandMinutes > 0 ? Math.round((c.total_minutes / grandMinutes) * 100) : 0;
                    });

                    const grandHours = Math.floor(grandMinutes / 60);
                    const grandMins = grandMinutes % 60;

                    const [yStr, mStr] = month.split("-");
                    const monthNamesId = [
                        "Januari", "Februari", "Maret", "April", "Mei", "Juni",
                        "Juli", "Agustus", "September", "Oktober", "November", "Desember"
                    ];
                    const monthIdx = parseInt(mStr, 10) - 1;
                    const monthLabel = `${monthNamesId[monthIdx] || mStr} ${yStr}`;

                    return jsonResponse({
                        success: true,
                        data: {
                            month,
                            month_label: monthLabel,
                            teacher: teacherInfo,
                            grand_total_minutes: grandMinutes,
                            grand_total_hours_formatted: `${grandHours} Jam ${grandMins} Menit`,
                            grand_total_activities: grandActivities,
                            grand_total_teaching_jp: grandTeachingJp,
                            grand_verified_count: grandVerified,
                            grand_unverified_count: grandUnverified,
                            grand_rejected_count: grandRejected,
                            verification_percentage: grandActivities > 0 ? Math.round((grandVerified / grandActivities) * 100) : 0,
                            effective_days_count: distinctDates.size,
                            categories: categoriesList
                        }
                    }, 200, request);
                } catch (err) {
                    return errorResponse("Gagal memuat rekapitulasi realisasi bulanan: " + err.message, 500, request);
                }
            }

            // 15c. GET & POST /api/guru-mapel/ai-vip-settings — Pengaturan Hak Akses VIP Koreksi AI Guru Mapel (Super Admin Only untuk Mutasi)
            if (path === "/api/guru-mapel/ai-vip-settings") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                const userRoles = [authResult.user.role, ...(authResult.user.additionalRoles || [])].filter(Boolean);
                const isSuperAdmin = userRoles.includes("super_admin");
                const isKepsek = userRoles.includes("kepala_sekolah");

                if (method === "GET") {
                    try {
                        let config = { all_teachers: false, allowed_teacher_ids: [], allowed_uids: [] };
                        let cached = getCachedSystemSetting("koreksi_ai_vip_config");
                        let rawValue = cached?.value;

                        if (!rawValue) {
                            const row = await env.DB.prepare("SELECT value FROM system_settings WHERE key = 'koreksi_ai_vip_config' LIMIT 1").first();
                            if (row && row.value) {
                                rawValue = row.value;
                                setCachedSystemSetting("koreksi_ai_vip_config", rawValue);
                            }
                        }

                        if (rawValue) {
                            try {
                                const parsed = typeof rawValue === "string" ? JSON.parse(rawValue) : rawValue;
                                config = {
                                    all_teachers: parsed.all_teachers === true,
                                    allowed_teacher_ids: Array.isArray(parsed.allowed_teacher_ids) ? parsed.allowed_teacher_ids.map(String) : [],
                                    allowed_uids: Array.isArray(parsed.allowed_uids) ? parsed.allowed_uids.map(String) : [],
                                    updated_at: parsed.updated_at || null,
                                    updated_by: parsed.updated_by || null
                                };
                            } catch (_) {}
                        }

                        const userTeacherId = (authResult.user.linkedTeacherId || authResult.user.teacher_id || authResult.user.gtk_id) ? String(authResult.user.linkedTeacherId || authResult.user.teacher_id || authResult.user.gtk_id) : "";
                        const userUid = authResult.user.uid ? String(authResult.user.uid) : "";
                        const hasVipAccess = isSuperAdmin || isKepsek || config.all_teachers === true ||
                            (userTeacherId && config.allowed_teacher_ids.includes(userTeacherId)) ||
                            (userUid && config.allowed_uids.includes(userUid));

                        if (isSuperAdmin) {
                            return jsonResponse({
                                success: true,
                                has_vip_access: true,
                                config: config
                            }, 200, request);
                        } else {
                            return jsonResponse({
                                success: true,
                                has_vip_access: Boolean(hasVipAccess),
                                all_teachers: config.all_teachers === true
                            }, 200, request);
                        }
                    } catch (err) {
                        return errorResponse("Gagal mengambil pengaturan VIP Koreksi AI: " + err.message, 500, request);
                    }
                }

                if (method === "POST") {
                    if (!isSuperAdmin) {
                        return errorResponse("Forbidden: Hanya Super Admin yang berwenang mengubah hak akses VIP Koreksi AI", 403, request);
                    }

                    try {
                        const body = await request.json();
                        const allTeachers = body.all_teachers === true;
                        const allowedTeacherIds = Array.isArray(body.allowed_teacher_ids)
                            ? Array.from(new Set(body.allowed_teacher_ids.map(String).filter(Boolean)))
                            : [];
                        const allowedUids = Array.isArray(body.allowed_uids)
                            ? Array.from(new Set(body.allowed_uids.map(String).filter(Boolean)))
                            : [];

                        const newConfig = {
                            all_teachers: allTeachers,
                            allowed_teacher_ids: allowedTeacherIds,
                            allowed_uids: allowedUids,
                            updated_at: new Date().toISOString(),
                            updated_by: authResult.user.uid || "super_admin"
                        };

                        const jsonVal = JSON.stringify(newConfig);
                        await env.DB.prepare(`
                            INSERT INTO system_settings (key, value, updated_at)
                            VALUES ('koreksi_ai_vip_config', ?, datetime('now'))
                            ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = datetime('now')
                        `).bind(jsonVal).run();

                        invalidateSystemSettingCache("koreksi_ai_vip_config");

                        await recordWorkloadAuditLog(
                            env.DB, "system_settings", "koreksi_ai_vip_config", "UPDATE_KOREKSI_AI_VIP",
                            authResult.user.uid, authResult.user.name || authResult.user.email,
                            { allowed_teachers_count: allowedTeacherIds.length, all_teachers: allTeachers }
                        );

                        return jsonResponse({
                            success: true,
                            message: "Pengaturan hak akses VIP Koreksi AI berhasil disimpan",
                            config: newConfig
                        }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal menyimpan pengaturan VIP Koreksi AI: " + err.message, 500, request);
                    }
                }

                return errorResponse("Method Not Allowed", 405, request);
            }

            // 15d. GET /api/vip/status-summary — Ringkasan Agregat Status VIP Terpadu (Untuk Penanda Foto Profil VIP)
            if (path === "/api/vip/status-summary" && method === "GET") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                try {
                    // Ambil 3 konfigurasi dari system_settings sekaligus
                    const rows = await env.DB.prepare(`
                        SELECT key, value FROM system_settings
                        WHERE key IN ('workload_policy_config', 'employee_agenda_vip_config', 'koreksi_ai_vip_config')
                    `).all();

                    const settingsMap = {};
                    (rows.results || []).forEach(r => {
                        try {
                            settingsMap[r.key] = typeof r.value === "string" ? JSON.parse(r.value) : r.value;
                        } catch (_) {
                            settingsMap[r.key] = null;
                        }
                    });

                    const workloadCfg = settingsMap['workload_policy_config'] || {};
                    const tendikCfg = settingsMap['employee_agenda_vip_config'] || {};
                    const aiCfg = settingsMap['koreksi_ai_vip_config'] || {};

                    const vipPtkIdSet = new Set();
                    const vipUidSet = new Set();

                    // 1. Whitelist Guru E-Kinerja
                    if (Array.isArray(workloadCfg.vip_teacher_ids)) {
                        workloadCfg.vip_teacher_ids.forEach(id => { if (id) vipPtkIdSet.add(String(id)); });
                    }

                    // 2. Whitelist Tendik
                    if (Array.isArray(tendikCfg.allowed_gtk_ids)) {
                        tendikCfg.allowed_gtk_ids.forEach(id => { if (id) vipPtkIdSet.add(String(id)); });
                    }
                    if (Array.isArray(tendikCfg.allowed_uids)) {
                        tendikCfg.allowed_uids.forEach(uid => { if (uid) vipUidSet.add(String(uid)); });
                    }

                    // 3. Whitelist Koreksi AI Guru Mapel
                    if (Array.isArray(aiCfg.allowed_teacher_ids)) {
                        aiCfg.allowed_teacher_ids.forEach(id => { if (id) vipPtkIdSet.add(String(id)); });
                    }
                    if (Array.isArray(aiCfg.allowed_uids)) {
                        aiCfg.allowed_uids.forEach(uid => { if (uid) vipUidSet.add(String(uid)); });
                    }

                    // 4. Jika all_tendik aktif, tambahkan semua id tendik aktif
                    if (tendikCfg.all_tendik === true) {
                        const tendikRows = await env.DB.prepare(`
                            SELECT id FROM gtk
                            WHERE status = 'active' AND (
                                jenis_ptk LIKE '%Tenaga Kependidikan%' OR jenis_ptk LIKE '%Kependidikan%' OR
                                jenis_ptk LIKE '%Tendik%' OR jenis_ptk LIKE '%Tata Usaha%' OR
                                jenis_ptk LIKE '%Keamanan%' OR
                                role IN ('tendik', 'tenaga_kependidikan', 'pegawai', 'staff', 'keamanan') OR
                                id IN (SELECT gtk_id FROM employee_assignments WHERE status = 'active' AND gtk_id IS NOT NULL)
                            )
                        `).all();
                        (tendikRows.results || []).forEach(r => { if (r.id) vipPtkIdSet.add(String(r.id)); });
                    }

                    // 5. Tambahkan Kepala Sekolah (Otomatis VIP)
                    const kepsekRows = await env.DB.prepare(`
                        SELECT id FROM gtk
                        WHERE status = 'active' AND (role = 'kepala_sekolah' OR jenis_ptk LIKE '%Kepala Sekolah%')
                    `).all();
                    (kepsekRows.results || []).forEach(r => { if (r.id) vipPtkIdSet.add(String(r.id)); });

                    // Evaluasi apakah user yang sedang login adalah VIP
                    const callerRoles = [authResult.user.role, ...(authResult.user.additionalRoles || [])].filter(Boolean);
                    const isKepsekCaller = callerRoles.includes("kepala_sekolah");
                    const userGtkId = (authResult.user.linkedTeacherId || authResult.user.teacher_id || authResult.user.gtk_id) ? String(authResult.user.linkedTeacherId || authResult.user.teacher_id || authResult.user.gtk_id) : "";
                    const userUid = authResult.user.uid ? String(authResult.user.uid) : "";

                    const isCurrentUserVip = isKepsekCaller ||
                        (userGtkId && vipPtkIdSet.has(userGtkId)) ||
                        (userUid && vipUidSet.has(userUid));

                    return jsonResponse({
                        success: true,
                        vip_ptk_ids: Array.from(vipPtkIdSet),
                        vip_uids: Array.from(vipUidSet),
                        is_current_user_vip: Boolean(isCurrentUserVip)
                    }, 200, request);
                } catch (err) {
                    return errorResponse("Gagal mengambil ringkasan status VIP: " + err.message, 500, request);
                }
            }

            // 16. GET & POST /api/workload/delegations (Pengelolaan Delegasi Pemeriksaan)
            if (path === "/api/workload/delegations") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                if (method === "GET") {
                    try {
                        const delegations = await env.DB.prepare(`
                            SELECT * FROM workload_delegations ORDER BY valid_until DESC
                        `).all();
                        return jsonResponse({ success: true, data: delegations.results || [] }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal mengambil daftar delegasi: " + err.message, 500, request);
                    }
                }

                if (method === "POST") {
                    if (!isWorkloadManager(authResult.user)) {
                        return errorResponse("Forbidden: Hanya Kepala Sekolah yang berwenang mendelegasikan tugas pemeriksaan", 403, request);
                    }
                    try {
                        const body = await request.json();
                        const {
                            id = crypto.randomUUID(),
                            delegatee_uid,
                            delegatee_name,
                            permission_scope = "review_all",
                            sk_number,
                            valid_from,
                            valid_until,
                            status = "active"
                        } = body;

                        if (!delegatee_uid || !delegatee_name || !sk_number || !valid_from || !valid_until) {
                            return errorResponse("delegatee_uid, delegatee_name, sk_number, valid_from, dan valid_until wajib diisi", 400, request);
                        }

                        await env.DB.prepare(`
                            INSERT INTO workload_delegations (
                                id, delegator_uid, delegatee_uid, delegatee_name,
                                permission_scope, sk_number, valid_from, valid_until, status, created_at
                            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
                            ON CONFLICT(id) DO UPDATE SET
                                permission_scope = excluded.permission_scope,
                                sk_number = excluded.sk_number,
                                valid_from = excluded.valid_from,
                                valid_until = excluded.valid_until,
                                status = excluded.status
                        `).bind(
                            id, authResult.user.uid, delegatee_uid, delegatee_name,
                            permission_scope, sk_number, valid_from, valid_until, status
                        ).run();

                        return jsonResponse({ success: true, message: "Delegasi pemeriksaan berhasil disimpan" }, 200, request);
                    } catch (err) {
                        return errorResponse("Gagal menyimpan delegasi: " + err.message, 500, request);
                    }
                }

                return errorResponse("Method tidak didukung", 405, request);
            }

            // =================================================================
            // 🔐 ROUTE: LOGIN HISTORY (/api/login-history)
            // =================================================================

            // GET /api/login-history (Khusus Super Admin & Kepala Sekolah - Membaca dari Supabase)
            if (path === "/api/login-history" && method === "GET") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                const allowedRoles = ["super_admin", "kepala_sekolah"];
                const isAuthorized = allowedRoles.includes(authResult.user.role) ||
                    (authResult.user.additionalRoles && authResult.user.additionalRoles.some(r => allowedRoles.includes(r)));

                if (!isAuthorized) {
                    return errorResponse("Forbidden: Access restricted to Super Admin and Kepala Sekolah", 403, request);
                }

                const start = url.searchParams.get("start");
                const end = url.searchParams.get("end");
                const role = url.searchParams.get("role");
                const limit = parseInt(url.searchParams.get("limit") || "500", 10);
                const offset = parseInt(url.searchParams.get("offset") || "0", 10);

                const supabaseUrl = (env.SUPABASE_URL || DEFAULT_SUPABASE_URL).replace(/\/$/, '');
                const supabaseKey = getSupabaseServerKey(env);

                const queryParams = new URLSearchParams();
                queryParams.set('select', '*');
                queryParams.set('order', 'login_at.desc');
                queryParams.set('limit', String(limit));
                queryParams.set('offset', String(offset));

                if (start && end) {
                    const startVal = start.includes("T") ? start : `${start}T00:00:00.000Z`;
                    const endVal = end.includes("T") ? end : `${end}T23:59:59.999Z`;
                    queryParams.set('and', `(login_at.gte.${startVal},login_at.lte.${endVal})`);
                } else if (start) {
                    const startVal = start.includes("T") ? start : `${start}T00:00:00.000Z`;
                    queryParams.set('login_at', `gte.${startVal}`);
                } else if (end) {
                    const endVal = end.includes("T") ? end : `${end}T23:59:59.999Z`;
                    queryParams.set('login_at', `lte.${endVal}`);
                }

                if (role && role !== "all") {
                    queryParams.set('role', `eq.${role}`);
                }

                try {
                    const sbRes = await fetch(`${supabaseUrl}/rest/v1/login_history?${queryParams.toString()}`, {
                        method: 'GET',
                        headers: {
                            'apikey': supabaseKey,
                            'Authorization': `Bearer ${supabaseKey}`
                        }
                    });

                    if (!sbRes.ok) {
                        const errTxt = await sbRes.text();
                        console.warn("[GET login-history Supabase Error]:", sbRes.status, errTxt);
                        return errorResponse("Gagal mengambil riwayat login dari database: " + errTxt, sbRes.status, request);
                    }

                    const results = await sbRes.json();
                    return jsonResponse({ success: true, data: results || [] }, 200, request);
                } catch (e) {
                    console.error("[GET login-history Network Error]:", e);
                    return errorResponse("Gagal terhubung ke database riwayat login: " + e.message, 502, request);
                }
            }

            // POST /api/login-history (Catat Log Login Baru ke Supabase - Wajib Token Valid)
            if (path === "/api/login-history" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                const body = await request.json();
                const { id, email, name, role, login_at, user_agent } = body;

                // Bind UID ke UID token otentik untuk mencegah pemalsuan identitas
                const targetUid = (authResult.user.role === "super_admin" && body.uid) ? body.uid : authResult.user.uid;

                const logId = id || "log_" + Date.now() + "_" + Math.random().toString(36).substring(2, 7);
                const loginAt = login_at || new Date().toISOString();

                const supabaseUrl = (env.SUPABASE_URL || DEFAULT_SUPABASE_URL).replace(/\/$/, '');
                const supabaseKey = getSupabaseServerKey(env);

                const payload = {
                    id: logId,
                    uid: String(targetUid).trim(),
                    email: email ? String(email).trim() : authResult.user.email,
                    name: name ? String(name).trim() : "Pengguna",
                    role: role ? String(role).trim() : (authResult.user.role || "unknown"),
                    login_at: loginAt,
                    user_agent: user_agent ? String(user_agent).trim() : ""
                };

                try {
                    const sbRes = await fetch(`${supabaseUrl}/rest/v1/login_history`, {
                        method: 'POST',
                        headers: {
                            'apikey': supabaseKey,
                            'Authorization': `Bearer ${supabaseKey}`,
                            'Content-Type': 'application/json',
                            'Prefer': 'resolution=merge-duplicates,return=minimal'
                        },
                        body: JSON.stringify(payload)
                    });

                    if (!sbRes.ok) {
                        console.warn("[POST login-history Supabase Error]:", sbRes.status, await sbRes.text());
                    }
                } catch (e) {
                    console.warn("[POST login-history Network Error]:", e.message);
                }

                return jsonResponse({ success: true, id: logId, message: "Login activity logged" }, 201, request);
            }

            // =================================================================
            // 🛡️ ROUTE: AUDIT LOGS (/api/audit-logs)
            // =================================================================

            // GET /api/audit-logs (Khusus Super Admin & Kepala Sekolah - Membaca dari Supabase)
            if (path === "/api/audit-logs" && method === "GET") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                const allowedRoles = ["super_admin", "kepala_sekolah"];
                const isAuthorized = allowedRoles.includes(authResult.user.role) ||
                    (authResult.user.additionalRoles && authResult.user.additionalRoles.some(r => allowedRoles.includes(r)));

                if (!isAuthorized) {
                    return errorResponse("Forbidden: Access restricted to Super Admin and Kepala Sekolah", 403, request);
                }

                const start = url.searchParams.get("start");
                const end = url.searchParams.get("end");
                const action = url.searchParams.get("action");
                const targetId = url.searchParams.get("target_id") || url.searchParams.get("targetId");
                const actorUid = url.searchParams.get("actor_uid") || url.searchParams.get("actorUid");
                const actorName = url.searchParams.get("actor_name") || url.searchParams.get("actorName");
                const limit = parseInt(url.searchParams.get("limit") || "200", 10);
                const offset = parseInt(url.searchParams.get("offset") || "0", 10);

                const supabaseUrl = (env.SUPABASE_URL || DEFAULT_SUPABASE_URL).replace(/\/$/, '');
                const supabaseKey = getSupabaseServerKey(env);

                const queryParams = new URLSearchParams();
                queryParams.set('select', '*');
                queryParams.set('order', 'timestamp.desc');
                queryParams.set('limit', String(limit));
                queryParams.set('offset', String(offset));

                if (start && end) {
                    const startVal = start.includes("T") ? start : `${start}T00:00:00.000Z`;
                    const endVal = end.includes("T") ? end : `${end}T23:59:59.999Z`;
                    queryParams.set('and', `(timestamp.gte.${startVal},timestamp.lte.${endVal})`);
                } else if (start) {
                    const startVal = start.includes("T") ? start : `${start}T00:00:00.000Z`;
                    queryParams.set('timestamp', `gte.${startVal}`);
                } else if (end) {
                    const endVal = end.includes("T") ? end : `${end}T23:59:59.999Z`;
                    queryParams.set('timestamp', `lte.${endVal}`);
                }

                if (action && action !== "all") {
                    queryParams.set('action', `eq.${action}`);
                }
                if (targetId) {
                    queryParams.set('target_id', `eq.${targetId.trim()}`);
                }
                if (actorUid) {
                    queryParams.set('actor_uid', `eq.${actorUid.trim()}`);
                }
                if (actorName) {
                    queryParams.set('actor_name', `ilike.*${actorName.trim()}*`);
                }

                try {
                    const sbRes = await fetch(`${supabaseUrl}/rest/v1/audit_logs?${queryParams.toString()}`, {
                        method: 'GET',
                        headers: {
                            'apikey': supabaseKey,
                            'Authorization': `Bearer ${supabaseKey}`
                        }
                    });

                    if (!sbRes.ok) {
                        const errTxt = await sbRes.text();
                        console.warn("[GET audit-logs Supabase Error]:", sbRes.status, errTxt);
                        return errorResponse("Gagal mengambil log audit dari database: " + errTxt, sbRes.status, request);
                    }

                    const results = await sbRes.json();
                    return jsonResponse({ success: true, data: results || [] }, 200, request);
                } catch (e) {
                    console.error("[GET audit-logs Network Error]:", e);
                    return errorResponse("Gagal terhubung ke database log audit: " + e.message, 502, request);
                }
            }

            // POST /api/audit-logs (Catat Jejak Audit ke Supabase - Wajib Token Valid)
            if (path === "/api/audit-logs" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                const body = await request.json();
                const { id, action, target_id, actor_name, old_data, new_data, details, timestamp } = body;

                if (!action) {
                    return errorResponse("Missing required field: action", 400, request);
                }

                // Bind actor UID ke token otentik
                const actorUid = (authResult.user.role === "super_admin" && body.actor_uid) ? body.actor_uid : authResult.user.uid;
                const logId = id || "audit_" + Date.now() + "_" + Math.random().toString(36).substring(2, 7);

                await recordAuditLog(env, {
                    id: logId,
                    action,
                    target_id,
                    actor_uid: actorUid,
                    actor_name: actor_name ? String(actor_name).trim() : (authResult.user.displayName || authResult.user.email || "Pengguna"),
                    old_data,
                    new_data,
                    details,
                    timestamp
                });

                return jsonResponse({ success: true, id: logId, message: "Audit log recorded" }, 201, request);
            }


            // =================================================================
            // 🔄 ROUTE: BATCH TELEMETRY MIGRATION (/api/migrate/telemetry)
            // =================================================================
            if (path === "/api/migrate/telemetry" && method === "POST") {
                const migrationKey = request.headers.get("X-Migration-Key") || url.searchParams.get("key");
                const isSecretValid = env.MIGRATION_SECRET && migrationKey && migrationKey === env.MIGRATION_SECRET;
                
                const authResult = await verifyFirebaseToken(request);
                const isSuperAdmin = authResult.valid && authResult.user.role === "super_admin";

                if (!isSuperAdmin && !isSecretValid) {
                    return errorResponse("Unauthorized: Migration requires super_admin authentication or valid migration secret", 401, request);
                }

                const body = await request.json();
                const { loginHistory = [], auditLogs = [] } = body;

                const supabaseUrl = (env.SUPABASE_URL || DEFAULT_SUPABASE_URL).replace(/\/$/, '');
                const supabaseKey = getSupabaseServerKey(env);

                if (loginHistory.length > 0) {
                    const mappedLogins = loginHistory.map(item => ({
                        id: item.id || crypto.randomUUID(),
                        uid: String(item.uid || "").trim(),
                        email: item.email ? String(item.email).trim() : null,
                        name: item.name ? String(item.name).trim() : "Pengguna",
                        role: item.role ? String(item.role).trim() : "unknown",
                        login_at: item.login_at || new Date().toISOString(),
                        user_agent: item.user_agent ? String(item.user_agent).trim() : null
                    }));
                    await fetch(`${supabaseUrl}/rest/v1/login_history`, {
                        method: 'POST',
                        headers: {
                            'apikey': supabaseKey,
                            'Authorization': `Bearer ${supabaseKey}`,
                            'Content-Type': 'application/json',
                            'Prefer': 'resolution=merge-duplicates,return=minimal'
                        },
                        body: JSON.stringify(mappedLogins)
                    });
                }

                if (auditLogs.length > 0) {
                    const mappedAudits = auditLogs.map(item => {
                        const oldStr = typeof item.old_data === "object" && item.old_data !== null ? JSON.stringify(item.old_data) : (item.old_data || null);
                        const newStr = typeof item.new_data === "object" && item.new_data !== null ? JSON.stringify(item.new_data) : (item.new_data || null);
                        return {
                            id: item.id || crypto.randomUUID(),
                            action: String(item.action || "UNKNOWN").trim(),
                            target_id: item.target_id ? String(item.target_id).trim() : null,
                            actor_uid: item.actor_uid ? String(item.actor_uid).trim() : "system",
                            actor_name: item.actor_name ? String(item.actor_name).trim() : "System",
                            old_data: oldStr,
                            new_data: newStr,
                            details: item.details ? String(item.details).trim() : null,
                            timestamp: item.timestamp || new Date().toISOString()
                        };
                    });
                    await fetch(`${supabaseUrl}/rest/v1/audit_logs`, {
                        method: 'POST',
                        headers: {
                            'apikey': supabaseKey,
                            'Authorization': `Bearer ${supabaseKey}`,
                            'Content-Type': 'application/json',
                            'Prefer': 'resolution=merge-duplicates,return=minimal'
                        },
                        body: JSON.stringify(mappedAudits)
                    });
                }

                return jsonResponse({
                    success: true,
                    migratedLoginHistory: loginHistory.length,
                    migratedAuditLogs: auditLogs.length,
                    message: "Data login_history dan audit_logs berhasil dimigrasikan ke Supabase PostgreSQL."
                }, 200, request);
            }

            // =================================================================
            // 🔄 ROUTE: SINKRONISASI JURNAL MENGAJAR (/api/sync/jurnal-students)
            // Standar: OWASP ASVS Level 1 & 2 (Data Minimization, M2M Secret & Audit Log)
            // =================================================================
            if (path === "/api/sync/jurnal-students" && method === "GET") {
                const syncKey = request.headers.get("X-Sync-Key") || request.headers.get("X-Api-Key") || url.searchParams.get("key");
                const isSecretValid = Boolean(syncKey && env.MIGRATION_SECRET && syncKey === env.MIGRATION_SECRET);

                let isAuthorized = isSecretValid;
                let actorName = "Jurnal Integration Service (Server-to-Server)";

                if (!isAuthorized) {
                    const authResult = await verifyFirebaseToken(request);
                    if (authResult.valid && isStaffOrTeacher(authResult.user)) {
                        isAuthorized = true;
                        actorName = authResult.user.email || authResult.user.uid;
                    }
                }

                const classParam = url.searchParams.get("class");
                const classesParam = url.searchParams.get("classes"); // Support comma-separated 'X-1,XI-2'
                const statusParam = (url.searchParams.get("status") || "active").toLowerCase().trim();

                // ASVS Data Minimization: Jika bukan staf/secret terotorisasi, hanya izinkan query per-kelas untuk form jurnal presensi
                const isSingleClassQuery = Boolean(classParam && classParam.trim() && classParam !== "all" && classParam !== "Semua");
                if (!isAuthorized && !isSingleClassQuery) {
                    return errorResponse("Unauthorized: Akses sinkronisasi massal ditolak. Diperlukan secret key integrasi atau token otentikasi staf/admin.", 401, request);
                }

                // Rate limiting khusus pemanggilan publik / unauthenticated QR jurnal
                if (!isAuthorized) {
                    const clientIp = request.headers.get("CF-Connecting-IP") || request.headers.get("x-forwarded-for") || "unknown";
                    const rateLimitId = await sha256Id(`jurnal_students:${clientIp}`);
                    const allowed = await consumeD1RateLimit(env, rateLimitId, 60, 5 * 60 * 1000);
                    if (!allowed) {
                        return errorResponse("Terlalu banyak permintaan data presensi jurnal. Silakan coba beberapa saat lagi.", 429, request);
                    }
                }

                let sql = isAuthorized 
                    ? `SELECT nis, nisn, name, class, status FROM students WHERE 1=1`
                    : `SELECT nis, name, class, status FROM students WHERE 1=1`;
                const params = [];

                if (statusParam && statusParam !== "all" && statusParam !== "semua") {
                    sql += ` AND status = ?`;
                    params.push(statusParam);
                }

                if (isAuthorized && classesParam && classesParam.trim()) {
                    const classList = classesParam.split(",").map(c => c.trim()).filter(Boolean);
                    if (classList.length > 0) {
                        const placeholders = classList.map(() => "?").join(",");
                        sql += ` AND class IN (${placeholders})`;
                        params.push(...classList);
                    }
                } else if (classParam && classParam !== "all" && classParam !== "Semua") {
                    const cleanClass = classParam.trim();
                    const altClass = cleanClass.includes(".") ? cleanClass.replace(/\./g, "-") : cleanClass.replace(/-/g, ".");
                    sql += ` AND (class = ? OR class = ? OR REPLACE(class, '-', '.') = REPLACE(?, '-', '.'))`;
                    params.push(cleanClass, altClass, cleanClass);
                }

                sql += ` ORDER BY class ASC, name ASC LIMIT 3000`;

                const stmt = env.DB.prepare(sql);
                const { results } = await stmt.bind(...params).all();

                // ASVS Level 2 Data Minimization: Kembalikan hanya identitas dasar presensi tanpa NIK/KK/TTL/Data Orang Tua
                const formatted = (results || []).map(row => ({
                    nis: row.nis,
                    ...(isAuthorized ? { nisn: row.nisn || "-" } : {}),
                    nama: row.name || "Tanpa Nama",
                    kelas: row.class || "-",
                    status: row.status || "active"
                }));

                return jsonResponse({
                    success: true,
                    source: "cloudflare-d1",
                    count: formatted.length,
                    timestamp: new Date().toISOString(),
                    data: formatted
                }, 200, request);
            }


            // =================================================================
            // 🎓 ROUTES: MASTER DATA SISWA & DAPODIK (/api/students)
            // Standar: OWASP Top 10 & ASVS Level 1 & 2 (RS256 JWT, RBAC & Prepared SQL)
            // =================================================================

            // 1. GET /api/students (List Siswa dengan filter kelas, status, search, limit, offset)
            if (path === "/api/students" && method === "GET") {
                const syncKey = request.headers.get("X-Sync-Key") || request.headers.get("X-Api-Key") || request.headers.get("X-Migration-Key") || url.searchParams.get("key");
                const isSecretValid = Boolean(syncKey && env.MIGRATION_SECRET && syncKey === env.MIGRATION_SECRET);

                let authUser = null;
                if (!isSecretValid) {
                    const authResult = await verifyFirebaseToken(request);
                    if (!authResult.valid) {
                        return errorResponse("Unauthorized: " + authResult.error, 401, request);
                    }
                    if (!isStaffOrTeacher(authResult.user)) {
                        return errorResponse("Forbidden: Akses ditolak untuk role ini", 403, request);
                    }
                    authUser = authResult.user;
                }

                const includeSensitivePii = isSecretValid || canViewSensitiveStudentPii(authUser);

                const classParam = url.searchParams.get("class");
                const statusParam = url.searchParams.get("status") || "active";
                const searchParam = url.searchParams.get("search") || url.searchParams.get("q");
                const limitParam = parseInt(url.searchParams.get("limit") || "1000", 10);
                const offsetParam = parseInt(url.searchParams.get("offset") || "0", 10);
                const safeLimit = Math.min(Math.max(limitParam, 1), 2000);
                const safeOffset = Math.max(offsetParam, 0);

                let sql = `
                    SELECT s.*, 
                           sp.active_photo_url, 
                           sp.pending_photo_url, 
                           sp.status AS photo_status, 
                           sp.public_token, 
                           sp.rejection_reason,
                           sp.verified_at AS photo_verified_at,
                           sp.verified_by_name AS photo_verified_by_name
                    FROM students s
                    LEFT JOIN student_photos sp ON sp.nis = s.nis
                    WHERE 1=1
                `;
                const params = [];

                if (classParam && classParam !== "all" && classParam !== "Semua") {
                    const cleanClass = classParam.trim();
                    const altClass = cleanClass.includes(".") ? cleanClass.replace(/\./g, "-") : cleanClass.replace(/-/g, ".");
                    sql += ` AND (s.class = ? OR s.class = ? OR REPLACE(s.class, '-', '.') = REPLACE(?, '-', '.'))`;
                    params.push(cleanClass, altClass, cleanClass);
                }

                if (statusParam && statusParam !== "all" && statusParam !== "semua") {
                    sql += ` AND s.status = ?`;
                    params.push(statusParam.trim().toLowerCase());
                }

                if (searchParam && searchParam.trim()) {
                    const term = `%${searchParam.trim()}%`;
                    if (includeSensitivePii) {
                        sql += ` AND (s.nis LIKE ? OR s.name LIKE ? OR s.nisn LIKE ? OR s.nik LIKE ?)`;
                        params.push(term, term, term, term);
                    } else {
                        sql += ` AND (s.nis LIKE ? OR s.name LIKE ?)`;
                        params.push(term, term);
                    }
                }

                sql += ` ORDER BY s.class ASC, s.name ASC LIMIT ? OFFSET ?`;
                params.push(safeLimit, safeOffset);

                let studentsIndex = null;
                const hasClassFilter = Boolean(classParam && classParam !== "all" && classParam !== "Semua");
                const hasStatusFilter = Boolean(statusParam && statusParam !== "all" && statusParam !== "semua");
                const hasSearchFilter = Boolean(searchParam && searchParam.trim());

                if (hasStatusFilter && !hasClassFilter && !hasSearchFilter) {
                    studentsIndex = "idx_students_status_class_name";
                }

                const indexedSql = studentsIndex
                    ? sql.replace("FROM students s", `FROM students s INDEXED BY ${studentsIndex}`)
                    : sql;

                let results;
                try {
                    ({ results } = await env.DB.prepare(indexedSql).bind(...params).all());
                } catch (error) {
                    const message = `${error.message || ""} ${error.cause?.message || ""}`;
                    if (!studentsIndex || !message.includes(`no such index: ${studentsIndex}`)) throw error;
                    ({ results } = await env.DB.prepare(sql).bind(...params).all());
                }
                const formatted = (results || []).map(row => formatStudentRow(row, env, { includeSensitivePii }));

                return jsonResponse({
                    success: true,
                    data: formatted,
                    count: formatted.length
                }, 200, request);
            }

            // 2. GET /api/students/:nis (Detail Siswa Tunggal)
            if (path.startsWith("/api/students/") && method === "GET" && path.split("/").length === 4) {
                const nisParam = decodeURIComponent(path.split("/")[3]).trim();
                const authResult = await verifyFirebaseToken(request, env);
                let user = authResult.valid ? authResult.user : null;
                let isOwner = false;

                if (user) {
                    const studentNisClaim = user.claims?.studentNis || user.claims?.nis;
                    isOwner = Boolean(studentNisClaim && String(studentNisClaim).trim() === nisParam);
                }

                if (!isOwner) {
                    const studentSession = await getVerifiedStudentSession(request, env, authResult);
                    if (studentSession && String(studentSession.nis).trim() === nisParam) {
                        isOwner = true;
                    }
                }

                if (!authResult.valid && !isOwner) {
                    return errorResponse("Unauthorized: " + (authResult.error || "Autentikasi gagal"), 401, request);
                }

                if (!isStaffOrTeacher(user) && !isOwner) {
                    return errorResponse("Forbidden: Anda hanya diizinkan mengakses data diri sendiri", 403, request);
                }

                const stmt = env.DB.prepare(`
                    SELECT s.*, 
                           sp.active_photo_url, 
                           sp.pending_photo_url, 
                           sp.status AS photo_status, 
                           sp.public_token, 
                           sp.rejection_reason,
                           sp.verified_at AS photo_verified_at,
                           sp.verified_by_name AS photo_verified_by_name
                    FROM students s
                    LEFT JOIN student_photos sp ON sp.nis = s.nis
                    WHERE s.nis = ? 
                    LIMIT 1
                `);
                const row = await stmt.bind(nisParam).first();

                if (!row) {
                    return errorResponse("Data siswa tidak ditemukan", 404, request);
                }

                const includeSensitivePii = isOwner || canViewSensitiveStudentPii(user);

                return jsonResponse({
                    success: true,
                    data: formatStudentRow(row, env, { includeSensitivePii })
                }, 200, request);
            }

            // 3. POST /api/students (Tambah Siswa Baru)
            if (path === "/api/students" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }
                if (!canMutateStudent(authResult.user)) {
                    return errorResponse("Forbidden: Anda tidak memiliki wewenang menambah data siswa", 403, request);
                }

                const body = await request.json();
                const nis = String(body.nis || "").trim();
                const name = String(body.name || "").trim();

                if (!nis || !name) {
                    return errorResponse("NIS dan Nama Siswa wajib diisi", 400, request);
                }

                // Cek duplikasi NIS
                const existing = await env.DB.prepare(`SELECT nis FROM students WHERE nis = ? LIMIT 1`).bind(nis).first();
                if (existing) {
                    return errorResponse("Siswa dengan NIS " + nis + " sudah terdaftar di sistem", 409, request);
                }

                const nisn = body.nisn ? String(body.nisn).trim() : "";
                const gender = body.gender ? String(body.gender).trim().toUpperCase() : "";
                const className = body.class || body.kelas ? String(body.class || body.kelas).trim() : "";
                const birthPlace = body.birthPlace ? String(body.birthPlace).trim() : "";
                const birthDate = body.birthDate ? String(body.birthDate).trim() : "";
                const nik = body.nik ? String(body.nik).trim() : "";
                const status = body.status ? String(body.status).trim().toLowerCase() : "active";
                const violationPoints = Number(body.violationPoints || 0);

                const dapodikJson = JSON.stringify(body);

                const stmt = env.DB.prepare(`
                    INSERT INTO students (nis, nisn, name, gender, class, birth_place, birth_date, nik, status, violation_points, dapodik_data, created_at, updated_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))
                `);

                await stmt.bind(nis, nisn, name, gender, className, birthPlace, birthDate, nik, status, violationPoints, dapodikJson).run();

                if (className) {
                    await autoSyncMetadataClasses(env.DB, [className]);
                } else {
                    invalidateMasterBundleCache();
                }
                await updateServerMetadata(env.DB, { lastUpdateStudents: Date.now() });

                return jsonResponse({
                    success: true,
                    nis,
                    message: "Data siswa berhasil ditambahkan ke Cloudflare D1"
                }, 201, request);
            }

            // 4. PUT /api/students/:nis (Edit Siswa - Mendukung Full Update Admin & Whitelist Siswa Mandiri)
            if (path.startsWith("/api/students/") && method === "PUT" && path.split("/").length === 4) {
                const nisParam = decodeURIComponent(path.split("/")[3]).trim();
                const authResult = await verifyFirebaseToken(request, env);
                let user = authResult.valid ? authResult.user : null;
                let isOwner = false;

                if (user) {
                    const studentNisClaim = user.claims?.studentNis || user.claims?.nis;
                    isOwner = Boolean(studentNisClaim && String(studentNisClaim).trim() === nisParam);
                }

                if (!isOwner) {
                    const studentSession = await getVerifiedStudentSession(request, env, authResult);
                    if (studentSession && String(studentSession.nis).trim() === nisParam) {
                        isOwner = true;
                    }
                }

                if (!authResult.valid && !isOwner) {
                    return errorResponse("Unauthorized: " + (authResult.error || "Autentikasi gagal"), 401, request);
                }

                const existingRow = await env.DB.prepare(`SELECT * FROM students WHERE nis = ? LIMIT 1`).bind(nisParam).first();
                if (!existingRow) {
                    return errorResponse("Data siswa dengan NIS " + nisParam + " tidak ditemukan", 404, request);
                }

                // Otorisasi Mutasi Siswa:
                // 1. Staf Global (super_admin, kesiswaan, staff, admin): Boleh ubah semua siswa
                // 2. Wali Kelas: Boleh ubah siswa di kelas perwaliannya sendiri (user.assignedClass)
                // 3. Siswa Mandiri (isOwner): Boleh ubah data dirinya sendiri sesuai whitelist
                const isGlobalStaff = user ? canMutateStudent(user) : false;
                const isWaliKelasUser = user ? hasUserRole(user, 'wali_kelas') : false;

                const normalizeClass = (c) => String(c || '').trim().toLowerCase();
                const isMyHomeroomStudent = Boolean(
                    isWaliKelasUser &&
                    user?.assignedClass &&
                    existingRow.class &&
                    (normalizeClass(user.assignedClass) === normalizeClass(existingRow.class))
                );

                const canEditAsStaff = isGlobalStaff || isMyHomeroomStudent;

                if (!canEditAsStaff && !isOwner) {
                    if (isWaliKelasUser && !isMyHomeroomStudent) {
                        const assignedMsg = user?.assignedClass ? ` (${user.assignedClass})` : ' (belum memiliki rombel perwalian)';
                        return errorResponse("Forbidden: Wali Kelas hanya berhak mengedit data siswa di rombel perwaliannya sendiri" + assignedMsg, 403, request);
                    }
                    return errorResponse("Forbidden: Anda tidak memiliki wewenang mengubah data siswa ini", 403, request);
                }

                const body = await request.json();
                let existingDapodik = {};
                if (existingRow.dapodik_data) {
                    try { existingDapodik = JSON.parse(existingRow.dapodik_data); } catch (e) {}
                }

                let updatedRowData;
                let mergedDapodik;

                if (canEditAsStaff) {
                    // Full update untuk Admin / Staff / Wali Kelas Rombel (Preservasi Data Pintar: nilai kosong tidak boleh menghapus identitas pokok seperti class/name)
                    const sanitizeField = (val, existingVal) => {
                        if (val === undefined || val === null) return existingVal;
                        const str = String(val).trim();
                        if (str === "" || str === "-" || str === "--" || str.toLowerCase() === "null" || str.toLowerCase() === "undefined") return existingVal;
                        return str;
                    };

                    const nisn = sanitizeField(body.nisn, existingRow.nisn);
                    const name = sanitizeField(body.name, existingRow.name);
                    const gender = sanitizeField(body.gender, existingRow.gender).toUpperCase();
                    const rawClass = body.class !== undefined ? body.class : body.kelas;
                    const className = sanitizeField(rawClass, existingRow.class);
                    const birthPlace = sanitizeField(body.birthPlace, existingRow.birth_place);
                    const birthDate = sanitizeField(body.birthDate, existingRow.birth_date);
                    const nik = sanitizeField(body.nik, existingRow.nik);
                    const status = sanitizeField(body.status, existingRow.status).toLowerCase();
                    const violationPoints = body.violationPoints !== undefined && body.violationPoints !== null && body.violationPoints !== '' ? Number(body.violationPoints) : existingRow.violation_points;

                    // Buat payload dapodik yang bersih (abaikan nilai kosong agar tidak menimpa biodata lama)
                    const sanitizedBody = {};
                    for (const k in body) {
                        if (body[k] !== undefined && body[k] !== null) {
                            const str = String(body[k]).trim();
                            if (str !== "" && str !== "-" && str !== "--" && str.toLowerCase() !== "null" && str.toLowerCase() !== "undefined") {
                                sanitizedBody[k] = typeof body[k] === "number" ? body[k] : str;
                            }
                        }
                    }
                    mergedDapodik = { ...existingDapodik, ...sanitizedBody, nis: nisParam };
                    if (className) mergedDapodik.class = className;
                    updatedRowData = { nisn, name, gender, class: className, birth_place: birthPlace, birth_date: birthDate, nik, status, violation_points: violationPoints };
                } else {
                    // Whitelist Update Mandiri Siswa (Kolom integritas seperti NIS, NISN, Nama, Kelas, Tanggal Lahir, Gender, Status dikunci)
                    const STUDENT_WHITELIST_FIELDS = [
                        "agama", "birthPlace", "nik", "kk_no", "child_order", "jml_saudara_kandung",
                        "no_akta_lahir", "sekolah_asal", "phone_siswa", "email_siswa", "email", "alamat", "dusun",
                        "kelurahan", "kecamatan", "kode_pos", "jenis_tinggal", "alat_transportasi", "jarak_sekolah_km",
                        "father", "father_nik", "father_phone", "phone_parent", "father_birth_year", "father_education",
                        "father_job", "father_income", "mother", "mother_nik", "mother_phone", "mother_birth_year",
                        "mother_education", "mother_job", "mother_income", "guardian", "guardian_nik", "guardian_phone",
                        "guardian_birth_year", "guardian_education", "guardian_job", "guardian_income",
                        "berat_badan", "tinggi_badan", "lingkar_kepala",
                        "kk_document_url", "kk_file_id", "kk_uploaded_at", "kk_file_name", "kk_drive_folder"
                    ];

                    const sanitizedUpdates = {};
                    for (const f of STUDENT_WHITELIST_FIELDS) {
                        if (body[f] !== undefined) {
                            sanitizedUpdates[f] = body[f];
                        }
                    }

                    mergedDapodik = { ...existingDapodik, ...sanitizedUpdates, nis: nisParam };
                    updatedRowData = {
                        nisn: existingRow.nisn,
                        name: existingRow.name,
                        gender: existingRow.gender,
                        class: existingRow.class,
                        birth_place: sanitizedUpdates.birthPlace !== undefined ? String(sanitizedUpdates.birthPlace).trim() : existingRow.birth_place,
                        birth_date: existingRow.birth_date,
                        nik: sanitizedUpdates.nik !== undefined ? String(sanitizedUpdates.nik).trim() : existingRow.nik,
                        status: existingRow.status,
                        violation_points: existingRow.violation_points
                    };
                }

                const stmt = env.DB.prepare(`
                    UPDATE students 
                    SET nisn = ?, name = ?, gender = ?, class = ?, birth_place = ?, birth_date = ?, nik = ?, status = ?, violation_points = ?, dapodik_data = ?, updated_at = datetime('now')
                    WHERE nis = ?
                `);

                await stmt.bind(
                    updatedRowData.nisn,
                    updatedRowData.name,
                    updatedRowData.gender,
                    updatedRowData.class,
                    updatedRowData.birth_place,
                    updatedRowData.birth_date,
                    updatedRowData.nik,
                    updatedRowData.status,
                    updatedRowData.violation_points,
                    JSON.stringify(mergedDapodik),
                    nisParam
                ).run();

                if (updatedRowData.class) {
                    await autoSyncMetadataClasses(env.DB, [updatedRowData.class]);
                } else {
                    invalidateMasterBundleCache();
                }
                await updateServerMetadata(env.DB, { lastUpdateStudents: Date.now() });

                return jsonResponse({
                    success: true,
                    nis: nisParam,
                    message: "Data profil siswa berhasil diperbarui di Cloudflare D1"
                }, 200, request);
            }

            // 5. DELETE /api/students/:nis (Hapus Siswa / Mutasi)
            if (path.startsWith("/api/students/") && method === "DELETE" && path.split("/").length === 4) {
                const nisParam = decodeURIComponent(path.split("/")[3]).trim();
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }
                if (!canMutateStudent(authResult.user)) {
                    return errorResponse("Forbidden: Hanya Super Admin / Kesiswaan yang dapat menghapus siswa", 403, request);
                }

                // Hapus berkas foto siswa di Cloudflare R2 & record tabel student_photos jika ada
                try {
                    const photoRow = await env.DB.prepare("SELECT active_photo_url, pending_photo_url FROM student_photos WHERE nis = ?").bind(nisParam).first();
                    if (photoRow) {
                        await env.DB.prepare("DELETE FROM student_photos WHERE nis = ?").bind(nisParam).run();
                        if (env.STUDENT_PHOTOS_BUCKET) {
                            const keys = [];
                            const activeKey = extractStudentPhotoR2Key(photoRow.active_photo_url);
                            const pendingKey = extractStudentPhotoR2Key(photoRow.pending_photo_url);
                            if (activeKey) keys.push(activeKey);
                            if (pendingKey) keys.push(pendingKey);
                            const bucket = env.STUDENT_PHOTOS_BUCKET;
                            ctx?.waitUntil?.(listAllStudentPhotoKeysForNis(bucket, nisParam)
                                .catch(() => [`active/${nisParam}.webp`])
                                .then(allKeys => deleteStudentPhotosFromR2(bucket, [...keys, ...allKeys]))
                                .catch(() => {}));
                        }
                    }
                } catch (photoErr) {
                    console.warn("[StudentDelete] Gagal membersihkan foto siswa:", photoErr.message);
                }

                const stmt = env.DB.prepare(`DELETE FROM students WHERE nis = ?`);
                const result = await stmt.bind(nisParam).run();

                invalidateMasterBundleCache();
                await updateServerMetadata(env.DB, { lastUpdateStudents: Date.now() });

                return jsonResponse({
                    success: true,
                    nis: nisParam,
                    deleted: result.meta?.changes ?? 1,
                    message: "Siswa dengan NIS " + nisParam + " berhasil dihapus dari Cloudflare D1"
                }, 200, request);
            }

            // 6. POST /api/students/bulk-sync (Bulk Import / Upsert Siswa ke Cloudflare D1)
            if (path === "/api/students/bulk-sync" && method === "POST") {
                const migrationKey = request.headers.get("X-Migration-Key") || url.searchParams.get("key");
                const isSecretValid = env.MIGRATION_SECRET && migrationKey && migrationKey === env.MIGRATION_SECRET;
                
                const authResult = await verifyFirebaseToken(request);
                const isSuperAdmin = authResult.valid && authResult.user.role === "super_admin";

                if (!isSuperAdmin && !isSecretValid) {
                    return errorResponse("Unauthorized: Bulk sync requires super_admin authentication or valid migration secret", 401, request);
                }

                const body = await request.json();
                const studentsList = Array.isArray(body.students) ? body.students : (Array.isArray(body) ? body : []);

                if (studentsList.length === 0) {
                    return errorResponse("Array data 'students' kosong", 400, request);
                }

                const statements = [];
                for (const s of studentsList) {
                    const nis = String(s.nis || s.id || "").trim();
                    if (!nis) continue;

                    const sanitizeVal = (val) => {
                        if (val === undefined || val === null) return "";
                        const str = String(val).trim();
                        if (str === "" || str === "-" || str === "--" || str.toLowerCase() === "null" || str.toLowerCase() === "undefined") return "";
                        return str;
                    };

                    const name = sanitizeVal(s.name || s.nama);
                    const nisn = sanitizeVal(s.nisn);
                    const gender = sanitizeVal(s.gender).toUpperCase();
                    const className = sanitizeVal(s.class || s.kelas);
                    const birthPlace = sanitizeVal(s.birthPlace);
                    const birthDate = sanitizeVal(s.birthDate);
                    const nik = sanitizeVal(s.nik);
                    const status = sanitizeVal(s.status).toLowerCase();
                    const violationPoints = s.violationPoints !== undefined && s.violationPoints !== null && s.violationPoints !== '' ? Number(s.violationPoints || 0) : null;

                    // SMART MERGE: Hanya sertakan field yang memiliki isi riil ke dapodik_data
                    const cleanDapodik = {};
                    for (const k in s) {
                        const cleanV = sanitizeVal(s[k]);
                        if (cleanV !== "") {
                            cleanDapodik[k] = typeof s[k] === "number" ? s[k] : cleanV;
                        }
                    }
                    cleanDapodik.nis = nis;
                    if (name) cleanDapodik.name = name;
                    if (className) cleanDapodik.class = className;
                    const dapodikJson = JSON.stringify(cleanDapodik);

                    statements.push(
                        env.DB.prepare(`
                            INSERT INTO students (
                                nis, nisn, name, gender, class, birth_place, birth_date, nik, status, violation_points, dapodik_data, created_at, updated_at
                            ) VALUES (
                                ?, ?, COALESCE(NULLIF(?, ''), 'Siswa'), ?, ?, ?, ?, ?, COALESCE(NULLIF(?, ''), 'active'), COALESCE(?, 0), ?, datetime('now'), datetime('now')
                            )
                            ON CONFLICT(nis) DO UPDATE SET
                                nisn = CASE WHEN excluded.nisn != '' AND excluded.nisn IS NOT NULL THEN excluded.nisn ELSE students.nisn END,
                                name = CASE WHEN excluded.name != '' AND excluded.name != 'Siswa' AND excluded.name IS NOT NULL THEN excluded.name ELSE students.name END,
                                gender = CASE WHEN excluded.gender != '' AND excluded.gender IS NOT NULL THEN excluded.gender ELSE students.gender END,
                                class = CASE WHEN excluded.class != '' AND excluded.class IS NOT NULL THEN excluded.class ELSE students.class END,
                                birth_place = CASE WHEN excluded.birth_place != '' AND excluded.birth_place IS NOT NULL THEN excluded.birth_place ELSE students.birth_place END,
                                birth_date = CASE WHEN excluded.birth_date != '' AND excluded.birth_date IS NOT NULL THEN excluded.birth_date ELSE students.birth_date END,
                                nik = CASE WHEN excluded.nik != '' AND excluded.nik IS NOT NULL THEN excluded.nik ELSE students.nik END,
                                status = CASE WHEN ? != '' THEN ? ELSE students.status END,
                                violation_points = CASE WHEN excluded.violation_points IS NOT NULL AND excluded.violation_points > 0 THEN excluded.violation_points ELSE students.violation_points END,
                                dapodik_data = json_patch(COALESCE(NULLIF(students.dapodik_data, ''), '{}'), excluded.dapodik_data),
                                updated_at = datetime('now')
                        `).bind(
                            nis, nisn, name, gender, className, birthPlace, birthDate, nik, status, violationPoints, dapodikJson, status, status
                        )
                    );
                }

                if (statements.length > 0) {
                    const chunkSize = 50;
                    for (let i = 0; i < statements.length; i += chunkSize) {
                        const chunk = statements.slice(i, i + chunkSize);
                        await env.DB.batch(chunk);
                    }

                    // Kumpulkan semua kelas yang diimport untuk sinkronisasi otomatis metadata_classes
                    const importedClasses = new Set();
                    for (const s of studentsList) {
                        const c = s.class || s.kelas;
                        if (c) importedClasses.add(String(c).trim());
                    }
                    if (importedClasses.size > 0) {
                        await autoSyncMetadataClasses(env.DB, Array.from(importedClasses));
                    } else {
                        invalidateMasterBundleCache();
                    }
                    await updateServerMetadata(env.DB, { lastUpdateStudents: Date.now() });
                }

                return jsonResponse({
                    success: true,
                    migratedCount: statements.length,
                    message: `Berhasil menyinkronkan ${statements.length} data siswa ke Cloudflare D1.`
                }, 200, request);
            }

            // 6.5 POST /api/students/transfer-class (Atomic Multi-Table Class Transfer on Cloudflare D1)
            if (path === "/api/students/transfer-class" && method === "POST") {
                const migrationKey = request.headers.get("X-Migration-Key") || url.searchParams.get("key");
                const isSecretValid = Boolean(env.MIGRATION_SECRET && migrationKey && migrationKey === env.MIGRATION_SECRET);
                
                const authResult = await verifyFirebaseToken(request);
                const isSuperAdmin = authResult.valid && authResult.user.role === "super_admin";

                if (!isSuperAdmin && !isSecretValid) {
                    return errorResponse("Unauthorized: Transfer class requires super_admin authentication or valid migration secret", 401, request);
                }

                const body = await request.json().catch(() => ({}));
                const nis = String(body.nis || "").trim();
                const fromClass = String(body.from_class || body.fromClass || "").trim();
                const toClass = String(body.to_class || body.toClass || "").trim();
                const academicYear = String(body.academic_year || body.academicYear || "").trim();

                if (!nis || !fromClass || !toClass) {
                    return errorResponse("NIS, kelas asal (from_class), dan kelas tujuan (to_class) wajib diisi.", 400, request);
                }

                if (fromClass === toClass) {
                    return errorResponse("Kelas tujuan tidak boleh sama dengan kelas asal.", 400, request);
                }

                // Cek keberadaan siswa di master D1
                const existingStudent = await env.DB.prepare("SELECT * FROM students WHERE nis = ? LIMIT 1").bind(nis).first();
                if (!existingStudent) {
                    return errorResponse(`Siswa dengan NIS ${nis} tidak ditemukan di Cloudflare D1.`, 404, request);
                }

                // Update dapodik_data JSON jika ada atribut class/rombel_saat_ini
                let dapodikObj = {};
                try {
                    dapodikObj = existingStudent.dapodik_data ? JSON.parse(existingStudent.dapodik_data) : {};
                } catch (e) {}
                dapodikObj.class = toClass;
                dapodikObj.kelas = toClass;
                if (dapodikObj.rombel_saat_ini) dapodikObj.rombel_saat_ini = toClass;
                const updatedDapodikJson = JSON.stringify(dapodikObj);

                const statements = [
                    // 1. Master Profil Siswa (students)
                    env.DB.prepare("UPDATE students SET class = ?, dapodik_data = ?, updated_at = datetime('now') WHERE nis = ?").bind(toClass, updatedDapodikJson, nis),
                    // 2. Catatan Pelanggaran & Prestasi (records - Scoped by fromClass)
                    env.DB.prepare("UPDATE records SET student_class = ? WHERE student_nis = ? AND student_class = ?").bind(toClass, nis, fromClass),
                    // 3. Layanan & Tindakan BK (bk_actions - Scoped by fromClass)
                    env.DB.prepare("UPDATE bk_actions SET student_class = ? WHERE student_nis = ? AND student_class = ?").bind(toClass, nis, fromClass),
                    // 4. Pengajuan Izin Permisi (permisi_requests - Scoped by fromClass)
                    env.DB.prepare("UPDATE permisi_requests SET student_class = ? WHERE student_nis = ? AND student_class = ?").bind(toClass, nis, fromClass),
                    // 5. Catatan Pembinaan Guru Wali (guru_wali_notes - Scoped by fromClass)
                    env.DB.prepare("UPDATE guru_wali_notes SET student_class = ? WHERE student_nis = ? AND student_class = ?").bind(toClass, nis, fromClass),
                    // 6. Respon Angket Peminatan (peminatan_responses - Scoped by fromClass)
                    env.DB.prepare("UPDATE peminatan_responses SET class = ? WHERE nis = ? AND class = ?").bind(toClass, nis, fromClass)
                ];

                // 7. Penugasan Guru Wali (guru_wali_assignments - Scoped by fromClass & Academic Year jika ada)
                if (academicYear) {
                    statements.push(
                        env.DB.prepare("UPDATE guru_wali_assignments SET student_class = ? WHERE student_nis = ? AND student_class = ? AND academic_year = ?").bind(toClass, nis, fromClass, academicYear)
                    );
                    // 8. Catatan Rapor Semester Wali Kelas (walikelas_notes - Scoped by fromClass & Academic Year)
                    statements.push(
                        env.DB.prepare("UPDATE walikelas_notes SET student_class = ? WHERE student_nis = ? AND student_class = ? AND academic_year = ?").bind(toClass, nis, fromClass, academicYear)
                    );
                    // 9. E-Rapor Kelas XII (rapor_scores - Update ID & Class jika record ada)
                    const oldRaporId = `${fromClass}_${nis}_${academicYear}`;
                    const newRaporId = `${toClass}_${nis}_${academicYear}`;
                    statements.push(
                        env.DB.prepare("UPDATE rapor_scores SET id = ?, class = ? WHERE id = ?").bind(newRaporId, toClass, oldRaporId)
                    );
                } else {
                    statements.push(
                        env.DB.prepare("UPDATE guru_wali_assignments SET student_class = ? WHERE student_nis = ? AND student_class = ?").bind(toClass, nis, fromClass)
                    );
                    statements.push(
                        env.DB.prepare("UPDATE walikelas_notes SET student_class = ? WHERE student_nis = ? AND student_class = ?").bind(toClass, nis, fromClass)
                    );
                    statements.push(
                        env.DB.prepare("UPDATE rapor_scores SET class = ? WHERE nis = ? AND class = ?").bind(toClass, nis, fromClass)
                    );
                }

                // Eksekusi atomik batch di D1
                await env.DB.batch(statements);

                await autoSyncMetadataClasses(env.DB, [fromClass, toClass]);

                return jsonResponse({
                    success: true,
                    nis,
                    from_class: fromClass,
                    to_class: toClass,
                    message: `Berhasil memindahkan seluruh relasi data siswa ${nis} dari ${fromClass} ke ${toClass} di Cloudflare D1.`
                }, 200, request);
            }

            // 6.6 GET /api/students/alumni-classes (Daftar Kelas Alumni Terindeks Edge D1)
            if (path === "/api/students/alumni-classes" && method === "GET") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }
                if (!isStaffOrTeacher(authResult.user)) {
                    return errorResponse("Forbidden: Akses ditolak untuk role ini", 403, request);
                }

                const stmt = env.DB.prepare(`
                    SELECT DISTINCT class FROM students 
                    WHERE (LOWER(TRIM(class)) LIKE 'alumni%' OR LOWER(TRIM(status)) = 'alumni')
                      AND class IS NOT NULL AND TRIM(class) != ''
                    ORDER BY class ASC
                `);
                const { results } = await stmt.all();
                const classes = (results || []).map(r => r.class).filter(Boolean);

                return jsonResponse({
                    success: true,
                    count: classes.length,
                    data: classes
                }, 200, request);
            }

            // Cached clients must use the new backup-first protocol.
            if ((path === "/api/students/cleanup-alumni-class" || path === "/api/students/promote-classes") && method === "POST") {
                return errorResponse("Modul reset telah diperbarui. Muat ulang halaman untuk menyiapkan backup aman sebelum reset.", 409, request);
            }

            // 7. POST /api/students/verify-credentials (Verifikasi Kredensial Login Siswa di Edge D1)
            if (path === "/api/students/verify-credentials" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid || !authResult.user.isAnonymous) {
                    return errorResponse("Sesi anonim Firebase yang valid diperlukan", 401, request);
                }
                const studentSessionSecret = getStudentSessionSecret(env);
                if (!studentSessionSecret) {
                    return errorResponse("SESSION_SECRET wajib dipasang sebagai Worker secret", 503, request);
                }
                const body = await request.json();
                const nis = String(body.nis || "").trim();
                const birthDate = String(body.birthDate || "").trim();
                const nisn = String(body.nisn || "").trim();

                if (!nis || (!birthDate && !nisn)) {
                    return errorResponse("NIS dan kredensial tanggal lahir/NISN wajib diisi", 400, request);
                }

                const clientIp = request.headers.get("CF-Connecting-IP") || "unknown";
                const rateLimitId = await sha256Id(`${clientIp}|${nis}`);
                const nowMs = Date.now();
                const rateLimit = await env.DB.prepare("SELECT failure_count, window_started_at FROM auth_rate_limits WHERE id = ?")
                    .bind(rateLimitId).first();
                if (rateLimit && nowMs - Number(rateLimit.window_started_at || 0) < 15 * 60 * 1000 && Number(rateLimit.failure_count || 0) >= 8) {
                    return errorResponse("Terlalu banyak percobaan login. Silakan coba lagi dalam 15 menit.", 429, request);
                }
                const recordFailure = async () => {
                    const sameWindow = rateLimit && nowMs - Number(rateLimit.window_started_at || 0) < 15 * 60 * 1000;
                    await env.DB.prepare(`
                        INSERT INTO auth_rate_limits (id, failure_count, window_started_at)
                        VALUES (?, ?, ?)
                        ON CONFLICT(id) DO UPDATE SET
                            failure_count = excluded.failure_count,
                            window_started_at = excluded.window_started_at,
                            updated_at = datetime('now')
                    `).bind(rateLimitId, sameWindow ? Number(rateLimit.failure_count || 0) + 1 : 1, sameWindow ? Number(rateLimit.window_started_at) : nowMs).run();
                };

                const stmt = env.DB.prepare(`SELECT * FROM students WHERE nis = ? LIMIT 1`);
                const row = await stmt.bind(nis).first();

                if (!row) {
                    await recordFailure();
                    return jsonResponse({ success: false, verified: false, error: "NIS tidak ditemukan di database siswa" }, 404, request);
                }

                if (row.status && row.status !== "active") {
                    await recordFailure();
                    return jsonResponse({ success: false, verified: false, error: "Akun siswa sudah tidak aktif (alumni/mutasi/keluar)" }, 403, request);
                }

                let matches = false;
                if (birthDate && row.birth_date) {
                    matches = row.birth_date === birthDate;
                }
                if (!matches && nisn && row.nisn) {
                    matches = String(row.nisn).trim() === nisn;
                }

                if (!matches) {
                    await recordFailure();
                    return jsonResponse({
                        success: false,
                        verified: false,
                        error: nisn ? "Nomor NISN salah untuk NIS ini." : "Tanggal lahir salah untuk NIS ini."
                    }, 401, request);
                }

                const formatted = formatStudentRow(row, env);
                await setFirebaseCustomClaims(env, authResult.user.uid, {
                    studentVerified: true,
                    studentNis: formatted.nis,
                    studentClass: formatted.class
                });
                await env.DB.prepare("DELETE FROM auth_rate_limits WHERE id = ?").bind(rateLimitId).run();
                const studentToken = await signStudentSession({
                    nis: formatted.nis,
                    name: formatted.name,
                    class: formatted.class,
                    exp: Math.floor(Date.now() / 1000) + (30 * 24 * 3600) // 30 hari
                }, studentSessionSecret);
                return jsonResponse({
                    success: true,
                    verified: true,
                    token: studentToken,
                    student: {
                        id: formatted.nis,
                        nis: formatted.nis,
                        name: formatted.name,
                        class: formatted.class,
                        gender: formatted.gender,
                        status: formatted.status
                    }
                }, 200, request);
            }

            // =================================================================
            // 🪪 ROUTES: KARTU SISWA DIGITAL & FOTO RESMI R2 (/api/students/photo/* & /api/students/public-card/*)
            // Standar: OWASP Top 10 & ASVS Level 1 & 2 (Secure Signed Token, Data Minimization, RBAC, Anti-IDOR)
            // Storage: Cloudflare R2 'STUDENT_PHOTOS_BUCKET' (bucket 'smagesa-student-photos')
            // =================================================================

            // 1. POST /api/students/photo/upload (Siswa/Admin Upload Foto Pasfoto WebP)
            if (path === "/api/students/photo/upload" && method === "POST") {
                const body = await request.json().catch(() => null);
                const rawImage = body.image || body.photoBase64;
                if (!body || !body.nis || !rawImage) {
                    return errorResponse("NIS dan data gambar WebP base64 wajib diisi", 400, request);
                }

                const nisParam = String(body.nis).trim();
                const authResult = await verifyFirebaseToken(request, env);
                let user = authResult.valid ? authResult.user : null;
                let isOwner = false;

                if (user) {
                    const studentNisClaim = user.claims?.studentNis || user.claims?.nis;
                    isOwner = Boolean(studentNisClaim && String(studentNisClaim).trim() === nisParam);
                }

                if (!isOwner) {
                    const studentSession = await getVerifiedStudentSession(request, env, authResult);
                    if (studentSession && String(studentSession.nis).trim() === nisParam) {
                        isOwner = true;
                    }
                }

                const isStaff = isStaffOrTeacher(user);
                if (!isOwner && !isStaff) {
                    return errorResponse("Forbidden: Anda hanya berhak mengunggah foto profil Anda sendiri", 403, request);
                }

                // Cek keberadaan siswa di DB
                const student = await env.DB.prepare("SELECT nis, name, class FROM students WHERE nis = ? LIMIT 1").bind(nisParam).first();
                if (!student) {
                    return errorResponse("Siswa dengan NIS " + nisParam + " tidak ditemukan di sistem", 404, request);
                }

                // Validasi data base64
                let base64Clean = String(rawImage);
                if (base64Clean.includes(",")) {
                    base64Clean = base64Clean.split(",")[1];
                }
                base64Clean = base64Clean.trim();

                // Maksimal 500 KB base64 (~375 KB binary)
                if (base64Clean.length > 500 * 1024) {
                    return errorResponse("Ukuran foto terlalu besar. Maksimal 300 KB setelah kompresi WebP.", 400, request);
                }

                let imageBytes;
                try {
                    const binaryStr = atob(base64Clean);
                    imageBytes = new Uint8Array(binaryStr.length);
                    for (let i = 0; i < binaryStr.length; i++) {
                        imageBytes[i] = binaryStr.charCodeAt(i);
                    }
                } catch (e) {
                    return errorResponse("Format data gambar base64 tidak valid: " + e.message, 400, request);
                }

                if (!env.STUDENT_PHOTOS_BUCKET) {
                    return errorResponse("Cloudflare R2 Bucket 'STUDENT_PHOTOS_BUCKET' belum dikonfigurasi pada environment", 500, request);
                }

                // Cek data student_photos yang sudah ada
                const existingPhoto = await env.DB.prepare("SELECT * FROM student_photos WHERE nis = ? LIMIT 1").bind(nisParam).first();
                let publicToken = existingPhoto?.public_token;
                if (!publicToken) {
                    // Generate token acak kriptografis tahan enumerasi
                    publicToken = crypto.randomUUID().replace(/-/g, "") + Math.random().toString(36).substring(2, 8);
                }

                const autoVerify = Boolean(isStaff && body.autoVerify === true);
                const timestamp = Date.now();

                if (autoVerify) {
                    // Admin upload langsung aktif
                    const activeFileName = `${nisParam}_${generatePhotoKeySuffix()}.webp`;
                    const activeKey = `active/${activeFileName}`;
                    await env.STUDENT_PHOTOS_BUCKET.put(activeKey, imageBytes, {
                        httpMetadata: { contentType: "image/webp" }
                    });
                    const photoUrl = `/api/photos/student/active/${activeFileName}?v=${timestamp}`;

                    await env.DB.prepare(`
                        INSERT INTO student_photos (
                            nis, active_photo_url, pending_photo_url, status, rejection_reason,
                            public_token, uploaded_at, verified_at, verified_by_uid, verified_by_name, updated_at
                        ) VALUES (?, ?, NULL, 'verified', NULL, ?, datetime('now'), datetime('now'), ?, ?, datetime('now'))
                        ON CONFLICT(nis) DO UPDATE SET
                            active_photo_url = excluded.active_photo_url,
                            pending_photo_url = NULL,
                            status = 'verified',
                            rejection_reason = NULL,
                            verified_at = datetime('now'),
                            verified_by_uid = excluded.verified_by_uid,
                            verified_by_name = excluded.verified_by_name,
                            updated_at = datetime('now')
                    `).bind(nisParam, photoUrl, publicToken, user?.uid || "admin", user?.displayName || user?.email || "Admin").run();

                    // Pangkas versi lama setelah URL baru tersimpan (versi sebelumnya dipertahankan untuk cache klien)
                    ctx?.waitUntil?.(pruneSupersededPhotos(env.STUDENT_PHOTOS_BUCKET, "active/", nisParam,
                        [activeKey, extractStudentPhotoR2Key(existingPhoto?.active_photo_url)]).catch(() => {}));

                    return jsonResponse({
                        success: true,
                        status: "verified",
                        active_photo_url: photoUrl,
                        pending_photo_url: null,
                        public_token: publicToken,
                        message: "Foto resmi siswa berhasil disimpan dan langsung aktif."
                    }, 200, request);
                } else {
                    // Upload mandiri oleh siswa: masuk ke pending, active_photo_url lama tetap dipertahankan
                    const pendingFileName = `${nisParam}_${timestamp}_${generatePhotoKeySuffix()}.webp`;
                    const pendingKey = `pending/${pendingFileName}`;
                    await env.STUDENT_PHOTOS_BUCKET.put(pendingKey, imageBytes, {
                        httpMetadata: { contentType: "image/webp" }
                    });
                    const pendingUrl = `/api/photos/student/pending/${pendingFileName}`;

                    await env.DB.prepare(`
                        INSERT INTO student_photos (
                            nis, active_photo_url, pending_photo_url, status, rejection_reason,
                            public_token, uploaded_at, updated_at
                        ) VALUES (?, NULL, ?, 'pending', NULL, ?, datetime('now'), datetime('now'))
                        ON CONFLICT(nis) DO UPDATE SET
                            pending_photo_url = excluded.pending_photo_url,
                            status = 'pending',
                            rejection_reason = NULL,
                            uploaded_at = datetime('now'),
                            updated_at = datetime('now')
                    `).bind(nisParam, pendingUrl, publicToken).run();

                    // Pangkas pengajuan pending yang lebih lama (pengajuan sebelumnya dipertahankan untuk cache klien)
                    ctx?.waitUntil?.(pruneSupersededPhotos(env.STUDENT_PHOTOS_BUCKET, "pending/", nisParam,
                        [pendingKey, extractStudentPhotoR2Key(existingPhoto?.pending_photo_url)]).catch(() => {}));

                    return jsonResponse({
                        success: true,
                        status: "pending",
                        active_photo_url: existingPhoto?.active_photo_url || null,
                        pending_photo_url: pendingUrl,
                        public_token: publicToken,
                        message: "Foto berhasil diunggah! Sedang menunggu verifikasi Wali Kelas. Kartu tetap menggunakan foto sebelumnya hingga diverifikasi."
                    }, 200, request);
                }
            }

            // 2. POST /api/students/photo/verify (Wali Kelas / Kesiswaan Menyetujui / Menolak Foto)
            if (path === "/api/students/photo/verify" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }
                const user = authResult.user;
                if (!isStaffOrTeacher(user)) {
                    return errorResponse("Forbidden: Hanya Guru/Wali Kelas/Staf yang berhak memverifikasi foto", 403, request);
                }

                const body = await request.json().catch(() => null);
                if (!body || !body.nis || !body.action) {
                    return errorResponse("NIS dan aksi (approve / reject) wajib diisi", 400, request);
                }

                const nisParam = String(body.nis).trim();
                const action = String(body.action).trim().toLowerCase();
                const reason = body.reason ? String(body.reason).trim() : null;

                if (!["approve", "reject"].includes(action)) {
                    return errorResponse("Aksi tidak valid. Gunakan 'approve' atau 'reject'", 400, request);
                }

                const existing = await env.DB.prepare("SELECT * FROM student_photos WHERE nis = ? LIMIT 1").bind(nisParam).first();
                if (!existing || !existing.pending_photo_url) {
                    return errorResponse("Tidak ditemukan pengajuan foto yang tertunda untuk siswa ini", 404, request);
                }

                if (!env.STUDENT_PHOTOS_BUCKET) {
                    return errorResponse("Cloudflare R2 Bucket 'STUDENT_PHOTOS_BUCKET' belum dikonfigurasi", 500, request);
                }

                const verifierUid = user.uid || "staff";
                const verifierName = user.displayName || user.email || "Wali Kelas";
                const timestamp = Date.now();

                if (action === "approve") {
                    const pendingUrl = existing.pending_photo_url;
                    const pendingFileName = pendingUrl.split("/").pop().split("?")[0];
                    const pendingKey = `pending/${pendingFileName}`;

                    const pendingObj = await env.STUDENT_PHOTOS_BUCKET.get(pendingKey);
                    if (!pendingObj) {
                        return errorResponse("File foto pending tidak ditemukan di penyimpanan R2", 404, request);
                    }

                    const activeFileName = `${nisParam}_${generatePhotoKeySuffix()}.webp`;
                    const activeKey = `active/${activeFileName}`;
                    await env.STUDENT_PHOTOS_BUCKET.put(activeKey, pendingObj.body, {
                        httpMetadata: { contentType: "image/webp" }
                    });

                    const activeUrl = `/api/photos/student/active/${activeFileName}?v=${timestamp}`;

                    await env.DB.prepare(`
                        UPDATE student_photos SET
                            active_photo_url = ?,
                            pending_photo_url = NULL,
                            status = 'verified',
                            rejection_reason = NULL,
                            verified_at = datetime('now'),
                            verified_by_uid = ?,
                            verified_by_name = ?,
                            updated_at = datetime('now')
                        WHERE nis = ?
                    `).bind(activeUrl, verifierUid, verifierName, nisParam).run();

                    // Hapus pending file dari R2 & pangkas versi aktif lama (versi sebelumnya dipertahankan untuk cache klien)
                    ctx?.waitUntil?.(Promise.all([
                        env.STUDENT_PHOTOS_BUCKET.delete(pendingKey),
                        pruneSupersededPhotos(env.STUDENT_PHOTOS_BUCKET, "active/", nisParam,
                            [activeKey, extractStudentPhotoR2Key(existing.active_photo_url)])
                    ]).catch(() => {}));

                    return jsonResponse({
                        success: true,
                        status: "verified",
                        active_photo_url: activeUrl,
                        message: "Foto resmi siswa berhasil disetujui dan kartu telah diperbarui."
                    }, 200, request);
                } else {
                    const pendingUrl = existing.pending_photo_url;
                    const pendingFileName = pendingUrl.split("/").pop().split("?")[0];
                    const pendingKey = `pending/${pendingFileName}`;
                    ctx?.waitUntil?.(env.STUDENT_PHOTOS_BUCKET.delete(pendingKey).catch(() => {}));

                    await env.DB.prepare(`
                        UPDATE student_photos SET
                            pending_photo_url = NULL,
                            status = 'rejected',
                            rejection_reason = ?,
                            verified_at = datetime('now'),
                            verified_by_uid = ?,
                            verified_by_name = ?,
                            updated_at = datetime('now')
                        WHERE nis = ?
                    `).bind(reason || "Foto tidak memenuhi ketentuan seragam / latar belakang", verifierUid, verifierName, nisParam).run();

                    return jsonResponse({
                        success: true,
                        status: "rejected",
                        active_photo_url: existing.active_photo_url || null,
                        message: "Pengajuan foto siswa ditolak. Siswa diminta mengunggah ulang sesuai alasan."
                    }, 200, request);
                }
            }

            // 2b. POST /api/students/photo/migrate-legacy-keys (Super Admin: ganti nama berkas foto `<nis>.webp` yang dapat ditebak)
            // Tahap 1 (default): salin ke nama acak + perbarui DB per batch; berkas lama TIDAK dihapus agar cache klien tetap tampil.
            // Tahap 2 ({ purge: true }): jalankan setelah klien sempat menyegarkan data (mis. keesokan hari) untuk menghapus
            // berkas yang tidak lagi dirujuk DB (pola lama `<nis>.webp` & pending yatim).
            if (path === "/api/students/photo/migrate-legacy-keys" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }
                if (authResult.user?.role !== "super_admin") {
                    return errorResponse("Forbidden: Hanya Super Admin yang dapat memigrasi berkas foto", 403, request);
                }
                const bucket = env.STUDENT_PHOTOS_BUCKET;
                if (!bucket) {
                    return errorResponse("Bucket R2 belum terpasang", 500, request);
                }
                const body = await request.json().catch(() => ({})) || {};
                const limit = Math.min(Math.max(parseInt(body.limit, 10) || 25, 1), 100);

                if (body.purge === true) {
                    const { results: spRows } = await env.DB.prepare("SELECT active_photo_url, pending_photo_url FROM student_photos").all();
                    const { results: ybRows } = await env.DB.prepare("SELECT casual_photo_url FROM yearbook_profiles WHERE casual_photo_url IS NOT NULL").all();
                    const referenced = new Set();
                    for (const r of spRows || []) {
                        referenced.add(extractStudentPhotoR2Key(r.active_photo_url));
                        referenced.add(extractStudentPhotoR2Key(r.pending_photo_url));
                    }
                    for (const r of ybRows || []) referenced.add(extractYearbookPhotoR2Key(r.casual_photo_url));

                    const toDelete = [];
                    const isLegacyName = (key) => !key.split("/").pop().includes("_");
                    for (const key of await listR2KeysByPrefix(bucket, "active/")) {
                        if (isLegacyName(key) && !referenced.has(key)) toDelete.push(key);
                    }
                    for (const key of await listR2KeysByPrefix(bucket, "yearbook/")) {
                        if (isLegacyName(key) && !referenced.has(key)) toDelete.push(key);
                    }
                    for (const key of await listR2KeysByPrefix(bucket, "pending/")) {
                        if (!referenced.has(key)) toDelete.push(key);
                    }
                    const deleted = await deleteStudentPhotosFromR2(bucket, toDelete);
                    return jsonResponse({ success: true, phase: "purge", deleted }, 200, request);
                }

                // Kursor berbasis NIS agar baris yang gagal (mis. berkas hilang) tidak menghambat batch berikutnya
                const afterNis = String(body.afterNis || "");
                const afterYearbookNis = String(body.afterYearbookNis || "");
                const { results: legacyActive } = await env.DB.prepare(`
                    SELECT nis, active_photo_url FROM student_photos
                    WHERE active_photo_url LIKE '%/api/photos/student/active/' || nis || '.webp%' AND nis > ?
                    ORDER BY nis LIMIT ?
                `).bind(afterNis, limit).all();
                const { results: legacyYearbook } = await env.DB.prepare(`
                    SELECT nis, casual_photo_url FROM yearbook_profiles
                    WHERE casual_photo_url LIKE '%/' || nis || '.webp%' AND nis > ?
                    ORDER BY nis LIMIT ?
                `).bind(afterYearbookNis, limit).all();

                let migrated = 0;
                const failed = [];
                for (const row of legacyActive || []) {
                    try {
                        const oldKey = extractStudentPhotoR2Key(row.active_photo_url);
                        const obj = oldKey ? await bucket.get(oldKey) : null;
                        if (!obj) { failed.push({ nis: row.nis, reason: "berkas tidak ditemukan" }); continue; }
                        const fileName = `${row.nis}_${generatePhotoKeySuffix()}.webp`;
                        await bucket.put(`active/${fileName}`, obj.body, { httpMetadata: { contentType: "image/webp" } });
                        await env.DB.prepare("UPDATE student_photos SET active_photo_url = ?, updated_at = datetime('now') WHERE nis = ? AND active_photo_url = ?")
                            .bind(`/api/photos/student/active/${fileName}?v=${Date.now()}`, row.nis, row.active_photo_url).run();
                        migrated++;
                    } catch (e) {
                        failed.push({ nis: row.nis, reason: e.message });
                    }
                }
                for (const row of legacyYearbook || []) {
                    try {
                        const oldKey = extractYearbookPhotoR2Key(row.casual_photo_url);
                        const obj = oldKey ? await bucket.get(oldKey) : null;
                        if (!obj) { failed.push({ nis: row.nis, reason: "berkas yearbook tidak ditemukan" }); continue; }
                        const folder = oldKey.slice(0, oldKey.lastIndexOf("/") + 1); // yearbook/<slug>/
                        const fileName = `${row.nis}_${generatePhotoKeySuffix()}.webp`;
                        await bucket.put(`${folder}${fileName}`, obj.body, { httpMetadata: { contentType: "image/webp" } });
                        await env.DB.prepare("UPDATE yearbook_profiles SET casual_photo_url = ?, updated_at = datetime('now') WHERE nis = ? AND casual_photo_url = ?")
                            .bind(`/api/photos/${folder}${fileName}?v=${Date.now()}`, row.nis, row.casual_photo_url).run();
                        migrated++;
                    } catch (e) {
                        failed.push({ nis: row.nis, reason: e.message });
                    }
                }

                if (migrated > 0) {
                    // Paksa klien memuat ulang cache siswa agar memakai URL baru
                    invalidateMasterBundleCache();
                    await updateServerMetadata(env.DB, { lastUpdateStudents: Date.now() });
                }

                const nextAfterNis = legacyActive?.length ? String(legacyActive[legacyActive.length - 1].nis) : afterNis;
                const nextAfterYearbookNis = legacyYearbook?.length ? String(legacyYearbook[legacyYearbook.length - 1].nis) : afterYearbookNis;
                const remainingActive = await env.DB.prepare(`
                    SELECT COUNT(*) AS c FROM student_photos
                    WHERE active_photo_url LIKE '%/api/photos/student/active/' || nis || '.webp%' AND nis > ?
                `).bind(nextAfterNis).first();
                const remainingYearbook = await env.DB.prepare(`
                    SELECT COUNT(*) AS c FROM yearbook_profiles WHERE casual_photo_url LIKE '%/' || nis || '.webp%' AND nis > ?
                `).bind(nextAfterYearbookNis).first();
                const remaining = (remainingActive?.c || 0) + (remainingYearbook?.c || 0);

                return jsonResponse({
                    success: true,
                    phase: "migrate",
                    migrated,
                    failed,
                    remaining,
                    next: { afterNis: nextAfterNis, afterYearbookNis: nextAfterYearbookNis },
                    message: remaining > 0
                        ? "Batch selesai. Panggil ulang endpoint ini dengan body `next` hingga remaining = 0."
                        : "Migrasi selesai. Jalankan { purge: true } setelah klien menyegarkan data (mis. besok)."
                }, 200, request);
            }

            // 3. GET /api/photos/student/:folder/:filename (Streaming File Foto dari Cloudflare R2)
            if (path.startsWith("/api/photos/student/") && method === "GET") {
                const parts = path.split("/").filter(Boolean); // ['api', 'photos', 'student', folder, filename]
                if (parts.length < 5) {
                    return errorResponse("URL foto tidak valid", 400, request);
                }
                const folder = parts[3]; // 'active' atau 'pending'
                const filename = parts[4].split("?")[0]; // sanitize query param

                if (!["active", "pending"].includes(folder)) {
                    return errorResponse("Folder tidak diizinkan", 403, request);
                }

                if (!/^[a-zA-Z0-9_\-\.]+\.webp$/.test(filename)) {
                    return errorResponse("Nama file tidak valid", 400, request);
                }

                if (!env.STUDENT_PHOTOS_BUCKET) {
                    return errorResponse("Bucket R2 belum terpasang", 500, request);
                }

                const r2Key = `${folder}/${filename}`;
                const object = await env.STUDENT_PHOTOS_BUCKET.get(r2Key);

                if (!object) {
                    return errorResponse("Foto tidak ditemukan", 404, request);
                }

                const headers = new Headers();
                object.writeHttpMetadata(headers);
                headers.set("Content-Type", "image/webp");
                headers.set("Cache-Control", folder === "active" ? "public, max-age=604800, stale-while-revalidate=86400" : "private, no-cache");
                headers.set("Access-Control-Allow-Origin", "*");
                headers.set("ETag", object.httpEtag);

                return new Response(object.body, { headers });
            }

            // 3b. GET /api/photos/yearbook/:year/:filename (Streaming Foto Kasual Yearbook dari R2)
            if (path.startsWith("/api/photos/yearbook/") && method === "GET") {
                const parts = path.split("/").filter(Boolean);
                if (parts.length < 5) {
                    return errorResponse("URL foto tidak valid", 400, request);
                }
                const year = decodeURIComponent(parts[3]).replace(/[^a-zA-Z0-9_\-\.]/g, "");
                const filename = parts[4].split("?")[0];

                if (!/^[a-zA-Z0-9_\-\.]+\.webp$/.test(filename)) {
                    return errorResponse("Nama file tidak valid", 400, request);
                }

                if (!env.STUDENT_PHOTOS_BUCKET) {
                    return errorResponse("Bucket R2 belum terpasang", 500, request);
                }

                const r2Key = `yearbook/${year}/${filename}`;
                const object = await env.STUDENT_PHOTOS_BUCKET.get(r2Key);

                if (!object) {
                    return errorResponse("Foto buku tahunan tidak ditemukan", 404, request);
                }

                const headers = new Headers();
                object.writeHttpMetadata(headers);
                const storedType = object.httpMetadata?.contentType;
                headers.set("Content-Type", /^image\/(webp|jpeg|png)$/.test(storedType || "") ? storedType : "image/webp");
                headers.set("Cache-Control", "public, max-age=604800, stale-while-revalidate=86400");
                headers.set("Access-Control-Allow-Origin", "*");
                headers.set("ETag", object.httpEtag);

                return new Response(object.body, { headers });
            }

            // 4. GET /api/students/photo/info/:nis (Info Status Foto & Token Siswa)
            if (path.startsWith("/api/students/photo/info/") && method === "GET") {
                const nisParam = decodeURIComponent(path.split("/")[5] || "").trim();
                if (!nisParam) return errorResponse("NIS diperlukan", 400, request);

                const authResult = await verifyFirebaseToken(request, env);
                let user = authResult.valid ? authResult.user : null;
                let isOwner = false;

                if (user) {
                    const studentNisClaim = user.claims?.studentNis || user.claims?.nis;
                    isOwner = Boolean(studentNisClaim && String(studentNisClaim).trim() === nisParam);
                }

                if (!isOwner) {
                    const studentSession = await getVerifiedStudentSession(request, env, authResult);
                    if (studentSession && String(studentSession.nis).trim() === nisParam) {
                        isOwner = true;
                    }
                }

                if (!isOwner && !isStaffOrTeacher(user)) {
                    return errorResponse("Forbidden: Akses ditolak", 403, request);
                }

                const photoRow = await env.DB.prepare("SELECT * FROM student_photos WHERE nis = ? LIMIT 1").bind(nisParam).first();
                let publicToken = photoRow?.public_token;

                if (!publicToken) {
                    publicToken = crypto.randomUUID().replace(/-/g, "") + Math.random().toString(36).substring(2, 8);
                    await env.DB.prepare(`
                        INSERT INTO student_photos (nis, public_token, status, created_at, updated_at)
                        VALUES (?, ?, 'none', datetime('now'), datetime('now'))
                        ON CONFLICT(nis) DO UPDATE SET public_token = excluded.public_token, updated_at = datetime('now')
                    `).bind(nisParam, publicToken).run();
                }

                return jsonResponse({
                    success: true,
                    data: {
                        nis: nisParam,
                        active_photo_url: photoRow?.active_photo_url || null,
                        pending_photo_url: photoRow?.pending_photo_url || null,
                        status: photoRow?.status || "none",
                        rejection_reason: photoRow?.rejection_reason || null,
                        public_token: publicToken,
                        uploaded_at: photoRow?.uploaded_at || null,
                        verified_at: photoRow?.verified_at || null,
                        verified_by_name: photoRow?.verified_by_name || null
                    }
                }, 200, request);
            }

            // 4b. DELETE /api/students/photo/:nis (Wali Kelas & Super Admin Menghapus Foto Siswa)
            if (path.startsWith("/api/students/photo/") && method === "DELETE") {
                const nisParam = decodeURIComponent(path.split("/")[4] || "").trim();
                if (!nisParam) return errorResponse("NIS diperlukan", 400, request);

                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }
                const user = authResult.user;
                if (!isStaffOrTeacher(user)) {
                    return errorResponse("Forbidden: Hanya Wali Kelas, Staf, atau Super Admin yang berhak menghapus foto siswa", 403, request);
                }

                const existingPhoto = await env.DB.prepare("SELECT * FROM student_photos WHERE nis = ? LIMIT 1").bind(nisParam).first();
                if (existingPhoto) {
                    if (env.STUDENT_PHOTOS_BUCKET) {
                        const keysToDelete = [`active/${nisParam}.webp`];
                        if (existingPhoto.pending_photo_url) {
                            const pendingFileName = existingPhoto.pending_photo_url.split("/").pop().split("?")[0];
                            keysToDelete.push(`pending/${pendingFileName}`);
                        }
                        ctx?.waitUntil?.(deleteStudentPhotosFromR2(env.STUDENT_PHOTOS_BUCKET, keysToDelete).catch(() => {}));
                    }

                    await env.DB.prepare(`
                        UPDATE student_photos SET
                            active_photo_url = NULL,
                            pending_photo_url = NULL,
                            status = 'none',
                            rejection_reason = NULL,
                            verified_at = NULL,
                            verified_by_uid = NULL,
                            verified_by_name = NULL,
                            updated_at = datetime('now')
                        WHERE nis = ?
                    `).bind(nisParam).run();
                }

                return jsonResponse({
                    success: true,
                    nis: nisParam,
                    message: "Foto resmi siswa berhasil dihapus dari kartu pelajar."
                }, 200, request);
            }

            // 4b. GET /api/students/resolve-card/:token (Staf: terjemahkan hasil scan QR kartu menjadi NIS untuk SPP & perpustakaan)
            // Kunci token kartu hanya ada di server, sehingga browser tidak dapat mendekripsi kts_ sendiri.
            if (path.startsWith("/api/students/resolve-card/") && method === "GET") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }
                if (!isSchoolStaff(authResult.user)) {
                    return errorResponse("Forbidden: Hanya staf sekolah yang dapat memindai kartu siswa", 403, request);
                }
                const tokenParam = decodeURIComponent(path.split("/")[4] || "").trim();
                if (!tokenParam || tokenParam.length < 8) {
                    return errorResponse("Token kartu tidak valid", 400, request);
                }
                let resolvedNis = null;
                const byPublicToken = await env.DB.prepare("SELECT nis FROM student_photos WHERE public_token = ? LIMIT 1").bind(tokenParam).first();
                if (byPublicToken?.nis) {
                    resolvedNis = String(byPublicToken.nis).trim();
                } else if (tokenParam.startsWith("kts_")) {
                    resolvedNis = decryptSecureCardToken(tokenParam, env.CARD_TOKEN_SECRET);
                }
                const student = resolvedNis
                    ? await env.DB.prepare("SELECT nis, name, class FROM students WHERE nis = ? LIMIT 1").bind(resolvedNis).first()
                    : null;
                if (!student) {
                    return errorResponse("Kartu tidak dikenali atau siswa tidak ditemukan", 404, request);
                }
                return jsonResponse({
                    success: true,
                    data: { nis: String(student.nis).trim(), name: student.name || "", class: student.class || "" }
                }, 200, request);
            }

            // 5. GET /api/students/public-card/:token (Publik Tanpa Login: Verifikasi Keaslian Kartu Siswa di kartu-shakti.html)
            if (path.startsWith("/api/students/public-card/") && method === "GET") {
                const tokenParam = decodeURIComponent(path.split("/")[4] || "").trim();
                if (!tokenParam || tokenParam.length < 8) {
                    return errorResponse("Token verifikasi kartu tidak valid", 400, request);
                }

                const clientIp = request.headers.get("CF-Connecting-IP") || request.headers.get("x-forwarded-for") || "unknown";
                const rateLimitId = await sha256Id(`public_card:${clientIp}`);
                const allowed = await consumeD1RateLimit(env, rateLimitId, 40, 5 * 60 * 1000);
                if (!allowed) {
                    return errorResponse("Terlalu banyak permintaan verifikasi kartu dari jaringan Anda. Silakan coba beberapa saat lagi.", 429, request);
                }

                // 1. Query data gabungan dengan sanitasi data privasi ketat (Zero NIK, Zero BK, Zero Data Ortu, Zero No HP)
                let query = `
                    SELECT 
                        s.nis, s.nisn, s.name, s.gender, s.class, s.birth_date, s.birth_place, s.status AS student_status,
                        s.dapodik_data,
                        sp.active_photo_url, sp.status AS photo_status, sp.verified_at, sp.verified_by_name, sp.public_token
                    FROM students s
                    LEFT JOIN student_photos sp ON sp.nis = s.nis
                    WHERE sp.public_token = ?
                    LIMIT 1
                `;
                let row = await env.DB.prepare(query).bind(tokenParam).first();

                // 2. Jika tidak ditemukan dan token menggunakan format kriptografis aman kts_...
                if (!row && tokenParam.startsWith("kts_")) {
                    const decryptedNis = decryptSecureCardToken(tokenParam, env.CARD_TOKEN_SECRET);
                    if (decryptedNis) {
                        const nisQuery = `
                            SELECT 
                                s.nis, s.nisn, s.name, s.gender, s.class, s.birth_date, s.birth_place, s.status AS student_status,
                                s.dapodik_data,
                                sp.active_photo_url, sp.status AS photo_status, sp.verified_at, sp.verified_by_name, sp.public_token
                            FROM students s
                            LEFT JOIN student_photos sp ON sp.nis = s.nis
                            WHERE s.nis = ?
                            LIMIT 1
                        `;
                        row = await env.DB.prepare(nisQuery).bind(decryptedNis).first();
                    }
                }

                if (!row) {
                    return errorResponse("Kartu Pelajar tidak ditemukan atau token verifikasi tidak valid", 404, request);
                }

                // Tentukan status kesiswaan: jika kelas alumni atau bukan kelas reguler (X, XI, XII aktif), status nonaktif
                const isRegularClass = (className) => {
                    if (!className || typeof className !== "string") return false;
                    const trimmed = className.trim();
                    if (!trimmed || trimmed === "-" || trimmed.toLowerCase() === "null") return false;
                    const lower = trimmed.toLowerCase();
                    const inactive = [/\balumni\b/, /\bmutasi\b/, /\bpindah\b/, /\bkeluar\b/, /\bnon\s*aktif\b/, /\blulus\b/, /\bdrop\s*out\b/, /^do$/];
                    if (inactive.some(p => p.test(lower))) return false;
                    return /^(XII|XI|X)([-.\s_]|$|[A-Za-z0-9])/i.test(trimmed);
                };

                const isRegular = isRegularClass(row.class);
                const isExplicitActive = !row.student_status || row.student_status === "active" || row.student_status === "aktif";
                const calculatedStatus = (isRegular && isExplicitActive) ? "active" : "nonaktif";

                // Ekstraksi Alamat Domisili Siswa (Level Dusun, Desa, Kecamatan - Sesuai Standar Kartu & UU PDP No. 27/2022)
                let dapodik = {};
                if (row.dapodik_data) {
                    try {
                        dapodik = typeof row.dapodik_data === "object" ? row.dapodik_data : JSON.parse(row.dapodik_data);
                    } catch (e) {
                        dapodik = {};
                    }
                }

                const toTitleCase = (str) => {
                    if (!str || typeof str !== 'string') return '';
                    const trimmed = str.trim();
                    if (!trimmed || trimmed === '-') return '';
                    return trimmed.toLowerCase().replace(/\b[a-z]/g, c => c.toUpperCase());
                };

                const getBaseKeyword = (s) => {
                    return String(s || '')
                        .toLowerCase()
                        .replace(/^(desa|kelurahan|kel\.?|kecamatan|kec\.?)\s+/i, '')
                        .trim();
                };

                const rawAlamat = String(dapodik.address || dapodik.alamat || dapodik.alamat_jalan || '').trim();
                const rawDusun = String(dapodik.dusun || '').trim();
                const rawDesa = String(dapodik.kelurahan || dapodik.desa || dapodik.desa_kelurahan || '').trim();
                const rawKecamatan = String(dapodik.kecamatan || '').trim();

                const addrParts = [];
                const mainAddr = rawAlamat || rawDusun;
                if (mainAddr && mainAddr !== '-') {
                    addrParts.push(toTitleCase(mainAddr));
                }
                if (rawDesa && rawDesa !== '-') {
                    const cleanDesa = toTitleCase(rawDesa);
                    const dBase = getBaseKeyword(cleanDesa);
                    const existing = addrParts.join(', ').split(',').map(s => getBaseKeyword(s));
                    if (!existing.some(seg => seg === dBase)) {
                        addrParts.push(cleanDesa);
                    }
                }
                if (rawKecamatan && rawKecamatan !== '-') {
                    const cleanKec = toTitleCase(rawKecamatan);
                    const kBase = getBaseKeyword(cleanKec);
                    const existing = addrParts.join(', ').split(',').map(s => getBaseKeyword(s));
                    if (!existing.some(seg => seg === kBase)) {
                        addrParts.push(cleanKec);
                    }
                }
                const formattedStudentAddress = addrParts.filter(Boolean).join(', ').trim() || '-';

                // Sensor Kredensial Login Siswa: Samarkan NISN dan Tanggal Lahir untuk publik
                const maskedNisn = maskPublicNisn(row.nisn);
                const maskedBirthDate = maskPublicBirthDate(row.birth_date);

                const publicCardData = {
                    nis: row.nis,
                    nisn: maskedNisn,
                    nama: row.name,
                    jenis_kelamin: row.gender === "L" ? "Laki-laki" : (row.gender === "P" ? "Perempuan" : "-"),
                    kelas: row.class,
                    tempat_tanggal_lahir: (row.birth_place ? row.birth_place + ", " : "") + maskedBirthDate,
                    alamat_domisili: formattedStudentAddress,
                    status_siswa: calculatedStatus,
                    foto_url: row.active_photo_url || null,
                    is_verified: row.photo_status === "verified",
                    diverifikasi_pada: row.verified_at || null,
                    diverifikasi_oleh: row.verified_by_name || "Sistem SIMAS CERDAS",
                    token: row.public_token,
                    sekolah: PUBLIC_SCHOOL_IDENTITY
                };

                const res = jsonResponse({
                    success: true,
                    card: publicCardData
                }, 200, request);

                // Cache di Edge Cloudflare selama 1 hari (0 read ke D1 pada scan berulang)
                res.headers.set("Cache-Control", "public, max-age=86400, stale-while-revalidate=3600");
                return res;
            }

            // 0. SUBMISSIONS: Pengajuan Data GTK Mandiri (Calon PTK / Form Registrasi)
            // Standar: OWASP Top 10 & ASVS Level 1 & 2 (Honeypot, Rate Limit, Anti-Duplikasi & RBAC Approval)

            // POST /api/gtk/submissions (Publik / Unauthenticated)
            if (path === "/api/gtk/submissions" && method === "POST") {
                await ensureGtkSubmissionsSchema(env);

                const clientIp = request.headers.get("CF-Connecting-IP") || request.headers.get("x-forwarded-for") || "unknown";
                const rateLimitId = await sha256Id(`gtk_sub:${clientIp}`);
                const allowed = await consumeD1RateLimit(env, rateLimitId, 50, 10 * 60 * 1000);
                if (!allowed) {
                    return errorResponse("Terlalu banyak permintaan pendaftaran dari jaringan Anda. Silakan tunggu 10 menit.", 429, request);
                }

                const body = await request.json().catch(() => null);
                if (!body) return errorResponse("Body request tidak valid", 400, request);
                if (typeof body !== 'object' || Array.isArray(body) || Object.values(body).some(v => v != null && typeof v !== 'string')) {
                    return errorResponse("Format data pengajuan tidak valid.", 400, request);
                }
                if (Object.values(body).some(v => typeof v === 'string' && v.length > 500)) {
                    return errorResponse("Ada isian yang terlalu panjang (maksimal 500 karakter).", 400, request);
                }

                // Honeypot check (Anti Bot Spam)
                if (body._hp || body.website) {
                    return jsonResponse({ success: true, id: "sub_ack", message: "Pengajuan data GTK berhasil diterima." }, 200, request);
                }

                // Helper sanitasi string & pencegahan XSS
                const sanitizeStr = (v) => {
                    if (v === null || v === undefined) return "";
                    return String(v).replace(/<[^>]*>?/gm, "").trim();
                };

                const name = sanitizeStr(body.name || body.nama);
                const gender = sanitizeStr(body.gender || body.jenis_kelamin).toUpperCase();
                const nik = sanitizeStr(body.nik);
                const nuptk = sanitizeStr(body.nuptk);
                const nip = sanitizeStr(body.nip);
                const agama = sanitizeStr(body.agama);
                const birthPlace = sanitizeStr(body.birth_place || body.tempat_lahir);
                const birthDate = sanitizeStr(body.birth_date || body.tanggal_lahir);
                const statusKepegawaian = sanitizeStr(body.status_kepegawaian);
                const jenisPtk = sanitizeStr(body.jenis_ptk);
                const tugasTambahan = sanitizeStr(body.tugas_tambahan);
                const alamat = sanitizeStr(body.alamat || body.address);
                const rt = sanitizeStr(body.rt);
                const rw = sanitizeStr(body.rw);
                const dusun = sanitizeStr(body.dusun);
                const kelurahan = sanitizeStr(body.kelurahan);
                const kecamatan = sanitizeStr(body.kecamatan);
                const kodePos = sanitizeStr(body.kode_pos);
                const phone = sanitizeStr(body.phone || body.no_wa || body.hp);
                const email = sanitizeStr(body.email).toLowerCase();
                const telegramChatId = sanitizeStr(body.telegram_chat_id || body.telegramChatId);

                // Validasi input penting
                if (!name || name.length < 3) {
                    return errorResponse("Nama lengkap wajib diisi minimal 3 karakter.", 400, request);
                }
                if (!gender || !["L", "P"].includes(gender)) {
                    return errorResponse("Jenis kelamin wajib dipilih (Laki-laki / Perempuan).", 400, request);
                }
                if (!/^[+\d\s().-]+$/.test(phone) || phone.replace(/\D/g, '').length < 8 || phone.replace(/\D/g, '').length > 15) {
                    return errorResponse("Nomor WhatsApp/HP harus berisi 8 sampai 15 digit.", 400, request);
                }
                if (email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
                    return errorResponse("Alamat email aktif wajib diisi dengan format yang benar.", 400, request);
                }
                if (!nip || (nip !== '-' && !/^\d{18}$/.test(nip))) {
                    return errorResponse("NIP harus 18 digit atau tanda strip (-) jika belum memiliki NIP.", 400, request);
                }
                if (nuptk && nuptk !== '-' && !/^\d{16}$/.test(nuptk)) {
                    return errorResponse("NUPTK harus 16 digit angka.", 400, request);
                }
                if (kodePos && kodePos !== '-' && !/^\d{5}$/.test(kodePos)) {
                    return errorResponse("Kode pos harus 5 digit angka.", 400, request);
                }

                // Cek apakah NIK sudah terdaftar di Master GTK
                if (nik && nik !== "-") {
                    if (!/^\d{16}$/.test(nik)) {
                        return errorResponse("NIK wajib 16 digit angka.", 400, request);
                    }
                    const existNik = await env.DB.prepare("SELECT id, name FROM gtk WHERE nik = ? LIMIT 1").bind(nik).first();
                    if (existNik) {
                        return errorResponse("NIK sudah terdaftar. Silakan hubungi admin.", 409, request);
                    }
                    // Cek apakah ada di antrean pending
                    const existPendingNik = await env.DB.prepare("SELECT id, name FROM gtk_submissions WHERE nik = ? AND status = 'pending' LIMIT 1").bind(nik).first();
                    if (existPendingNik) {
                        return errorResponse(`Pengajuan data GTK dengan NIK ${nik} sudah dalam antrean verifikasi.`, 409, request);
                    }
                }

                // Cek apakah NIP sudah terdaftar di Master GTK jika bukan '-'
                if (nip && nip !== "-") {
                    const existNip = await env.DB.prepare("SELECT id, name FROM gtk WHERE nip = ? LIMIT 1").bind(nip).first();
                    if (existNip) {
                        return errorResponse("NIP sudah terdaftar. Silakan hubungi admin.", 409, request);
                    }
                }

                // Cek email di Master GTK
                const existEmail = await env.DB.prepare("SELECT id, name FROM gtk WHERE LOWER(email) = ? LIMIT 1").bind(email).first();
                if (existEmail) {
                    return errorResponse("Email sudah terdaftar. Silakan hubungi admin.", 409, request);
                }

                const subId = `sub_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
                const nowIso = new Date().toISOString();

                const inserted = await env.DB.prepare(`
                    INSERT INTO gtk_submissions (
                        id, name, gender, nik, nuptk, nip, agama,
                        birth_place, birth_date, status_kepegawaian, jenis_ptk, tugas_tambahan,
                        alamat, rt, rw, dusun, kelurahan, kecamatan, kode_pos,
                        phone, email, telegram_chat_id, status, ip_address, created_at
                    ) SELECT
                        ?, ?, ?, ?, ?, ?, ?,
                        ?, ?, ?, ?, ?,
                        ?, ?, ?, ?, ?, ?, ?,
                        ?, ?, ?, 'pending', ?, ?
                    WHERE NOT EXISTS (
                        SELECT 1 FROM gtk_submissions WHERE status = 'pending' AND
                            (LOWER(TRIM(email)) = ? OR (? <> '-' AND nik = ?) OR (? <> '-' AND nip = ?))
                    ) AND NOT EXISTS (
                        SELECT 1 FROM gtk WHERE LOWER(TRIM(email)) = ? OR (? <> '-' AND nik = ?) OR (? <> '-' AND nip = ?)
                    )
                `).bind(
                    subId, name, gender, nik || "-", nuptk || "-", nip || "-", agama || "-",
                    birthPlace || "-", birthDate || "-", statusKepegawaian || "-", jenisPtk || "-", tugasTambahan || "-",
                    alamat || "-", rt || "00", rw || "00", dusun || "-", kelurahan || "-", kecamatan || "-", kodePos || "-",
                    phone, email, telegramChatId || "-", clientIp, nowIso,
                    email, nik || '-', nik || '-', nip, nip,
                    email, nik || '-', nik || '-', nip, nip
                ).run();
                if (!inserted.meta?.changes) {
                    return errorResponse("Data sudah terdaftar atau masih menunggu verifikasi. Silakan hubungi admin.", 409, request);
                }

                ctx.waitUntil(notifyGtkRegistration(env, subId));

                return jsonResponse({
                    success: true,
                    message: "Pengajuan data GTK berhasil dikirim. Data Anda akan ditinjau oleh Tim Kurikulum / Staf.",
                    id: subId
                }, 201, request);
            }

            // GET /api/gtk/submissions (Terproteksi: Kurikulum, Staff, Admin)
            if (path === "/api/gtk/submissions" && method === "GET") {
                await ensureGtkSubmissionsSchema(env);
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult || !authResult.valid || !authResult.user) {
                    return errorResponse("Unauthorized: " + (authResult?.error || "Token otentikasi tidak valid"), 401, request);
                }

                if (!canApproveGtkSubmission(authResult.user)) {
                    return errorResponse("Forbidden: Hanya Kurikulum dan Staff yang berhak mengakses data pengajuan GTK.", 403, request);
                }

                const statusFilter = url.searchParams.get("status") || "pending";
                let query = "SELECT * FROM gtk_submissions";
                const params = [];

                if (statusFilter !== "all") {
                    query += " WHERE status = ?";
                    params.push(statusFilter);
                }
                query += " ORDER BY created_at DESC LIMIT 200";

                const stmt = env.DB.prepare(query);
                const { results } = await (params.length > 0 ? stmt.bind(...params) : stmt).all();

                return jsonResponse({
                    success: true,
                    count: (results || []).length,
                    data: results || []
                }, 200, request);
            }

            // POST /api/gtk/submissions/:id/approve (Terproteksi: Kurikulum, Staff, Admin)
            if (path.startsWith("/api/gtk/submissions/") && path.endsWith("/approve") && method === "POST") {
                await ensureGtkSubmissionsSchema(env);
                await ensureGtkPhotoColumn(env);
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult || !authResult.valid || !authResult.user) {
                    return errorResponse("Unauthorized: " + (authResult?.error || "Token otentikasi tidak valid"), 401, request);
                }

                if (!canApproveGtkSubmission(authResult.user)) {
                    return errorResponse("Forbidden: Hanya Kurikulum dan Staff yang berhak menyetujui pengajuan data GTK.", 403, request);
                }

                const parts = path.split("/").filter(Boolean); // ['api', 'gtk', 'submissions', id, 'approve']
                const subId = parts[3];
                if (!subId) return errorResponse("ID pengajuan tidak valid.", 400, request);

                const sub = await env.DB.prepare("SELECT * FROM gtk_submissions WHERE id = ?").bind(subId).first();
                if (!sub) {
                    return errorResponse("Pengajuan data GTK tidak ditemukan.", 404, request);
                }

                if (sub.status !== "pending") {
                    return errorResponse(`Pengajuan ini sudah berstatus "${sub.status}" dan tidak dapat diproses ulang.`, 400, request);
                }

                // Susun ID GTK definitif
                const cleanNik = (sub.nik || "").trim();
                const cleanNip = (sub.nip || "").trim();
                const cleanNuptk = (sub.nuptk || "").trim();
                const gtkId = (cleanNik && cleanNik !== "-") ? cleanNik : ((cleanNip && cleanNip !== "-") ? cleanNip : ((cleanNuptk && cleanNuptk !== "-") ? cleanNuptk : `gtk_${crypto.randomUUID()}`));

                // Format alamat komprehensif
                let formattedAddress = (sub.alamat || "").trim();
                const addrParts = [];
                if (sub.rt && sub.rt !== "-" && sub.rt !== "00" && sub.rw && sub.rw !== "-") {
                    addrParts.push(`RT ${sub.rt}/RW ${sub.rw}`);
                }
                if (sub.dusun && sub.dusun !== "-") addrParts.push(`Dusun ${sub.dusun}`);
                if (sub.kelurahan && sub.kelurahan !== "-") addrParts.push(`Desa/Kel. ${sub.kelurahan}`);
                if (sub.kecamatan && sub.kecamatan !== "-") addrParts.push(`Kec. ${sub.kecamatan}`);
                if (sub.kode_pos && sub.kode_pos !== "-") addrParts.push(sub.kode_pos);
                if (addrParts.length > 0) {
                    formattedAddress = formattedAddress && formattedAddress !== "-" ? `${formattedAddress}, ${addrParts.join(", ")}` : addrParts.join(", ");
                }

                const notes = `Pendaftaran mandiri. Agama: ${sub.agama || '-'}. Tugas Tambahan: ${sub.tugas_tambahan || '-'}`;
                const approverName = authResult.user.name || authResult.user.email || authResult.user.uid;
                const defaultRole = (sub.jenis_ptk || "").toLowerCase().includes("pendidik") || (sub.jenis_ptk || "").toLowerCase().includes("guru") ? "guru_mapel" : "staff";

                // Kedua perubahan berjalan dalam satu transaksi D1. Jangan pernah menimpa GTK lama.
                const insertGtk = env.DB.prepare(`
                    INSERT INTO gtk (
                        id, nik, nip, nuptk, name, gender, birth_place, birth_date,
                        phone, email, address, jenis_ptk, status_kepegawaian,
                        pendidikan_terakhir, mapel, role, telegram_chat_id, notes, status, updated_at
                    ) SELECT
                        ?, ?, ?, ?, ?, ?, ?, ?,
                        ?, ?, ?, ?, ?,
                        ?, ?, ?, ?, ?, 'active', datetime('now')
                    WHERE EXISTS (SELECT 1 FROM gtk_submissions WHERE id = ? AND status = 'pending')
                      AND NOT EXISTS (SELECT 1 FROM gtk WHERE id = ? OR LOWER(TRIM(email)) = LOWER(TRIM(?))
                          OR (? <> '-' AND nik = ?) OR (? <> '-' AND nip = ?) OR (? <> '-' AND nuptk = ?))
                `).bind(
                    gtkId,
                    cleanNik || "-",
                    cleanNip || "-",
                    cleanNuptk || "-",
                    sub.name,
                    sub.gender || "L",
                    sub.birth_place || "-",
                    sub.birth_date || "-",
                    sub.phone || "-",
                    sub.email || "-",
                    formattedAddress || "-",
                    sub.jenis_ptk || "Pendidik",
                    sub.status_kepegawaian || "Honorer",
                    "-",
                    "",
                    defaultRole,
                    sub.telegram_chat_id || "-",
                    notes,
                    subId, gtkId, sub.email, cleanNik || '-', cleanNik || '-', cleanNip || '-', cleanNip || '-', cleanNuptk || '-', cleanNuptk || '-'
                );

                // Update status di tabel gtk_submissions
                const approveSubmission = env.DB.prepare(`
                    UPDATE gtk_submissions 
                    SET status = 'approved', approved_by = ?, approved_at = datetime('now')
                    WHERE id = ? AND status = 'pending' AND changes() = 1
                `).bind(approverName, subId);
                const approvalWrites = await env.DB.batch([insertGtk, approveSubmission]);
                if (!approvalWrites[0].meta?.changes) {
                    return errorResponse("Data GTK sudah ada atau status pengajuan telah berubah. Muat ulang dan periksa data master.", 409, request);
                }

                // Bersihkan cache in-memory dan metadata
                invalidateMasterBundleCache();
                try { await updateServerMetadata(env.DB, { lastUpdateTeachers: Date.now() }); }
                catch (err) { console.warn('[GTK approval] Metadata update failed:', err); }

                return jsonResponse({
                    success: true,
                    message: `Data GTK "${sub.name}" berhasil disetujui dan ditambahkan ke Master Data GTK. Pembuatan akun login dapat dilakukan di Manajemen Pengguna.`,
                    gtk_id: gtkId
                }, 200, request);
            }

            // POST /api/gtk/submissions/:id/reject (Terproteksi: Kurikulum, Staff, Admin)
            if (path.startsWith("/api/gtk/submissions/") && path.endsWith("/reject") && method === "POST") {
                await ensureGtkSubmissionsSchema(env);
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult || !authResult.valid || !authResult.user) {
                    return errorResponse("Unauthorized: " + (authResult?.error || "Token otentikasi tidak valid"), 401, request);
                }

                if (!canApproveGtkSubmission(authResult.user)) {
                    return errorResponse("Forbidden: Hanya Kurikulum dan Staff yang berhak menolak pengajuan data GTK.", 403, request);
                }

                const parts = path.split("/").filter(Boolean); // ['api', 'gtk', 'submissions', id, 'reject']
                const subId = parts[3];
                if (!subId) return errorResponse("ID pengajuan tidak valid.", 400, request);

                const sub = await env.DB.prepare("SELECT * FROM gtk_submissions WHERE id = ?").bind(subId).first();
                if (!sub) {
                    return errorResponse("Pengajuan data GTK tidak ditemukan.", 404, request);
                }

                if (sub.status !== "pending") {
                    return errorResponse(`Pengajuan ini sudah berstatus "${sub.status}" dan tidak dapat diproses ulang.`, 400, request);
                }

                const body = await request.json().catch(() => ({}));
                const reason = String(body.reason || body.alasan || "Data tidak sesuai atau tidak lengkap").trim();
                const approverName = authResult.user.name || authResult.user.email || authResult.user.uid;

                const rejected = await env.DB.prepare(`
                    UPDATE gtk_submissions 
                    SET status = 'rejected', rejection_reason = ?, approved_by = ?, approved_at = datetime('now')
                    WHERE id = ? AND status = 'pending'
                `).bind(reason, approverName, subId).run();
                if (!rejected.meta?.changes) return errorResponse("Status pengajuan telah berubah. Muat ulang daftar.", 409, request);

                return jsonResponse({
                    success: true,
                    message: `Pengajuan data GTK "${sub.name}" telah ditolak.`
                }, 200, request);
            }

            // 0a. POST /api/gtk/photo/upload (Upload Foto Profil GTK Resmi ke Cloudflare R2)
            if (path === "/api/gtk/photo/upload" && method === "POST") {
                await ensureGtkPhotoColumn(env);
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult || !authResult.valid || !authResult.user) {
                    return errorResponse("Unauthorized: " + (authResult?.error || "Token otentikasi tidak valid"), 401, request);
                }

                const user = authResult.user;
                const role = String(user.role || "").toLowerCase().trim();
                if (['siswa', 'admin_kelas', 'admin_pks'].includes(role) || user.isAnonymous) {
                    return errorResponse("Forbidden: Akses upload foto profil GTK ditolak untuk akun siswa/admin kelas.", 403, request);
                }

                const body = await request.json().catch(() => null);
                if (!body) return errorResponse("Body request tidak valid", 400, request);

                const rawImage = body.image || body.photoBase64;
                if (!rawImage) return errorResponse("Data gambar WebP base64 wajib diisi", 400, request);

                const requestedGtkId = String(body.gtkId || body.id || "").trim();
                const isSuperAdmin = role === 'super_admin' || (Array.isArray(user.additionalRoles) && user.additionalRoles.includes('super_admin'));
                const userTeacherId = user.linkedTeacherId || user.profile?.linkedTeacherId || "";
                const userNik = user.profile?.nik || "";
                const userNip = user.profile?.nip || "";
                const userEmail = (user.email || "").toLowerCase().trim();

                let existingGtk = null;
                if (requestedGtkId) {
                    existingGtk = await env.DB.prepare(`
                        SELECT * FROM gtk 
                        WHERE id = ? OR nik = ? OR nip = ? OR LOWER(email) = ? 
                        LIMIT 1
                    `).bind(requestedGtkId, requestedGtkId, requestedGtkId, requestedGtkId.toLowerCase()).first();
                }

                if (!existingGtk) {
                    // Cari berdasarkan relasi akun user sendiri
                    existingGtk = await env.DB.prepare(`
                        SELECT * FROM gtk 
                        WHERE id = ? OR nik = ? OR nip = ? OR LOWER(email) = ? 
                        LIMIT 1
                    `).bind(userTeacherId || user.uid, userNik || "___", userNip || "___", userEmail || "___").first();
                }

                // Strict rule: Akun yang tidak terhubung ke tabel GTK tidak diberikan fitur foto profil
                if (!existingGtk) {
                    return errorResponse("Akun Anda tidak terhubung dengan data Master GTK di SIMAS. Fitur foto profil hanya tersedia bagi PTK/GTK yang terdaftar.", 403, request);
                }

                // Cek wewenang edit: Super Admin berhak untuk semua GTK; user biasa hanya untuk GTK miliknya sendiri
                const gtkEmail = (existingGtk.email || "").toLowerCase().trim();
                const isSelf = Boolean(
                    (userEmail && gtkEmail && userEmail === gtkEmail) ||
                    (userTeacherId && (existingGtk.id === userTeacherId || existingGtk.nik === userTeacherId || existingGtk.nip === userTeacherId)) ||
                    (userNik && existingGtk.nik && userNik === existingGtk.nik) ||
                    (userNip && existingGtk.nip && userNip === existingGtk.nip) ||
                    (existingGtk.id === user.uid) ||
                    (!requestedGtkId)
                );

                if (!isSuperAdmin && !isSelf) {
                    return errorResponse("Forbidden: Anda tidak memiliki wewenang untuk mengubah foto profil pengguna lain.", 403, request);
                }

                // Validasi data base64
                let base64Clean = String(rawImage);
                if (base64Clean.includes(",")) {
                    base64Clean = base64Clean.split(",")[1];
                }
                base64Clean = base64Clean.trim();

                // Maksimal 500 KB base64 (~375 KB binary)
                if (base64Clean.length > 500 * 1024) {
                    return errorResponse("Ukuran foto terlalu besar. Maksimal 300 KB setelah kompresi WebP.", 400, request);
                }

                let imageBytes;
                try {
                    const binaryStr = atob(base64Clean);
                    imageBytes = new Uint8Array(binaryStr.length);
                    for (let i = 0; i < binaryStr.length; i++) {
                        imageBytes[i] = binaryStr.charCodeAt(i);
                    }
                } catch (e) {
                    return errorResponse("Format data gambar base64 tidak valid: " + e.message, 400, request);
                }

                const r2Bucket = env.GTK_PHOTOS_BUCKET || env.STUDENT_PHOTOS_BUCKET;
                if (!r2Bucket) {
                    return errorResponse("Cloudflare R2 Bucket belum dikonfigurasi pada environment", 500, request);
                }

                // Key terisolasi pada folder 'gtk/'
                const safeFileId = String(existingGtk.id).replace(/[^a-zA-Z0-9_\-]/g, "_");
                const r2Key = `gtk/${safeFileId}.webp`;

                await r2Bucket.put(r2Key, imageBytes, {
                    httpMetadata: { contentType: "image/webp" }
                });

                const timestamp = Date.now();
                const photoUrl = `/api/photos/gtk/${safeFileId}.webp?v=${timestamp}`;

                // Simpan secara eksklusif ke tabel Cloudflare D1 'gtk' (0 Firestore Read/Write & 0 write ke tabel users)
                await env.DB.prepare(`
                    UPDATE gtk SET foto = ?, updated_at = datetime('now')
                    WHERE id = ?
                `).bind(photoUrl, existingGtk.id).run();

                invalidateMasterBundleCache();
                await updateServerMetadata(env.DB, { lastUpdateTeachers: Date.now() });

                const requestOrigin = new URL(request.url).origin;
                const fullPhotoUrl = `${requestOrigin}${photoUrl}`;

                return jsonResponse({
                    success: true,
                    foto_url: fullPhotoUrl,
                    photo_url: fullPhotoUrl,
                    photo_path: photoUrl,
                    gtk_id: existingGtk.id,
                    message: "Foto profil GTK berhasil diperbarui."
                }, 200, request);
            }

            // 0b. DELETE /api/gtk/photo/:id (Hapus Foto Profil GTK dari R2 & D1)
            if (path.startsWith("/api/gtk/photo/") && method === "DELETE") {
                await ensureGtkPhotoColumn(env);
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult || !authResult.valid || !authResult.user) {
                    return errorResponse("Unauthorized: " + (authResult?.error || "Token otentikasi tidak valid"), 401, request);
                }

                const user = authResult.user;
                const role = String(user.role || "").toLowerCase().trim();
                const targetId = decodeURIComponent(path.replace("/api/gtk/photo/", "")).trim();
                const isSuperAdmin = role === 'super_admin' || (Array.isArray(user.additionalRoles) && user.additionalRoles.includes('super_admin'));
                const userTeacherId = user.linkedTeacherId || user.profile?.linkedTeacherId || "";
                const userEmail = (user.email || "").toLowerCase().trim();

                const existingGtk = await env.DB.prepare(`
                    SELECT * FROM gtk 
                    WHERE id = ? OR nik = ? OR nip = ? OR LOWER(email) = ? 
                    LIMIT 1
                `).bind(targetId, targetId, targetId, targetId.toLowerCase()).first();

                if (!existingGtk) {
                    return errorResponse("Data GTK tidak ditemukan.", 404, request);
                }

                const gtkEmail = (existingGtk.email || "").toLowerCase().trim();
                const isSelf = Boolean(
                    (userEmail && gtkEmail && userEmail === gtkEmail) ||
                    (userTeacherId && (existingGtk.id === userTeacherId || existingGtk.nik === userTeacherId || existingGtk.nip === userTeacherId)) ||
                    (existingGtk.id === user.uid)
                );

                if (!isSuperAdmin) {
                    return errorResponse("Forbidden: Hanya Super Admin yang berhak menghapus foto profil GTK. Guru dan staf hanya diperkenankan mengedit / mengganti foto.", 403, request);
                }

                const r2Bucket = env.GTK_PHOTOS_BUCKET || env.STUDENT_PHOTOS_BUCKET;
                const safeFileId = String(existingGtk.id).replace(/[^a-zA-Z0-9_\-]/g, "_");
                const r2Key = `gtk/${safeFileId}.webp`;

                if (r2Bucket) {
                    ctx?.waitUntil?.(r2Bucket.delete(r2Key).catch(() => {}));
                }

                await env.DB.prepare("UPDATE gtk SET foto = NULL, updated_at = datetime('now') WHERE id = ?").bind(existingGtk.id).run();
                invalidateMasterBundleCache();
                await updateServerMetadata(env.DB, { lastUpdateTeachers: Date.now() });

                return jsonResponse({
                    success: true,
                    message: "Foto profil GTK berhasil dihapus."
                }, 200, request);
            }

            // 0c. GET /api/photos/gtk/:filename (Streaming File Foto GTK dari Cloudflare R2)
            if (path.startsWith("/api/photos/gtk/") && method === "GET") {
                const parts = path.split("/").filter(Boolean); // ['api', 'photos', 'gtk', filename]
                if (parts.length < 4) {
                    return errorResponse("URL foto GTK tidak valid", 400, request);
                }
                const filename = parts[3].split("?")[0]; // sanitize query param

                if (!/^[a-zA-Z0-9_\-\.]+\.webp$/.test(filename)) {
                    return errorResponse("Nama file foto tidak valid", 400, request);
                }

                const r2Bucket = env.GTK_PHOTOS_BUCKET || env.STUDENT_PHOTOS_BUCKET;
                if (!r2Bucket) {
                    return errorResponse("Bucket R2 belum terpasang", 500, request);
                }

                const r2Key = `gtk/${filename}`;
                const object = await r2Bucket.get(r2Key);

                if (!object) {
                    return errorResponse("Foto profil GTK tidak ditemukan", 404, request);
                }

                const headers = new Headers();
                object.writeHttpMetadata(headers);
                headers.set("Content-Type", "image/webp");
                headers.set("Cache-Control", "public, max-age=604800, stale-while-revalidate=86400");
                headers.set("Access-Control-Allow-Origin", "*");
                return new Response(object.body, { headers });
            }

            // 1. GET /api/gtk & GET /api/teachers (List Seluruh GTK dengan filter status, q, limit, offset)
            if ((path === "/api/gtk" || path === "/api/teachers") && method === "GET") {
                await ensureGtkPhotoColumn(env);
                const syncKey = request.headers.get("X-Sync-Key") || request.headers.get("X-Api-Key") || request.headers.get("X-Migration-Key") || url.searchParams.get("key");
                const isSecretValid = Boolean(syncKey && env.MIGRATION_SECRET && syncKey === env.MIGRATION_SECRET);

                let isStaff = isSecretValid;
                let isVerifiedStudent = false;

                if (!isStaff) {
                    const authResult = await verifyFirebaseToken(request, env);
                    if (!authResult.valid) {
                        return errorResponse("Unauthorized: " + authResult.error, 401, request);
                    }
                    if (isSchoolStaff(authResult.user)) {
                        isStaff = true;
                    } else {
                        const studentSession = await getVerifiedStudentSession(request, env, authResult);
                        if (studentSession?.nis) {
                            isVerifiedStudent = true;
                        } else {
                            return errorResponse("Forbidden: Akses daftar GTK ditolak. Diperlukan autentikasi staf atau siswa terverifikasi.", 403, request);
                        }
                    }
                }

                const statusParam = url.searchParams.get("status") || "all";
                const searchParam = url.searchParams.get("search") || url.searchParams.get("q");
                const limitParam = parseInt(url.searchParams.get("limit") || "1000", 10);
                const offsetParam = parseInt(url.searchParams.get("offset") || "0", 10);
                const safeLimit = Math.min(Math.max(limitParam, 1), 2000);
                const safeOffset = Math.max(offsetParam, 0);

                const isFullListQuery = (!searchParam || !searchParam.trim()) && (statusParam === "all" || statusParam === "semua") && safeOffset === 0 && safeLimit >= 500;
                const now = Date.now();
                if (isFullListQuery && isStaff && gtkListMemoryCache.data && gtkListMemoryCache.expiry > now) {
                    const cachedRes = jsonResponse({
                        success: true,
                        count: gtkListMemoryCache.data.length,
                        data: gtkListMemoryCache.data
                    }, 200, request);
                    cachedRes.headers.set("Cache-Control", "private, max-age=60");
                    return cachedRes;
                }

                let sql = `SELECT * FROM gtk WHERE 1=1`;
                const params = [];

                if (statusParam && statusParam !== "all" && statusParam !== "semua") {
                    sql += ` AND status = ?`;
                    params.push(statusParam.trim().toLowerCase());
                }

                if (searchParam && searchParam.trim()) {
                    const term = `%${searchParam.trim()}%`;
                    sql += ` AND (name LIKE ? OR nip LIKE ? OR nik LIKE ? OR nuptk LIKE ? OR email LIKE ? OR mapel LIKE ? OR jenis_ptk LIKE ?)`;
                    params.push(term, term, term, term, term, term, term);
                }

                sql += ` ORDER BY name ASC LIMIT ? OFFSET ?`;
                params.push(safeLimit, safeOffset);

                const stmt = env.DB.prepare(sql);
                const { results } = await stmt.bind(...params).all();

                const formattedList = (results || []).map(r => {
                    if (isStaff) {
                        return {
                            ...r,
                            id: r.id || r.nik || r.nip,
                            nama: r.name,
                            jenis_kelamin: r.gender,
                            tempat_lahir: r.birth_place,
                            tanggal_lahir: r.birth_date,
                            no_wa: r.phone,
                            hp: r.phone,
                            alamat: r.alamat || r.address || "",
                            jabatan: r.tugas_tambahan || r.jenis_ptk,
                            agama: r.agama || "Hindu",
                            tugas_tambahan: r.tugas_tambahan || "-",
                            rt: r.rt || "",
                            rw: r.rw || "",
                            dusun: r.dusun || "",
                            kelurahan: r.kelurahan || "",
                            kecamatan: r.kecamatan || "",
                            kode_pos: r.kode_pos || "",
                            telegramChatId: r.telegram_chat_id,
                            foto: r.foto || null,
                            photo_url: r.foto || null
                        };
                    }
                    // Siswa terverifikasi: Data Minimization (hanya profil kontak pendidik, tanpa NIK/NUPTK/TTL/Alamat lengkap/Telegram/Notes)
                    return {
                        id: r.id || r.nip || "gtk",
                        nama: r.name,
                        name: r.name,
                        nip: r.nip || "-",
                        jenis_kelamin: r.gender,
                        gender: r.gender,
                        no_wa: r.phone || "",
                        hp: r.phone || "",
                        phone: r.phone || "",
                        email: r.email || "",
                        jabatan: r.tugas_tambahan || r.jenis_ptk || "Pendidik",
                        jenis_ptk: r.jenis_ptk || "Pendidik",
                        tugas_tambahan: r.tugas_tambahan || "-",
                        mapel: r.mapel || "",
                        role: r.role || "guru_mapel",
                        status: r.status || "active",
                        foto: r.foto || null,
                        photo_url: r.foto || null
                    };
                });

                if (isFullListQuery && isStaff) {
                    gtkListMemoryCache = {
                        data: formattedList,
                        expiry: now + (10 * 60 * 1000)
                    };
                }

                const res = jsonResponse({
                    success: true,
                    count: formattedList.length,
                    data: formattedList
                }, 200, request);
                res.headers.set("Cache-Control", isStaff ? "private, max-age=60" : "private, no-store");
                return res;
            }

            // 2. GET /api/gtk/:id & GET /api/teachers/:id (Detail GTK Tunggal)
            if (((path.startsWith("/api/gtk/") && path.split("/").length === 4) || (path.startsWith("/api/teachers/") && path.split("/").length === 4)) && method === "GET") {
                await ensureGtkPhotoColumn(env);
                const syncKey = request.headers.get("X-Sync-Key") || request.headers.get("X-Api-Key") || request.headers.get("X-Migration-Key") || url.searchParams.get("key");
                const isSecretValid = Boolean(syncKey && env.MIGRATION_SECRET && syncKey === env.MIGRATION_SECRET);

                let isStaff = isSecretValid;
                let isVerifiedStudent = false;

                if (!isStaff) {
                    const authResult = await verifyFirebaseToken(request, env);
                    if (!authResult.valid) {
                        return errorResponse("Unauthorized: " + authResult.error, 401, request);
                    }
                    if (isSchoolStaff(authResult.user)) {
                        isStaff = true;
                    } else {
                        const studentSession = await getVerifiedStudentSession(request, env, authResult);
                        if (studentSession?.nis) {
                            isVerifiedStudent = true;
                        } else {
                            return errorResponse("Forbidden: Akses detail GTK ditolak. Diperlukan autentikasi staf atau siswa terverifikasi.", 403, request);
                        }
                    }
                }

                const targetId = decodeURIComponent(path.split("/")[3]).trim();
                const legacySearch = `%legacy_id: ${targetId}%`;
                const stmt = env.DB.prepare(`
                    SELECT * FROM gtk 
                    WHERE id = ? OR nik = ? OR nip = ? OR email = ? OR notes LIKE ? 
                    LIMIT 1
                `);
                const row = await stmt.bind(targetId, targetId, targetId, targetId.toLowerCase(), legacySearch).first();

                if (!row) {
                    return errorResponse("Data GTK tidak ditemukan di Cloudflare D1", 404, request);
                }

                const formatted = isStaff ? {
                    ...row,
                    id: row.id || row.nik || row.nip,
                    nama: row.name,
                    jenis_kelamin: row.gender,
                    tempat_lahir: row.birth_place,
                    tanggal_lahir: row.birth_date,
                    no_wa: row.phone,
                    hp: row.phone,
                    alamat: row.alamat || row.address || "",
                    jabatan: row.tugas_tambahan || row.jenis_ptk,
                    agama: row.agama || "Hindu",
                    tugas_tambahan: row.tugas_tambahan || "-",
                    rt: row.rt || "",
                    rw: row.rw || "",
                    dusun: row.dusun || "",
                    kelurahan: row.kelurahan || "",
                    kecamatan: row.kecamatan || "",
                    kode_pos: row.kode_pos || "",
                    telegramChatId: row.telegram_chat_id,
                    foto: row.foto || null,
                    photo_url: row.foto || null
                } : {
                    id: row.id || row.nip || "gtk",
                    nama: row.name,
                    name: row.name,
                    nip: row.nip || "-",
                    jenis_kelamin: row.gender,
                    gender: row.gender,
                    no_wa: row.phone || "",
                    hp: row.phone || "",
                    phone: row.phone || "",
                    email: row.email || "",
                    jabatan: row.tugas_tambahan || row.jenis_ptk || "Pendidik",
                    jenis_ptk: row.jenis_ptk || "Pendidik",
                    tugas_tambahan: row.tugas_tambahan || "-",
                    mapel: row.mapel || "",
                    role: row.role || "guru_mapel",
                    status: row.status || "active",
                    foto: row.foto || null,
                    photo_url: row.foto || null
                };

                const res = jsonResponse({ success: true, data: formatted }, 200, request);
                res.headers.set("Cache-Control", isStaff ? "private, max-age=60" : "private, no-store");
                return res;
            }

            // 3. POST /api/gtk & POST /api/teachers (Tambah GTK Baru)
            if ((path === "/api/gtk" || path === "/api/teachers") && method === "POST") {
                const syncKey = request.headers.get("X-Sync-Key") || request.headers.get("X-Api-Key") || request.headers.get("X-Migration-Key") || url.searchParams.get("key");
                const isSecretValid = Boolean(syncKey && env.MIGRATION_SECRET && syncKey === env.MIGRATION_SECRET);

                let actor = "API Key / System";
                if (!isSecretValid) {
                    const authResult = await verifyFirebaseToken(request);
                    if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);
                    if (!canMutateTeacher(authResult.user)) {
                        return errorResponse("Forbidden: Anda tidak memiliki izin untuk menambah data GTK.", 403, request);
                    }
                    actor = authResult.user.name || authResult.user.email || authResult.user.uid;
                }

                const body = await request.json().catch(() => ({}));
                const name = String(body.name || body.nama || "").trim();
                if (!name) {
                    return errorResponse("Nama GTK wajib diisi.", 400, request);
                }

                const nik = String(body.nik || "").trim();
                const nip = String(body.nip || "").trim();
                const nuptk = String(body.nuptk || "").trim();
                const id = String(body.id || (nik && nik !== "-" ? nik : (nip && nip !== "-" ? nip : (nuptk && nuptk !== "-" ? nuptk : `gtk_${Date.now()}`)))).trim();

                // Cek keunikan NIK jika diisi
                if (nik && nik !== "-") {
                    const existNik = await env.DB.prepare("SELECT id, name FROM gtk WHERE nik = ? LIMIT 1").bind(nik).first();
                    if (existNik && existNik.id !== id) {
                        return errorResponse(`NIK ${nik} sudah terdaftar untuk ${existNik.name}.`, 409, request);
                    }
                }

                // Cek keunikan NIP jika diisi
                if (nip && nip !== "-") {
                    const existNip = await env.DB.prepare("SELECT id, name FROM gtk WHERE nip = ? LIMIT 1").bind(nip).first();
                    if (existNip && existNip.id !== id) {
                        return errorResponse(`NIP ${nip} sudah terdaftar untuk ${existNip.name}.`, 409, request);
                    }
                }

                const gender = String(body.gender || body.jenis_kelamin || "L").toUpperCase();
                const birthPlace = String(body.birth_place || body.tempat_lahir || "").trim();
                const birthDate = String(body.birth_date || body.tanggal_lahir || "").trim();
                const phone = String(body.phone || body.no_wa || body.hp || "").trim();
                const email = String(body.email || "").trim().toLowerCase();
                const address = String(body.address || body.alamat || "").trim();
                const jenisPtk = String(body.jenis_ptk || body.jabatan || "Pendidik").trim();
                const statusKepegawaian = String(body.status_kepegawaian || "Honorer").trim();
                const pendidikanTerakhir = String(body.pendidikan_terakhir || "").trim();
                const mapel = String(body.mapel || (Array.isArray(body.subject) ? JSON.stringify(body.subject) : (body.subject || ""))).trim();
                const role = String(body.role || "guru_mapel").trim();
                const telegramChatId = String(body.telegram_chat_id || body.telegramChatId || "").trim();
                const notes = String(body.notes || "").trim();
                const foto = String(body.foto || body.photo_url || "").trim() || null;
                const status = String(body.status || "active").toLowerCase().trim();

                await env.DB.prepare(`
                    INSERT INTO gtk (
                        id, nik, nip, nuptk, name, gender, birth_place, birth_date, 
                        phone, email, address, jenis_ptk, status_kepegawaian, 
                        pendidikan_terakhir, mapel, role, telegram_chat_id, notes, foto, status, updated_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
                    ON CONFLICT(id) DO UPDATE SET
                        nik = excluded.nik,
                        nip = excluded.nip,
                        nuptk = excluded.nuptk,
                        name = excluded.name,
                        gender = excluded.gender,
                        birth_place = excluded.birth_place,
                        birth_date = excluded.birth_date,
                        phone = excluded.phone,
                        email = excluded.email,
                        address = excluded.address,
                        jenis_ptk = excluded.jenis_ptk,
                        status_kepegawaian = excluded.status_kepegawaian,
                        pendidikan_terakhir = excluded.pendidikan_terakhir,
                        mapel = excluded.mapel,
                        role = excluded.role,
                        telegram_chat_id = excluded.telegram_chat_id,
                        notes = excluded.notes,
                        foto = COALESCE(excluded.foto, gtk.foto),
                        status = excluded.status,
                        updated_at = datetime('now')
                `).bind(
                    id, nik, nip, nuptk, name, gender, birthPlace, birthDate,
                    phone, email, address, jenisPtk, statusKepegawaian,
                    pendidikanTerakhir, mapel, role, telegramChatId, notes, foto, status
                ).run();

                invalidateMasterBundleCache();
                await updateServerMetadata(env.DB, { lastUpdateTeachers: Date.now() });

                return jsonResponse({
                    success: true,
                    id: id,
                    message: `Data GTK ${name} berhasil disimpan ke Cloudflare D1.`
                }, 201, request);
            }

            // 4. PUT /api/gtk/:id & PUT /api/teachers/:id (Edit GTK)
            if (((path.startsWith("/api/gtk/") && path.split("/").length === 4) || (path.startsWith("/api/teachers/") && path.split("/").length === 4)) && method === "PUT") {
                await ensureGtkPhotoColumn(env);
                const syncKey = request.headers.get("X-Sync-Key") || request.headers.get("X-Api-Key") || request.headers.get("X-Migration-Key") || url.searchParams.get("key");
                const isSecretValid = Boolean(syncKey && env.MIGRATION_SECRET && syncKey === env.MIGRATION_SECRET);

                const targetId = decodeURIComponent(path.split("/")[3]).trim();
                let actor = "API Key / System";

                const body = await request.json().catch(() => ({}));
                const existing = await env.DB.prepare(`
                    SELECT * FROM gtk 
                    WHERE id = ? OR nik = ? OR nip = ? OR email = ? 
                    LIMIT 1
                `).bind(targetId, targetId, targetId, targetId.toLowerCase()).first();

                if (!existing) {
                    return errorResponse("Data GTK yang akan diperbarui tidak ditemukan.", 404, request);
                }

                let isManager = true;
                let isSelf = false;
                if (!isSecretValid) {
                    const authResult = await verifyFirebaseToken(request, env);
                    if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                    const user = authResult.user;
                    isManager = canMutateTeacher(user);

                    const userTeacherId = user.linkedTeacherId || user.profile?.linkedTeacherId || "";
                    const userNik = user.profile?.nik || "";
                    const userNip = user.profile?.nip || "";
                    const userEmail = (user.email || user.profile?.email || "").toLowerCase().trim();
                    const existingEmail = (existing.email || "").toLowerCase().trim();
                    const userName = (user.name || user.displayName || user.profile?.name || "").trim().toLowerCase();
                    const existingName = (existing.name || "").trim().toLowerCase();

                    // Toleran gelar akademik/keagamaan saat pencocokan nama
                    const cleanNameStr = (n) => n.replace(/,\s*.*$/g, '').replace(/\b(drs|dr|ir|s\.pd|m\.pd|s\.kom|s\.ag|s\.h|h)\b\.?/gi, '').replace(/[^a-z0-9]/g, '');
                    const isNameMatch = Boolean(userName && existingName && (userName === existingName || cleanNameStr(userName) === cleanNameStr(existingName)));

                    isSelf = Boolean(
                        (userEmail && existingEmail && userEmail === existingEmail) ||
                        (userTeacherId && (existing.id === userTeacherId || existing.nik === userTeacherId || existing.nip === userTeacherId)) ||
                        (targetId && userTeacherId && targetId === userTeacherId) ||
                        (userNik && existing.nik && userNik === existing.nik) ||
                        (userNip && existing.nip && userNip === existing.nip) ||
                        (userEmail && targetId.toLowerCase() === userEmail) ||
                        (user.uid && existing.id === user.uid) ||
                        isNameMatch
                    );

                    if (!isManager && !isSelf) {
                        return errorResponse("Forbidden: Anda tidak memiliki wewenang untuk memperbarui data GTK ini.", 403, request);
                    }
                    actor = user.name || user.displayName || user.email || user.uid;
                }

                // Helper One-Time Fill Policy: Boleh diisi mandiri oleh pemilik akun jika data lama masih kosong/'-'
                const canFillOrChange = (fieldKey) => {
                    if (isManager) return true;
                    if (!isSelf) return false;
                    const currentVal = existing[fieldKey];
                    return !currentVal || currentVal === '-' || String(currentVal).trim() === '';
                };

                const newNik = canFillOrChange('nik') && body.nik !== undefined ? String(body.nik).trim() : existing.nik;
                const newNip = canFillOrChange('nip') && body.nip !== undefined ? String(body.nip).trim() : existing.nip;
                const newNuptk = canFillOrChange('nuptk') && body.nuptk !== undefined ? String(body.nuptk).trim() : existing.nuptk;
                const newStatusKepegawaian = canFillOrChange('status_kepegawaian') && body.status_kepegawaian !== undefined ? String(body.status_kepegawaian).trim() : existing.status_kepegawaian;
                const newJenisPtk = canFillOrChange('jenis_ptk') && body.jenis_ptk !== undefined ? String(body.jenis_ptk).trim() : (body.jabatan !== undefined && canFillOrChange('jenis_ptk') ? String(body.jabatan).trim() : existing.jenis_ptk);
                const newTugasTambahan = canFillOrChange('tugas_tambahan') && body.tugas_tambahan !== undefined ? String(body.tugas_tambahan).trim() : (existing.tugas_tambahan || '-');

                const newName = body.name !== undefined ? String(body.name).trim() : (body.nama !== undefined ? String(body.nama).trim() : existing.name);
                const newGender = body.gender !== undefined ? String(body.gender).trim().toUpperCase() : (body.jenis_kelamin !== undefined ? String(body.jenis_kelamin).trim().toUpperCase() : existing.gender);
                const newAgama = body.agama !== undefined ? String(body.agama).trim() : (existing.agama || 'Hindu');
                const newBirthPlace = body.birth_place !== undefined ? String(body.birth_place).trim() : (body.tempat_lahir !== undefined ? String(body.tempat_lahir).trim() : existing.birth_place);
                const newBirthDate = body.birth_date !== undefined ? String(body.birth_date).trim() : (body.tanggal_lahir !== undefined ? String(body.tanggal_lahir).trim() : existing.birth_date);
                const newPhone = body.phone !== undefined ? String(body.phone).trim() : (body.no_wa !== undefined ? String(body.no_wa).trim() : (body.hp !== undefined ? String(body.hp).trim() : existing.phone));
                const newEmail = isManager && body.email !== undefined ? String(body.email).trim().toLowerCase() : (existing.email || (isSelf && userEmail ? userEmail : existing.email));

                const newAlamat = body.alamat !== undefined ? String(body.alamat).trim() : (existing.alamat || '');
                const newRt = body.rt !== undefined ? String(body.rt).trim() : (existing.rt || '');
                const newRw = body.rw !== undefined ? String(body.rw).trim() : (existing.rw || '');
                const newDusun = body.dusun !== undefined ? String(body.dusun).trim() : (existing.dusun || '');
                const newKelurahan = body.kelurahan !== undefined ? String(body.kelurahan).trim() : (existing.kelurahan || '');
                const newKecamatan = body.kecamatan !== undefined ? String(body.kecamatan).trim() : (existing.kecamatan || '');
                const newKodePos = body.kode_pos !== undefined ? String(body.kode_pos).trim() : (existing.kode_pos || '');

                // Susun Alamat komposit untuk kompatibilitas penuh modul lain
                let formattedAddress = newAlamat || (body.address !== undefined ? String(body.address).trim() : (existing.address || ''));
                const addrParts = [];
                if (newRt && newRt !== '-' && newRt !== '00' && newRw && newRw !== '-') {
                    addrParts.push(`RT ${newRt}/RW ${newRw}`);
                } else if (newRt && newRt !== '-') {
                    addrParts.push(`RT ${newRt}`);
                }
                if (newDusun && newDusun !== '-') addrParts.push(`Dusun ${newDusun}`);
                if (newKelurahan && newKelurahan !== '-') addrParts.push(`Desa/Kel. ${newKelurahan}`);
                if (newKecamatan && newKecamatan !== '-') addrParts.push(`Kec. ${newKecamatan}`);
                if (newKodePos && newKodePos !== '-') addrParts.push(newKodePos);
                if (addrParts.length > 0) {
                    formattedAddress = newAlamat && newAlamat !== '-' ? `${newAlamat}, ${addrParts.join(', ')}` : addrParts.join(', ');
                }
                const newAddress = formattedAddress;

                const newPendidikan = body.pendidikan_terakhir !== undefined ? String(body.pendidikan_terakhir).trim() : existing.pendidikan_terakhir;
                const newMapel = isManager && body.mapel !== undefined ? String(body.mapel).trim() : (body.subject !== undefined && isManager ? String(body.subject).trim() : existing.mapel);
                const newRole = isManager && body.role !== undefined ? String(body.role).trim() : existing.role;
                const newTelegram = body.telegram_chat_id !== undefined ? String(body.telegram_chat_id).trim() : (body.telegramChatId !== undefined ? String(body.telegramChatId).trim() : existing.telegram_chat_id);
                const newNotes = isManager && body.notes !== undefined ? String(body.notes).trim() : existing.notes;
                const newFoto = body.foto !== undefined ? (body.foto ? String(body.foto).trim() : null) : (body.photo_url !== undefined ? (body.photo_url ? String(body.photo_url).trim() : null) : (existing.foto || null));
                const newStatus = isManager && body.status !== undefined ? String(body.status).trim().toLowerCase() : existing.status;

                if (newTelegram && !isValidTelegramChatId(newTelegram)) {
                    return errorResponse("Format Telegram Chat ID tidak valid (harus 5-19 digit angka)", 400, request);
                }

                // Safe Key Transition: Jika ID bermigrasi ke NIK 16 digit baru
                const destinationId = (newNik && newNik !== "-" && /^\d{16}$/.test(newNik)) ? newNik : existing.id;

                // Helper deteksi toleran apakah baris di D1 merupakan orang yang sama
                const isSamePerson = (row) => {
                    if (!row) return false;
                    if (row.id === destinationId || row.id === existing.id) return true;
                    const rName = (row.name || '').trim().toLowerCase();
                    const cName = newName.trim().toLowerCase();
                    if (rName && cName && (rName === cName || cleanNameStr(rName) === cleanNameStr(cName))) return true;
                    return false;
                };

                // Validasi & Cek Keunikan NIK jika diisi/diubah
                if (newNik && newNik !== "-" && newNik !== existing.nik) {
                    if (!/^\d{16}$/.test(newNik)) {
                        return errorResponse("NIK harus terdiri dari tepat 16 digit angka.", 400, request);
                    }
                    const existNik = await env.DB.prepare("SELECT id, name FROM gtk WHERE nik = ? AND id != ? LIMIT 1").bind(newNik, existing.id).first();
                    if (existNik) {
                        if (!isSamePerson(existNik)) {
                            return errorResponse(`NIK ${newNik} sudah digunakan oleh ${existNik.name}.`, 409, request);
                        } else if (existNik.id !== destinationId) {
                            try {
                                await env.DB.prepare("DELETE FROM gtk WHERE id = ?").bind(existNik.id).run();
                            } catch (delErr) {
                                console.warn("[Worker] Gagal hapus duplikat NIK yatim:", delErr.message);
                            }
                        }
                    }
                }

                // Validasi Keunikan NIP jika diisi/diubah
                if (newNip && newNip !== "-" && newNip !== existing.nip) {
                    const existNip = await env.DB.prepare("SELECT id, name FROM gtk WHERE nip = ? AND id != ? LIMIT 1").bind(newNip, existing.id).first();
                    if (existNip) {
                        if (!isSamePerson(existNip)) {
                            return errorResponse(`NIP ${newNip} sudah digunakan oleh ${existNip.name}.`, 409, request);
                        } else if (existNip.id !== destinationId && existNip.id !== existing.id) {
                            try {
                                await env.DB.prepare("DELETE FROM gtk WHERE id = ?").bind(existNip.id).run();
                            } catch (delErr) {
                                console.warn("[Worker] Gagal hapus duplikat NIP yatim:", delErr.message);
                            }
                        }
                    }
                }

                // Validasi Keunikan NUPTK jika diisi/diubah
                if (newNuptk && newNuptk !== "-" && newNuptk !== existing.nuptk) {
                    const existNuptk = await env.DB.prepare("SELECT id, name FROM gtk WHERE nuptk = ? AND id != ? LIMIT 1").bind(newNuptk, existing.id).first();
                    if (existNuptk) {
                        if (!isSamePerson(existNuptk)) {
                            return errorResponse(`NUPTK ${newNuptk} sudah digunakan oleh ${existNuptk.name}.`, 409, request);
                        } else if (existNuptk.id !== destinationId && existNuptk.id !== existing.id) {
                            try {
                                await env.DB.prepare("DELETE FROM gtk WHERE id = ?").bind(existNuptk.id).run();
                            } catch (delErr) {
                                console.warn("[Worker] Gagal hapus duplikat NUPTK yatim:", delErr.message);
                            }
                        }
                    }
                }

                if (destinationId !== existing.id) {
                    await env.DB.prepare(`
                        INSERT INTO gtk (
                            id, nik, nip, nuptk, name, gender, birth_place, birth_date,
                            phone, email, address, jenis_ptk, status_kepegawaian,
                            pendidikan_terakhir, mapel, role, telegram_chat_id, notes, foto, status,
                            agama, tugas_tambahan, alamat, rt, rw, dusun, kelurahan, kecamatan, kode_pos,
                            updated_at
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
                        ON CONFLICT(id) DO UPDATE SET
                            nik = excluded.nik, nip = excluded.nip, nuptk = excluded.nuptk,
                            name = excluded.name, gender = excluded.gender, birth_place = excluded.birth_place,
                            birth_date = excluded.birth_date, phone = excluded.phone, email = excluded.email,
                            address = excluded.address, jenis_ptk = excluded.jenis_ptk,
                            status_kepegawaian = excluded.status_kepegawaian,
                            pendidikan_terakhir = excluded.pendidikan_terakhir, mapel = excluded.mapel,
                            role = excluded.role, telegram_chat_id = excluded.telegram_chat_id,
                            notes = excluded.notes, foto = excluded.foto, status = excluded.status,
                            agama = excluded.agama, tugas_tambahan = excluded.tugas_tambahan,
                            alamat = excluded.alamat, rt = excluded.rt, rw = excluded.rw,
                            dusun = excluded.dusun, kelurahan = excluded.kelurahan,
                            kecamatan = excluded.kecamatan, kode_pos = excluded.kode_pos,
                            updated_at = datetime('now')
                    `).bind(
                        destinationId, newNik, newNip, newNuptk, newName, newGender, newBirthPlace, newBirthDate,
                        newPhone, newEmail, newAddress, newJenisPtk, newStatusKepegawaian,
                        newPendidikan, newMapel, newRole, newTelegram, newNotes, newFoto, newStatus,
                        newAgama, newTugasTambahan, newAlamat, newRt, newRw, newDusun, newKelurahan, newKecamatan, newKodePos
                    ).run();

                    // Sinkronisasi seluruh Foreign Key & Relasi yang merujuk ke existing.id
                    try {
                        await env.DB.prepare("UPDATE teacher_assignments SET teacher_id = ? WHERE teacher_id = ?").bind(destinationId, existing.id).run();
                    } catch (fkErr1) {
                        console.warn("[Worker] Gagal sync teacher_assignments saat migrasi GTK ID:", fkErr1.message);
                    }
                    try {
                        await env.DB.prepare(`
                            DELETE FROM work_weeks
                            WHERE teacher_id = ? AND week_start_date IN (
                                SELECT week_start_date FROM work_weeks WHERE teacher_id = ?
                            )
                        `).bind(existing.id, destinationId).run();
                        await env.DB.prepare("UPDATE work_weeks SET teacher_id = ? WHERE teacher_id = ?").bind(destinationId, existing.id).run();
                    } catch (fkErr2) {
                        console.warn("[Worker] Gagal sync work_weeks saat migrasi GTK ID:", fkErr2.message);
                    }
                    try {
                        await env.DB.prepare("UPDATE weekly_templates SET teacher_id = ? WHERE teacher_id = ?").bind(destinationId, existing.id).run();
                    } catch (fkErr3) {
                        console.warn("[Worker] Gagal sync weekly_templates saat migrasi GTK ID:", fkErr3.message);
                    }
                    try {
                        await env.DB.prepare("UPDATE work_logs SET teacher_id = ? WHERE teacher_id = ?").bind(destinationId, existing.id).run();
                    } catch (fkErr4) {
                        console.warn("[Worker] Gagal sync work_logs saat migrasi GTK ID:", fkErr4.message);
                    }
                    try {
                        await env.DB.prepare("UPDATE employee_assignments SET gtk_id = ? WHERE gtk_id = ?").bind(destinationId, existing.id).run();
                        await env.DB.prepare("UPDATE employee_activities SET gtk_id = ? WHERE gtk_id = ?").bind(destinationId, existing.id).run();
                        await env.DB.prepare("UPDATE employee_absences SET gtk_id = ? WHERE gtk_id = ?").bind(destinationId, existing.id).run();
                    } catch (syncErr) {
                        console.warn("[Worker] Gagal sync employee_assignments/activities saat migrasi GTK ID:", syncErr.message);
                    }

                    // Hapus baris lama setelah relasi dipindahkan
                    await env.DB.prepare("DELETE FROM gtk WHERE id = ?").bind(existing.id).run();

                    // Bersihkan sisa duplikat NIK yatim jika ada
                    if (/^\d{16}$/.test(destinationId)) {
                        try {
                            await env.DB.prepare("DELETE FROM gtk WHERE nik = ? AND id != ?").bind(destinationId, destinationId).run();
                        } catch (cleanDupErr) {
                            console.warn("[Worker] Gagal bersihkan residual duplikat NIK:", cleanDupErr.message);
                        }
                    }
                } else {
                    await env.DB.prepare(`
                        UPDATE gtk SET
                            nik = ?, nip = ?, nuptk = ?, name = ?, gender = ?, birth_place = ?, birth_date = ?,
                            phone = ?, email = ?, address = ?, jenis_ptk = ?, status_kepegawaian = ?,
                            pendidikan_terakhir = ?, mapel = ?, role = ?, telegram_chat_id = ?,
                            notes = ?, foto = ?, status = ?,
                            agama = ?, tugas_tambahan = ?, alamat = ?, rt = ?, rw = ?, dusun = ?, kelurahan = ?, kecamatan = ?, kode_pos = ?,
                            updated_at = datetime('now')
                        WHERE id = ?
                    `).bind(
                        newNik, newNip, newNuptk, newName, newGender, newBirthPlace, newBirthDate,
                        newPhone, newEmail, newAddress, newJenisPtk, newStatusKepegawaian,
                        newPendidikan, newMapel, newRole, newTelegram, newNotes, newFoto, newStatus,
                        newAgama, newTugasTambahan, newAlamat, newRt, newRw, newDusun, newKelurahan, newKecamatan, newKodePos,
                        existing.id
                    ).run();
                }

                invalidateMasterBundleCache();
                await updateServerMetadata(env.DB, { lastUpdateTeachers: Date.now() });

                return jsonResponse({
                    success: true,
                    id: destinationId,
                    migratedFrom: destinationId !== existing.id ? existing.id : undefined,
                    message: `Data GTK ${newName} berhasil diperbarui di Cloudflare D1.`
                }, 200, request);
            }

            // 5. DELETE /api/gtk/:id & DELETE /api/teachers/:id (Hapus GTK)
            if (((path.startsWith("/api/gtk/") && path.split("/").length === 4) || (path.startsWith("/api/teachers/") && path.split("/").length === 4)) && method === "DELETE") {
                const syncKey = request.headers.get("X-Sync-Key") || request.headers.get("X-Api-Key") || request.headers.get("X-Migration-Key") || url.searchParams.get("key");
                const isSecretValid = Boolean(syncKey && env.MIGRATION_SECRET && syncKey === env.MIGRATION_SECRET);

                if (!isSecretValid) {
                    const authResult = await verifyFirebaseToken(request);
                    if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);
                    if (!canMutateTeacher(authResult.user)) {
                        return errorResponse("Forbidden: Anda tidak memiliki hak menghapus data GTK.", 403, request);
                    }
                }

                const targetId = decodeURIComponent(path.split("/")[3]).trim();
                const delRes = await env.DB.prepare(`
                    DELETE FROM gtk 
                    WHERE id = ? OR nik = ? OR nip = ?
                `).bind(targetId, targetId, targetId).run();

                invalidateMasterBundleCache();
                await updateServerMetadata(env.DB, { lastUpdateTeachers: Date.now() });

                return jsonResponse({
                    success: true,
                    deleted: delRes.meta?.changes || 0,
                    message: `Data GTK ${targetId} berhasil dihapus dari Cloudflare D1.`
                }, 200, request);
            }

            // 6. POST /api/gtk/batch & POST /api/teachers/batch (Batch Import / Upsert Massal GTK dari Excel/CSV)
            if ((path === "/api/gtk/batch" || path === "/api/gtk/bulk-sync" || path === "/api/teachers/batch" || path === "/api/teachers/bulk-sync") && method === "POST") {
                const syncKey = request.headers.get("X-Sync-Key") || request.headers.get("X-Api-Key") || request.headers.get("X-Migration-Key") || url.searchParams.get("key");
                const isSecretValid = Boolean(syncKey && env.MIGRATION_SECRET && syncKey === env.MIGRATION_SECRET);

                if (!isSecretValid) {
                    const authResult = await verifyFirebaseToken(request);
                    if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);
                    if (!canMutateTeacher(authResult.user)) {
                        return errorResponse("Forbidden: Anda tidak memiliki hak untuk mengimpor massal data GTK.", 403, request);
                    }
                }

                const body = await request.json().catch(() => ({}));
                const teachersList = Array.isArray(body.teachers) ? body.teachers : (Array.isArray(body.gtk) ? body.gtk : (Array.isArray(body) ? body : []));

                if (teachersList.length === 0) {
                    return errorResponse("Array data GTK kosong atau tidak valid.", 400, request);
                }

                const statements = [];
                for (const t of teachersList) {
                    const nik = String(t.nik || "").trim();
                    const nip = String(t.nip || "").trim();
                    const nuptk = String(t.nuptk || "").trim();
                    const name = String(t.name || t.nama || "").trim();
                    if (!name) continue;

                    const id = String(t.id || (nik && nik !== "-" ? nik : (nip && nip !== "-" ? nip : (nuptk && nuptk !== "-" ? nuptk : `gtk_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`)))).trim();

                    statements.push(
                        env.DB.prepare(`
                            INSERT INTO gtk (
                                id, nik, nip, nuptk, name, gender, birth_place, birth_date,
                                phone, email, address, jenis_ptk, status_kepegawaian,
                                pendidikan_terakhir, mapel, role, telegram_chat_id, notes, status, updated_at
                            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
                            ON CONFLICT(id) DO UPDATE SET
                                nik = excluded.nik,
                                nip = excluded.nip,
                                nuptk = excluded.nuptk,
                                name = excluded.name,
                                gender = excluded.gender,
                                birth_place = excluded.birth_place,
                                birth_date = excluded.birth_date,
                                phone = excluded.phone,
                                email = excluded.email,
                                address = excluded.address,
                                jenis_ptk = excluded.jenis_ptk,
                                status_kepegawaian = excluded.status_kepegawaian,
                                pendidikan_terakhir = excluded.pendidikan_terakhir,
                                mapel = excluded.mapel,
                                role = excluded.role,
                                telegram_chat_id = excluded.telegram_chat_id,
                                notes = excluded.notes,
                                status = excluded.status,
                                updated_at = datetime('now')
                        `).bind(
                            id,
                            nik,
                            nip,
                            nuptk,
                            name,
                            String(t.gender || t.jenis_kelamin || "L").toUpperCase(),
                            String(t.birth_place || t.tempat_lahir || "").trim(),
                            String(t.birth_date || t.tanggal_lahir || "").trim(),
                            String(t.phone || t.no_wa || t.hp || "").trim(),
                            String(t.email || "").trim().toLowerCase(),
                            String(t.address || t.alamat || "").trim(),
                            String(t.jenis_ptk || t.jabatan || "Pendidik").trim(),
                            String(t.status_kepegawaian || "Honorer").trim(),
                            String(t.pendidikan_terakhir || "").trim(),
                            String(t.mapel || (Array.isArray(t.subject) ? JSON.stringify(t.subject) : (t.subject || ""))).trim(),
                            String(t.role || "guru_mapel").trim(),
                            String(t.telegram_chat_id || t.telegramChatId || "").trim(),
                            String(t.notes || "").trim(),
                            String(t.status || "active").toLowerCase().trim() === 'inactive' ? 'inactive' : 'active'
                        )
                    );
                }

                if (statements.length > 0) {
                    const chunkSize = 50;
                    for (let i = 0; i < statements.length; i += chunkSize) {
                        await env.DB.batch(statements.slice(i, i + chunkSize));
                    }
                }

                invalidateMasterBundleCache();
                await updateServerMetadata(env.DB, { lastUpdateTeachers: Date.now() });

                return jsonResponse({
                    success: true,
                    importedCount: statements.length,
                    message: `Berhasil mengimpor/memperbarui ${statements.length} data GTK ke Cloudflare D1.`
                }, 200, request);
            }

            // =================================================================
            // 💬 ROUTE: NOTIFIKASI WHATSAPP & TELEGRAM (/api/notify)
            // =================================================================

            // Token tidak dicabut saat logout. UNIQUE(token) membuat perangkat
            // otomatis dipindahkan ke UID baru ketika akun lain login di HP sama.
            if (path === "/api/push/register" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const body = await request.json().catch(() => ({}));
                const token = String(body.token || "").trim();
                if (token.length < 80 || token.length > 4096) {
                    return errorResponse("Token FCM tidak valid", 400, request);
                }

                await ensureNotificationTables(env);

                const user = authResult.user;
                // SSOT Keamanan: Peran dan hak akses perangkat HANYA berasal dari Manajemen Users (Firestore users)
                // Dilarang keras menerima peran (role/additionalRoles) dari body request klien guna mencegah privilege escalation
                let userRole = user.role || "";
                let userAdditionalRoles = Array.isArray(user.additionalRoles) ? user.additionalRoles : [];
                let userAssignedClass = user.assignedClass || "";
                let userDisplayName = user.displayName || "";
                let userPhone = user.phone || "";
                let userTelegramChatId = user.telegramChatId || "";

                if (user.isAnonymous) {
                    userRole = "siswa";
                    userAdditionalRoles = [];
                    if (user.claims?.studentVerified) {
                        userAssignedClass = String(user.claims.studentClass || "").trim();
                        userDisplayName = String(user.claims.studentName || userDisplayName).trim();
                    }
                } else if (!userRole) {
                    try {
                        const adminUserDoc = await getFirestoreAdminDocument(env, `users/${encodeURIComponent(user.uid)}`);
                        if (adminUserDoc && adminUserDoc.fields) {
                            const adminProfile = decodeFirestoreFields(adminUserDoc.fields || {});
                            userRole = String(adminProfile.role || "").toLowerCase().trim();
                            if (Array.isArray(adminProfile.additionalRoles)) {
                                userAdditionalRoles = adminProfile.additionalRoles.map(r => String(r).toLowerCase().trim()).filter(Boolean);
                            }
                            userAssignedClass = adminProfile.assignedClass || adminProfile.class || "";
                            userDisplayName = adminProfile.name || userDisplayName;
                            userPhone = adminProfile.phone || userPhone;
                            userTelegramChatId = adminProfile.telegramChatId || userTelegramChatId;
                        }
                    } catch (eAdminDoc) {
                        console.warn("[Push/Register] Gagal baca dokumen admin users:", eAdminDoc.message);
                    }
                }

                let studentNis = String(user.claims?.studentNis || user.claims?.nis || body.studentNis || "").trim();
                const tokenId = await sha256Id(token);
                const rebindResults = await env.DB.batch([
                // Batalkan antrean pemilik sebelumnya dalam transaksi yang sama
                // dengan rebind. Logout tidak melewati jalur ini.
                env.DB.prepare(`UPDATE notification_deliveries
                    SET status = 'cancelled', claim_id = '', lease_until = 0,
                        error = 'Perangkat berpindah akun', processed_at = datetime('now')
                    WHERE token_id = ? AND status IN ('pending', 'processing')
                      AND EXISTS (SELECT 1 FROM fcm_tokens WHERE id = ? AND user_id <> ?)
                `).bind(tokenId, tokenId, user.uid),
                env.DB.prepare(`
                    INSERT INTO fcm_tokens (
                        id, user_id, token, role, additional_roles, assigned_class,
                        display_name, phone, telegram_chat_id, device_type, user_agent, student_nis
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    ON CONFLICT(token) DO UPDATE SET
                        user_id = excluded.user_id,
                        role = excluded.role,
                        additional_roles = excluded.additional_roles,
                        assigned_class = excluded.assigned_class,
                        display_name = excluded.display_name,
                        phone = excluded.phone,
                        telegram_chat_id = excluded.telegram_chat_id,
                        device_type = excluded.device_type,
                        user_agent = excluded.user_agent,
                        student_nis = excluded.student_nis,
                        updated_at = datetime('now')
                `).bind(
                    tokenId,
                    user.uid,
                    token,
                    userRole,
                    JSON.stringify(userAdditionalRoles),
                    userAssignedClass,
                    userDisplayName,
                    userPhone,
                    userTelegramChatId,
                    String(body.deviceType || "unknown").slice(0, 30),
                    String(body.userAgent || "").slice(0, 500),
                    studentNis
                )]);
                if (rebindResults[0].meta?.changes) await refreshNotificationJobStatuses(env);

                return jsonResponse({ success: true, reboundToUser: user.uid }, 200, request);
            }

            if (path === "/api/push/send" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);
                if (!isStaffOrTeacher(authResult.user)) return errorResponse("Forbidden: role tidak berhak mengirim notifikasi", 403, request);

                await ensureNotificationTables(env);

                const body = await request.json().catch(() => ({}));
                const title = String(body.title || "").trim().slice(0, 120);
                const messageBody = String(body.body || body.message || "").trim().slice(0, 1000);
                const targetType = String(body.targetType || "user").toLowerCase();
                const targetValue = String(body.targetValue || body.userId || body.role || body.className || "").trim();
                const safeUrl = String(body.url || "./dashboard.html").trim();
                const notificationUrl = (safeUrl.startsWith("./") || safeUrl.startsWith("/")) ? safeUrl.slice(0, 500) : "./dashboard.html";

                if (!title || !messageBody) return errorResponse("Judul dan isi notifikasi wajib diisi", 400, request);
                if (!["user", "role", "class", "all"].includes(targetType)) return errorResponse("Target notifikasi tidak valid", 400, request);
                if (targetType !== "all" && !targetValue) return errorResponse("Nilai target wajib diisi", 400, request);
                if (targetType === "all" && !userHasRole(authResult.user, "super_admin")) {
                    return errorResponse("Forbidden: broadcast seluruh perangkat hanya untuk super_admin", 403, request);
                }

                const job = await createNotificationJob(env, authResult.user.uid, {
                    title,
                    body: messageBody,
                    url: notificationUrl,
                    targetType,
                    targetValue
                });
                if (job.targetCount) ctx.waitUntil(processPendingNotifications(env, job.jobId));
                let telegramQueued = false;
                if (body.sendTelegram === true && targetType === "user" && env.TELEGRAM_BOT_TOKEN) {
                    const contact = await getAdminUserContact(env, targetValue);
                    if (contact.telegramChatId) {
                        telegramQueued = true;
                        ctx.waitUntil(executeTelegramFetch(
                            env.TELEGRAM_BOT_TOKEN,
                            contact.telegramChatId,
                            `<b>${escapeTelegramHtml(title)}</b>\n\n${escapeTelegramHtml(messageBody)}`
                        ));
                    }
                }
                return jsonResponse({ success: true, queued: job.targetCount > 0, telegramQueued, ...job }, 202, request);
            }

            // POST /api/feedback/notify (Mengirim notifikasi multi-channel masukan/laporan baru ke akun target dan pimpinan)
            if (path === "/api/feedback/notify" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                await ensureNotificationTables(env);

                const body = await request.json().catch(() => ({}));
                const rawTitle = String(body.title || "").trim();
                const rawMessage = String(body.message || "").trim();
                const targetRecipient = Array.isArray(body.targetRecipient)
                    ? body.targetRecipient
                    : String(body.targetRecipient || "super_admin").trim().toLowerCase();
                const category = String(body.category || "Umum").trim().slice(0, 80);
                const senderName = String(body.senderName || "Anonim").trim().slice(0, 100);

                if (!rawTitle || !rawMessage) {
                    return errorResponse("Judul dan isi masukan wajib diisi", 400, request);
                }

                // Rate limiting sederhana anti-spam: max 5 notifikasi per 10 menit per UID/IP
                const clientIp = request.headers.get("CF-Connecting-IP") || "0.0.0.0";
                const rateLimitKey = `feedback_notif:${authResult.user.uid || clientIp}`;
                const nowMs = Date.now();
                const rateLimitRow = await env.DB.prepare(
                    "SELECT failure_count, window_started_at FROM auth_rate_limits WHERE id = ?"
                ).bind(rateLimitKey).first().catch(() => null);

                if (rateLimitRow && (nowMs - Number(rateLimitRow.window_started_at || 0) < 10 * 60 * 1000) && Number(rateLimitRow.failure_count || 0) >= 5) {
                    return errorResponse("Terlalu banyak pengiriman laporan. Silakan tunggu beberapa menit.", 429, request);
                }

                const sameWindow = rateLimitRow && (nowMs - Number(rateLimitRow.window_started_at || 0) < 10 * 60 * 1000);
                await env.DB.prepare(`
                    INSERT INTO auth_rate_limits (id, failure_count, window_started_at)
                    VALUES (?, ?, ?)
                    ON CONFLICT(id) DO UPDATE SET
                        failure_count = ?,
                        window_started_at = ?
                `).bind(
                    rateLimitKey,
                    sameWindow ? Number(rateLimitRow.failure_count || 0) + 1 : 1,
                    sameWindow ? Number(rateLimitRow.window_started_at) : nowMs,
                    sameWindow ? Number(rateLimitRow.failure_count || 0) + 1 : 1,
                    sameWindow ? Number(rateLimitRow.window_started_at) : nowMs
                ).run().catch(() => {});

                // Resolusi target penerima (peran utama + tembusan super_admin & kepala_sekolah)
                const targetRoles = resolveFeedbackTargetRoles(targetRecipient);
                const targetLabel = getFeedbackTargetLabel(targetRecipient);

                const notifTitle = `Masukan Baru: ${rawTitle.slice(0, 100)}`;
                const notifBody = `${senderName} [${targetLabel}]: ${rawMessage.slice(0, 120)}`;

                const job = await createNotificationJob(env, authResult.user.uid, {
                    title: notifTitle,
                    body: notifBody,
                    url: "./masukan.html",
                    targetType: "role",
                    targetValue: targetRoles.join(",")
                });

                if (job.targetCount) {
                    ctx.waitUntil(processPendingNotifications(env, job.jobId));
                }

                // Teruskan ke Telegram Bot jika akun target memiliki Telegram Chat ID
                let telegramSentCount = 0;
                if (env.TELEGRAM_BOT_TOKEN) {
                    try {
                        const filter = notificationTargetFilter("role", targetRoles.join(","));
                        const [tgTokens, tgGtk] = await env.DB.batch([
                            env.DB.prepare(`
                                SELECT DISTINCT telegram_chat_id 
                                FROM fcm_tokens t 
                                WHERE telegram_chat_id IS NOT NULL AND telegram_chat_id <> '' AND ${filter.sql}
                            `).bind(...filter.args),
                            env.DB.prepare(`
                                SELECT DISTINCT telegram_chat_id 
                                FROM gtk 
                                WHERE telegram_chat_id IS NOT NULL AND telegram_chat_id <> '' 
                                  AND role IN (SELECT value FROM json_each(?))
                            `).bind(JSON.stringify(targetRoles))
                        ]);

                        const chatIds = new Set();
                        for (const row of (tgTokens.results || [])) {
                            const cid = String(row.telegram_chat_id || "").trim();
                            if (isValidTelegramChatId(cid)) chatIds.add(cid);
                        }
                        for (const row of (tgGtk.results || [])) {
                            const cid = String(row.telegram_chat_id || "").trim();
                            if (isValidTelegramChatId(cid)) chatIds.add(cid);
                        }

                        if (chatIds.size > 0) {
                            const tgMsg = `📢 <b>MASUKAN / LAPORAN BARU</b>\n\n` +
                                `<b>Tujuan:</b> ${escapeTelegramHtml(targetLabel)}\n` +
                                `<b>Kategori:</b> ${escapeTelegramHtml(category)}\n` +
                                `<b>Pengirim:</b> ${escapeTelegramHtml(senderName)}\n` +
                                `<b>Judul:</b> ${escapeTelegramHtml(rawTitle.slice(0, 120))}\n\n` +
                                `<i>"${escapeTelegramHtml(rawMessage.slice(0, 300))}"</i>\n\n` +
                                `🔗 <b>Buka di SIMAS:</b> <a href="${getAppBaseUrl(env)}/masukan.html">masukan.html</a>`;

                            for (const cid of chatIds) {
                                ctx.waitUntil(executeTelegramFetch(env.TELEGRAM_BOT_TOKEN, cid, tgMsg));
                                telegramSentCount++;
                            }
                        }
                    } catch (tgErr) {
                        console.warn("[Worker] Telegram forward masukan dilewati:", tgErr.message);
                    }
                }

                return jsonResponse({
                    success: true,
                    queued: job.targetCount > 0,
                    targetCount: job.targetCount,
                    targetRoles,
                    targetLabel,
                    telegramSentCount
                }, 200, request);
            }

            // POST /api/feedback/reply (Membalas tiket masukan di Supabase oleh pemilik, pimpinan, atau seluruh GTK internal)
            if (path === "/api/feedback/reply" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const body = await request.json().catch(() => ({}));
                const feedbackId = String(body.id || "").trim();
                const replyMessage = String(body.message || "").trim().slice(0, 3000);
                const senderName = String(body.senderName || authResult.user.displayName || "GTK").trim().slice(0, 100);
                const senderRole = String(body.senderRole || authResult.user.role || "guru_mapel").trim();

                if (!feedbackId || !replyMessage) {
                    return errorResponse("ID tiket dan isi balasan wajib diisi", 400, request);
                }

                const baseUrl = (env.SUPABASE_URL || DEFAULT_SUPABASE_URL).replace(/\/$/, '');
                const serviceKey = String(env.SUPABASE_SERVICE_ROLE_KEY || "").trim() || (env.SUPABASE_ANON_KEY || DEFAULT_SUPABASE_ANON_KEY).trim();

                // 1. Ambil data masukan eksis dari Supabase
                const getRes = await fetch(`${baseUrl}/rest/v1/masukkan_saran?id=eq.${encodeURIComponent(feedbackId)}&select=*`, {
                    method: 'GET',
                    headers: {
                        'apikey': serviceKey,
                        'Authorization': `Bearer ${serviceKey}`
                    }
                });

                if (!getRes.ok) {
                    const getErrText = await getRes.text().catch(() => '');
                    return errorResponse(`Gagal membaca masukan: HTTP ${getRes.status} ${getErrText.slice(0, 200)}`, 500, request);
                }

                const existingRows = await getRes.json().catch(() => []);
                const feedbackItem = Array.isArray(existingRows) ? existingRows[0] : null;
                if (!feedbackItem) {
                    return errorResponse("Masukan tidak ditemukan", 404, request);
                }

                const uid = authResult.user.uid;
                const isSender = feedbackItem.sender_uid === uid;
                const isLeadership = ['super_admin', 'kepala_sekolah', 'kesiswaan', 'wakasek_kurikulum', 'kepala_lab', 'humas', 'sarpras'].some(r => userHasRole(authResult.user, r));
                const isGtk = isSchoolStaff(authResult.user);

                if (!isSender && !isLeadership && !isGtk) {
                    return errorResponse("Forbidden: Hanya GTK atau pembuat masukan yang berhak membalas.", 403, request);
                }

                const senderType = isLeadership ? "leadership" : (isSender ? "reporter" : "gtk");
                const existingReplies = Array.isArray(feedbackItem.replies) ? [...feedbackItem.replies] : [];

                if (existingReplies.length === 0 && feedbackItem.response_text) {
                    existingReplies.push({
                        id: crypto.randomUUID(),
                        sender_uid: feedbackItem.response_by_uid || "leadership",
                        sender_name: feedbackItem.response_by_name || "Pimpinan",
                        sender_role: "leadership",
                        sender_type: "leadership",
                        message: feedbackItem.response_text,
                        created_at: feedbackItem.responded_at || feedbackItem.updated_at || feedbackItem.created_at
                    });
                }

                const senderPhoto = typeof body.senderPhoto === "string" ? body.senderPhoto.slice(0, 500).trim() : null;
                const newReply = {
                    id: crypto.randomUUID(),
                    sender_uid: uid,
                    sender_name: senderName,
                    sender_role: senderRole,
                    sender_type: senderType,
                    sender_photo: senderPhoto,
                    message: replyMessage,
                    created_at: new Date().toISOString()
                };
                const updatedReplies = [...existingReplies, newReply];

                const updatePayload = {
                    replies: updatedReplies,
                    updated_at: new Date().toISOString()
                };

                if (isSender) {
                    if (["selesai", "ditolak", "butuh_info"].includes(feedbackItem.status)) {
                        updatePayload.status = "proses";
                    }
                } else if (isLeadership) {
                    if (body.status && ["baru", "proses", "direncanakan", "butuh_info", "selesai", "ditolak"].includes(body.status)) {
                        updatePayload.status = body.status;
                    }
                    updatePayload.response_text = replyMessage;
                    updatePayload.response_by_uid = uid;
                    updatePayload.response_by_name = senderName;
                    updatePayload.responded_at = new Date().toISOString();
                } else if (isGtk) {
                    if (feedbackItem.status === "baru") {
                        updatePayload.status = "proses";
                    }
                }

                const patchRes = await fetch(`${baseUrl}/rest/v1/masukkan_saran?id=eq.${encodeURIComponent(feedbackId)}`, {
                    method: 'PATCH',
                    headers: {
                        'apikey': serviceKey,
                        'Authorization': `Bearer ${serviceKey}`,
                        'Content-Type': 'application/json',
                        'Prefer': 'return=representation'
                    },
                    body: JSON.stringify(updatePayload)
                });

                if (!patchRes.ok) {
                    const errText = await patchRes.text().catch(() => '');
                    return errorResponse(`Gagal memperbarui database: HTTP ${patchRes.status} ${errText.slice(0, 200)}`, 500, request);
                }

                const patchedData = await patchRes.json().catch(() => null);

                return jsonResponse({
                    success: true,
                    data: patchedData?.[0] || updatePayload
                }, 200, request);
            }

            // PUT /api/feedback/reply atau POST /api/feedback/reply/edit (Edit balasan thread oleh pembuat balasan atau super_admin)
            if ((path === "/api/feedback/reply/edit" && method === "POST") || (path === "/api/feedback/reply" && (method === "PUT" || method === "PATCH"))) {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const body = await request.json().catch(() => ({}));
                const feedbackId = String(body.id || body.feedbackId || "").trim();
                const replyId = String(body.replyId || body.reply_id || "").trim();
                const newMessage = String(body.message || "").trim().slice(0, 3000);

                if (!feedbackId || !replyId || !newMessage) {
                    return errorResponse("ID tiket, ID balasan, dan pesan baru wajib diisi", 400, request);
                }

                const baseUrl = (env.SUPABASE_URL || DEFAULT_SUPABASE_URL).replace(/\/$/, '');
                const serviceKey = String(env.SUPABASE_SERVICE_ROLE_KEY || "").trim() || (env.SUPABASE_ANON_KEY || DEFAULT_SUPABASE_ANON_KEY).trim();

                const getRes = await fetch(`${baseUrl}/rest/v1/masukkan_saran?id=eq.${encodeURIComponent(feedbackId)}&select=*`, {
                    method: 'GET',
                    headers: {
                        'apikey': serviceKey,
                        'Authorization': `Bearer ${serviceKey}`
                    }
                });

                if (!getRes.ok) {
                    const getErrText = await getRes.text().catch(() => '');
                    return errorResponse(`Gagal membaca masukan: HTTP ${getRes.status} ${getErrText.slice(0, 200)}`, 500, request);
                }

                const existingRows = await getRes.json().catch(() => []);
                const feedbackItem = Array.isArray(existingRows) ? existingRows[0] : null;
                if (!feedbackItem) {
                    return errorResponse("Masukan tidak ditemukan", 404, request);
                }

                const existingReplies = Array.isArray(feedbackItem.replies) ? [...feedbackItem.replies] : [];
                const targetIndex = existingReplies.findIndex(r => r && r.id === replyId);
                if (targetIndex === -1) {
                    return errorResponse("Balasan tidak ditemukan", 404, request);
                }

                const targetReply = existingReplies[targetIndex];
                const uid = authResult.user.uid;
                const isOwner = targetReply.sender_uid === uid;
                const isSuperAdmin = userHasRole(authResult.user, 'super_admin');

                if (!isOwner && !isSuperAdmin) {
                    return errorResponse("Forbidden: Anda hanya berhak mengedit balasan milik sendiri.", 403, request);
                }

                existingReplies[targetIndex] = {
                    ...targetReply,
                    message: newMessage,
                    edited_at: new Date().toISOString()
                };

                const updatePayload = {
                    replies: existingReplies,
                    updated_at: new Date().toISOString()
                };

                if (feedbackItem.response_by_uid === uid && feedbackItem.response_text === targetReply.message) {
                    updatePayload.response_text = newMessage;
                }

                const patchRes = await fetch(`${baseUrl}/rest/v1/masukkan_saran?id=eq.${encodeURIComponent(feedbackId)}`, {
                    method: 'PATCH',
                    headers: {
                        'apikey': serviceKey,
                        'Authorization': `Bearer ${serviceKey}`,
                        'Content-Type': 'application/json',
                        'Prefer': 'return=representation'
                    },
                    body: JSON.stringify(updatePayload)
                });

                if (!patchRes.ok) {
                    const errText = await patchRes.text().catch(() => '');
                    return errorResponse(`Gagal memperbarui database: HTTP ${patchRes.status} ${errText.slice(0, 200)}`, 500, request);
                }

                const patchedData = await patchRes.json().catch(() => null);

                return jsonResponse({
                    success: true,
                    data: patchedData?.[0] || updatePayload
                }, 200, request);
            }

            // PUT /api/feedback atau POST /api/feedback/edit (Edit masukan utama oleh pemilik masukan atau super_admin)
            if ((path === "/api/feedback/edit" && method === "POST") || (path === "/api/feedback" && (method === "PUT" || method === "PATCH"))) {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const body = await request.json().catch(() => ({}));
                const feedbackId = String(body.id || body.feedbackId || "").trim();
                const title = typeof body.title === "string" ? body.title.trim().slice(0, 150) : "";
                const message = typeof body.message === "string" ? body.message.trim().slice(0, 2500) : "";
                const category = typeof body.category === "string" ? body.category.trim().slice(0, 80) : "";

                if (!feedbackId || !title || !message) {
                    return errorResponse("ID tiket, judul, dan isi masukan wajib diisi", 400, request);
                }

                const baseUrl = (env.SUPABASE_URL || DEFAULT_SUPABASE_URL).replace(/\/$/, '');
                const serviceKey = String(env.SUPABASE_SERVICE_ROLE_KEY || "").trim() || (env.SUPABASE_ANON_KEY || DEFAULT_SUPABASE_ANON_KEY).trim();

                const getRes = await fetch(`${baseUrl}/rest/v1/masukkan_saran?id=eq.${encodeURIComponent(feedbackId)}&select=*`, {
                    method: 'GET',
                    headers: {
                        'apikey': serviceKey,
                        'Authorization': `Bearer ${serviceKey}`
                    }
                });

                if (!getRes.ok) {
                    const getErrText = await getRes.text().catch(() => '');
                    return errorResponse(`Gagal membaca masukan: HTTP ${getRes.status} ${getErrText.slice(0, 200)}`, 500, request);
                }

                const existingRows = await getRes.json().catch(() => []);
                const feedbackItem = Array.isArray(existingRows) ? existingRows[0] : null;
                if (!feedbackItem) {
                    return errorResponse("Masukan tidak ditemukan", 404, request);
                }

                const uid = authResult.user.uid;
                const userEmail = (authResult.user.email || "").toLowerCase().trim();
                const feedbackEmail = (feedbackItem.sender_email || "").toLowerCase().trim();
                const isOwner = feedbackItem.sender_uid === uid || (Boolean(userEmail && feedbackEmail && userEmail === feedbackEmail));
                const isSuperAdmin = userHasRole(authResult.user, 'super_admin');

                if (!isOwner && !isSuperAdmin) {
                    return errorResponse("Forbidden: Anda hanya berhak mengedit masukan milik sendiri.", 403, request);
                }

                // Pengeditan mandiri hanya diizinkan untuk tiket berstatus aktif (baru, proses, direncanakan, butuh_info)
                const currentStatus = String(feedbackItem.status || 'baru').toLowerCase();
                if (!isSuperAdmin && (currentStatus === 'selesai' || currentStatus === 'ditolak')) {
                    return errorResponse(`Masukan yang telah berstatus '${currentStatus}' sudah final dan tidak dapat diedit kembali.`, 400, request);
                }

                const updatePayload = {
                    title,
                    message,
                    updated_at: new Date().toISOString()
                };
                if (category) {
                    updatePayload.category = category;
                }

                const patchRes = await fetch(`${baseUrl}/rest/v1/masukkan_saran?id=eq.${encodeURIComponent(feedbackId)}`, {
                    method: 'PATCH',
                    headers: {
                        'apikey': serviceKey,
                        'Authorization': `Bearer ${serviceKey}`,
                        'Content-Type': 'application/json',
                        'Prefer': 'return=representation'
                    },
                    body: JSON.stringify(updatePayload)
                });

                if (!patchRes.ok) {
                    const errText = await patchRes.text().catch(() => '');
                    return errorResponse(`Gagal memperbarui database: HTTP ${patchRes.status} ${errText.slice(0, 200)}`, 500, request);
                }

                const patchedData = await patchRes.json().catch(() => null);

                return jsonResponse({
                    success: true,
                    data: patchedData?.[0] || updatePayload
                }, 200, request);
            }

            // GET /api/notifications/inbox (Mengambil daftar notifikasi personal pengguna untuk Notification Center)
            if (path === "/api/notifications/inbox" && method === "GET") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                try {
                    await ensureNotificationTables(env);

                    const audience = notificationInboxAudience(authResult.user);
                    const recipients = notificationRecipientIds(audience);
                    const recipientsJson = JSON.stringify(recipients.length > 0 ? recipients : ["__no_recipient__"]);
                    // Hemat rows read D1: kandidat diambil lewat indeks (lihat notificationCandidateJobsSql),
                    // tidak lagi memindai notifikasi pribadi milik semua pengguna.
                    const candidates = notificationCandidateJobsSql(audience);
                    const visibleJobsSql = `
                        WITH candidate_jobs AS (${candidates.sql}
                        )
                        SELECT j.id AS id, j.title, j.body, j.url, j.target_type, j.created_at,
                            COALESCE((
                                SELECT MAX(d.is_read) FROM notification_deliveries d
                                WHERE d.job_id = j.id AND d.recipient_uid IN (SELECT value FROM json_each(?))
                            ), 0) AS is_read
                        FROM notification_jobs j
                        WHERE j.id IN (SELECT id FROM candidate_jobs)
                          AND j.created_at >= datetime('now', ?)
                        ORDER BY j.created_at DESC
                        LIMIT 40`;
                    const visibleJobsArgs = [...candidates.args, recipientsJson, NOTIFICATION_INBOX_WINDOW];

                    const inboxRes = await env.DB.prepare(visibleJobsSql).bind(...visibleJobsArgs).all();

                    const notifications = (inboxRes.results || []).map(row => ({
                        id: row.id,
                        title: row.title,
                        body: row.body,
                        url: row.url || "./dashboard.html",
                        targetType: row.target_type,
                        createdAt: row.created_at,
                        isRead: Boolean(row.is_read)
                    }));
                    // Menghemat kuota D1: unreadCount dihitung langsung dari entri aktif tanpa scan ulang 60 hari
                    const unreadCount = notifications.filter(n => !n.isRead).length;

                    return jsonResponse({ success: true, notifications, unreadCount }, 200, request);
                } catch (errInbox) {
                    console.error("[Notification Inbox Worker Error]:", errInbox);
                    return jsonResponse({ success: true, notifications: [], unreadCount: 0 }, 200, request);
                }
            }


            // POST /api/notifications/mark-read (Menandai notifikasi sebagai sudah dibaca)
            if (path === "/api/notifications/mark-read" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                await ensureNotificationTables(env);

                const audience = notificationInboxAudience(authResult.user);
                const userUid = audience.uid;
                const studentNis = audience.studentNis;
                const body = await request.json().catch(() => ({}));
                const targetId = String(body.id || "").trim();
                const markAll = body.markAll === true || targetId === "all";

                let markedCount = 0;
                if (markAll) {
                    const res = await env.DB.prepare(`
                        UPDATE notification_deliveries
                        SET is_read = 1, read_at = datetime('now')
                        WHERE (recipient_uid = ? OR (recipient_uid = ? AND ? <> '')) AND is_read = 0
                    `).bind(userUid, studentNis, studentNis).run();
                    markedCount += Number(res.meta?.changes || 0);

                    // Job role/all/class/agenda_staff tidak punya baris delivery bila
                    // perangkat pembaca belum terdaftar push. Tanpa baris tanda baca,
                    // badge lonceng kembali muncul setelah halaman dimuat ulang.
                    // Himpunan job sama persis dengan yang tampil di lonceng (notificationCandidateJobsSql).
                    const recipient = notificationRecipientSql("d", audience);
                    const candidates = notificationCandidateJobsSql(audience);
                    const inserted = await env.DB.prepare(`
                        INSERT OR IGNORE INTO notification_deliveries (id, job_id, token_id, token, recipient_uid, status, is_read, read_at)
                        SELECT j.id || ':inapp:' || ?, j.id, 'inapp', '', ?, 'inapp', 1, datetime('now')
                        FROM notification_jobs j
                        WHERE j.id IN (${candidates.sql})
                          AND NOT EXISTS (SELECT 1 FROM notification_deliveries d WHERE d.job_id = j.id AND ${recipient.sql})
                    `).bind(userUid, userUid, ...candidates.args, ...recipient.args).run();
                    markedCount += Number(inserted.meta?.changes || 0);
                } else if (targetId) {
                    const res = await env.DB.prepare(`
                        UPDATE notification_deliveries
                        SET is_read = 1, read_at = datetime('now')
                        WHERE (recipient_uid = ? OR (recipient_uid = ? AND ? <> '')) AND (job_id = ? OR id = ?)
                    `).bind(userUid, studentNis, studentNis, targetId, targetId).run();
                    markedCount = Number(res.meta?.changes || 0);

                    // Notifikasi broadcast tanpa baris delivery milik pembaca: buat baris tanda baca.
                    // Jalur UPDATE lama tetap menerima ID job maupun delivery milik akun ini.
                    // INSERT baru hanya untuk job yang benar-benar terlihat di inbox pembaca,
                    // agar ID job akun lain tidak bisa disisipkan sebagai notifikasi pribadi.
                    if (!markedCount) {
                        const candidates = notificationCandidateJobsSql(audience);
                        const inserted = await env.DB.prepare(`
                            INSERT OR IGNORE INTO notification_deliveries (id, job_id, token_id, token, recipient_uid, status, is_read, read_at)
                            SELECT j.id || ':inapp:' || ?, j.id, 'inapp', '', ?, 'inapp', 1, datetime('now')
                            FROM notification_jobs j WHERE j.id = ? AND j.id IN (${candidates.sql})
                        `).bind(userUid, userUid, targetId, ...candidates.args).run();
                        markedCount = Number(inserted.meta?.changes || 0);
                        if (!markedCount) return errorResponse("Notifikasi tidak tersedia untuk akun ini", 404, request);
                    }
                } else {
                    return errorResponse("Parameter id atau markAll wajib diisi", 400, request);
                }

                return jsonResponse({ success: true, markedCount }, 200, request);
            }

            // POST /api/sukaduka/announce-event (Siaran Pengumuman Acara / Kabar Sosial Suka Duka)
            if (path === "/api/sukaduka/announce-event" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const allowedRoles = ["super_admin", "kepala_sekolah", "admin_sukaduka", "guru", "guru_mapel", "staff"];
                const userRole = authResult.user.role;
                const additionalRoles = authResult.user.additionalRoles || [];
                const hasAccess = allowedRoles.includes(userRole) || additionalRoles.some(r => allowedRoles.includes(r));
                if (!hasAccess) {
                    return errorResponse("Hanya admin suka duka, GTK, atau pimpinan yang berhak menyiarkan pengumuman suka duka", 403, request);
                }

                const body = await request.json().catch(() => null);
                if (!body || !body.title || !body.body) {
                    return errorResponse("Judul dan isi pengumuman wajib diisi", 400, request);
                }

                await ensureNotificationTables(env);

                const title = String(body.title).trim();
                const messageBody = String(body.body).trim();
                const url = body.url ? String(body.url).trim() : "./sukaduka/suka-duka.html";

                const job = await createNotificationJob(env, authResult.user.uid, {
                    title: title || "📢 Pengumuman Suka Duka SMANTARA",
                    body: messageBody,
                    url: url,
                    targetType: "role",
                    targetValue: "guru,staff,admin_sukaduka"
                });

                if (job.targetCount) {
                    ctx.waitUntil(processPendingNotifications(env, job.jobId));
                }

                return jsonResponse({
                    success: true,
                    message: "Pengumuman Suka Duka berhasil disiarkan",
                    jobId: job.jobId,
                    targetCount: job.targetCount
                }, 200, request);
            }

            if (path === "/api/agenda/notification-queue" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);
                if (!isManager(authResult.user)) return errorResponse("Forbidden", 403, request);

                await ensureNotificationTables(env);

                const body = await request.json().catch(() => ({}));
                const eventId = String(body.eventId || "").trim();
                const title = String(body.title || "Agenda Sekolah").trim().slice(0, 180);
                const changeType = String(body.changeType || "updated").trim().slice(0, 30);
                if (!eventId) return errorResponse("eventId wajib diisi", 400, request);
                await env.DB.prepare(`
                    INSERT INTO agenda_notification_queue (id, event_id, title, change_type, created_by)
                    VALUES (?, ?, ?, ?, ?)
                `).bind(crypto.randomUUID(), eventId, title, changeType, authResult.user.uid).run();
                return jsonResponse({ success: true, queued: true }, 202, request);
            }

            if (path === "/api/notify/attendance-reminder" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);
                if (!isStaffOrTeacher(authResult.user)) return errorResponse("Forbidden", 403, request);

                await ensureNotificationTables(env);

                const body = await request.json().catch(() => ({}));
                const className = String(body.className || body.class || "").trim().slice(0, 60);
                const date = String(body.date || "").trim().slice(0, 10);
                if (!className || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return errorResponse("Kelas dan tanggal wajib valid", 400, request);

                const dedupeKey = `attendance:${className}:${date}`;
                const recent = await env.DB.prepare(`
                    SELECT created_at FROM notification_channel_log
                    WHERE channel = 'attendance' AND dedupe_key = ? AND status = 'sent'
                      AND datetime(created_at) >= datetime('now', '-30 minutes')
                    ORDER BY created_at DESC LIMIT 1
                `).bind(dedupeKey).first();
                if (recent) return jsonResponse({ success: true, duplicate: true, skipped: true, lastSentAt: recent.created_at }, 200, request);

                // Resolusi Wali Kelas secara SSOT (bukan broadcast ke seluruh rombel kelas!)
                const homeroom = await findHomeroomTeacherForClass(env, className);
                const waliUid = homeroom?.uid || "";
                let phone = cleanPhoneNumber(homeroom?.phone || "");
                let telegramChatId = String(homeroom?.telegramChatId || "").trim();
                const waliName = homeroom?.name || `Wali Kelas ${className}`;

                // Resolusi telegramChatId secara komprehensif jika di homeroom kosong:
                // 1) Cari di tabel gtk (kolom telegram_chat_id / telegram_id)
                if (!telegramChatId && env.DB) {
                    try {
                        const gtkRow = await env.DB.prepare(`
                            SELECT COALESCE(NULLIF(telegram_chat_id, ''), '') AS tg_id 
                            FROM gtk 
                            WHERE (id = ? OR nik = ? OR id = ?) 
                              AND telegram_chat_id IS NOT NULL AND telegram_chat_id <> '' 
                            LIMIT 1
                        `).bind(homeroom?.linkedTeacherId || waliUid, homeroom?.linkedTeacherId || waliUid, waliUid).first().catch(() => null);
                        if (gtkRow?.tg_id) {
                            telegramChatId = String(gtkRow.tg_id).trim();
                        }
                    } catch (_) {
                        try {
                            const gtkFallback = await env.DB.prepare(`
                                SELECT COALESCE(NULLIF(telegram_id, ''), '') AS tg_id 
                                FROM gtk 
                                WHERE (id = ? OR nik = ? OR id = ?) 
                                  AND telegram_id IS NOT NULL AND telegram_id <> '' 
                                LIMIT 1
                            `).bind(homeroom?.linkedTeacherId || waliUid, homeroom?.linkedTeacherId || waliUid, waliUid).first().catch(() => null);
                            if (gtkFallback?.tg_id) {
                                telegramChatId = String(gtkFallback.tg_id).trim();
                            }
                        } catch (_) {}
                    }
                }
                // 2) Cari di tabel fcm_tokens berdasarkan user_id = waliUid
                if (!telegramChatId && waliUid && env.DB) {
                    try {
                        const tokenRow = await env.DB.prepare(`
                            SELECT telegram_chat_id FROM fcm_tokens 
                            WHERE user_id = ? AND telegram_chat_id IS NOT NULL AND telegram_chat_id <> '' 
                            ORDER BY updated_at DESC LIMIT 1
                        `).bind(waliUid).first().catch(() => null);
                        if (tokenRow?.telegram_chat_id) {
                            telegramChatId = String(tokenRow.telegram_chat_id).trim();
                        }
                    } catch (_) {}
                }

                // Resolusi nomor telepon wali kelas secara komprehensif jika di homeroom kosong
                if (!phone && env.DB) {
                    try {
                        const gtkPhoneRow = await env.DB.prepare(`
                            SELECT phone FROM gtk WHERE (id = ? OR nik = ? OR id = ?) AND phone IS NOT NULL AND phone <> '' LIMIT 1
                        `).bind(homeroom?.linkedTeacherId || waliUid, homeroom?.linkedTeacherId || waliUid, waliUid).first().catch(() => null);
                        if (gtkPhoneRow?.phone) {
                            phone = cleanPhoneNumber(gtkPhoneRow.phone);
                        }
                    } catch (_) {}
                    if (!phone && waliUid) {
                        try {
                            const fcmPhoneRow = await env.DB.prepare(`
                                SELECT phone FROM fcm_tokens WHERE user_id = ? AND phone IS NOT NULL AND phone <> '' ORDER BY updated_at DESC LIMIT 1
                            `).bind(waliUid).first().catch(() => null);
                            if (fcmPhoneRow?.phone) {
                                phone = cleanPhoneNumber(fcmPhoneRow.phone);
                            }
                        } catch (_) {}
                    }
                }

                const message = `Pengingat presensi kelas ${className} tanggal ${date}. Mohon segera melengkapi data presensi di SIMAS.`;

                // Push Notification:
                // a. Dikirim ke Wali Kelas (targetType: 'user', targetValue: waliUid)
                // b. Otomatis dikirim juga ke Admin Kelas siswa rombel bersangkutan (targetType: 'class_admin', targetValue: className) — bukan siswa individu
                const pushJobs = [];
                let totalPushTargets = 0;

                if (waliUid) {
                    try {
                        const waliJob = await createNotificationJob(env, authResult.user.uid, {
                            title: "⏰ Pengingat Presensi",
                            body: message,
                            url: "./presensi.html",
                            targetType: "user",
                            targetValue: waliUid
                        });
                        if (waliJob.targetCount > 0) {
                            pushJobs.push(waliJob.jobId);
                            totalPushTargets += waliJob.targetCount;
                        }
                    } catch (eWaliJob) {
                        console.warn("[Attendance Reminder] Gagal membuat push job wali kelas:", eWaliJob.message);
                    }
                }

                try {
                    const classJob = await createNotificationJob(env, authResult.user.uid, {
                        title: "⏰ Pengingat Presensi",
                        body: message,
                        url: "./presensi.html",
                        targetType: "class_admin",
                        targetValue: className
                    });
                    if (classJob.targetCount > 0) {
                        pushJobs.push(classJob.jobId);
                        totalPushTargets += classJob.targetCount;
                    }
                } catch (eClassJob) {
                    console.warn("[Attendance Reminder] Gagal membuat push job admin kelas:", eClassJob.message);
                }

                if (pushJobs.length > 0) {
                    const drainPush = async () => {
                        for (const jid of pushJobs) {
                            await processPendingNotifications(env, jid).catch(err => console.warn("[Attendance Reminder] Error drain push job:", err.message));
                        }
                    };
                    if (ctx && typeof ctx.waitUntil === 'function') {
                        ctx.waitUntil(drainPush());
                    } else {
                        await drainPush();
                    }
                }

                const channelResults = [];

                // 1. Channel Telegram Bot Otomatis (Prioritas Utama, Berjalan Cepat & Andal)
                if (telegramChatId && env.TELEGRAM_BOT_TOKEN) {
                    try {
                        const tgRes = await executeTelegramFetch(
                            env.TELEGRAM_BOT_TOKEN,
                            telegramChatId,
                            `⏰ <b>[PENGINGAT PRESENSI KELAS]</b>\n\n` +
                            `Halo Bapak/Ibu <b>${escapeTelegramHtml(waliName)}</b>,\n\n` +
                            `Presensi siswa kelas <b>${escapeTelegramHtml(className)}</b> untuk tanggal <b>${escapeTelegramHtml(date)}</b> belum lengkap.\n` +
                            `Mohon kesediaannya untuk segera melengkapi data presensi di aplikasi SIMAS CERDAS.\n\n` +
                            `> <i>SIMAS - CERDAS</i>`
                        );
                        channelResults.push({ channel: "telegram", ...tgRes });
                    } catch (tgErr) {
                        console.warn("[Attendance Reminder] Gagal kirim Telegram:", tgErr.message);
                        channelResults.push({ channel: "telegram", status: false, error: tgErr.message });
                    }
                }

                // 2. Channel WhatsApp (Terisolasi Penuh - Kegagalan/Timeout WA Tidak Mengganggu Push & Telegram)
                if (phone && (env.FONNTE_TOKEN || env.WA_TOKEN)) {
                    try {
                        const waRes = await executeWaProviderFetch(
                            env.WA_PROVIDER || "fonnte",
                            env.FONNTE_TOKEN || env.WA_TOKEN,
                            phone,
                            message,
                            env.WAPANELS_APP_KEY || ""
                        );
                        channelResults.push({ channel: "wa", ...waRes });
                    } catch (waErr) {
                        console.warn("[Attendance Reminder] WA provider fetch error bypassed:", waErr.message);
                        channelResults.push({ channel: "wa", status: false, error: waErr.message });
                    }
                }

                await env.DB.prepare(`
                    INSERT INTO notification_channel_log (id, channel, dedupe_key, target, status, created_by)
                    VALUES (?, 'attendance', ?, ?, 'sent', ?)
                `).bind(crypto.randomUUID(), dedupeKey, className, authResult.user.uid).run();

                const telegramResult = channelResults.find(r => r.channel === "telegram");
                const waResult = channelResults.find(r => r.channel === "wa");

                return jsonResponse({
                    success: true,
                    queued: (totalPushTargets > 0) || channelResults.some(r => r.status === true),
                    waliFound: Boolean(waliUid),
                    waliName,
                    jobId: pushJobs[0] || "",
                    targetCount: totalPushTargets,
                    skipped: totalPushTargets === 0 && channelResults.length === 0,
                    push: {
                        success: totalPushTargets > 0,
                        targetCount: totalPushTargets,
                        jobs: pushJobs
                    },
                    telegram: {
                        success: telegramResult ? Boolean(telegramResult.status) : false,
                        chatId: telegramChatId ? "configured" : "not_found",
                        detail: telegramResult || null
                    },
                    wa: {
                        success: waResult ? Boolean(waResult.status) : false,
                        phone: phone ? "configured" : "not_found",
                        detail: waResult || null
                    },
                    externalChannels: channelResults
                }, 202, request);
            }

            // POST /api/notify/jurnal-verification (Notifikasi Pengesahan & Pembatalan Jurnal Mingguan ke Wali Kelas via Web Push & Telegram)
            if (path === "/api/notify/jurnal-verification" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);
                if (!isStaffOrTeacher(authResult.user)) return errorResponse("Forbidden: role tidak berhak mengirim notifikasi pengesahan", 403, request);

                await ensureNotificationTables(env);

                const body = await request.json().catch(() => ({}));
                const className = String(body.className || body.class || "").trim().slice(0, 60);
                const startDateIso = String(body.startDateIso || "").trim().slice(0, 10);
                const endDateIso = String(body.endDateIso || "").trim().slice(0, 10);
                const weekLabel = String(body.weekLabel || "").trim().slice(0, 120);
                const status = String(body.status || "verified").trim().toLowerCase();
                const verifiedByName = String(body.verifiedByName || authResult.user.name || "Kepala Sekolah").trim().slice(0, 120);
                const catatan = String(body.catatan || "").trim().slice(0, 500);

                if (!className || !/^\d{4}-\d{2}-\d{2}$/.test(startDateIso)) {
                    return errorResponse("Kelas dan tanggal awal pekan (startDateIso) wajib valid", 400, request);
                }

                const action = status === "cancelled" ? "cancelled" : "verified";
                const dedupeKey = `jurnal_verif:${action}:${className}:${startDateIso}`;
                const recent = await env.DB.prepare(`
                    SELECT created_at FROM notification_channel_log
                    WHERE channel = 'jurnal_verification' AND dedupe_key = ? AND status = 'sent'
                      AND datetime(created_at) >= datetime('now', '-10 minutes')
                    ORDER BY created_at DESC LIMIT 1
                `).bind(dedupeKey).first().catch(() => null);

                if (recent) {
                    return jsonResponse({ success: true, duplicate: true, skipped: true, lastSentAt: recent.created_at }, 200, request);
                }

                // Resolusi Wali Kelas secara SSOT
                const homeroom = await findHomeroomTeacherForClass(env, className);
                const waliUid = homeroom?.uid || "";
                let telegramChatId = String(homeroom?.telegramChatId || "").trim();
                const waliName = homeroom?.name || `Wali Kelas ${className}`;

                // Resolusi cadangan telegramChatId jika di profil homeroom belum ada
                if (!telegramChatId && env.DB) {
                    try {
                        const gtkRow = await env.DB.prepare(`
                            SELECT COALESCE(NULLIF(telegram_chat_id, ''), '') AS tg_id 
                            FROM gtk 
                            WHERE (id = ? OR nik = ? OR id = ?) 
                              AND telegram_chat_id IS NOT NULL AND telegram_chat_id <> '' 
                            LIMIT 1
                        `).bind(homeroom?.linkedTeacherId || waliUid, homeroom?.linkedTeacherId || waliUid, waliUid).first().catch(() => null);
                        if (gtkRow?.tg_id) {
                            telegramChatId = String(gtkRow.tg_id).trim();
                        }
                    } catch (_) {}
                }
                if (!telegramChatId && waliUid && env.DB) {
                    try {
                        const tokenRow = await env.DB.prepare(`
                            SELECT telegram_chat_id FROM fcm_tokens 
                            WHERE user_id = ? AND telegram_chat_id IS NOT NULL AND telegram_chat_id <> '' 
                            ORDER BY updated_at DESC LIMIT 1
                        `).bind(waliUid).first().catch(() => null);
                        if (tokenRow?.telegram_chat_id) {
                            telegramChatId = String(tokenRow.telegram_chat_id).trim();
                        }
                    } catch (_) {}
                }

                const pushJobs = [];
                let totalPushTargets = 0;
                const safeUrl = `./wali-kelas.html?tab=jurnal&class=${encodeURIComponent(className)}`;

                // Format Konten Notifikasi
                const isVerified = action === "verified";
                const pushTitle = isVerified ? "✅ Jurnal Mingguan Disahkan" : "⚠️ Pengesahan Jurnal Dibatalkan";
                const pushBody = isVerified
                    ? `Jurnal mengajar kelas ${className} untuk ${weekLabel || 'pekan ini'} telah disahkan resmi oleh Kepala Sekolah (${verifiedByName}).${catatan ? ` Catatan: "${catatan}"` : ''}`
                    : `Pengesahan jurnal mengajar kelas ${className} untuk ${weekLabel || 'pekan ini'} telah dibatalkan oleh Kepala Sekolah (${verifiedByName}).`;

                // 1. Web Push Notification ke Wali Kelas
                if (waliUid) {
                    try {
                        const waliJob = await createNotificationJob(env, authResult.user.uid, {
                            title: pushTitle,
                            body: pushBody,
                            url: safeUrl,
                            targetType: "user",
                            targetValue: waliUid
                        });
                        if (waliJob.targetCount > 0) {
                            pushJobs.push(waliJob.jobId);
                            totalPushTargets += waliJob.targetCount;
                        }
                    } catch (eWaliJob) {
                        console.warn("[Jurnal Verification] Gagal membuat push job wali kelas:", eWaliJob.message);
                    }
                }

                if (pushJobs.length > 0) {
                    const drainPush = async () => {
                        for (const jid of pushJobs) {
                            await processPendingNotifications(env, jid).catch(err => console.warn("[Jurnal Verification] Error drain push job:", err.message));
                        }
                    };
                    if (ctx && typeof ctx.waitUntil === 'function') {
                        ctx.waitUntil(drainPush());
                    } else {
                        await drainPush();
                    }
                }

                const channelResults = [];

                // 2. Telegram Bot Notification (Format Ringkas)
                if (telegramChatId && env.TELEGRAM_BOT_TOKEN) {
                    try {
                        let tgMessage = "";
                        if (isVerified) {
                            tgMessage = `✅ <b>[JURNAL MINGGUAN DISAHKAN]</b>\n\n` +
                                `Halo Bapak/Ibu Wali Kelas <b>${escapeTelegramHtml(className)}</b>,\n\n` +
                                `Jurnal mengajar kelas <b>${escapeTelegramHtml(className)}</b> untuk periode <b>${escapeTelegramHtml(weekLabel || `${startDateIso} s.d. ${endDateIso}`)}</b> telah diverifikasi dan disahkan secara resmi oleh Kepala Sekolah (<b>${escapeTelegramHtml(verifiedByName)}</b>).\n` +
                                (catatan ? `\n📝 <b>Catatan Arahan:</b>\n<i>"${escapeTelegramHtml(catatan)}"</i>\n` : `\n`) +
                                `Silakan periksa rekapitulasi jurnal mengajar pada aplikasi SIMAS CERDAS.\n\n` +
                                `> <i>SIMAS - CERDAS</i>`;
                        } else {
                            tgMessage = `⚠️ <b>[PENGESAHAN JURNAL DIBATALKAN]</b>\n\n` +
                                `Halo Bapak/Ibu Wali Kelas <b>${escapeTelegramHtml(className)}</b>,\n\n` +
                                `Pengesahan jurnal mengajar kelas <b>${escapeTelegramHtml(className)}</b> untuk periode <b>${escapeTelegramHtml(weekLabel || `${startDateIso} s.d. ${endDateIso}`)}</b> telah dibatalkan / ditarik oleh Kepala Sekolah (<b>${escapeTelegramHtml(verifiedByName)}</b>).\n\n` +
                                `Silakan periksa dan koordinasikan kembali jurnal mengajar pada aplikasi SIMAS CERDAS.\n\n` +
                                `> <i>SIMAS - CERDAS</i>`;
                        }

                        const tgRes = await executeTelegramFetch(
                            env.TELEGRAM_BOT_TOKEN,
                            telegramChatId,
                            tgMessage
                        );
                        channelResults.push({ channel: "telegram", ...tgRes });
                    } catch (tgErr) {
                        console.warn("[Jurnal Verification] Gagal kirim Telegram:", tgErr.message);
                        channelResults.push({ channel: "telegram", status: false, error: tgErr.message });
                    }
                }

                await env.DB.prepare(`
                    INSERT INTO notification_channel_log (id, channel, dedupe_key, target, status, created_by)
                    VALUES (?, 'jurnal_verification', ?, ?, 'sent', ?)
                `).bind(crypto.randomUUID(), dedupeKey, className, authResult.user.uid).run().catch(() => null);

                const telegramResult = channelResults.find(r => r.channel === "telegram");

                return jsonResponse({
                    success: true,
                    action,
                    waliFound: Boolean(waliUid),
                    waliName,
                    jobId: pushJobs[0] || "",
                    targetCount: totalPushTargets,
                    push: {
                        success: totalPushTargets > 0,
                        targetCount: totalPushTargets
                    },
                    telegram: {
                        success: telegramResult ? Boolean(telegramResult.status) : false,
                        chatId: telegramChatId ? "configured" : "not_found",
                        detail: telegramResult || null
                    }
                }, 200, request);
            }

            // POST /api/notify/consecutive-alpha-alert (Alert Realtime Siswa Alpha >= 2 Hari Berturut-turut ke Wali Kelas & Guru BK)
            if (path === "/api/notify/consecutive-alpha-alert" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                await ensureNotificationTables(env);

                const body = await request.json().catch(() => ({}));
                const className = String(body.className || body.class || "").trim().slice(0, 60);
                const dateStr = String(body.dateStr || body.date || "").trim().slice(0, 10);
                const alphaStudents = Array.isArray(body.alphaStudents) ? body.alphaStudents : [];

                if (!className || !/^\d{4}-\d{2}-\d{2}$/.test(dateStr) || alphaStudents.length === 0) {
                    return jsonResponse({ success: true, processed: 0, message: "Tidak ada siswa alpha yang perlu divalidasi" }, 200, request);
                }

                // 1. Cari tanggal aktif sekolah sebelumnya (mundur 1 - 7 hari, melewati hari libur / akhir pekan)
                let prevActiveDate = "";
                const curDate = new Date(`${dateStr}T00:00:00Z`);
                for (let i = 1; i <= 7; i++) {
                    const checkDate = new Date(curDate);
                    checkDate.setUTCDate(curDate.getUTCDate() - i);
                    const checkDateStr = checkDate.toISOString().slice(0, 10);
                    const isHoliday = await isSchoolHolidayOrWeekend(env.DB, checkDateStr);
                    if (!isHoliday) {
                        prevActiveDate = checkDateStr;
                        break;
                    }
                }

                if (!prevActiveDate) {
                    return jsonResponse({ success: true, processed: 0, reason: "tidak_ditemukan_hari_aktif_sebelumnya" }, 200, request);
                }

                // 2. Ambil presensi siswa pada prevActiveDate dari Supabase siswa_presensi via service role
                let prevAttendanceRows = [];
                try {
                    prevAttendanceRows = await fetchSupabaseRowsAsService(
                        env,
                        "siswa_presensi",
                        `tanggal=eq.${prevActiveDate}&status=eq.A&select=student_nis,status`
                    );
                } catch (eSb) {
                    console.warn("[ConsecutiveAlphaAlert] Gagal query siswa_presensi:", eSb.message);
                }

                const prevAlphaNisSet = new Set((prevAttendanceRows || []).map(r => String(r.student_nis).trim()));

                // 3. Filter siswa yang Alpha berturut-turut (Alpha hari ini DAN Alpha pada hari aktif sebelumnya)
                const consecutiveAlphaStudents = alphaStudents.filter(s => s && s.nis && prevAlphaNisSet.has(String(s.nis).trim()));

                if (consecutiveAlphaStudents.length === 0) {
                    return jsonResponse({ success: true, processed: 0, checkedCount: alphaStudents.length, message: "Tidak ada siswa yang alpha >= 2 hari beruntun" }, 200, request);
                }

                // 4. Resolusi Wali Kelas
                const homeroom = await findHomeroomTeacherForClass(env, className);
                const waliUid = homeroom?.uid || "";
                let waliTelegramChatId = String(homeroom?.telegramChatId || "").trim();
                if (!waliTelegramChatId && env.DB) {
                    const gtkRow = await env.DB.prepare(
                        "SELECT telegram_chat_id FROM gtk WHERE (id = ? OR nik = ? OR id = ?) AND telegram_chat_id IS NOT NULL AND telegram_chat_id != '' LIMIT 1"
                    ).bind(homeroom?.linkedTeacherId || waliUid, homeroom?.linkedTeacherId || waliUid, waliUid).first().catch(() => null);
                    if (gtkRow?.telegram_chat_id) waliTelegramChatId = String(gtkRow.telegram_chat_id).trim();
                }

                // 5. Resolusi Guru BK Telegram (jika ada yang terhubung)
                let bkTelegramChatIds = [];
                if (env.DB && env.TELEGRAM_BOT_TOKEN) {
                    try {
                        const bkJobs = await env.DB.prepare(`
                            SELECT DISTINCT telegram_chat_id FROM gtk 
                            WHERE (role = 'guru_bk' OR jenis_ptk LIKE '%BK%') 
                              AND telegram_chat_id IS NOT NULL AND telegram_chat_id <> ''
                        `).all().catch(() => ({ results: [] }));
                        bkTelegramChatIds = (bkJobs?.results || []).map(r => String(r.telegram_chat_id).trim()).filter(Boolean);
                    } catch (_) {}
                }

                let alertsDispatched = 0;
                for (const student of consecutiveAlphaStudents) {
                    const studentNis = String(student.nis).trim();
                    const studentName = String(student.name || studentNis).trim();

                    // Kunci idempotensi harian per siswa: hanya 1 alert per hari per siswa agar tidak spam
                    const lockKey = `alpha_consec_${studentNis}`;
                    const canAlert = await acquireDailyCronJobLock(env.DB, lockKey, dateStr);
                    if (!canAlert) continue;

                    const alertTitle = "⚠️ Peringatan Siswa Alpha Beruntun";
                    const alertBody = `Siswa ${studentName} (${studentNis}) di kelas ${className} tercatat ALPHA selama 2 hari aktif berturut-turut (terakhir ${dateStr}). Mohon segera dilakukan konfirmasi dan penanganan.`;

                    // Web Push ke Wali Kelas
                    if (waliUid) {
                        try {
                            const waliJob = await createNotificationJob(env, authResult.user.uid, {
                                title: alertTitle,
                                body: alertBody,
                                url: "./walikelas.html",
                                targetType: "user",
                                targetValue: waliUid
                            });
                            if (waliJob?.targetCount && ctx?.waitUntil) {
                                ctx.waitUntil(processPendingNotifications(env, waliJob.jobId));
                            }
                        } catch (eWaliPush) {
                            console.warn(`[ConsecutiveAlphaAlert] Gagal push wali kelas ${waliUid}:`, eWaliPush.message);
                        }
                    }

                    // Telegram Bot ke Wali Kelas
                    if (waliTelegramChatId && env.TELEGRAM_BOT_TOKEN && ctx?.waitUntil) {
                        const tgMsg = `⚠️ <b>[ALERT SISWA ALPHA BERTURUT-TURUT]</b>\n\n` +
                            `Halo Bapak/Ibu Wali Kelas <b>${escapeTelegramHtml(className)}</b>,\n\n` +
                            `Siswa binaan Anda:\n` +
                            `• <b>Nama:</b> ${escapeTelegramHtml(studentName)}\n` +
                            `• <b>NIS:</b> ${escapeTelegramHtml(studentNis)}\n` +
                            `• <b>Status:</b> ALPHA ≥ 2 hari aktif berturut-turut (terakhir: <b>${escapeTelegramHtml(dateStr)}</b>)\n\n` +
                            `Mohon segera menindaklanjuti dan mengonfirmasi kondisi siswa tersebut.\n` +
                            `👉 <a href="${getAppBaseUrl(env)}/walikelas.html">Buka Modul Wali Kelas</a>`;
                        ctx.waitUntil(executeTelegramFetch(env.TELEGRAM_BOT_TOKEN, waliTelegramChatId, tgMsg));
                    }

                    // Web Push ke Guru BK (Broadcast ke role guru_bk)
                    try {
                        const bkJob = await createNotificationJob(env, authResult.user.uid, {
                            title: "⚠️ Alert BK: Siswa Alpha Beruntun",
                            body: `Siswa ${studentName} (${className}) tercatat ALPHA >= 2 hari aktif berturut-turut. Perlu pendampingan / pemanggilan BK.`,
                            url: "./bk.html",
                            targetType: "role",
                            targetValue: "guru_bk"
                        });
                        if (bkJob?.targetCount && ctx?.waitUntil) {
                            ctx.waitUntil(processPendingNotifications(env, bkJob.jobId));
                        }
                    } catch (eBkPush) {
                        console.warn("[ConsecutiveAlphaAlert] Gagal push role guru_bk:", eBkPush.message);
                    }

                    // Telegram Bot ke Guru BK
                    if (bkTelegramChatIds.length > 0 && env.TELEGRAM_BOT_TOKEN && ctx?.waitUntil) {
                        const tgBkMsg = `⚠️ <b>[PERHATIAN BK: SISWA ALPHA BERUNTUN]</b>\n\n` +
                            `Siswa berikut memerlukan perhatian BK:\n` +
                            `• <b>Nama:</b> ${escapeTelegramHtml(studentName)}\n` +
                            `• <b>Kelas:</b> ${escapeTelegramHtml(className)}\n` +
                            `• <b>Status:</b> ALPHA ≥ 2 hari berturut-turut (terakhir: <b>${escapeTelegramHtml(dateStr)}</b>)\n\n` +
                            `👉 <a href="${getAppBaseUrl(env)}/bk.html">Buka Modul BK</a>`;
                        for (const chatId of bkTelegramChatIds) {
                            ctx.waitUntil(executeTelegramFetch(env.TELEGRAM_BOT_TOKEN, chatId, tgBkMsg));
                        }
                    }

                    alertsDispatched++;
                }

                return jsonResponse({
                    success: true,
                    prevActiveDate,
                    consecutiveCount: consecutiveAlphaStudents.length,
                    alertsDispatched
                }, 200, request);
            }

            // POST /api/notify/wa (Kirim Notifikasi WhatsApp via Gateway Fonnte / Wapanels)
            if (path === "/api/notify/wa" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }
                if (!isStaffOrTeacher(authResult.user)) {
                    return errorResponse("Forbidden: role tidak berhak mengirim WhatsApp", 403, request);
                }

                const body = await request.json();
                const { phone, message, provider, token, appKey, targetName } = body;
                const dedupeKey = String(body.dedupeKey || "").trim().slice(0, 200);
                const cooldownHours = Math.max(0, Math.min(24 * 31, Number(body.cooldownHours || 0)));

                if (!phone || !message) {
                    return errorResponse("Nomor tujuan (phone) dan pesan (message) wajib diisi", 400, request);
                }

                const cleanPhone = cleanPhoneNumber(phone);
                if (!cleanPhone || cleanPhone.length < 9) {
                    return errorResponse("Nomor telepon tujuan tidak valid", 400, request);
                }

                if (dedupeKey && cooldownHours > 0) {
                    const recent = await env.DB.prepare(`
                        SELECT created_at FROM notification_channel_log
                        WHERE channel = 'wa' AND dedupe_key = ? AND status = 'sent'
                          AND datetime(created_at) >= datetime('now', ?)
                        ORDER BY created_at DESC LIMIT 1
                    `).bind(dedupeKey, `-${cooldownHours} hours`).first();
                    if (recent) {
                        return jsonResponse({ success: true, duplicate: true, skipped: true, lastSentAt: recent.created_at }, 200, request);
                    }
                }

                // Secret server selalu diprioritaskan. Token payload hanya boleh
                // dipakai super_admin untuk tes konfigurasi sebelum secret dipasang.
                const finalProvider = provider || env.WA_PROVIDER || "fonnte";
                const mayTestCredential = userHasRole(authResult.user, "super_admin");
                const finalToken = env.FONNTE_TOKEN || env.WA_TOKEN || (mayTestCredential ? token : "") || "";
                const finalAppKey = env.WAPANELS_APP_KEY || (mayTestCredential ? appKey : "") || "";

                if (!finalToken) {
                    return errorResponse("Token API WhatsApp belum dikonfigurasi di server maupun payload", 500, request);
                }

                const result = await executeWaProviderFetch(finalProvider, finalToken, cleanPhone, message, finalAppKey);

                if (result.status) {
                    if (dedupeKey) {
                        await env.DB.prepare(`
                            INSERT INTO notification_channel_log (id, channel, dedupe_key, target, status, created_by)
                            VALUES (?, 'wa', ?, ?, 'sent', ?)
                        `).bind(crypto.randomUUID(), dedupeKey, cleanPhone, authResult.user.uid).run();
                    }
                    return jsonResponse({
                        success: true,
                        message: `Notifikasi WhatsApp berhasil dikirim ke ${targetName || cleanPhone}`,
                        provider: finalProvider,
                        detail: result.raw
                    }, 200, request);
                } else {
                    return jsonResponse({
                        success: false,
                        error: result.error || "Gagal mengirim pesan WhatsApp",
                        detail: result.raw
                    }, 502, request);
                }
            }

            // POST /api/notify/telegram (Kirim Notifikasi Telegram Bot)
            if (path === "/api/notify/telegram" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }
                if (!isStaffOrTeacher(authResult.user)) {
                    return errorResponse("Forbidden: role tidak berhak mengirim Telegram", 403, request);
                }

                const body = await request.json();
                const { chatId, message, botToken: paramBotToken, parseMode } = body;

                const cleanChatId = String(chatId || "").trim();
                if (!isValidTelegramChatId(cleanChatId)) {
                    return errorResponse("Format Telegram Chat ID tidak valid (harus 5-19 digit angka)", 400, request);
                }

                if (!message) {
                    return errorResponse("Pesan (message) wajib diisi", 400, request);
                }

                const botToken = env.TELEGRAM_BOT_TOKEN || (userHasRole(authResult.user, "super_admin") ? paramBotToken : "") || "";
                if (!botToken) {
                    return errorResponse("Telegram Bot Token belum dikonfigurasi di server", 500, request);
                }

                const sendUrl = `https://api.telegram.org/bot${botToken}/sendMessage`;
                const controller = new AbortController();
                const timeoutId = setTimeout(() => controller.abort(), 8000);

                const tgRes = await fetch(sendUrl, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                        chat_id: cleanChatId,
                        text: message,
                        parse_mode: parseMode || "HTML",
                        disable_web_page_preview: true
                    }),
                    signal: controller.signal
                });
                clearTimeout(timeoutId);

                const tgJson = await tgRes.json().catch(() => ({ ok: false }));
                if (tgRes.ok && tgJson.ok) {
                    return jsonResponse({ success: true, message: "Notifikasi Telegram berhasil dikirim", result: tgJson.result }, 200, request);
                } else {
                    return jsonResponse({ success: false, error: tgJson.description || "Gagal mengirim pesan Telegram" }, 502, request);
                }
            }

            // =================================================================
            // 🤖 ROUTE: TELEGRAM BOT WEBHOOK & VERIFY
            // =================================================================

            // POST /api/telegram/webhook (Webhook Bot Telegram @smagesa_bot)
            if (path === "/api/telegram/webhook") {
                if (method === "GET") {
                    return jsonResponse({ status: "ok", service: "SIMAS Telegram Bot Webhook Active" }, 200, request);
                }

                if (method === "POST") {
                    const webhookSecret = (env.TELEGRAM_WEBHOOK_SECRET || "").trim();
                    if (!webhookSecret) {
                        return errorResponse("Telegram webhook secret belum dikonfigurasi", 503, request);
                    }
                    const headerSecret = request.headers.get("x-telegram-bot-api-secret-token") || "";
                    if (headerSecret !== webhookSecret) {
                        return errorResponse("Forbidden: Invalid webhook secret token", 403, request);
                    }

                    const update = await request.json().catch(() => null);
                    if (!update || (!update.message && !update.edited_message)) {
                        return jsonResponse({ ok: true }, 200, request);
                    }

                    const msg = update.message || update.edited_message;
                    const chatId = msg.chat?.id;
                    const rawFirstName = msg.from?.first_name || "Pengguna";
                    const sanitizedFirstName = escapeTelegramHtml(rawFirstName);
                    const botToken = (env.TELEGRAM_BOT_TOKEN || "").trim();

                    if (chatId && botToken) {
                        const replyText =
                            `👋 <b>Halo, ${sanitizedFirstName}!</b>\n\n` +
                            `🆔 <b>Telegram Chat ID Anda adalah:</b>\n` +
                            `<code>${chatId}</code> <i>(Sentuh/ketuk angka di atas untuk menyalin)</i>\n\n` +
                            `📌 <i>Tempelkan angka Chat ID ini pada kolom <b>Telegram Chat ID</b> di menu Edit Profil SIMAS CERDAS Anda untuk mulai menerima notifikasi personal.</i>\n\n` +
                            `> <i>SIMAS - CERDAS</i>`;

                        const sendUrl = `https://api.telegram.org/bot${botToken}/sendMessage`;
                        await fetch(sendUrl, {
                            method: "POST",
                            headers: { "Content-Type": "application/json" },
                            signal: AbortSignal.timeout(8000),
                            body: JSON.stringify({
                                chat_id: chatId,
                                text: replyText,
                                parse_mode: "HTML",
                                disable_web_page_preview: true
                            })
                        }).catch(() => {});
                    }

                    return jsonResponse({ ok: true }, 200, request);
                }
            }

            // Mendaftarkan webhook tanpa mengekspos bot token ke browser.
            if (path === "/api/telegram/configure-webhook" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);
                if (!userHasRole(authResult.user, "super_admin")) return errorResponse("Forbidden", 403, request);

                const botToken = String(env.TELEGRAM_BOT_TOKEN || "").trim();
                const webhookSecret = String(env.TELEGRAM_WEBHOOK_SECRET || "").trim();
                if (!botToken || !webhookSecret) {
                    return errorResponse("TELEGRAM_BOT_TOKEN dan TELEGRAM_WEBHOOK_SECRET wajib dipasang sebagai Worker secret", 503, request);
                }
                const workerBaseUrl = String(env.PUBLIC_WORKER_URL || new URL(request.url).origin).replace(/\/+$/, "");
                const telegramResponse = await fetch(`https://api.telegram.org/bot${botToken}/setWebhook`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                        url: `${workerBaseUrl}/api/telegram/webhook`,
                        secret_token: webhookSecret,
                        allowed_updates: ["message", "edited_message"],
                        drop_pending_updates: false
                    })
                });
                const result = await telegramResponse.json().catch(() => ({}));
                if (!telegramResponse.ok || !result.ok) {
                    return errorResponse(result.description || "Gagal mendaftarkan webhook Telegram", 502, request);
                }
                return jsonResponse({ success: true, message: "Webhook Telegram aktif di Cloudflare Worker" }, 200, request);
            }

            // POST /api/telegram/verify (Verifikasi Telegram Chat ID Pengguna)
            if (path === "/api/telegram/verify" && method === "POST") {
                const authResult = await verifyFirebaseToken(request, env);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                const body = await request.json();
                const cleanChatId = String(body.chatId || "").trim();
                const rawDisplayName = String(body.userName || authResult.user.claims?.name || "Pengguna").trim();

                if (!isValidTelegramChatId(cleanChatId)) {
                    return errorResponse("Format Chat ID harus berupa angka (contoh: 198160734)", 400, request);
                }

                const botToken = (env.TELEGRAM_BOT_TOKEN || (userHasRole(authResult.user, "super_admin") ? body.botToken : "") || "").trim();
                if (!botToken) {
                    return errorResponse("Bot Token Telegram belum diatur di server", 500, request);
                }

                const sanitizedDisplayName = escapeTelegramHtml(rawDisplayName);
                const verifyMsg =
                    `🧪 <b>[VERIFIKASI NOTIFIKASI SIMAS]</b>\n\n` +
                    `Halo, <b>${sanitizedDisplayName}</b>!\n` +
                    `Telegram Chat ID Anda (<code>${cleanChatId}</code>) <b>100% VALID</b> dan berhasil terhubung.\n\n` +
                    `Mulai sekarang, notifikasi personal SIMAS CERDAS akan dikirimkan ke akun Telegram ini.\n\n` +
                    `> <i>SIMAS - CERDAS</i>`;

                const sendUrl = `https://api.telegram.org/bot${botToken}/sendMessage`;
                const controller = new AbortController();
                const timeoutId = setTimeout(() => controller.abort(), 8000);

                let tgRes = null;
                try {
                    tgRes = await fetch(sendUrl, {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({
                            chat_id: cleanChatId,
                            text: verifyMsg,
                            parse_mode: "HTML",
                            disable_web_page_preview: true
                        }),
                        signal: controller.signal
                    });
                } catch (fetchErr) {
                    clearTimeout(timeoutId);
                    return jsonResponse({
                        valid: false,
                        message: "Koneksi ke Server Telegram Bot timeout atau terputus. Pastikan koneksi internet stabil dan coba kembali."
                    }, 200, request);
                }
                clearTimeout(timeoutId);

                const tgJson = await tgRes.json().catch(() => ({ ok: false }));
                if (tgRes.ok && tgJson.ok) {
                    return jsonResponse({ valid: true, message: "Chat ID Valid!" }, 200, request);
                } else {
                    let errDesc = tgJson.description || "Chat ID tidak ditemukan.";
                    if (errDesc.includes("chat not found")) {
                        errDesc = "Chat ID tidak ditemukan! Pastikan Anda sudah membuka bot Telegram sekolah (@simas_demo_bot) dan mengklik START terlebih dahulu.";
                    } else if (errDesc.includes("bot was blocked")) {
                        errDesc = "Bot Telegram diblokir! Buka blokir bot @simas_demo_bot di aplikasi Telegram Anda terlebih dahulu.";
                    }
                    return jsonResponse({ valid: false, message: errDesc }, 200, request);
                }
            }

            // =================================================================
            // 🎓 ROUTE: HOMEROOM CONTACT & TIME CAPSULE
            // =================================================================

            // POST or GET /api/students/homeroom-contact
            if (path === "/api/students/homeroom-contact" && (method === "POST" || method === "GET")) {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                let studentClass = "";
                if (authResult.user.isAnonymous && authResult.user.claims?.studentVerified !== true) {
                    return errorResponse("Identitas siswa belum terverifikasi", 403, request);
                }
                if (authResult.user.claims?.studentClass) {
                    studentClass = authResult.user.claims.studentClass;
                } else if (authResult.user.claims?.studentNis) {
                    const row = await env.DB.prepare("SELECT class FROM students WHERE nis = ? LIMIT 1")
                        .bind(authResult.user.claims.studentNis).first();
                    if (row && row.class) studentClass = row.class;
                }

                if (!studentClass && !authResult.user.isAnonymous && isStaffOrTeacher(authResult.user) && method === "POST") {
                    const body = await request.json().catch(() => ({}));
                    if (body.class) studentClass = String(body.class).trim();
                }

                if (!studentClass) return errorResponse("Kelas siswa tidak tersedia", 404, request);

                let homeroom = {};
                const userDocuments = await runFirestoreAdminQuery(env, {
                    from: [{ collectionId: "users" }],
                    where: {
                        fieldFilter: {
                            field: { fieldPath: "assignedClass" },
                            op: "EQUAL",
                            value: { stringValue: studentClass }
                        }
                    },
                    limit: 20
                });
                const homeroomDocument = userDocuments.find(document => {
                    const userData = decodeFirestoreFields(document.fields || {});
                    return userData.role === "wali_kelas" || (Array.isArray(userData.additionalRoles) && userData.additionalRoles.includes("wali_kelas"));
                });
                if (homeroomDocument) {
                    const uid = decodeURIComponent(homeroomDocument.name.split("/").pop());
                    homeroom = await getAdminUserContact(env, uid);
                }

                return jsonResponse({
                    success: true,
                    class: studentClass,
                    name: homeroom.name || "Wali Kelas",
                    phone: homeroom.phone || "",
                    nip: homeroom.nip || "",
                    foto: homeroom.foto || ""
                }, 200, request);
            }

            // POST /api/timecapsule/submit
            if (path === "/api/timecapsule/submit" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);
                const body = await request.json().catch(() => ({}));
                const year = String(body.year || "").trim();
                const makassarYear = new Intl.DateTimeFormat("en-US", { timeZone: "Asia/Makassar", year: "numeric" }).format(new Date());
                if (!/^\d{4}$/.test(year) || year !== makassarYear) return errorResponse("Tahun Kapsul Waktu tidak valid", 400, request);

                const clientIp = request.headers.get("CF-Connecting-IP") || "unknown";
                const uidRateId = `timecapsule_uid_${await sha256Id(authResult.user.uid)}`;
                const ipRateId = `timecapsule_ip_${await sha256Id(clientIp)}`;
                if (!await consumeD1RateLimit(env, uidRateId, 20, 15 * 60 * 1000) ||
                    !await consumeD1RateLimit(env, ipRateId, 100, 15 * 60 * 1000)) {
                    return errorResponse("Terlalu banyak percobaan. Silakan coba lagi dalam 15 menit.", 429, request);
                }

                let submission;
                try { submission = normalizeTimeCapsuleSubmission(body.submission || {}); }
                catch (validationError) { return errorResponse(validationError.message, 400, request); }

                const configPath = `kapsul_waktu/${year}`;
                const configDocument = await getFirestoreAdminDocument(env, configPath);
                const config = configDocument ? decodeFirestoreFields(configDocument.fields || {}) : {};
                if (!configDocument || config.formActive !== true) return errorResponse("Pengisian Kapsul Waktu sedang ditutup", 412, request);

                const entryId = await sha256Id(submission.email);
                const hashedPath = `${configPath}/entries/${entryId}`;
                const legacyPath = `${configPath}/entries/${encodeURIComponent(submission.email)}`;
                const hashedDocument = await getFirestoreAdminDocument(env, hashedPath);
                const legacyDocument = hashedDocument ? null : await getFirestoreAdminDocument(env, legacyPath);
                const existingDocument = hashedDocument || legacyDocument;
                const existing = existingDocument ? decodeFirestoreFields(existingDocument.fields || {}) : {};
                const overwrite = body.overwrite === true;
                const suppliedEditToken = String(body.editToken || "");

                if (existingDocument && !overwrite) {
                    return jsonResponse({ success: false, code: "already-exists", error: "Data dengan email ini sudah ada." }, 409, request);
                }
                if (!existingDocument && overwrite) {
                    return jsonResponse({ success: false, code: "not-found", error: "Data lama tidak ditemukan." }, 404, request);
                }
                if (existingDocument && overwrite) {
                    const suppliedHash = await sha256Id(suppliedEditToken);
                    if (!suppliedEditToken || suppliedHash !== String(existing._editTokenHash || "")) {
                        return jsonResponse({ success: false, code: "permission-denied", error: "Kunci edit tidak cocok." }, 403, request);
                    }
                }

                const newEditTokenBytes = crypto.getRandomValues(new Uint8Array(32));
                const newEditToken = bytesToBase64Url(newEditTokenBytes);
                const editTokenHash = existingDocument ? String(existing._editTokenHash || "") : await sha256Id(newEditToken);
                const nowIso = new Date().toISOString();
                const createdAt = existing.createdAt || nowIso;
                const configuredSendDate = config.tanggalBuka ? new Date(config.tanggalBuka) : null;
                const sendDate = configuredSendDate && !Number.isNaN(configuredSendDate.getTime())
                    ? configuredSendDate.toISOString()
                    : new Date(Date.UTC(Number(year) + 5, 5, 1)).toISOString();
                const documentRoot = `projects/${FIREBASE_PROJECT_ID}/databases/(default)/documents`;
                const fields = {};
                for (const [key, value] of Object.entries(submission)) fields[key] = firestoreNullableString(value);
                fields._editTokenHash = firestoreString(editTokenHash);
                fields.createdAt = { timestampValue: createdAt };
                fields.updatedAt = { timestampValue: nowIso };
                fields.sendDate = { timestampValue: sendDate };
                fields.submittedBy = firestoreString(authResult.user.uid);

                const writes = [{
                    update: { name: `${documentRoot}/${hashedPath}`, fields },
                    currentDocument: hashedDocument ? { updateTime: hashedDocument.updateTime } : { exists: false }
                }, {
                    update: {
                        name: `${documentRoot}/${configPath}/public_words/${entryId}`,
                        fields: {
                            tigaKata: firestoreString(submission.tigaKata),
                            kelas: firestoreString(submission.kelas),
                            createdAt: { timestampValue: createdAt },
                            updatedAt: { timestampValue: nowIso }
                        }
                    }
                }];
                if (legacyDocument) {
                    writes.push({ delete: legacyDocument.name, currentDocument: { updateTime: legacyDocument.updateTime } });
                    writes.push({ delete: `${documentRoot}/${configPath}/public_words/${submission.email}` });
                }
                try {
                    await commitFirestoreAdminWrites(env, writes);
                } catch (commitError) {
                    if (String(commitError.message).includes("ALREADY_EXISTS")) {
                        return jsonResponse({ success: false, code: "already-exists", error: "Data dengan email ini sudah ada." }, 409, request);
                    }
                    throw commitError;
                }
                return jsonResponse({ success: true, ok: true, overwritten: Boolean(existingDocument), editToken: existingDocument ? null : newEditToken }, 200, request);
            }

            // POST /api/timecapsule/search-students
            if (path === "/api/timecapsule/search-students" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                const body = await request.json().catch(() => ({}));
                const query = String(body.query || "").normalize("NFKC").replace(/[<>\u0000]/g, "").trim().toLocaleLowerCase("id-ID");
                const year = String(body.year || "").trim();

                if (query.length < 5 || query.length > 120 || query.split(/\s+/u).filter(Boolean).length < 3) {
                    return errorResponse("Masukkan sedikitnya tiga kata dari nama lengkap", 400, request);
                }

                const clientIp = request.headers.get("CF-Connecting-IP") || "unknown";
                const rateId = `timecapsule_search_${await sha256Id(`${authResult.user.uid}|${clientIp}`)}`;
                if (!await consumeD1RateLimit(env, rateId, 60, 15 * 60 * 1000)) return errorResponse("Terlalu banyak pencarian", 429, request);
                if (year) {
                    const configDocument = await getFirestoreAdminDocument(env, `kapsul_waktu/${year}`);
                    const config = configDocument ? decodeFirestoreFields(configDocument.fields || {}) : {};
                    if (!configDocument || config.formActive !== true) return errorResponse("Pengisian Kapsul Waktu sedang ditutup", 412, request);
                }

                const stmt = env.DB.prepare(`
                    SELECT nis, name, class, gender FROM students 
                    WHERE lower(name) LIKE ? AND class LIKE 'XII%' AND status = 'active'
                    ORDER BY name ASC LIMIT 10
                `);
                const { results } = await stmt.bind(`%${query}%`).all();

                return jsonResponse({
                    success: true,
                    students: results || [],
                    suggestions: (results || []).map(student => ({ name: student.name, class: student.class }))
                }, 200, request);
            }

            // =================================================================
            // ⚖️ ROUTE: VIOLATION TYPES (Master Jenis Pelanggaran & Poin BK)
            // =================================================================

            // 1. GET /api/violation-types (Ambil Daftar Master Jenis Pelanggaran)
            if (path === "/api/violation-types" && method === "GET") {
                const category = url.searchParams.get("category");
                const search = url.searchParams.get("search");

                let query = "SELECT * FROM violation_types";
                const params = [];

                if (category && search) {
                    query += " WHERE category = ? AND (title LIKE ? OR code LIKE ?)";
                    params.push(category, `%${search}%`, `%${search}%`);
                } else if (category) {
                    query += " WHERE category = ?";
                    params.push(category);
                } else if (search) {
                    query += " WHERE (title LIKE ? OR code LIKE ?)";
                    params.push(`%${search}%`, `%${search}%`);
                }

                query += " ORDER BY code ASC";

                const stmt = env.DB.prepare(query);
                const { results } = params.length > 0 ? await stmt.bind(...params).all() : await stmt.all();

                return jsonResponse({
                    success: true,
                    data: results || []
                }, 200, request);
            }

            // 2. POST /api/violation-types (Tambah Jenis Pelanggaran Baru / Smart Upsert)
            if (path === "/api/violation-types" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                if (!canManageViolationTypes(authResult.user)) {
                    return errorResponse("Forbidden: Anda tidak memiliki wewenang untuk menambah jenis pelanggaran", 403, request);
                }

                const body = await request.json();
                const code = String(body.code || "").trim();
                const title = String(body.title || "").trim();
                const category = String(body.category || "Umum").trim();
                const points = Number(body.points || 0);
                const id = String(body.id || `vt_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`).trim();

                if (!code || !title) {
                    return errorResponse("Kode (code) dan Nama/Deskripsi Pelanggaran (title) wajib diisi", 400, request);
                }

                // Cek apakah kode sudah ada untuk smart-update
                const existing = await env.DB.prepare("SELECT id FROM violation_types WHERE code = ? LIMIT 1").bind(code).first();
                if (existing && existing.id) {
                    await env.DB.prepare(`
                        UPDATE violation_types SET title = ?, category = ?, points = ?, updated_at = datetime('now') WHERE id = ?
                    `).bind(title, category, points, existing.id).run();

                    return jsonResponse({
                        success: true,
                        isUpdate: true,
                        id: existing.id,
                        message: `Jenis pelanggaran kode ${code} berhasil diperbarui.`
                    }, 200, request);
                }

                await env.DB.prepare(`
                    INSERT INTO violation_types (id, code, title, category, points, created_at, updated_at)
                    VALUES (?, ?, ?, ?, ?, datetime('now'), datetime('now'))
                `).bind(id, code, title, category, points).run();

                return jsonResponse({
                    success: true,
                    isUpdate: false,
                    id,
                    message: "Jenis pelanggaran baru berhasil ditambahkan."
                }, 201, request);
            }

            // 3. PUT /api/violation-types/:id (Update Jenis Pelanggaran)
            if (path.startsWith("/api/violation-types/") && method === "PUT") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                if (!canEditViolationTypes(authResult.user)) {
                    return errorResponse("Forbidden: Anda tidak memiliki wewenang untuk mengedit jenis pelanggaran", 403, request);
                }

                const typeId = decodeURIComponent(path.replace("/api/violation-types/", "")).trim();
                const body = await request.json();
                const code = String(body.code || "").trim();
                const title = String(body.title || "").trim();
                const category = String(body.category || "Umum").trim();
                const points = Number(body.points || 0);

                if (!title) {
                    return errorResponse("Nama Pelanggaran (title) wajib diisi", 400, request);
                }

                const stmt = env.DB.prepare(`
                    UPDATE violation_types 
                    SET code = COALESCE(NULLIF(?, ''), code),
                        title = ?, 
                        category = ?, 
                        points = ?, 
                        updated_at = datetime('now')
                    WHERE id = ?
                `);
                const res = await stmt.bind(code, title, category, points, typeId).run();

                if (res.meta?.changes === 0) {
                    return errorResponse("Data jenis pelanggaran tidak ditemukan", 404, request);
                }

                return jsonResponse({
                    success: true,
                    message: "Jenis pelanggaran berhasil diperbarui."
                }, 200, request);
            }

            // 4. DELETE /api/violation-types/:id (Hapus Jenis Pelanggaran)
            if (path.startsWith("/api/violation-types/") && method === "DELETE") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                if (!canManageViolationTypes(authResult.user)) {
                    return errorResponse("Forbidden: Anda tidak memiliki wewenang untuk menghapus jenis pelanggaran", 403, request);
                }

                const typeId = decodeURIComponent(path.replace("/api/violation-types/", "")).trim();
                const res = await env.DB.prepare("DELETE FROM violation_types WHERE id = ?").bind(typeId).run();

                if (res.meta?.changes === 0) {
                    return errorResponse("Data jenis pelanggaran tidak ditemukan", 404, request);
                }

                return jsonResponse({
                    success: true,
                    message: "Jenis pelanggaran berhasil dihapus."
                }, 200, request);
            }

            // 5. POST /api/violation-types/bulk-sync & /api/migrate/violation-types
            if ((path === "/api/violation-types/bulk-sync" || path === "/api/migrate/violation-types") && method === "POST") {
                const migrationKey = request.headers.get("X-Migration-Key") || url.searchParams.get("key");
                const isSecretValid = env.MIGRATION_SECRET && migrationKey && migrationKey === env.MIGRATION_SECRET;

                const authResult = await verifyFirebaseToken(request);
                const isAuthorized = (authResult.valid && canManageViolationTypes(authResult.user)) || isSecretValid;

                if (!isAuthorized) {
                    return errorResponse("Unauthorized: Hak akses kesiswaan/super_admin atau migration key diperlukan", 401, request);
                }

                const body = await request.json();
                const types = body.types || body.violationTypes || [];

                if (!Array.isArray(types) || types.length === 0) {
                    return errorResponse("Payload 'types' harus berupa array dan tidak boleh kosong", 400, request);
                }

                const statements = [];
                for (const t of types) {
                    const id = String(t.id || `vt_${t.code || Math.random().toString(36).substring(2, 9)}`).trim();
                    const code = String(t.code || "").trim();
                    const title = String(t.title || t.nama || "").trim();
                    const category = String(t.category || "Umum").trim();
                    const points = Number(t.points || t.poin || 0);

                    if (code && title) {
                        statements.push(
                            env.DB.prepare(`
                                INSERT OR REPLACE INTO violation_types (id, code, title, category, points, created_at, updated_at)
                                VALUES (?, ?, ?, ?, ?, datetime('now'), datetime('now'))
                            `).bind(id, code, title, category, points)
                        );
                    }
                }

                if (statements.length > 0) {
                    const chunkSize = 50;
                    for (let i = 0; i < statements.length; i += chunkSize) {
                        const chunk = statements.slice(i, i + chunkSize);
                        await env.DB.batch(chunk);
                    }
                }

                return jsonResponse({
                    success: true,
                    synced: statements.length,
                    message: `Berhasil menyinkronkan ${statements.length} jenis pelanggaran ke Cloudflare D1.`
                }, 200, request);
            }

            // =================================================================
            // 🔬 ROUTE: E-LABORATORIUM (labs & lab_bookings)
            // =================================================================

            // Helper Inisialisasi Idempotent Skema Labs & Koordinator
            let _labsColumnsChecked = false;
            async function ensureLabColumns(env) {
                if (_labsColumnsChecked) return;
                try {
                    try { await env.DB.prepare("ALTER TABLE labs ADD COLUMN kode TEXT").run(); } catch (_) {}
                    try { await env.DB.prepare("ALTER TABLE labs ADD COLUMN kepala_lab_uid TEXT").run(); } catch (_) {}
                    try { await env.DB.prepare("ALTER TABLE labs ADD COLUMN kepala_lab_nama TEXT").run(); } catch (_) {}
                    try { await env.DB.prepare("ALTER TABLE labs ADD COLUMN koordinator_uid TEXT").run(); } catch (_) {}
                    try { await env.DB.prepare("ALTER TABLE labs ADD COLUMN koordinator_nama TEXT").run(); } catch (_) {}
                    try { await env.DB.prepare("CREATE INDEX IF NOT EXISTS idx_labs_koordinator ON labs(koordinator_uid)").run(); } catch (_) {}
                    _labsColumnsChecked = true;
                } catch (e) {
                    console.warn("[Labs] ensureLabColumns error:", e);
                }
            }

            // 1. GET /api/labs (Ambil Daftar Master Laboratorium)
            if (path === "/api/labs" && method === "GET") {
                await ensureLabColumns(env);
                const stmt = env.DB.prepare("SELECT * FROM labs ORDER BY urutan ASC, nama ASC");
                const { results } = await stmt.all();

                return jsonResponse({
                    success: true,
                    data: results || []
                }, 200, request);
            }

            // 2. POST /api/labs (Tambah Master Lab Baru)
            if (path === "/api/labs" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                if (!canManageLabs(authResult.user)) {
                    return errorResponse("Forbidden: Hanya Kepala Lab atau Super Admin yang dapat menambah master lab", 403, request);
                }

                await ensureLabColumns(env);

                const body = await request.json();
                const nama = String(body.nama || "").trim();
                const deskripsi = String(body.deskripsi || "").trim();
                const urutan = Number(body.urutan || 0);
                const rawKode = String(body.kode || "").trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
                const kode = rawKode || nama.replace(/[^A-Za-z0-9]/g, "").substring(0, 3).toUpperCase() || "LAB";
                const kepalaLabUid = (body.kepala_lab_uid || body.kepalaLabUid) ? String(body.kepala_lab_uid || body.kepalaLabUid).trim() : "";
                const kepalaLabNama = (body.kepala_lab_nama || body.kepalaLabNama) ? String(body.kepala_lab_nama || body.kepalaLabNama).trim() : "";

                let koordinatorUid = null;
                const rawCoordUid = body.koordinator_uid !== undefined ? body.koordinator_uid : body.koordinatorUid;
                if (rawCoordUid !== undefined && rawCoordUid !== null && String(rawCoordUid).trim() !== "" && String(rawCoordUid).trim() !== "null") {
                    koordinatorUid = String(rawCoordUid).trim();
                }

                let koordinatorNama = null;
                const rawCoordNama = body.koordinator_nama !== undefined ? body.koordinator_nama : body.koordinatorNama;
                if (rawCoordNama !== undefined && rawCoordNama !== null && String(rawCoordNama).trim() !== "" && String(rawCoordNama).trim() !== "null") {
                    koordinatorNama = String(rawCoordNama).trim();
                }

                const id = String(body.id || `lab_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`).trim();

                if (!nama) {
                    return errorResponse("Nama laboratorium (nama) wajib diisi", 400, request);
                }

                await env.DB.prepare(`
                    INSERT INTO labs (id, nama, deskripsi, urutan, kode, kepala_lab_uid, kepala_lab_nama, koordinator_uid, koordinator_nama, created_at, updated_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))
                `).bind(id, nama, deskripsi, urutan, kode, kepalaLabUid || null, kepalaLabNama || null, koordinatorUid, koordinatorNama).run();

                return jsonResponse({
                    success: true,
                    data: { id, nama, deskripsi, urutan, kode, kepala_lab_uid: kepalaLabUid, kepala_lab_nama: kepalaLabNama, koordinator_uid: koordinatorUid, koordinator_nama: koordinatorNama },
                    message: "Laboratorium baru berhasil ditambahkan."
                }, 201, request);
            }

            // 3. PUT /api/labs/:id (Update Master Lab)
            if (path.startsWith("/api/labs/") && method === "PUT") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                if (!canManageLabs(authResult.user)) {
                    return errorResponse("Forbidden: Hanya Kepala Lab atau Super Admin yang dapat mengedit master lab", 403, request);
                }

                await ensureLabColumns(env);

                const labId = decodeURIComponent(path.replace("/api/labs/", "")).trim();
                const existing = await env.DB.prepare("SELECT * FROM labs WHERE id = ?").bind(labId).first();
                if (!existing) {
                    return errorResponse("Laboratorium tidak ditemukan", 404, request);
                }

                const body = await request.json();
                const nama = String(body.nama !== undefined ? body.nama : existing.nama).trim();
                const deskripsi = String(body.deskripsi !== undefined ? body.deskripsi : existing.deskripsi).trim();
                const urutan = Number(body.urutan !== undefined ? body.urutan : existing.urutan || 0);
                const rawKode = body.kode !== undefined ? String(body.kode).trim().toUpperCase().replace(/[^A-Z0-9]/g, "") : existing.kode;
                const kode = rawKode || nama.replace(/[^A-Za-z0-9]/g, "").substring(0, 3).toUpperCase() || "LAB";
                const kepalaLabUid = body.kepala_lab_uid !== undefined ? String(body.kepala_lab_uid || "").trim() : (existing.kepala_lab_uid || "");
                const kepalaLabNama = body.kepala_lab_nama !== undefined ? String(body.kepala_lab_nama || "").trim() : (existing.kepala_lab_nama || "");

                let koordinatorUid = null;
                const rawCoordUid = body.koordinator_uid !== undefined ? body.koordinator_uid : body.koordinatorUid;
                if (rawCoordUid !== undefined) {
                    if (rawCoordUid !== null && String(rawCoordUid).trim() !== "" && String(rawCoordUid).trim() !== "null") {
                        koordinatorUid = String(rawCoordUid).trim();
                    } else {
                        koordinatorUid = null;
                    }
                } else {
                    koordinatorUid = existing.koordinator_uid || null;
                }

                let koordinatorNama = null;
                const rawCoordNama = body.koordinator_nama !== undefined ? body.koordinator_nama : body.koordinatorNama;
                if (rawCoordNama !== undefined) {
                    if (rawCoordNama !== null && String(rawCoordNama).trim() !== "" && String(rawCoordNama).trim() !== "null") {
                        koordinatorNama = String(rawCoordNama).trim();
                    } else {
                        koordinatorNama = null;
                    }
                } else {
                    koordinatorNama = existing.koordinator_nama || null;
                }

                if (!nama) {
                    return errorResponse("Nama laboratorium (nama) wajib diisi", 400, request);
                }

                const res = await env.DB.prepare(`
                    UPDATE labs 
                    SET nama = ?, deskripsi = ?, urutan = ?, kode = ?, kepala_lab_uid = ?, kepala_lab_nama = ?, koordinator_uid = ?, koordinator_nama = ?, updated_at = datetime('now') 
                    WHERE id = ?
                `).bind(nama, deskripsi, urutan, kode, kepalaLabUid || null, kepalaLabNama || null, koordinatorUid, koordinatorNama, labId).run();

                if (res.meta?.changes === 0) {
                    return errorResponse("Laboratorium tidak ditemukan", 404, request);
                }

                return jsonResponse({
                    success: true,
                    data: { id: labId, nama, deskripsi, urutan, kode, kepala_lab_uid: kepalaLabUid, kepala_lab_nama: kepalaLabNama, koordinator_uid: koordinatorUid, koordinator_nama: koordinatorNama },
                    message: "Laboratorium berhasil diperbarui."
                }, 200, request);
            }

            // 4. DELETE /api/labs/:id (Hapus Master Lab)
            if (path.startsWith("/api/labs/") && method === "DELETE") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                if (!canManageLabs(authResult.user)) {
                    return errorResponse("Forbidden: Hanya Kepala Lab atau Super Admin yang dapat menghapus master lab", 403, request);
                }

                const labId = decodeURIComponent(path.replace("/api/labs/", "")).trim();

                // Proteksi integritas: tolak jika lab masih memiliki data barang inventaris aktif
                try {
                    await ensureInventoryTables(env);
                    const invCount = await env.DB.prepare("SELECT COUNT(*) as cnt FROM inventory_items WHERE lab_id = ?").bind(labId).first();
                    if (invCount && invCount.cnt > 0) {
                        return errorResponse(`Laboratorium tidak dapat dihapus karena masih memiliki ${invCount.cnt} barang inventaris. Silakan kosongkan atau pindahkan data inventaris terlebih dahulu.`, 400, request);
                    }
                } catch (_) {}

                const res = await env.DB.prepare("DELETE FROM labs WHERE id = ?").bind(labId).run();

                if (res.meta?.changes === 0) {
                    return errorResponse("Laboratorium tidak ditemukan", 404, request);
                }

                return jsonResponse({
                    success: true,
                    message: "Laboratorium berhasil dihapus."
                }, 200, request);
            }

            // 5. GET /api/lab-bookings (Ambil Jadwal & Riwayat Booking Lab)
            if (path === "/api/lab-bookings" && method === "GET") {
                const tanggal = url.searchParams.get("tanggal");
                const weekStart = url.searchParams.get("weekStart") || url.searchParams.get("startDate");
                const weekEnd = url.searchParams.get("weekEnd") || url.searchParams.get("endDate");
                const labId = url.searchParams.get("lab_id") || url.searchParams.get("labId");
                const status = url.searchParams.get("status");
                const pemohonUid = url.searchParams.get("pemohon_uid") || url.searchParams.get("pemohonUid");
                const limit = parseInt(url.searchParams.get("limit") || "200", 10);

                let query = "SELECT * FROM lab_bookings WHERE 1=1";
                const params = [];

                if (weekStart && weekEnd) {
                    query += " AND tanggal >= ? AND tanggal <= ?";
                    params.push(weekStart, weekEnd);
                } else if (tanggal) {
                    query += " AND tanggal = ?";
                    params.push(tanggal);
                }

                if (labId) {
                    query += " AND lab_id = ?";
                    params.push(labId);
                }

                if (status) {
                    query += " AND status = ?";
                    params.push(status);
                }

                if (pemohonUid) {
                    query += " AND pemohon_uid = ?";
                    params.push(pemohonUid);
                }

                query += " ORDER BY tanggal ASC, jam_mulai ASC LIMIT ?";
                params.push(limit);

                const stmt = env.DB.prepare(query);
                const { results } = await stmt.bind(...params).all();

                return jsonResponse({
                    success: true,
                    data: results || []
                }, 200, request);
            }

            // 6. POST /api/lab-bookings (Ajukan Booking Lab Baru)
            if (path === "/api/lab-bookings" && method === "POST") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                if (!isStaffOrTeacher(authResult.user)) {
                    return errorResponse("Forbidden: Pengajuan booking lab hanya dapat dilakukan oleh akun guru/staf resmi", 403, request);
                }

                const body = await request.json();
                const labId = String(body.lab_id || body.labId || "").trim();
                const labNama = String(body.lab_nama || body.labNama || "").trim();
                const tanggal = String(body.tanggal || "").trim();
                const jamMulai = parseInt(body.jam_mulai || body.jamMulai, 10);
                const jamSelesai = parseInt(body.jam_selesai || body.jamSelesai, 10);
                const kelas = String(body.kelas || "").trim();
                const kegiatan = String(body.kegiatan || "").trim();
                const catatan = String(body.catatan || "").trim();
                const status = String(body.status || "pending").trim();
                const id = String(body.id || `lb_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`).trim();
                const pemohonUid = authResult.user.uid;
                const pemohonNama = String(body.pemohon_nama || authResult.user.claims?.name || authResult.user.email || "Guru").trim();

                if (!labId || !tanggal || !jamMulai || !jamSelesai || !kelas || !kegiatan) {
                    return errorResponse("Data booking tidak lengkap (lab_id, tanggal, jam_mulai, jam_selesai, kelas, kegiatan wajib diisi)", 400, request);
                }

                await env.DB.prepare(`
                    INSERT INTO lab_bookings (
                        id, lab_id, lab_nama, tanggal, jam_mulai, jam_selesai,
                        kelas, kegiatan, catatan, pemohon_uid, pemohon_nama, status,
                        diajukan_pada, created_at, updated_at
                    ) VALUES (
                        ?, ?, ?, ?, ?, ?,
                        ?, ?, ?, ?, ?, ?,
                        datetime('now'), datetime('now'), datetime('now')
                    )
                `).bind(
                    id, labId, labNama, tanggal, jamMulai, jamSelesai,
                    kelas, kegiatan, catatan, pemohonUid, pemohonNama, status
                ).run();

                // Cek data lab untuk penentuan target notifikasi
                const labTarget = await env.DB.prepare("SELECT * FROM labs WHERE id = ?").bind(labId).first();
                const isConflict = status === "conflict";

                let notificationJob;
                if (!isConflict && labTarget && labTarget.koordinator_uid) {
                    // Booking biasa: arahkan ke Koordinator Lab
                    notificationJob = await createNotificationJob(env, pemohonUid, {
                        title: "🧪 Pengajuan Lab Baru",
                        body: `${pemohonNama} mengajukan ${labNama || labId} untuk kelas ${kelas} pada ${tanggal} (JP ${jamMulai}-${jamSelesai}).`,
                        url: "./e-lab.html",
                        targetType: "user",
                        targetValue: labTarget.koordinator_uid
                    });
                } else {
                    // Booking bentrok atau lab tanpa koordinator: arahkan ke Kepala Lab
                    notificationJob = await createNotificationJob(env, pemohonUid, {
                        title: isConflict ? "⚠️ Bentrok Jadwal Lab" : "🧪 Pengajuan Lab Baru",
                        body: isConflict
                            ? `${pemohonNama} mengajukan jadwal bentrok di ${labNama || labId} pada ${tanggal} (JP ${jamMulai}-${jamSelesai}). Memerlukan keputusan Kepala Lab.`
                            : `${pemohonNama} mengajukan ${labNama || labId} untuk kelas ${kelas} pada ${tanggal}.`,
                        url: "./e-lab.html",
                        targetType: "role",
                        targetValue: "kepala_lab"
                    });
                }
                if (notificationJob?.targetCount) ctx.waitUntil(processPendingNotifications(env, notificationJob.jobId));

                return jsonResponse({
                    success: true,
                    data: { id, lab_id: labId, tanggal, jam_mulai: jamMulai, jam_selesai: jamSelesai, status },
                    message: "Pengajuan booking laboratorium berhasil disimpan."
                }, 201, request);
            }

            // 7. PUT /api/lab-bookings/:id (Update Booking / Approval Pengelola Lab)
            if (path.startsWith("/api/lab-bookings/") && method === "PUT") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                const bookingId = decodeURIComponent(path.replace("/api/lab-bookings/", "")).trim();
                const existing = await env.DB.prepare("SELECT * FROM lab_bookings WHERE id = ? LIMIT 1").bind(bookingId).first();
                if (!existing) {
                    return errorResponse("Booking laboratorium tidak ditemukan", 404, request);
                }

                const labTarget = await env.DB.prepare("SELECT * FROM labs WHERE id = ?").bind(existing.lab_id).first();
                const isHeadOrAdmin = isLabAdmin(authResult.user) || isKepalaLabUser(authResult.user);
                const isCoordinator = Boolean(labTarget && labTarget.koordinator_uid && labTarget.koordinator_uid === authResult.user.uid);
                const isOwner = existing.pemohon_uid === authResult.user.uid;

                if (!isHeadOrAdmin && !isCoordinator && !isOwner) {
                    return errorResponse("Forbidden: Anda tidak memiliki wewenang untuk mengubah booking ini", 403, request);
                }

                const body = await request.json();

                // Jika update status approval atau pembatalan booking
                if (body.status && body.status !== existing.status) {
                    const newStatus = String(body.status).trim();
                    const isCancelling = newStatus === 'cancelled';
                    const isOwnerCancelling = isOwner && isCancelling;

                    if (isCancelling) {
                        // Pembatalan diizinkan untuk pemilik booking, Kepala Lab/Admin, atau Koordinator Lab terkait
                        if (!isOwner && !isHeadOrAdmin && !isCoordinator) {
                            return errorResponse("Forbidden: Anda tidak memiliki wewenang untuk membatalkan booking ini", 403, request);
                        }
                    } else {
                        // Persetujuan (approved) atau penolakan (rejected) hanya wewenang Kepala Lab / Koordinator Lab / Admin
                        if (!isHeadOrAdmin && !isCoordinator) {
                            return errorResponse("Forbidden: Hanya Kepala Lab, Koordinator Lab terkait, atau Admin yang dapat memproses persetujuan booking", 403, request);
                        }
                    }

                    const alasanPenolakan = String(body.alasan_penolakan || body.alasanPenolakan || (isCancelling ? "Dibatalkan oleh pemohon." : "")).trim();
                    const defaultApproverName = isOwnerCancelling
                        ? (authResult.user.claims?.name || existing.pemohon_nama || "Pemohon")
                        : (isCoordinator
                            ? (labTarget?.koordinator_nama || authResult.user.claims?.name || "Koordinator Lab")
                            : (authResult.user.claims?.name || "Kepala Lab"));
                    const diprosesOleh = String(body.diproses_oleh || defaultApproverName).trim();

                    // Proteksi Anti-Bentrok Keras: Koordinator dilarang keras menyetujui booking bentrok
                    if (newStatus === "approved" && !isHeadOrAdmin) {
                        // 1. Jika status booking sebelumnya sudah conflict
                        if (existing.status === "conflict") {
                            return errorResponse("Forbidden: Booking bentrok hanya dapat diputuskan dan disetujui oleh Kepala Laboratorium atau Admin", 403, request);
                        }

                        // 2. Cek apakah ada booking approved lain yang bertabrakan jamnya
                        const overlapApproved = await env.DB.prepare(`
                            SELECT id FROM lab_bookings 
                            WHERE lab_id = ? AND tanggal = ? AND status = 'approved' AND id != ?
                            AND NOT (jam_selesai < ? OR jam_mulai > ?)
                            LIMIT 1
                        `).bind(
                            existing.lab_id, existing.tanggal, bookingId,
                            existing.jam_mulai, existing.jam_selesai
                        ).first();

                        if (overlapApproved) {
                            return errorResponse("Forbidden: Booking bentrok hanya dapat diputuskan dan disetujui oleh Kepala Laboratorium atau Admin", 403, request);
                        }
                    }

                    // Jika Kepala Lab / Admin menyetujui dan meminta auto-reject booking lain yang bertabrakan
                    if (newStatus === "approved" && (body.auto_reject_conflicts || body.autoRejectConflicts)) {
                        await env.DB.prepare(`
                            UPDATE lab_bookings 
                            SET status = 'auto_rejected', 
                                alasan_penolakan = 'Jadwal bentrok dengan pengajuan lain yang telah disetujui oleh Kepala Lab/Admin',
                                diproses_oleh = ?,
                                diproses_pada = datetime('now'),
                                updated_at = datetime('now')
                            WHERE lab_id = ? AND tanggal = ? AND status IN ('pending', 'conflict') AND id != ?
                            AND NOT (jam_selesai < ? OR jam_mulai > ?)
                        `).bind(diprosesOleh, existing.lab_id, existing.tanggal, bookingId, existing.jam_mulai, existing.jam_selesai).run();
                    }

                    await env.DB.prepare(`
                        UPDATE lab_bookings 
                        SET status = ?, 
                            alasan_penolakan = ?,
                            diproses_oleh = ?,
                            diproses_pada = datetime('now'),
                            updated_at = datetime('now')
                        WHERE id = ?
                    `).bind(newStatus, alasanPenolakan, diprosesOleh, bookingId).run();

                    const statusLabel = newStatus === "approved" ? "disetujui" : (newStatus === "rejected" ? "ditolak" : (newStatus === "cancelled" ? "dibatalkan" : newStatus));

                    let notificationJob;
                    if (isOwnerCancelling) {
                        // Jika dibatalkan sendiri oleh pemohon, beritahu Koordinator Lab atau Kepala Lab agar mengetahui slot kembali kosong
                        const cancelTitle = "🧪 Pembatalan Booking Lab";
                        const cancelBody = `${authResult.user.claims?.name || existing.pemohon_nama || 'Guru'} membatalkan booking ${existing.lab_nama || existing.lab_id} pada ${existing.tanggal} (JP ${existing.jam_mulai}-${existing.jam_selesai}). Slot waktu kini tersedia kembali.`;
                        if (labTarget && labTarget.koordinator_uid) {
                            notificationJob = await createNotificationJob(env, authResult.user.uid, {
                                title: cancelTitle,
                                body: cancelBody,
                                url: "./e-lab.html",
                                targetType: "user",
                                targetValue: labTarget.koordinator_uid
                            });
                        } else {
                            notificationJob = await createNotificationJob(env, authResult.user.uid, {
                                title: cancelTitle,
                                body: cancelBody,
                                url: "./e-lab.html",
                                targetType: "role",
                                targetValue: "kepala_lab"
                            });
                        }
                    } else {
                        // Pengelola Lab memproses booking: kirim notifikasi ke pemohon
                        notificationJob = await createNotificationJob(env, authResult.user.uid, {
                            title: "🧪 Status Booking Lab",
                            body: `Pengajuan ${existing.lab_nama || existing.lab_id} tanggal ${existing.tanggal} ${statusLabel}.${alasanPenolakan ? ` Alasan: ${alasanPenolakan}` : ""}`,
                            url: "./e-lab.html",
                            targetType: "user",
                            targetValue: existing.pemohon_uid
                        });
                    }

                    if (notificationJob?.targetCount) ctx.waitUntil(processPendingNotifications(env, notificationJob.jobId));
                    if (env.TELEGRAM_BOT_TOKEN) {
                        const applicantContact = await getAdminUserContact(env, existing.pemohon_uid);
                        if (applicantContact.telegramChatId) {
                            ctx.waitUntil(executeTelegramFetch(
                                env.TELEGRAM_BOT_TOKEN,
                                applicantContact.telegramChatId,
                                `<b>🧪 Status Booking Lab</b>\n\nPengajuan ${escapeTelegramHtml(existing.lab_nama || existing.lab_id)} tanggal ${escapeTelegramHtml(existing.tanggal)} ${escapeTelegramHtml(statusLabel)}.${alasanPenolakan ? `\nAlasan: ${escapeTelegramHtml(alasanPenolakan)}` : ""}`
                            ));
                        }
                    }

                    return jsonResponse({
                        success: true,
                        message: `Status booking berhasil diubah menjadi ${newStatus}.`
                    }, 200, request);
                }

                // Update detail data form booking (bisa oleh pemilik atau pengelola lab)
                const labId = String(body.lab_id || body.labId || existing.lab_id).trim();
                const labNama = String(body.lab_nama || body.labNama || existing.lab_nama).trim();
                const tanggal = String(body.tanggal || existing.tanggal).trim();
                const jamMulai = parseInt(body.jam_mulai || body.jamMulai || existing.jam_mulai, 10);
                const jamSelesai = parseInt(body.jam_selesai || body.jamSelesai || existing.jam_selesai, 10);
                const kelas = String(body.kelas || existing.kelas).trim();
                const kegiatan = String(body.kegiatan || existing.kegiatan).trim();
                const catatan = String(body.catatan !== undefined ? body.catatan : existing.catatan).trim();
                const status = String(body.status || existing.status).trim();

                await env.DB.prepare(`
                    UPDATE lab_bookings 
                    SET lab_id = ?, lab_nama = ?, tanggal = ?, jam_mulai = ?, jam_selesai = ?,
                        kelas = ?, kegiatan = ?, catatan = ?, status = ?, updated_at = datetime('now')
                    WHERE id = ?
                `).bind(labId, labNama, tanggal, jamMulai, jamSelesai, kelas, kegiatan, catatan, status, bookingId).run();

                return jsonResponse({
                    success: true,
                    message: "Data booking laboratorium berhasil diperbarui."
                }, 200, request);
            }

            // 8. DELETE /api/lab-bookings/:id (Batalkan / Hapus Booking Lab)
            if (path.startsWith("/api/lab-bookings/") && method === "DELETE") {
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) {
                    return errorResponse("Unauthorized: " + authResult.error, 401, request);
                }

                const bookingId = decodeURIComponent(path.replace("/api/lab-bookings/", "")).trim();
                const existing = await env.DB.prepare("SELECT * FROM lab_bookings WHERE id = ? LIMIT 1").bind(bookingId).first();
                if (!existing) {
                    return errorResponse("Booking laboratorium tidak ditemukan", 404, request);
                }

                const labTarget = await env.DB.prepare("SELECT * FROM labs WHERE id = ?").bind(existing.lab_id).first();
                const isHeadOrAdmin = isLabAdmin(authResult.user) || isKepalaLabUser(authResult.user);
                const isCoordinator = Boolean(labTarget && labTarget.koordinator_uid && labTarget.koordinator_uid === authResult.user.uid);
                const isOwner = existing.pemohon_uid === authResult.user.uid;

                if (!isHeadOrAdmin && !isCoordinator && !isOwner) {
                    return errorResponse("Forbidden: Anda tidak memiliki wewenang untuk menghapus booking ini", 403, request);
                }

                await env.DB.prepare("DELETE FROM lab_bookings WHERE id = ?").bind(bookingId).run();

                return jsonResponse({
                    success: true,
                    message: "Booking laboratorium berhasil dihapus."
                }, 200, request);
            }

            // 9. POST /api/migrate/labs (Batch Migration Labs & Bookings dari Firestore)
            if (path === "/api/migrate/labs" && method === "POST") {
                const migrationKey = request.headers.get("X-Migration-Key") || url.searchParams.get("key");
                const isSecretValid = env.MIGRATION_SECRET && migrationKey && migrationKey === env.MIGRATION_SECRET;

                const authResult = await verifyFirebaseToken(request);
                const isAuthorized = (authResult.valid && authResult.user.role === "super_admin") || isSecretValid;

                if (!isAuthorized) {
                    return errorResponse("Unauthorized: Super Admin authentication atau valid migration key diperlukan", 401, request);
                }

                const body = await request.json();
                const labs = body.labs || [];
                const bookings = body.bookings || [];

                const statements = [];

                // 1. Batch insert labs
                for (const l of labs) {
                    if (l.nama) {
                        statements.push(
                            env.DB.prepare(`
                                INSERT OR REPLACE INTO labs (id, nama, deskripsi, urutan, created_at, updated_at)
                                VALUES (?, ?, ?, ?, datetime('now'), datetime('now'))
                            `).bind(
                                String(l.id || `lab_${Date.now()}`),
                                String(l.nama).trim(),
                                String(l.deskripsi || "").trim(),
                                Number(l.urutan || 0)
                            )
                        );
                    }
                }

                // 2. Batch insert bookings
                for (const b of bookings) {
                    if (b.lab_id && b.tanggal) {
                        statements.push(
                            env.DB.prepare(`
                                INSERT OR REPLACE INTO lab_bookings (
                                    id, lab_id, lab_nama, tanggal, jam_mulai, jam_selesai,
                                    kelas, kegiatan, catatan, pemohon_uid, pemohon_nama, status,
                                    alasan_penolakan, diajukan_pada, diproses_pada, diproses_oleh,
                                    created_at, updated_at
                                ) VALUES (
                                    ?, ?, ?, ?, ?, ?,
                                    ?, ?, ?, ?, ?, ?,
                                    ?, ?, ?, ?,
                                    datetime('now'), datetime('now')
                                )
                            `).bind(
                                String(b.id || `lb_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`),
                                String(b.lab_id || b.labId).trim(),
                                String(b.lab_nama || b.labNama || "").trim(),
                                String(b.tanggal).trim(),
                                Number(b.jam_mulai || b.jamMulai || 1),
                                Number(b.jam_selesai || b.jamSelesai || 1),
                                String(b.kelas || "").trim(),
                                String(b.kegiatan || "").trim(),
                                String(b.catatan || "").trim(),
                                String(b.pemohon_uid || b.pemohonUid || "admin"),
                                String(b.pemohon_nama || b.pemohonNama || "Guru"),
                                String(b.status || "pending"),
                                String(b.alasan_penolakan || b.alasanPenolakan || ""),
                                String(b.diajukan_pada || new Date().toISOString()),
                                b.diproses_pada ? String(b.diproses_pada) : null,
                                b.diproses_oleh ? String(b.diproses_oleh) : null
                            )
                        );
                    }
                }

                if (statements.length > 0) {
                    const chunkSize = 50;
                    for (let i = 0; i < statements.length; i += chunkSize) {
                        const chunk = statements.slice(i, i + chunkSize);
                        await env.DB.batch(chunk);
                    }
                }

                return jsonResponse({
                    success: true,
                    migratedLabs: labs.length,
                    migratedBookings: bookings.length,
                    message: `Berhasil memigrasikan ${labs.length} master lab dan ${bookings.length} data booking ke Cloudflare D1.`
                }, 200, request);
            }

            // =================================================================
            // 📦 ROUTE: E-LABORATORIUM INVENTARIS (BARANG TIDAK HABIS PAKAI)
            // SSOT: Cloudflare D1 SQL | 0 Firestore Read | RBAC Multi-Lab
            // =================================================================

            // Helper Inisialisasi Idempotent Skema Inventaris
            let _inventoryTablesChecked = false;
            async function ensureInventoryTables(env) {
                if (_inventoryTablesChecked) return;
                try {
                    try { await env.DB.prepare("ALTER TABLE labs ADD COLUMN kode TEXT").run(); } catch (_) {}
                    try { await env.DB.prepare("ALTER TABLE labs ADD COLUMN kepala_lab_uid TEXT").run(); } catch (_) {}
                    try { await env.DB.prepare("ALTER TABLE labs ADD COLUMN kepala_lab_nama TEXT").run(); } catch (_) {}
                    try { await env.DB.prepare("ALTER TABLE labs ADD COLUMN koordinator_uid TEXT").run(); } catch (_) {}
                    try { await env.DB.prepare("ALTER TABLE labs ADD COLUMN koordinator_nama TEXT").run(); } catch (_) {}
                    try { await env.DB.prepare("CREATE INDEX IF NOT EXISTS idx_labs_koordinator ON labs(koordinator_uid)").run(); } catch (_) {}

                    await env.DB.batch([
                        env.DB.prepare(`
                            CREATE TABLE IF NOT EXISTS inventory_categories (
                                id TEXT PRIMARY KEY,
                                lab_id TEXT NOT NULL,
                                name TEXT NOT NULL,
                                code TEXT NOT NULL,
                                is_active INTEGER DEFAULT 1,
                                created_at TEXT DEFAULT (datetime('now')),
                                updated_at TEXT DEFAULT (datetime('now'))
                            )
                        `),
                        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_inv_cat_lab ON inventory_categories(lab_id, is_active)`),
                        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_inv_cat_code ON inventory_categories(code)`),

                        env.DB.prepare(`
                            CREATE TABLE IF NOT EXISTS inventory_locations (
                                id TEXT PRIMARY KEY,
                                lab_id TEXT NOT NULL,
                                name TEXT NOT NULL,
                                is_active INTEGER DEFAULT 1,
                                created_at TEXT DEFAULT (datetime('now')),
                                updated_at TEXT DEFAULT (datetime('now'))
                            )
                        `),
                        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_inv_loc_lab ON inventory_locations(lab_id, is_active)`),

                        env.DB.prepare(`
                            CREATE TABLE IF NOT EXISTS inventory_items (
                                id TEXT PRIMARY KEY,
                                inventory_code TEXT NOT NULL UNIQUE,
                                lab_id TEXT NOT NULL,
                                category_id TEXT NOT NULL,
                                name TEXT NOT NULL,
                                specification TEXT DEFAULT '',
                                location_id TEXT NOT NULL,
                                unit TEXT NOT NULL DEFAULT 'Unit',
                                qty_good INTEGER NOT NULL DEFAULT 0,
                                qty_minor_damage INTEGER NOT NULL DEFAULT 0,
                                qty_major_damage INTEGER NOT NULL DEFAULT 0,
                                qty_total INTEGER NOT NULL DEFAULT 0,
                                acquisition_year INTEGER NOT NULL,
                                funding_source TEXT DEFAULT 'BOS Reguler',
                                notes TEXT DEFAULT '',
                                created_by TEXT NOT NULL,
                                created_at TEXT DEFAULT (datetime('now')),
                                updated_at TEXT DEFAULT (datetime('now'))
                            )
                        `),
                        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_inv_items_lab ON inventory_items(lab_id)`),
                        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_inv_items_category ON inventory_items(category_id)`),
                        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_inv_items_location ON inventory_items(location_id)`),
                        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_inv_items_code ON inventory_items(inventory_code)`),

                        env.DB.prepare(`
                            CREATE TABLE IF NOT EXISTS inventory_condition_history (
                                id TEXT PRIMARY KEY,
                                inventory_item_id TEXT NOT NULL,
                                from_condition TEXT NOT NULL,
                                to_condition TEXT NOT NULL,
                                quantity INTEGER NOT NULL,
                                notes TEXT DEFAULT '',
                                user_id TEXT NOT NULL,
                                user_name TEXT DEFAULT '',
                                created_at TEXT DEFAULT (datetime('now'))
                            )
                        `),
                        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_inv_hist_item ON inventory_condition_history(inventory_item_id, created_at DESC)`)
                    ]);
                    _inventoryTablesChecked = true;
                } catch (err) {
                    console.warn("[Inventory] ensureInventoryTables error:", err);
                }
            }

            // Helper Pembuat Kode Inventaris Unik: LAB-{KODE_LAB}-{KODE_KAT}-{TAHUN}-{SEQ:001}
            async function generateInventoryCode(env, lab, category, acquisitionYear) {
                const rawLabKode = (lab?.kode || lab?.nama || "LAB")
                    .toUpperCase()
                    .replace(/[^A-Z0-9]/g, "")
                    .substring(0, 4);
                const labKode = rawLabKode.length >= 2 ? rawLabKode : "LAB";

                const rawCatKode = (category?.code || category?.name || "UMM")
                    .toUpperCase()
                    .replace(/[^A-Z0-9]/g, "")
                    .substring(0, 4);
                const catKode = rawCatKode.length >= 2 ? rawCatKode : "ITM";

                const year = parseInt(acquisitionYear, 10) || new Date().getFullYear();
                const prefix = `LAB-${labKode}-${catKode}-${year}-`;

                const latestItem = await env.DB.prepare(`
                    SELECT inventory_code 
                    FROM inventory_items 
                    WHERE inventory_code LIKE ? 
                    ORDER BY inventory_code DESC 
                    LIMIT 1
                `).bind(`${prefix}%`).first();

                let nextSeq = 1;
                if (latestItem && latestItem.inventory_code) {
                    const parts = latestItem.inventory_code.split("-");
                    const lastPart = parts[parts.length - 1];
                    const num = parseInt(lastPart, 10);
                    if (!isNaN(num)) {
                        nextSeq = num + 1;
                    }
                }

                for (let attempts = 0; attempts < 10; attempts++) {
                    const seqStr = String(nextSeq).padStart(3, "0");
                    const candidateCode = `${prefix}${seqStr}`;
                    const exists = await env.DB.prepare("SELECT id FROM inventory_items WHERE inventory_code = ? LIMIT 1").bind(candidateCode).first();
                    if (!exists) {
                        return candidateCode;
                    }
                    nextSeq++;
                }

                return `${prefix}${String(nextSeq).padStart(3, "0")}-${Math.random().toString(36).substring(2, 5).toUpperCase()}`;
            }

            // 1. GET /api/inventory/categories (Daftar Kategori per Lab)
            if (path === "/api/inventory/categories" && method === "GET") {
                await ensureInventoryTables(env);
                const labId = url.searchParams.get("lab_id");
                const includeInactive = url.searchParams.get("include_inactive") === "1" || url.searchParams.get("include_inactive") === "true";

                let query = "SELECT * FROM inventory_categories WHERE 1=1";
                const params = [];

                if (labId) {
                    query += " AND lab_id = ?";
                    params.push(labId);
                }

                if (!includeInactive) {
                    query += " AND is_active = 1";
                }

                query += " ORDER BY name ASC";
                const { results } = await env.DB.prepare(query).bind(...params).all();

                return jsonResponse({
                    success: true,
                    data: results || []
                }, 200, request);
            }

            // 2. POST /api/inventory/categories (Tambah Kategori)
            if (path === "/api/inventory/categories" && method === "POST") {
                await ensureInventoryTables(env);
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const body = await request.json();
                const labId = String(body.lab_id || "").trim();
                const name = String(body.name || "").trim();
                const rawCode = String(body.code || "").trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
                const code = rawCode || name.substring(0, 3).toUpperCase() || "CAT";

                if (!labId || !name) {
                    return errorResponse("lab_id dan nama kategori (name) wajib diisi", 400, request);
                }

                const access = await verifyLabAccess(env, authResult.user, labId, "write");
                if (!access.allowed) return errorResponse(access.error, access.status, request);

                const id = `cat_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`;
                await env.DB.prepare(`
                    INSERT INTO inventory_categories (id, lab_id, name, code, is_active, created_at, updated_at)
                    VALUES (?, ?, ?, ?, 1, datetime('now'), datetime('now'))
                `).bind(id, labId, name, code).run();

                return jsonResponse({
                    success: true,
                    data: { id, lab_id: labId, name, code, is_active: 1 },
                    message: "Kategori inventaris berhasil ditambahkan."
                }, 201, request);
            }

            // 3. PUT /api/inventory/categories/:id (Edit Kategori)
            if (path.startsWith("/api/inventory/categories/") && method === "PUT") {
                await ensureInventoryTables(env);
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const catId = decodeURIComponent(path.replace("/api/inventory/categories/", "")).trim();
                const existing = await env.DB.prepare("SELECT * FROM inventory_categories WHERE id = ?").bind(catId).first();
                if (!existing) return errorResponse("Kategori tidak ditemukan", 404, request);

                const access = await verifyLabAccess(env, authResult.user, existing.lab_id, "write");
                if (!access.allowed) return errorResponse(access.error, access.status, request);

                const body = await request.json();
                const name = String(body.name !== undefined ? body.name : existing.name).trim();
                const rawCode = body.code !== undefined ? String(body.code).trim().toUpperCase().replace(/[^A-Z0-9]/g, "") : existing.code;
                const code = rawCode || name.substring(0, 3).toUpperCase() || "CAT";
                const isActive = body.is_active !== undefined ? (body.is_active ? 1 : 0) : existing.is_active;

                if (!name) return errorResponse("Nama kategori wajib diisi", 400, request);

                await env.DB.prepare(`
                    UPDATE inventory_categories 
                    SET name = ?, code = ?, is_active = ?, updated_at = datetime('now')
                    WHERE id = ?
                `).bind(name, code, isActive, catId).run();

                return jsonResponse({
                    success: true,
                    message: "Kategori inventaris berhasil diperbarui."
                }, 200, request);
            }

            // 4. DELETE /api/inventory/categories/:id (Nonaktifkan / Hapus Kategori)
            if (path.startsWith("/api/inventory/categories/") && method === "DELETE") {
                await ensureInventoryTables(env);
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const catId = decodeURIComponent(path.replace("/api/inventory/categories/", "")).trim();
                const existing = await env.DB.prepare("SELECT * FROM inventory_categories WHERE id = ?").bind(catId).first();
                if (!existing) return errorResponse("Kategori tidak ditemukan", 404, request);

                const access = await verifyLabAccess(env, authResult.user, existing.lab_id, "write");
                if (!access.allowed) return errorResponse(access.error, access.status, request);

                // Cek apakah sudah terpakai oleh barang inventaris
                const usage = await env.DB.prepare("SELECT COUNT(*) as cnt FROM inventory_items WHERE category_id = ?").bind(catId).first();
                if (usage && usage.cnt > 0) {
                    // Soft-deactivate jika sudah pernah terpakai
                    await env.DB.prepare("UPDATE inventory_categories SET is_active = 0, updated_at = datetime('now') WHERE id = ?").bind(catId).run();
                    return jsonResponse({
                        success: true,
                        deactivated: true,
                        message: `Kategori telah digunakan oleh ${usage.cnt} barang, status dinonaktifkan alih-alih dihapus permanen.`
                    }, 200, request);
                }

                await env.DB.prepare("DELETE FROM inventory_categories WHERE id = ?").bind(catId).run();
                return jsonResponse({
                    success: true,
                    message: "Kategori inventaris berhasil dihapus."
                }, 200, request);
            }

            // 5. GET /api/inventory/locations (Daftar Lokasi Simpan per Lab)
            if (path === "/api/inventory/locations" && method === "GET") {
                await ensureInventoryTables(env);
                const labId = url.searchParams.get("lab_id");
                const includeInactive = url.searchParams.get("include_inactive") === "1" || url.searchParams.get("include_inactive") === "true";

                let query = "SELECT * FROM inventory_locations WHERE 1=1";
                const params = [];

                if (labId) {
                    query += " AND lab_id = ?";
                    params.push(labId);
                }

                if (!includeInactive) {
                    query += " AND is_active = 1";
                }

                query += " ORDER BY name ASC";
                const { results } = await env.DB.prepare(query).bind(...params).all();

                return jsonResponse({
                    success: true,
                    data: results || []
                }, 200, request);
            }

            // 6. POST /api/inventory/locations (Tambah Lokasi Simpan)
            if (path === "/api/inventory/locations" && method === "POST") {
                await ensureInventoryTables(env);
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const body = await request.json();
                const labId = String(body.lab_id || "").trim();
                const name = String(body.name || "").trim();

                if (!labId || !name) {
                    return errorResponse("lab_id dan nama lokasi simpan (name) wajib diisi", 400, request);
                }

                const access = await verifyLabAccess(env, authResult.user, labId, "write");
                if (!access.allowed) return errorResponse(access.error, access.status, request);

                const id = `loc_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`;
                await env.DB.prepare(`
                    INSERT INTO inventory_locations (id, lab_id, name, is_active, created_at, updated_at)
                    VALUES (?, ?, ?, 1, datetime('now'), datetime('now'))
                `).bind(id, labId, name).run();

                return jsonResponse({
                    success: true,
                    data: { id, lab_id: labId, name, is_active: 1 },
                    message: "Lokasi penyimpanan berhasil ditambahkan."
                }, 201, request);
            }

            // 7. PUT /api/inventory/locations/:id (Edit Lokasi Simpan)
            if (path.startsWith("/api/inventory/locations/") && method === "PUT") {
                await ensureInventoryTables(env);
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const locId = decodeURIComponent(path.replace("/api/inventory/locations/", "")).trim();
                const existing = await env.DB.prepare("SELECT * FROM inventory_locations WHERE id = ?").bind(locId).first();
                if (!existing) return errorResponse("Lokasi simpan tidak ditemukan", 404, request);

                const access = await verifyLabAccess(env, authResult.user, existing.lab_id, "write");
                if (!access.allowed) return errorResponse(access.error, access.status, request);

                const body = await request.json();
                const name = String(body.name !== undefined ? body.name : existing.name).trim();
                const isActive = body.is_active !== undefined ? (body.is_active ? 1 : 0) : existing.is_active;

                if (!name) return errorResponse("Nama lokasi simpan wajib diisi", 400, request);

                await env.DB.prepare(`
                    UPDATE inventory_locations 
                    SET name = ?, is_active = ?, updated_at = datetime('now')
                    WHERE id = ?
                `).bind(name, isActive, locId).run();

                return jsonResponse({
                    success: true,
                    message: "Lokasi penyimpanan berhasil diperbarui."
                }, 200, request);
            }

            // 8. DELETE /api/inventory/locations/:id (Nonaktifkan / Hapus Lokasi Simpan)
            if (path.startsWith("/api/inventory/locations/") && method === "DELETE") {
                await ensureInventoryTables(env);
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const locId = decodeURIComponent(path.replace("/api/inventory/locations/", "")).trim();
                const existing = await env.DB.prepare("SELECT * FROM inventory_locations WHERE id = ?").bind(locId).first();
                if (!existing) return errorResponse("Lokasi simpan tidak ditemukan", 404, request);

                const access = await verifyLabAccess(env, authResult.user, existing.lab_id, "write");
                if (!access.allowed) return errorResponse(access.error, access.status, request);

                const usage = await env.DB.prepare("SELECT COUNT(*) as cnt FROM inventory_items WHERE location_id = ?").bind(locId).first();
                if (usage && usage.cnt > 0) {
                    await env.DB.prepare("UPDATE inventory_locations SET is_active = 0, updated_at = datetime('now') WHERE id = ?").bind(locId).run();
                    return jsonResponse({
                        success: true,
                        deactivated: true,
                        message: `Lokasi telah digunakan oleh ${usage.cnt} barang, status dinonaktifkan alih-alih dihapus permanen.`
                    }, 200, request);
                }

                await env.DB.prepare("DELETE FROM inventory_locations WHERE id = ?").bind(locId).run();
                return jsonResponse({
                    success: true,
                    message: "Lokasi penyimpanan berhasil dihapus."
                }, 200, request);
            }

            // 9. GET /api/inventory/summary (Statistik Metrik Ringkasan)
            if (path === "/api/inventory/summary" && method === "GET") {
                await ensureInventoryTables(env);
                const authResult = await verifyFirebaseToken(request);
                const labId = url.searchParams.get("lab_id");

                let query = `
                    SELECT 
                        COUNT(i.id) as total_items,
                        COALESCE(SUM(i.qty_total), 0) as total_units,
                        COALESCE(SUM(i.qty_good), 0) as total_good,
                        COALESCE(SUM(i.qty_minor_damage), 0) as total_minor_damage,
                        COALESCE(SUM(i.qty_major_damage), 0) as total_major_damage
                    FROM inventory_items i
                    JOIN labs l ON i.lab_id = l.id
                    WHERE 1=1
                `;
                const params = [];

                if (labId) {
                    query += " AND i.lab_id = ?";
                    params.push(labId);
                }

                const result = await env.DB.prepare(query).bind(...params).first();

                return jsonResponse({
                    success: true,
                    data: {
                        total_items: Number(result?.total_items || 0),
                        total_units: Number(result?.total_units || 0),
                        total_good: Number(result?.total_good || 0),
                        total_minor_damage: Number(result?.total_minor_damage || 0),
                        total_major_damage: Number(result?.total_major_damage || 0)
                    }
                }, 200, request);
            }

            // 10. GET /api/inventory/items (Daftar Barang Inventaris dengan Filter, Search & Sort)
            if (path === "/api/inventory/items" && method === "GET") {
                await ensureInventoryTables(env);
                const authResult = await verifyFirebaseToken(request);
                const labId = url.searchParams.get("lab_id");
                const categoryId = url.searchParams.get("category_id");
                const locationId = url.searchParams.get("location_id");
                const condition = url.searchParams.get("condition"); // all, good, minor_damage, major_damage
                const search = url.searchParams.get("search");
                const sortByParam = (url.searchParams.get("sort_by") || url.searchParams.get("sortBy") || "created_at").trim().toLowerCase();
                const sortDirParam = (url.searchParams.get("sort_dir") || url.searchParams.get("sortDir") || "").trim().toUpperCase();
                const limit = Math.min(Math.max(parseInt(url.searchParams.get("limit") || "100", 10), 1), 500);
                const offset = Math.max(parseInt(url.searchParams.get("offset") || "0", 10), 0);

                let whereClause = " WHERE 1=1";
                const params = [];

                if (labId) {
                    whereClause += " AND i.lab_id = ?";
                    params.push(labId);
                }

                if (categoryId) {
                    whereClause += " AND i.category_id = ?";
                    params.push(categoryId);
                }

                if (locationId) {
                    whereClause += " AND i.location_id = ?";
                    params.push(locationId);
                }

                if (condition === "minor_damage") {
                    whereClause += " AND i.qty_minor_damage > 0";
                } else if (condition === "major_damage") {
                    whereClause += " AND i.qty_major_damage > 0";
                } else if (condition === "good") {
                    whereClause += " AND i.qty_good = i.qty_total AND i.qty_total > 0";
                }

                if (search) {
                    whereClause += " AND (i.name LIKE ? OR i.inventory_code LIKE ? OR i.specification LIKE ?)";
                    const searchTerm = `%${search.trim()}%`;
                    params.push(searchTerm, searchTerm, searchTerm);
                }

                const countQuery = `
                    SELECT COUNT(i.id) as total 
                    FROM inventory_items i 
                    JOIN labs l ON i.lab_id = l.id 
                    ${whereClause}
                `;
                const countRes = await env.DB.prepare(countQuery).bind(...params).first();
                const totalRecords = countRes?.total || 0;

                const sortColumnMap = {
                    "created_at": "i.created_at",
                    "name": "i.name",
                    "code": "i.inventory_code",
                    "inventory_code": "i.inventory_code",
                    "qty": "i.qty_total",
                    "qty_total": "i.qty_total",
                    "year": "i.acquisition_year",
                    "acquisition_year": "i.acquisition_year"
                };

                const sortCol = sortColumnMap[sortByParam] || "i.created_at";
                const sortDir = (sortDirParam === "ASC" || sortDirParam === "DESC")
                    ? sortDirParam
                    : (sortByParam === "name" || sortByParam === "code" || sortByParam === "inventory_code" ? "ASC" : "DESC");

                const dataQuery = `
                    SELECT 
                        i.*,
                        l.nama as lab_nama,
                        l.kode as lab_kode,
                        c.name as category_name,
                        c.code as category_code,
                        loc.name as location_name
                    FROM inventory_items i
                    LEFT JOIN labs l ON i.lab_id = l.id
                    LEFT JOIN inventory_categories c ON i.category_id = c.id
                    LEFT JOIN inventory_locations loc ON i.location_id = loc.id
                    ${whereClause}
                    ORDER BY ${sortCol} ${sortDir}, i.id DESC
                    LIMIT ? OFFSET ?
                `;
                const queryParams = [...params, limit, offset];
                const { results } = await env.DB.prepare(dataQuery).bind(...queryParams).all();

                return jsonResponse({
                    success: true,
                    data: results || [],
                    total: totalRecords,
                    limit,
                    offset,
                    sort_by: sortByParam,
                    sort_dir: sortDir
                }, 200, request);
            }

            // 11. POST /api/inventory/items (Tambah Barang Inventaris Baru)
            if (path === "/api/inventory/items" && method === "POST") {
                await ensureInventoryTables(env);
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const body = await request.json();
                const labId = String(body.lab_id || "").trim();
                const categoryId = String(body.category_id || "").trim();
                const name = String(body.name || "").trim();
                const specification = String(body.specification || "").trim();
                const locationId = String(body.location_id || "").trim();
                const unit = String(body.unit || "Unit").trim();
                const acquisitionYear = parseInt(body.acquisition_year, 10);
                const fundingSource = String(body.funding_source || "BOS Reguler").trim();
                const notes = String(body.notes || "").trim();

                // Validasi otorisasi wewenang lab
                const access = await verifyLabAccess(env, authResult.user, labId, "write");
                if (!access.allowed) return errorResponse(access.error, access.status, request);

                // Validasi field wajib
                if (!labId || !categoryId || !name || !locationId || isNaN(acquisitionYear)) {
                    return errorResponse("Data tidak lengkap (lab_id, category_id, name, location_id, acquisition_year wajib diisi)", 400, request);
                }

                // Validasi kuantitas non-negatif integer
                const qtyGood = parseInt(body.qty_good !== undefined ? body.qty_good : 1, 10);
                const qtyMinor = parseInt(body.qty_minor_damage !== undefined ? body.qty_minor_damage : 0, 10);
                const qtyMajor = parseInt(body.qty_major_damage !== undefined ? body.qty_major_damage : 0, 10);

                if (isNaN(qtyGood) || qtyGood < 0 || isNaN(qtyMinor) || qtyMinor < 0 || isNaN(qtyMajor) || qtyMajor < 0) {
                    return errorResponse("Jumlah kondisi tidak boleh negatif dan wajib berupa bilangan bulat", 400, request);
                }

                const qtyTotal = qtyGood + qtyMinor + qtyMajor;
                if (qtyTotal < 1) {
                    return errorResponse("Total kuantitas barang minimal 1 unit", 400, request);
                }

                // Verifikasi keberadaan category dan location pada lab yang sama
                const category = await env.DB.prepare("SELECT * FROM inventory_categories WHERE id = ? AND lab_id = ?").bind(categoryId, labId).first();
                if (!category) return errorResponse("Kategori tidak valid atau tidak cocok dengan laboratorium yang dipilih", 400, request);

                const location = await env.DB.prepare("SELECT * FROM inventory_locations WHERE id = ? AND lab_id = ?").bind(locationId, labId).first();
                if (!location) return errorResponse("Lokasi penyimpanan tidak valid atau tidak cocok dengan laboratorium yang dipilih", 400, request);

                const inventoryCode = await generateInventoryCode(env, access.lab, category, acquisitionYear);
                const id = `inv_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
                const createdBy = authResult.user.claims?.name || authResult.user.email || "Staf Lab";

                await env.DB.prepare(`
                    INSERT INTO inventory_items (
                        id, inventory_code, lab_id, category_id, name, specification,
                        location_id, unit, qty_good, qty_minor_damage, qty_major_damage,
                        qty_total, acquisition_year, funding_source, notes, created_by,
                        created_at, updated_at
                    ) VALUES (
                        ?, ?, ?, ?, ?, ?,
                        ?, ?, ?, ?, ?,
                        ?, ?, ?, ?, ?,
                        datetime('now'), datetime('now')
                    )
                `).bind(
                    id, inventoryCode, labId, categoryId, name, specification,
                    locationId, unit, qtyGood, qtyMinor, qtyMajor,
                    qtyTotal, acquisitionYear, fundingSource, notes, createdBy
                ).run();

                const newItem = await env.DB.prepare("SELECT * FROM inventory_items WHERE id = ?").bind(id).first();

                return jsonResponse({
                    success: true,
                    data: newItem,
                    message: "Barang inventaris baru berhasil ditambahkan."
                }, 201, request);
            }

            // 11b. POST /api/inventory/items/bulk (Bulk Impor Barang Inventaris Baru dari Excel)
            if (path === "/api/inventory/items/bulk" && method === "POST") {
                await ensureInventoryTables(env);
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const body = await request.json();
                const labId = String(body.lab_id || "").trim();
                const itemsList = Array.isArray(body.items) ? body.items : [];

                if (!labId) {
                    return errorResponse("Parameter 'lab_id' wajib diisi", 400, request);
                }

                if (itemsList.length === 0) {
                    return errorResponse("Array 'items' kosong atau tidak valid", 400, request);
                }

                // Validasi otorisasi wewenang lab
                const access = await verifyLabAccess(env, authResult.user, labId, "write");
                if (!access.allowed) return errorResponse(access.error, access.status, request);

                // Ambil seluruh kategori dan lokasi di lab ini untuk validasi cepat di memori
                const categoriesRes = await env.DB.prepare("SELECT * FROM inventory_categories WHERE lab_id = ?").bind(labId).all();
                const locationsRes = await env.DB.prepare("SELECT * FROM inventory_locations WHERE lab_id = ?").bind(labId).all();
                const availableCategories = categoriesRes?.results || [];
                const availableLocations = locationsRes?.results || [];

                if (availableCategories.length === 0) {
                    return errorResponse("Laboratorium ini belum memiliki kategori inventaris. Buat kategori terlebih dahulu.", 400, request);
                }
                if (availableLocations.length === 0) {
                    return errorResponse("Laboratorium ini belum memiliki lokasi penyimpanan. Buat lokasi terlebih dahulu.", 400, request);
                }

                const catMap = new Map();
                for (const c of availableCategories) {
                    catMap.set(c.id, c);
                }
                const locMap = new Map();
                for (const l of availableLocations) {
                    locMap.set(l.id, l);
                }

                const createdBy = authResult.user.claims?.name || authResult.user.email || "Staf Lab";
                const statements = [];
                const insertedItems = [];
                const nowYear = new Date().getFullYear();

                // Tracker sequence kode inventaris per prefix
                const seqTracker = new Map();

                for (let idx = 0; idx < itemsList.length; idx++) {
                    const row = itemsList[idx];
                    const name = String(row.name || "").trim();
                    const specification = String(row.specification || "").trim();
                    const categoryId = String(row.category_id || "").trim();
                    const locationId = String(row.location_id || "").trim();
                    const unit = String(row.unit || "Unit").trim();
                    const acquisitionYear = parseInt(row.acquisition_year, 10) || nowYear;
                    const fundingSource = String(row.funding_source || "BOS Reguler").trim();
                    const notes = String(row.notes || "").trim();
                    const qty = parseInt(row.qty_good !== undefined ? row.qty_good : (row.qty_total || 1), 10);

                    // Validasi field wajib
                    if (!name || !specification || !categoryId || !locationId || isNaN(qty) || qty < 1) {
                        return errorResponse(`Baris ${idx + 1}: Data tidak lengkap atau tidak valid (Nama, Spesifikasi, Kategori, Lokasi, dan Kuantitas minimal 1 wajib diisi)`, 400, request);
                    }

                    const category = catMap.get(categoryId);
                    if (!category) {
                        return errorResponse(`Baris ${idx + 1}: Kategori ID '${categoryId}' tidak valid pada laboratorium ini`, 400, request);
                    }

                    const location = locMap.get(locationId);
                    if (!location) {
                        return errorResponse(`Baris ${idx + 1}: Lokasi ID '${locationId}' tidak valid pada laboratorium ini`, 400, request);
                    }

                    // Susun prefix kode
                    const rawLabKode = (access.lab?.kode || access.lab?.nama || "LAB")
                        .toUpperCase()
                        .replace(/[^A-Z0-9]/g, "")
                        .substring(0, 4);
                    const labKode = rawLabKode.length >= 2 ? rawLabKode : "LAB";

                    const rawCatKode = (category.code || category.name || "UMM")
                        .toUpperCase()
                        .replace(/[^A-Z0-9]/g, "")
                        .substring(0, 4);
                    const catKode = rawCatKode.length >= 2 ? rawCatKode : "ITM";

                    const prefix = `LAB-${labKode}-${catKode}-${acquisitionYear}-`;

                    let nextSeq;
                    if (seqTracker.has(prefix)) {
                        nextSeq = seqTracker.get(prefix) + 1;
                    } else {
                        const latestItem = await env.DB.prepare(`
                            SELECT inventory_code 
                            FROM inventory_items 
                            WHERE inventory_code LIKE ? 
                            ORDER BY inventory_code DESC 
                            LIMIT 1
                        `).bind(`${prefix}%`).first();

                        nextSeq = 1;
                        if (latestItem && latestItem.inventory_code) {
                            const parts = latestItem.inventory_code.split("-");
                            const num = parseInt(parts[parts.length - 1], 10);
                            if (!isNaN(num)) nextSeq = num + 1;
                        }
                    }
                    seqTracker.set(prefix, nextSeq);

                    const seqStr = String(nextSeq).padStart(3, "0");
                    const inventoryCode = `${prefix}${seqStr}`;
                    const id = `inv_${Date.now()}_${Math.random().toString(36).substring(2, 7)}_${idx}`;

                    statements.push(
                        env.DB.prepare(`
                            INSERT INTO inventory_items (
                                id, inventory_code, lab_id, category_id, name, specification,
                                location_id, unit, qty_good, qty_minor_damage, qty_major_damage,
                                qty_total, acquisition_year, funding_source, notes, created_by,
                                created_at, updated_at
                            ) VALUES (
                                ?, ?, ?, ?, ?, ?,
                                ?, ?, ?, 0, 0,
                                ?, ?, ?, ?, ?,
                                datetime('now'), datetime('now')
                            )
                        `).bind(
                            id, inventoryCode, labId, categoryId, name, specification,
                            locationId, unit, qty,
                            qty, acquisitionYear, fundingSource, notes, createdBy
                        )
                    );

                    insertedItems.push({
                        id,
                        inventory_code: inventoryCode,
                        name,
                        specification,
                        qty_total: qty,
                        unit
                    });
                }

                if (statements.length > 0) {
                    await env.DB.batch(statements);
                }

                return jsonResponse({
                    success: true,
                    count: statements.length,
                    data: insertedItems,
                    message: `Berhasil mengimpor ${statements.length} barang inventaris.`
                }, 201, request);
            }

            // 12. GET /api/inventory/items/:id (Detail Barang & Riwayat Kondisi)
            if (path.startsWith("/api/inventory/items/") && !path.includes("/change-condition") && !path.endsWith("/history") && method === "GET") {
                await ensureInventoryTables(env);
                const itemId = decodeURIComponent(path.replace("/api/inventory/items/", "")).trim();

                const item = await env.DB.prepare(`
                    SELECT 
                        i.*,
                        l.nama as lab_nama,
                        l.kode as lab_kode,
                        c.name as category_name,
                        c.code as category_code,
                        loc.name as location_name
                    FROM inventory_items i
                    LEFT JOIN labs l ON i.lab_id = l.id
                    LEFT JOIN inventory_categories c ON i.category_id = c.id
                    LEFT JOIN inventory_locations loc ON i.location_id = loc.id
                    WHERE i.id = ?
                `).bind(itemId).first();

                if (!item) return errorResponse("Barang inventaris tidak ditemukan", 404, request);

                const { results: history } = await env.DB.prepare(`
                    SELECT * FROM inventory_condition_history 
                    WHERE inventory_item_id = ? 
                    ORDER BY created_at DESC 
                    LIMIT 20
                `).bind(itemId).all();

                return jsonResponse({
                    success: true,
                    data: {
                        ...item,
                        condition_history: history || []
                    }
                }, 200, request);
            }

            // 13. PUT /api/inventory/items/:id (Edit Metadata Barang - Bukan Kuantitas)
            if (path.startsWith("/api/inventory/items/") && !path.includes("/change-condition") && method === "PUT") {
                await ensureInventoryTables(env);
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const itemId = decodeURIComponent(path.replace("/api/inventory/items/", "")).trim();
                const existing = await env.DB.prepare("SELECT * FROM inventory_items WHERE id = ?").bind(itemId).first();
                if (!existing) return errorResponse("Barang inventaris tidak ditemukan", 404, request);

                const access = await verifyLabAccess(env, authResult.user, existing.lab_id, "write");
                if (!access.allowed) return errorResponse(access.error, access.status, request);

                const body = await request.json();
                const name = String(body.name !== undefined ? body.name : existing.name).trim();
                const specification = String(body.specification !== undefined ? body.specification : existing.specification).trim();
                const categoryId = String(body.category_id !== undefined ? body.category_id : existing.category_id).trim();
                const locationId = String(body.location_id !== undefined ? body.location_id : existing.location_id).trim();
                const unit = String(body.unit !== undefined ? body.unit : existing.unit).trim();
                const acquisitionYear = parseInt(body.acquisition_year !== undefined ? body.acquisition_year : existing.acquisition_year, 10);
                const fundingSource = String(body.funding_source !== undefined ? body.funding_source : existing.funding_source).trim();
                const notes = String(body.notes !== undefined ? body.notes : existing.notes).trim();

                if (!name || isNaN(acquisitionYear)) {
                    return errorResponse("Nama barang dan tahun perolehan wajib diisi", 400, request);
                }

                await env.DB.prepare(`
                    UPDATE inventory_items 
                    SET name = ?, specification = ?, category_id = ?, location_id = ?,
                        unit = ?, acquisition_year = ?, funding_source = ?, notes = ?,
                        updated_at = datetime('now')
                    WHERE id = ?
                `).bind(name, specification, categoryId, locationId, unit, acquisitionYear, fundingSource, notes, itemId).run();

                const updated = await env.DB.prepare("SELECT * FROM inventory_items WHERE id = ?").bind(itemId).first();

                return jsonResponse({
                    success: true,
                    data: updated,
                    message: "Data barang inventaris berhasil diperbarui."
                }, 200, request);
            }

            // 14. DELETE /api/inventory/items/:id (Hapus Barang Inventaris)
            if (path.startsWith("/api/inventory/items/") && !path.includes("/change-condition") && method === "DELETE") {
                await ensureInventoryTables(env);
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const itemId = decodeURIComponent(path.replace("/api/inventory/items/", "")).trim();
                const existing = await env.DB.prepare("SELECT * FROM inventory_items WHERE id = ?").bind(itemId).first();
                if (!existing) return errorResponse("Barang inventaris tidak ditemukan", 404, request);

                const access = await verifyLabAccess(env, authResult.user, existing.lab_id, "write");
                if (!access.allowed) return errorResponse(access.error, access.status, request);

                // Hapus barang beserta log riwayat mutasi kondisinya secara atomik
                await env.DB.batch([
                    env.DB.prepare("DELETE FROM inventory_condition_history WHERE inventory_item_id = ?").bind(itemId),
                    env.DB.prepare("DELETE FROM inventory_items WHERE id = ?").bind(itemId)
                ]);

                return jsonResponse({
                    success: true,
                    message: "Barang inventaris berhasil dihapus."
                }, 200, request);
            }

            // 15. POST /api/inventory/items/:id/change-condition (Ubah Kondisi Stok & Catat Riwayat Atomik)
            if (path.startsWith("/api/inventory/items/") && path.endsWith("/change-condition") && method === "POST") {
                await ensureInventoryTables(env);
                const authResult = await verifyFirebaseToken(request);
                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);

                const itemId = decodeURIComponent(path.replace("/api/inventory/items/", "").replace("/change-condition", "")).trim();
                const existing = await env.DB.prepare("SELECT * FROM inventory_items WHERE id = ?").bind(itemId).first();
                if (!existing) return errorResponse("Barang inventaris tidak ditemukan", 404, request);

                const access = await verifyLabAccess(env, authResult.user, existing.lab_id, "write");
                if (!access.allowed) return errorResponse(access.error, access.status, request);

                const body = await request.json();
                const fromCond = String(body.from_condition || "").trim().toLowerCase();
                const toCond = String(body.to_condition || "").trim().toLowerCase();
                const quantity = parseInt(body.quantity, 10);
                const notes = String(body.notes || "").trim();

                const validConditions = ["good", "minor_damage", "major_damage"];
                if (!validConditions.includes(fromCond) || !validConditions.includes(toCond)) {
                    return errorResponse("Kondisi tidak valid (pilihan: good, minor_damage, major_damage)", 400, request);
                }

                if (fromCond === toCond) {
                    return errorResponse("Kondisi asal dan kondisi tujuan tidak boleh sama", 400, request);
                }

                if (isNaN(quantity) || quantity <= 0) {
                    return errorResponse("Jumlah unit yang dipindahkan harus berupa bilangan bulat positif (> 0)", 400, request);
                }

                const condColMap = {
                    good: "qty_good",
                    minor_damage: "qty_minor_damage",
                    major_damage: "qty_major_damage"
                };

                const fromCol = condColMap[fromCond];
                const toCol = condColMap[toCond];
                const availableStock = Number(existing[fromCol] || 0);

                if (quantity > availableStock) {
                    return errorResponse(`Jumlah perpindahan (${quantity}) melebihi stok yang tersedia pada kondisi asal (${availableStock})`, 400, request);
                }

                const historyId = `ich_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
                const userName = authResult.user.claims?.name || authResult.user.email || "Staf Lab";

                // Mutasi stok dan pencatatan history secara atomik
                await env.DB.batch([
                    env.DB.prepare(`
                        UPDATE inventory_items 
                        SET ${fromCol} = ${fromCol} - ?,
                            ${toCol} = ${toCol} + ?,
                            updated_at = datetime('now')
                        WHERE id = ?
                    `).bind(quantity, quantity, itemId),

                    env.DB.prepare(`
                        INSERT INTO inventory_condition_history (
                            id, inventory_item_id, from_condition, to_condition,
                            quantity, notes, user_id, user_name, created_at
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
                    `).bind(historyId, itemId, fromCond, toCond, quantity, notes, authResult.user.uid, userName)
                ]);

                const updated = await env.DB.prepare("SELECT * FROM inventory_items WHERE id = ?").bind(itemId).first();

                return jsonResponse({
                    success: true,
                    data: updated,
                    message: `Kondisi barang berhasil diubah: ${quantity} unit dipindahkan ke kondisi baru.`
                }, 200, request);
            }

            // 16. GET /api/inventory/items/:id/history (Riwayat Perubahan Kondisi Barang)
            if (path.startsWith("/api/inventory/items/") && path.endsWith("/history") && method === "GET") {
                await ensureInventoryTables(env);
                const itemId = decodeURIComponent(path.replace("/api/inventory/items/", "").replace("/history", "")).trim();

                const { results } = await env.DB.prepare(`
                    SELECT * FROM inventory_condition_history 
                    WHERE inventory_item_id = ? 
                    ORDER BY created_at DESC
                `).bind(itemId).all();

                return jsonResponse({
                    success: true,
                    data: results || []
                }, 200, request);
            }

