                if (!authResult.valid) return errorResponse("Unauthorized: " + authResult.error, 401, request);
                if (!canManageSarpras(authResult.user)) return errorResponse("Forbidden: Hak akses tidak memadai", 403, request);

                const logId = decodeURIComponent(path.replace("/api/sarpras/maintenance/logs/", "")).trim();
                await env.DB.prepare("DELETE FROM sarpras_maintenance_logs WHERE id = ?").bind(logId).run();
                return jsonResponse({ success: true, message: "Tiket pemeliharaan berhasil dihapus" }, 200, request);
